- &#x60;traffic_timestamp&#x60; (string) — &#x60;YYYY-MM-DD HH:MM:SS&#x60; in account timezone.

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

     */
    @Location("/affiliate/web_traffic") class getAffiliateWebTraffic()

    /**
     * Read the current shopping cart contents, totals, and available payment methods
     * Returns the customer&#x27;s checkout state — every pending/unpaid invoice on the account aggregated as a cart, plus available payment methods, currency totals, and checkout metadata. Use to render a checkout page or, in agent flows, as a pre-payment confirmation step before calling &#x60;initiatePayment&#x60;. Backed by the &#x60;cart&#x60; helper module; &#x60;modules_json&#x60; and &#x60;csrf_token&#x60; are stripped from the response. Read-only. Sibling ops: &#x60;getBillingInvoices&#x60; (raw list), &#x60;getBillingInvoice&#x60; (one invoice in detail), &#x60;initiatePayment&#x60; (pay), &#x60;getBillingPrePays&#x60; (check prepay balance first).

**Path/Query/Body:** None.

**Returns:** A cart object with:
- Line items aggregated from unpaid &#x60;invoices&#x60; rows for the session account.
- Currency-normalized subtotal / total.
- Available payment methods (filtered by feature flags, account country, and which gateways are enabled): &#x60;cc&#x60;, &#x60;paypal&#x60;, &#x60;btcpay&#x60;, &#x60;coinbase&#x60;, &#x60;payu&#x60;, &#x60;ccavenue&#x60;, &#x60;cashfree&#x60;, &#x60;payssion&#x60;, &#x60;prepay&#x60;.
- Per-invoice description, module, service-id, amount.

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **List unpaid invoices directly:** &#x60;getBillingInvoices&#x60;.
- **Drill into one invoice:** &#x60;getBillingInvoice&#x60;.
- **Pay:** &#x60;initiatePayment&#x60; (use the cart&#x27;s invoice ids or the &#x60;SERVICEvpsN&#x60; / &#x60;INVvpsN&#x60; tag forms).
- **Top up prepay first:** &#x60;getBillingPrePays&#x60;, &#x60;addBillingPrepay&#x60;.

     */
    @Location("/billing/cart") class getBillingCart()

    /**
     * Probe whether a stored card still needs micro-charge verification
     * Status probe for the credit-card verification flow. Read-only — current implementation returns a placeholder string indicating verification is pending; the actual two-step verification happens via &#x60;patchBillingCreditCardVerify&#x60; (initiate dual micro-charge with CVV) followed by &#x60;postBillingCreditCardVerify&#x60; (submit the charged amounts). Use to drive the UI&#x27;s &quot;verify card&quot; form rendering. Sibling ops: &#x60;patchBillingCreditCardVerify&#x60;, &#x60;postBillingCreditCardVerify&#x60;, &#x60;addBillingCreditCard&#x60;, &#x60;updateBillingPaymentMethod&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — credit card index from &#x60;parse_ccs&#x60;.

**Body:** None.

**Returns:** &#x60;Verification requirements&#x60; (placeholder text — reserved for future structured response with &#x60;requires_cvv&#x60; / &#x60;requires_amounts&#x60; flags).

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Step 1 of verify flow:** &#x60;patchBillingCreditCardVerify&#x60;.
- **Step 2 of verify flow:** &#x60;postBillingCreditCardVerify&#x60;.
- **Add a new card:** &#x60;addBillingCreditCard&#x60;.

     * @param id The credit card ID to verify. Use the ID returned from &#x60;POST /billing/creditcards&#x60;. 
     */
    @Location("/billing/creditcards/{id}/verify") class getBillingCreditCardVerify(val id: kotlin.Int)

    /**
     * Read full invoice detail — line items, totals, paid status, customer info
     * Returns the full rendered invoice payload for a single invoice — backed by &#x60;get_invoice_data()&#x60;, the same helper that builds the email-style invoice document. Use to confirm the exact balance due and the invoice description before calling &#x60;initiatePayment&#x60;, or to render an invoice viewer page. Read-only. The response is an email-style/HTML payload (not a structured line-item array) — for a structured cart-style summary use &#x60;getBillingCart&#x60;. The response includes a Link to &#x60;deleteBillingInvoice&#x60; for unpaid pending-service invoices. Sibling ops: &#x60;getBillingInvoices&#x60;, &#x60;deleteBillingInvoice&#x60;, &#x60;initiatePayment&#x60;, &#x60;getBillingCart&#x60;, per-service &#x60;getVpsInvoices&#x60; / &#x60;getMailInvoices&#x60; / etc.

**Path param:**
- &#x60;id&#x60; (integer, required) — invoice id from &#x60;getBillingInvoices.rows[].id&#x60;, from an order endpoint&#x27;s response (e.g. &#x60;addVps.iid&#x60;), or from a per-service invoice list.

**Body:** None.

**Returns:** &#x60;BillingInvoiceDetail&#x60; — full rendered invoice payload (email body) with line items, totals, customer/billing info, and paid status. The exact shape mirrors what gets sent to the customer.

**Auth:** Session/API key. Ownership enforced through the invoice&#x27;s &#x60;invoices_custid&#x60;.

**Errors:**
- &#x60;Invalid Invoice&#x60; — &#x60;id&#x60; not found or owned by another account.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Pay it:** &#x60;initiatePayment&#x60; (&#x60;/billing/pay/{method}/{id}&#x60;).
- **Delete if pending/unpaid:** &#x60;deleteBillingInvoice&#x60;.
- **List all:** &#x60;getBillingInvoices&#x60;.
- **Cart-style summary across all unpaid:** &#x60;getBillingCart&#x60;.

     * @param id The invoice ID. Use IDs from &#x60;GET /billing/invoices&#x60; or from order responses. 
     */
    @Location("/billing/invoices/{id}") class getBillingInvoice(val id: kotlin.Int)

    /**
     * List every invoice on the account with summary totals and paid/unpaid status
     * Returns the customer&#x27;s complete invoice ledger — every charge, paid or unpaid, across every service module. Use to render a billing-history page, find an unpaid invoice id to pass to &#x60;initiatePayment&#x60;, or audit recent activity. Server-side strips the first synthetic header row from &#x60;get_view_invoices()&#x60; and reindexes the array. Read-only. The response includes a Link to &#x60;getBillingInvoice&#x60; for drilling into any row. Sibling ops: &#x60;getBillingInvoice&#x60;, &#x60;deleteBillingInvoice&#x60;, &#x60;initiatePayment&#x60;, &#x60;getBillingCart&#x60;, &#x60;getBillingPrePays&#x60;.

**Path/Query/Body:** None.

**Returns:** &#x60;BillingInvoiceList&#x60; — object containing:
- &#x60;rows&#x60; (array) — per-invoice summaries: &#x60;id&#x60;, &#x60;amount&#x60;, &#x60;paid&#x60;, &#x60;description&#x60;, &#x60;date&#x60;, &#x60;due_date&#x60;, &#x60;module&#x60;, &#x60;service&#x60; (service-id within the module), &#x60;currency&#x60;.
- Aggregate totals across the array (totals object: &#x60;total&#x60;, &#x60;paid_total&#x60;, &#x60;unpaid_total&#x60;).

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Drill into one invoice:** &#x60;getBillingInvoice&#x60;.
- **Pay an unpaid invoice:** &#x60;initiatePayment&#x60;.
- **Cancel an unpaid pending-service invoice:** &#x60;deleteBillingInvoice&#x60; (only works on pending services / unpaid prepays).
- **Per-service invoices instead:** &#x60;getVpsInvoices&#x60;, &#x60;getDomainInvoices&#x60;, &#x60;getMailInvoices&#x60;, &#x60;getBackupInvoices&#x60;, etc.

     */
    @Location("/billing/invoices") class getBillingInvoices()

    /**
     * List prepay deposits on the account — remaining balance and auto-use flags
     * Returns every prepay deposit on the account — funded or pending — with remaining balances, modules they&#x27;re scoped to, and the &#x60;automatic_use&#x60; flag controlling whether the balance auto-applies to future invoices. Use to gate &#x60;method&#x3D;prepay&#x60; at checkout (a prepay must be funded to count toward payment) or to render a prepays management page. Read-only. &#x60;csrf_token&#x60; is stripped from the helper output. Sibling ops: &#x60;addBillingPrepay&#x60; (top up), &#x60;deleteBillingPrepay&#x60; (remove), &#x60;initiatePayment&#x60; (&#x60;method&#x3D;prepay&#x60;), &#x60;getBillingCart&#x60;.

**Path/Query/Body:** None.

**Returns:** Object with per-prepay rows:
- &#x60;prepay_id&#x60; (integer).
- &#x60;prepay_module&#x60; (string) — service module the prepay is scoped to (or &#x60;default&#x60; for any).
- &#x60;prepay_amount&#x60; (decimal) — original deposit amount.
- &#x60;prepay_remaining&#x60; (decimal) — funds left.
- &#x60;prepay_automatic_use&#x60; (bool) — auto-apply to invoices.
- &#x60;prepay_paid&#x60; (bool) — whether the funding invoice has been paid (unpaid prepays are listed but unusable).

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Top up:** &#x60;addBillingPrepay&#x60; (returns an invoice id you then pay via &#x60;initiatePayment&#x60;).
- **Pay with prepay:** &#x60;initiatePayment&#x60; with &#x60;method&#x3D;prepay&#x60;.
- **Remove an unfunded prepay:** &#x60;deleteBillingPrepay&#x60;.
- **Cart view:** &#x60;getBillingCart&#x60; (includes prepay summary).

     */
    @Location("/billing/prepays") class getBillingPrePays()

    /**
     * Pay invoices through the chosen gateway — returns the next-step action
     * Universal payment trigger — the final step in every order/checkout flow. Use after any order endpoint (&#x60;addVps&#x60;, &#x60;addQs&#x60;, &#x60;addBackup&#x60;, &#x60;addMail&#x60;, &#x60;addBillingPrepay&#x60;) returns an invoice id, or after &#x60;getBillingInvoices&#x60; surfaces unpaid invoices. Resolves the chosen gateway class under &#x60;include/Api/Billing/Pay/&#x60;, populates it with the invoices, and returns one of three response shapes the client must act on: &#x60;redirect&#x60; (send the user to the gateway URL), &#x60;submit&#x60; (POST a form with the supplied items), or &#x60;single&#x60; (processed synchronously). Sibling ops: &#x60;getBillingCart&#x60;, &#x60;getBillingInvoices&#x60;, &#x60;getBillingInvoice&#x60;, &#x60;addBillingPrepay&#x60;, &#x60;updateBillingPaymentMethod&#x60;, &#x60;addBillingCreditCard&#x60;.

**Path params:**
- &#x60;method&#x60; (string enum, required) — one of &#x60;cc&#x60;, &#x60;paypal&#x60;, &#x60;prepay&#x60;, &#x60;payssion&#x60;, &#x60;payu&#x60;, &#x60;ccavenue&#x60;, &#x60;cashfree&#x60;, &#x60;coinbase&#x60;, &#x60;btcpay&#x60;. Rejected with 400 otherwise.
- &#x60;invoices&#x60; (string, required) — comma-separated identifiers. Each identifier may be:
  - a bare integer invoice id (e.g. &#x60;25296600&#x60;);
  - &#x60;INV&lt;module&gt;&lt;iid&gt;&#x60; (e.g. &#x60;INVvps25296600&#x60;) — strict invoice lookup;
  - &#x60;SERVICE&lt;module&gt;&lt;id&gt;&#x60; (e.g. &#x60;SERVICEvps12345&#x60;) — picks the most recent unpaid invoice for that service;
  - &#x60;RINV&lt;module&gt;&lt;rid&gt;&#x60; (e.g. &#x60;RINVvps78901&#x60;) — picks the most recent unpaid invoice for that repeat-invoice row;
  - &#x60;PREPAYID&lt;pid&gt;INV&lt;iid&gt;&#x60; — explicit prepay-funding invoice.

**Query params:**
- &#x60;redirectUrl&#x60; (string, optional) — override the gateway return-URL. Defaults to &#x60;https://my.interserver.net/pay/&#x60;.

**Returns** (one of three shapes — branch on &#x60;type&#x60;):
- **type&#x3D;&#x60;redirect&#x60;:** &#x60;{type: &quot;redirect&quot;, redirect: &quot;&lt;gateway-url&gt;&quot;, text: &quot;...&quot;}&#x60; — send the user to &#x60;redirect&#x60;.
- **type&#x3D;&#x60;submit&#x60;:** &#x60;{type: &quot;submit&quot;, action: &quot;&lt;url&gt;&quot;, method: &quot;POST&quot;, items: {field: value, ...}}&#x60; — render a form with those fields, POST to &#x60;action&#x60;.
- **type&#x3D;&#x60;single&#x60;:** &#x60;{type: &quot;single&quot;, text: &quot;...&quot;}&#x60; — payment already processed; surface &#x60;text&#x60; to the customer.

**Side effects:**
- Creates a &#x60;payment_requests&#x60; row tracking the attempt (via &#x60;addPaymentRequest&#x60;).
- On &#x60;single&#x60;-mode success (&#x60;cc&#x60;, &#x60;prepay&#x60;): marks the underlying &#x60;invoices.invoices_paid&#x3D;1&#x60;, triggers &#x60;queue_process_payment($iid)&#x60; → service activation.
- On &#x60;redirect&#x60;/&#x60;submit&#x60;-mode: nothing is paid yet; the gateway IPN/callback handler in &#x60;confirm()&#x60; (in each &#x60;Pay/*.php&#x60; subclass) runs &#x60;queue_process_payment&#x60; after the gateway notifies us of success.

**Auth:** Session/API key. Ownership of every referenced invoice is enforced through the &#x60;setInvoices()&#x60; lookup (filters by session &#x60;account_id&#x60;).

**Errors:**
- &#x60;400 Invalid payment method&#x60; — unrecognized &#x60;method&#x60;.
- &#x60;402&#x60; / gateway-specific text — card declined, balance insufficient, etc. Returned as &#x60;{error: &quot;&lt;text&gt;&quot;}&#x60;.
- &#x60;422 Invalid Invoice Tag&#x60; — identifier format not recognized.
- &#x60;401&#x60; — unauthenticated.
- Method-specific:
  - &#x60;cc&#x60;: card not verified (use &#x60;addBillingCreditCard&#x60; → &#x60;patchBillingCreditCardVerify&#x60; → &#x60;postBillingCreditCardVerify&#x60; first; verify via &#x60;updateBillingPaymentMethod&#x60;).
  - &#x60;prepay&#x60;: insufficient prepay balance (use &#x60;addBillingPrepay&#x60; to top up first).

**Related calls:**
- **Get an invoice id to pass:** &#x60;addVps&#x60; / &#x60;addQs&#x60; / &#x60;addBackup&#x60; / &#x60;addMail&#x60; / &#x60;addBillingPrepay&#x60; / &#x60;getBillingInvoices&#x60;.
- **Confirm invoice detail first:** &#x60;getBillingInvoice&#x60;.
- **Set up payment methods:** &#x60;addBillingCreditCard&#x60;, &#x60;patchBillingCreditCardVerify&#x60;, &#x60;postBillingCreditCardVerify&#x60;, &#x60;updateBillingPaymentMethod&#x60;.
- **After payment:** poll the originating service endpoint (e.g. &#x60;getVpsInfo&#x60; for VPS) until status flips to &#x60;active&#x60;.

**Example happy-path (VPS):**
&#x60;&#x60;&#x60;text
# 1) Order created — POST /vps/order returned {serviceid: 12345, real_iids: [&quot;25296600&quot;]}
# 2) Pay with stored credit card:
GET /apiv2/billing/pay/cc/25296600
# 3) Response:
{&quot;type&quot;: &quot;single&quot;, &quot;text&quot;: &quot;Payment processed.&quot;}
# 4) Poll service:
GET /apiv2/vps/12345  -&gt; {&quot;vps_status&quot;: &quot;active&quot;, ...}
&#x60;&#x60;&#x60;
**Example PayPal flow:**
&#x60;&#x60;&#x60;text
GET /apiv2/billing/pay/paypal/25296600
{&quot;type&quot;: &quot;redirect&quot;, &quot;redirect&quot;: &quot;https://www.paypal.com/...&quot;, &quot;text&quot;: &quot;...&quot;}
# Client redirects user; PayPal IPN later marks invoice paid and activates service.
&#x60;&#x60;&#x60;

     * @param method The payment method to use. Valid values: &#x60;cc&#x60; (credit card), &#x60;paypal&#x60;, &#x60;prepay&#x60;, &#x60;payssion&#x60;, &#x60;payu&#x60;, &#x60;ccavenue&#x60;, &#x60;cashfree&#x60;, &#x60;coinbase&#x60;, &#x60;btcpay&#x60;. 
     * @param invoices A comma-separated list of invoice IDs or invoice Tags to pay. These IDs are returned by order endpoints (e.g. &#x60;/backups/order&#x60;, &#x60;/vps/order&#x60;) and by &#x60;/billing/invoices&#x60;. Invoice tags accepted are SERVICE&lt;module&gt;&lt;id&gt;, RINV&lt;module&gt;&lt;repeat invoice id&gt;, INV&lt;module&gt;&lt;invoice id&gt;, PREPAY&lt;prepay id&gt;&lt;invoice id&gt;, and &lt;invoice id&gt;. 
     */
    @Location("/billing/pay/{method}/{invoices}") class initiatePayment(val method: kotlin.String, val invoices: kotlin.String)

    /**
     * Place two micro-charges on the card to start CVV verification (step 1 of 2)
     * Step 1 of the two-step card-verification flow. After &#x60;addBillingCreditCard&#x60; returns &#x60;action&#x3D;&#x27;verify&#x27;&#x60;, call this with the card&#x27;s CVV to place two small charges (cents-scale) on the card. The customer must then look up the exact amounts in their bank statement and submit them via &#x60;postBillingCreditCardVerify&#x60; to finalize verification. **After 3 failed CVV attempts** (&#x60;cc_fails_&lt;cc&gt;&#x60; counter on the account) the card is locked from further verification attempts — contact support. Sibling ops: &#x60;getBillingCreditCardVerify&#x60;, &#x60;postBillingCreditCardVerify&#x60;, &#x60;addBillingCreditCard&#x60;, &#x60;updateBillingPaymentMethod&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — credit card index from &#x60;parse_ccs&#x60;.

**Body fields:**
- &#x60;cc_ccv2&#x60; (string, required) — the 3- or 4-digit CVV/CVC code from the back (or front, for Amex) of the card.

**Returns:** &#x60;Your card is charged. Please enter the amounts charged up!&#x60; — surface to the UI to prompt for the two amounts.

**Side effects:**
- Places two test charges via &#x60;verify_cc_charge()&#x60; (gateway-side).
- On failure: increments &#x60;cc_fails_&lt;cc&gt;&#x60; on the account.

**Auth:** Session/API key. Card ownership enforced.

**Errors:**
- &#x60;Invalid Credit Card Passed&#x60; — &#x60;id&#x60; not in &#x60;parse_ccs&#x60;.
- &#x60;Reached the max number of tries to authenticate this card&#x60; — &#x60;cc_fails_&lt;cc&gt; &gt; 3&#x60;.
- &#x60;Missing or blank CVV&#x60; — &#x60;cc_ccv2&#x60; absent or empty.
- Gateway error text — charge attempt failed.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Prerequisite:** &#x60;addBillingCreditCard&#x60; (must have returned &#x60;action&#x3D;&#x27;verify&#x27;&#x60;).
- **Next (step 2):** &#x60;postBillingCreditCardVerify&#x60; (submit &#x60;cc_amount1&#x60; + &#x60;cc_amount2&#x60;).
- **After verification:** &#x60;updateBillingPaymentMethod&#x60; to make it the default.

     * @param body  
     * @param id The credit card ID to verify. Use the ID returned from &#x60;POST /billing/creditcards&#x60;. 
     */
    @Location("/billing/creditcards/{id}/verify") class patchBillingCreditCardVerify(val body: IdVerifyBody, val id: kotlin.Int)

    /**
     * Submit two micro-charge amounts to finalize card verification (step 2 of 2)
     * Step 2 of the two-step card-verification flow. Submits the two exact micro-charge amounts the customer saw on their statement (placed by &#x60;patchBillingCreditCardVerify&#x60;) so the gateway can confirm the customer controls the card. On success, the card is marked verified and can be selected via &#x60;updateBillingPaymentMethod&#x60; (&#x60;payment_method&#x3D;cc&lt;idx&gt;&#x60;) or used directly with &#x60;initiatePayment&#x60; (&#x60;method&#x3D;cc&#x60;). After 3 failed attempts (&#x60;cc_fails_&lt;cc&gt; &gt; 3&#x60;) the card is locked. Sibling ops: &#x60;getBillingCreditCardVerify&#x60;, &#x60;patchBillingCreditCardVerify&#x60;, &#x60;addBillingCreditCard&#x60;, &#x60;updateBillingPaymentMethod&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — credit card index from &#x60;parse_ccs&#x60;.

**Body fields (schema &#x60;BillingVerifyCcRequest&#x60;):**
- &#x60;cc_amount1&#x60; (number, required) — first micro-charge amount (in dollars, decimal).
- &#x60;cc_amount2&#x60; (number, required) — second micro-charge amount.

**Returns:** Verification success text (gateway-returned).

**Side effects:**
- Marks the card as verified when amounts match.
- On failure: increments &#x60;cc_fails_&lt;cc&gt;&#x60; on the account.

**Auth:** Session/API key. Card ownership enforced.

**Errors:**
- &#x60;Invalid Credit Card Passed&#x60; — &#x60;id&#x60; not in &#x60;parse_ccs&#x60;.
- &#x60;Reached the max number of tries to authenticate this card&#x60; — &#x60;cc_fails_&lt;cc&gt; &gt; 3&#x60;.
- &#x60;Missing charge amounts&#x60; — &#x60;cc_amount1&#x60; or &#x60;cc_amount2&#x60; absent.
- Verification failure text (status &#x60;failed&#x60; / &#x60;error&#x60; / &#x60;warning&#x60;) — amounts don&#x27;t match.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Prerequisite (step 1):** &#x60;patchBillingCreditCardVerify&#x60;.
- **Next:** &#x60;updateBillingPaymentMethod&#x60; to make the verified card default, or &#x60;initiatePayment&#x60; (&#x60;method&#x3D;cc&#x60;) to pay immediately.

     * @param body  
     * @param id The credit card ID to verify. Use the ID returned from &#x60;POST /billing/creditcards&#x60;. 
     */
    @Location("/billing/creditcards/{id}/verify") class postBillingCreditCardVerify(val body: BillingVerifyCcRequest, val id: kotlin.Int)

    /**
     * Configure the affiliate landing dock title, description, and referrer coupon
     * Customizes the branded landing-dock page shown to visitors arriving via the affiliate&#x27;s referral link, and reserves a unique referrer coupon code that&#x27;s automatically created across all affiliate-eligible modules. Title/description allow a limited HTML allowlist (&#x60;&lt;b&gt;&#x60;, &#x60;&lt;br&gt;&#x60;, &#x60;&lt;strong&gt;&#x60;, &#x60;&lt;hr&gt;&#x60;); everything else is entity-escaped. Coupon changes propagate to **all** affiliate modules atomically. Sibling ops: &#x60;updateAffiliatePaymentSetup&#x60;, &#x60;getAffiliateSignups&#x60;.

**Body fields (multipart or JSON, schema &#x60;AffiliateDockSetup&#x60;):**
- &#x60;affiliate_dock_title&#x60; (string, optional) — landing-page title. HTML allowlist: &#x60;&lt;b&gt;&#x60;, &#x60;&lt;br&gt;&#x60;, &#x60;&lt;strong&gt;&#x60;, &#x60;&lt;hr&gt;&#x60;.
- &#x60;affiliate_dock_description&#x60; (string, optional) — landing-page body. Same allowlist.
- &#x60;referrer_coupon&#x60; (string, optional) — coupon code reservation. Requirements:
  - ≥ 6 chars.
  - &#x60;^[a-zA-Z0-9]+$&#x60; (alphanumeric only).
  - Must NOT contain &#x60;facebook&#x60;, &#x60;test&#x60;, or &#x60;interserver&#x60; (substring check, case-insensitive).
  - Must NOT exactly match a reserved word.
  - Must NOT already exist as a coupon in any affiliate module (&#x60;webhosting&#x60;, &#x60;vps&#x60;, &#x60;quickservers&#x60;, &#x60;servers&#x60;, &#x60;backups&#x60;).

**Returns:** &#x60;{text: &quot;&lt;status message&gt;&quot;}&#x60;.

**Side effects:**
- First time setting &#x60;referrer_coupon&#x60;: inserts a &#x60;coupons&#x60; row in each affiliate module (&#x60;type&#x3D;3&#x60;, &#x60;amount&#x3D;0.01&#x60;, &#x60;onetime&#x3D;1&#x60;, &#x60;customer&#x3D;-1&#x60;, &#x60;usable&#x3D;1&#x60;, &#x60;applies&#x3D;-1&#x60;).
- Changing &#x60;referrer_coupon&#x60;: renames the coupon across all affiliate modules in one transaction.
- Updates the account&#x27;s &#x60;affiliate_dock_title&#x60;, &#x60;affiliate_dock_description&#x60;, &#x60;referrer_coupon&#x60; fields.

**Auth:** Session/API key.

**Errors:**
- &#x60;422 The name must be at least 6 characters long&#x60;.
- &#x60;422 Invalid Characters, use only standard english letters and numbers&#x60;.
- &#x60;422 That is a reserved word that cannot be used here&#x60;.
- &#x60;422 &lt;position&gt; is a reserved word that cannot be used here&#x60; (substring match against &#x60;facebook&#x60;/&#x60;test&#x60;/&#x60;interserver&#x60;).
- &#x60;409 That name is already taken&#x60; — coupon exists in another account&#x27;s module.
- &#x60;401&#x60; — unauthenticated.

     * @param affiliateDockTitle  
     * @param affiliateDockDescription  
     * @param referrerCoupon  
     */
    @Location("/affiliate/dock_setup") class updateAffiliateDockSetup(val affiliateDockTitle: kotlin.String, val affiliateDockDescription: kotlin.String, val referrerCoupon: kotlin.String)

    /**
     * Configure how affiliate commissions get paid out (PayPal or internal prepay)
     * Sets the disbursement preferences for affiliate commission payouts. Choose between PayPal payout (provide an email — validated) or internal prepay credit (auto-applied to future invoices via &#x60;method&#x3D;prepay&#x60;). Selecting &#x60;not set&#x60; suspends payouts. Sibling ops: &#x60;updateAffiliateDockSetup&#x60;, &#x60;getAffiliateRichReport&#x60;, &#x60;getAffiliateDownload&#x60;.

**Body fields (multipart or JSON, schema &#x60;AffiliatePaymentSetup&#x60;):**
- &#x60;affiliate_payment_method&#x60; (string, optional) — one of &#x60;paypal&#x60; / &#x60;prepay&#x60; / &#x60;not set&#x60;.
- &#x60;affiliate_paypal&#x60; (string, optional, required when method&#x3D;&#x60;paypal&#x60;) — email validated by &#x60;valid_email()&#x60;.

**Returns:** &#x60;{text: &quot;Ok&quot;}&#x60;.

**Side effects:**
- Updates the account&#x27;s &#x60;affiliate_payment_method&#x60; and/or &#x60;affiliate_paypal&#x60; fields.

**Auth:** Session/API key.

**Errors:**
- &#x60;422 Invalid Email&#x60; — &#x60;affiliate_paypal&#x60; fails &#x60;valid_email()&#x60;.
- &#x60;422 Invalid Payment Method&#x60; — value not in &#x60;{paypal, prepay, not set}&#x60;.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Read current commissions:** &#x60;getAffiliateRichReport&#x60;, &#x60;getAffiliateSalesGraph&#x60;.
- **Export commission report:** &#x60;getAffiliateDownload&#x60;.

     * @param affiliatePaypal  
     * @param affiliatePaymentMethod  
     */
    @Location("/affiliate/payment_setup") class updateAffiliatePaymentSetup(val affiliatePaypal: kotlin.String, val affiliatePaymentMethod: kotlin.String)

    /**
     * Refresh stored card expiration and re-trigger MaxMind fraud scoring
     * Updates the expiration date on a stored credit card and re-encrypts the card record. If the updated card matches the account&#x27;s primary &#x60;cc&#x60;, the account-level &#x60;cc_exp&#x60; is also refreshed. If no MaxMind risk score exists yet for the card, &#x60;update_maxmind()&#x60; is called to compute one. Use to fix an upcoming expiration before recurring charges fail. Sibling ops: &#x60;addBillingCreditCard&#x60;, &#x60;deleteBillingCreditCard&#x60;, &#x60;getBillingCreditCardVerify&#x60;, &#x60;postBillingCreditCardVerify&#x60;, &#x60;updateBillingPaymentMethod&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — credit card index (the key in the account&#x27;s &#x60;ccs&#x60; array, returned by &#x60;parse_ccs&#x60; and surfaced as &#x60;cc&lt;idx&gt;&#x60; in &#x60;updateBillingPaymentMethod&#x60;).

**Body fields:**
- &#x60;cc_exp&#x60; (string, required) — new expiration in &#x60;MM/YYYY&#x60; format.

**Returns:** &#x60;Card updated successfully.&#x60;.

**Side effects:**
- Updates the &#x60;ccs&#x60; array (re-serialized via &#x60;myadmin_stringify&#x60;) on the account.
- When the card &#x3D;&#x3D; primary &#x60;cc&#x60;, the account-level &#x60;cc_exp&#x60; is also written.
- Triggers &#x60;update_maxmind($custid, false, $cc_idx)&#x60; if no risk score exists.

**Auth:** Session/API key. Card ownership enforced via &#x60;parse_ccs&#x60;.

**Errors:**
- &#x60;Invalid Credit Card Passed&#x60; — &#x60;id&#x60; not in &#x60;parse_ccs&#x60;.
- &#x60;Please enter valid card expiry date&#x60; — &#x60;cc_exp&#x60; body field missing.
- &#x60;Invalid expiration date. It must be in the form of MM/YYYY&#x60; — wrong format.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Verify a freshly added card:** &#x60;patchBillingCreditCardVerify&#x60; → &#x60;postBillingCreditCardVerify&#x60;.
- **Remove the card:** &#x60;deleteBillingCreditCard&#x60;.
- **Make it default:** &#x60;updateBillingPaymentMethod&#x60; with &#x60;payment_method&#x3D;cc&lt;idx&gt;&#x60;.

     * @param id The credit card ID. Use IDs from &#x60;GET /billing/creditcards&#x60; or the response from &#x60;POST /billing/creditcards&#x60;. 
     */
    @Location("/billing/creditcards/{id}") class updateBillingCreditCard(val id: kotlin.Int)

    /**
     * Set the account&#x27;s default payment method for recurring/auto charges
     * Sets the account&#x27;s preferred payment method for recurring/automatic charges and (when applicable) promotes a specific stored credit card to be the primary &#x60;cc&#x60; on the account. Use after &#x60;addBillingCreditCard&#x60; + verification to select the new card, or when switching between PayPal and credit-card billing. First-time payment-method assignment triggers &#x60;update_maxmind()&#x60; and &#x60;update_fraudrecord()&#x60; risk-score generation. Sibling ops: &#x60;addBillingCreditCard&#x60;, &#x60;postBillingCreditCardVerify&#x60;, &#x60;deleteBillingCreditCard&#x60;, &#x60;initiatePayment&#x60;.

**Body fields (JSON or multipart, schema &#x60;BillingPaymentMethodRequest&#x60;):**
- &#x60;payment_method&#x60; (string, required) — one of:
  - &#x60;cc&#x60; — use the existing primary credit card.
  - &#x60;cc&lt;idx&gt;&#x60; (e.g. &#x60;cc2&#x60;) — promote the card at index &#x60;idx&#x60; (from &#x60;parse_ccs&#x60;) to primary. Must be verified.
  - &#x60;paypal&#x60; — switch to PayPal.
- &#x60;cc_auto&#x60; (string &#x60;0&#x60;/&#x60;1&#x60;, optional) — auto-charge flag. Implicitly set to &#x60;1&#x60; when selecting &#x60;cc&#x60;/&#x60;cc&lt;idx&gt;&#x60;, &#x60;0&#x60; for &#x60;paypal&#x60;.

**Returns:** &#x60;{text: &quot;Payment Method Updated&quot;}&#x60;.

**Side effects:**
- When &#x60;payment_method&#x3D;cc&lt;idx&gt;&#x60;: copies the indexed card&#x27;s encrypted &#x60;cc&#x60; and &#x60;cc_exp&#x60; onto the account&#x27;s primary fields.
- First time a payment method is set: runs MaxMind risk score, then FraudRecord score.

**Auth:** Session/API key.

**Errors:**
- &#x60;Invalid Credit Card Specified&#x60; — &#x60;cc&lt;idx&gt;&#x60; is malformed or &#x60;idx&#x60; not found in &#x60;parse_ccs&#x60;.
- &#x60;This CC has not been verified.&#x60; — the chosen card hasn&#x27;t completed &#x60;postBillingCreditCardVerify&#x60;.
- &#x60;Invalid Payment Method Specified&#x60; — value not in &#x60;{cc, paypal, cc&lt;idx&gt;}&#x60;.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Prerequisite for &#x60;cc&lt;idx&gt;&#x60;:** &#x60;addBillingCreditCard&#x60; → &#x60;patchBillingCreditCardVerify&#x60; → &#x60;postBillingCreditCardVerify&#x60;.
- **Now pay an invoice:** &#x60;initiatePayment&#x60; (&#x60;method&#x3D;cc&#x60; will use the default; &#x60;method&#x3D;paypal&#x60; if you switched).
- **Audit current methods:** &#x60;getAccountInfo&#x60; (account profile shows cards as masked).

     * @param body  
     */
    @Location("/billing/payment_method") class updateBillingPaymentMethod(val body: BillingPaymentMethodRequest)

    /**
     * Create a new authoritative DNS zone seeded with apex A + NS + SOA records
     * Creates a new authoritative zone in PowerDNS for this account and seeds it with a default record set: apex &#x60;A&#x60; record pointing at &#x60;ip&#x60;, &#x60;NS&#x60; records for InterServer&#x27;s &#x60;cdns1.interserver.net&#x60; / &#x60;cdns2.interserver.net&#x60; anycast resolvers, and an &#x60;SOA&#x60;. Served immediately by InterServer&#x27;s nameservers via supermaster propagation. **Important:** this only creates the hosted zone — the customer must still point their registrar&#x27;s nameservers at &#x60;cdns1.interserver.net&#x60; / &#x60;cdns2.interserver.net&#x60; for queries to resolve through this zone (use &#x60;updateDomainNameservers&#x60; if the domain is registered through InterServer). Sibling ops: &#x60;getDnsList&#x60;, &#x60;getDnsDomain&#x60;, &#x60;addDnsRecord&#x60;, &#x60;updateDomainNameservers&#x60;.

**Body fields (form or JSON, schema &#x60;DnsNewDomain&#x60;):**
- &#x60;domain&#x60; (string, required) — FQDN of the zone (e.g. &#x60;example.com&#x60;).
- &#x60;ip&#x60; (string, required) — IPv4 address for the apex A record.

**Returns:** &#x60;SuccessTextResponse&#x60; — status text confirming the zone was created.

**Side effects:**
- Inserts &#x60;domains&#x60; row scoped to session &#x60;account_id&#x60;.
- Inserts default &#x60;records&#x60; rows: apex &#x60;A&#x60;, two &#x60;NS&#x60;, one &#x60;SOA&#x60;.

**Auth:** Session/API key.

**Errors:**
- &#x60;400&#x60; — missing &#x60;domain&#x60; or &#x60;ip&#x60;.
- &#x60;401&#x60; — unauthenticated.
- &#x60;409&#x60; — zone already exists.

**Related calls:**
- **Find new zone id:** &#x60;getDnsList&#x60;.
- **Add more records:** &#x60;addDnsRecord&#x60;.
- **Update registrar nameservers:** &#x60;updateDomainNameservers&#x60; (Domains tag).

**Example request:**
&#x60;&#x60;&#x60;json
{ &quot;domain&quot;: &quot;mydomain.com&quot;, &quot;ip&quot;: &quot;203.0.113.42&quot; }
&#x60;&#x60;&#x60;

     * @param domain  
     * @param ip  
     */
    @Location("/dns") class addDnsDomain(val domain: kotlin.String, val ip: kotlin.String)

    /**
     * Add a DNS record (A, AAAA, MX, TXT, CNAME, NS, SRV, CAA, ...) to a zone
     * Adds a single record to the zone identified by path &#x60;id&#x60;. Type is validated against the global &#x60;$rtypes&#x60; allowlist (A, AAAA, CNAME, MX, TXT, NS, SRV, CAA, PTR, SPF, TLSA, etc.); content is validated against the record type by &#x60;validate_input()&#x60;. The record goes live on PowerDNS immediately; resolvers honor the existing TTL on any cached answer. Sibling ops: &#x60;getDnsDomain&#x60; (find record id afterward), &#x60;updateDnsRecord&#x60;, &#x60;deleteDnsRecord&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — zone ID from &#x60;getDnsList.id&#x60;.

**Body fields (form or JSON, schema &#x60;DnsNewRecord&#x60;):**
- &#x60;name&#x60; (string, required) — FQDN of the record (must be at or below the zone apex).
- &#x60;type&#x60; (string, required) — &#x60;A&#x60; / &#x60;AAAA&#x60; / &#x60;CNAME&#x60; / &#x60;MX&#x60; / &#x60;TXT&#x60; / &#x60;NS&#x60; / &#x60;SRV&#x60; / &#x60;CAA&#x60; / &#x60;PTR&#x60; / &#x60;SPF&#x60; / &#x60;TLSA&#x60; (must be in &#x60;$rtypes&#x60;).
- &#x60;content&#x60; (string, required) — value matching &#x60;type&#x60; syntax (IPv4 for A, IPv6 for AAAA, hostname for CNAME/NS/MX, free text for TXT).
- &#x60;ttl&#x60; (integer, optional, default 86400) — seconds.
- &#x60;prio&#x60; (integer, optional, default 0) — priority (MX/SRV only).

**Returns:** &#x60;{success: true, text: &quot;Record added&quot;}&#x60;.

**Auth:** Session/API key. Zone ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;Type must be one of: ...&#x60; — &#x60;type&#x60; not in allowlist.
- &#x60;invalid or missing domain or record id&#x60; — zone not found / not owned.
- Content-format validation failure (&#x60;text&#x60; describes the issue).

**Related calls:**
- **Find new record id:** &#x60;getDnsDomain&#x60;.
- **Edit later:** &#x60;updateDnsRecord&#x60;.
- **Delete:** &#x60;deleteDnsRecord&#x60;.

     * @param name  
     * @param type  
     * @param content  
     * @param ttl  
     * @param prio  
     * @param id The DNS Domain ID. 
     */
    @Location("/dns/{id}") class addDnsRecord(val name: kotlin.String, val type: DnsRecordType, val content: kotlin.String, val ttl: kotlin.Int, val prio: kotlin.Int, val id: kotlin.String)

    /**
     * Permanently delete a DNS zone and every record it contains
     * Removes the zone identified by path &#x60;id&#x60; AND every record it contains from PowerDNS in a single transaction. **Permanent — no soft-delete, no undo.** Any service relying on these records (web, mail, SPF/DKIM, third-party domain verifications, ACME challenges) will start failing as resolver caches expire (per-record TTL, default 86400s). **Note:** this only deletes the hosted zone on InterServer&#x27;s nameservers — it does not affect registrar delegation. If &#x60;cdns1&#x60;/&#x60;cdns2&#x60; are still delegated at the registrar, queries will return NXDOMAIN/SERVFAIL until delegation is changed or the zone is recreated. Sibling ops: &#x60;deleteDnsRecord&#x60; (delete one record only), &#x60;addDnsDomain&#x60; (recreate), &#x60;updateDomainNameservers&#x60; (change registrar delegation).

**Path param:**
- &#x60;id&#x60; (string, required) — zone ID from &#x60;getDnsList&#x60;.

**Returns:** &#x60;{success: true, text: &quot;Domain deleted&quot;}&#x60;.

**Side effects:**
- Deletes every &#x60;records&#x60; row with &#x60;domain_id&#x3D;{id}&#x60;.
- Deletes the &#x60;domains&#x60; row.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;invalid or missing domain or record id&#x60; — zone not found / not owned.

**Related calls:**
- **Delete one record only:** &#x60;deleteDnsRecord&#x60;.
- **Recreate the zone:** &#x60;addDnsDomain&#x60;.
- **Update registrar delegation:** &#x60;updateDomainNameservers&#x60; (Domains tag).

     * @param id The DNS domain ID to delete. Use the &#x60;id&#x60; from &#x60;GET /dns&#x60; to identify the domain. 
     */
    @Location("/dns/{id}") class deleteDnsDomain(val id: kotlin.String)

    /**
     * Permanently delete one DNS record from a zone — zone itself is preserved
     * Removes the record identified by &#x60;recordId&#x60; from zone &#x60;domainId&#x60;. The zone itself remains intact — only the one record is dropped. **Permanent** — applied to PowerDNS immediately, but resolvers continue to answer with cached values until the previous TTL expires. Use to surgically remove an A/AAAA/MX/TXT etc. record; to drop the entire zone and all its records, use &#x60;deleteDnsDomain&#x60;. Sibling ops: &#x60;getDnsDomain&#x60; (verify after deletion), &#x60;deleteDnsDomain&#x60;, &#x60;updateDnsRecord&#x60;.

**Path params:**
- &#x60;domainId&#x60; (integer, required) — zone ID from &#x60;getDnsList.id&#x60;.
- &#x60;recordId&#x60; (integer, required) — record ID from &#x60;getDnsDomain.id&#x60;.

**Returns:** &#x60;{success: true, text: &quot;domain record deleted&quot;}&#x60;.

**Auth:** Session/API key. Zone ownership enforced via &#x60;get_dns_domain($domainId)&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;invalid or missing domain or record id&#x60; — zone/record not found or not owned.
- &#x60;error removing domain record&#x60; — underlying DB delete failed.

**Related calls:**
- **Verify after delete:** &#x60;getDnsDomain&#x60;.
- **Recreate:** &#x60;addDnsRecord&#x60;.
- **Delete entire zone instead:** &#x60;deleteDnsDomain&#x60;.

     * @param domainId The DNS domain ID. Use the &#x60;id&#x60; from &#x60;GET /dns&#x60; to identify the domain. 
     * @param recordId The DNS record ID within the domain. Use the record &#x60;id&#x60; from &#x60;GET /dns/{id}&#x60; to identify the record. 
     */
    @Location("/dns/{domainId}/{recordId}") class deleteDnsRecord(val domainId: kotlin.Int, val recordId: kotlin.Int)

    /**
     * List every DNS record in one zone with the IDs needed to edit or delete them
     * Returns the full record set for the specified PowerDNS zone (NS, A, AAAA, CNAME, MX, TXT, SRV, CAA, SOA, etc.) in a single response. Ownership is enforced via &#x60;get_dns_domain($id)&#x60; against the session account — cross-account access returns an error rather than 200. Use a returned record &#x60;id&#x60; together with the zone &#x60;id&#x60; to call &#x60;updateDnsRecord&#x60; or &#x60;deleteDnsRecord&#x60;. Sibling ops: &#x60;getDnsList&#x60;, &#x60;addDnsRecord&#x60;, &#x60;updateDnsRecord&#x60;, &#x60;deleteDnsRecord&#x60;, &#x60;deleteDnsDomain&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — zone ID from &#x60;getDnsList.id&#x60;.

**Returns:** Array of &#x60;DnsRecord&#x60;:
- &#x60;id&#x60; (string) — record ID; pass to &#x60;updateDnsRecord&#x60; / &#x60;deleteDnsRecord&#x60;.
- &#x60;domain_id&#x60; (string) — parent zone ID.
- &#x60;name&#x60; (string) — FQDN of the record (apex or subdomain).
- &#x60;type&#x60; (string) — &#x60;A&#x60; / &#x60;AAAA&#x60; / &#x60;CNAME&#x60; / &#x60;MX&#x60; / &#x60;TXT&#x60; / &#x60;NS&#x60; / &#x60;SRV&#x60; / &#x60;CAA&#x60; / &#x60;SOA&#x60; / &#x60;PTR&#x60; / &#x60;SPF&#x60; / &#x60;TLSA&#x60;.
- &#x60;content&#x60; (string) — record value (IP for A/AAAA, hostname for CNAME/NS/MX, free text for TXT, etc.).
- &#x60;ttl&#x60; (string) — seconds; default 86400.
- &#x60;prio&#x60; (string) — priority for MX/SRV (&#x60;0&#x60; for non-priority records).
- &#x60;disabled&#x60; (string &#x60;0&#x60;/&#x60;1&#x60;), &#x60;ordername&#x60; (string), &#x60;auth&#x60; (string &#x60;0&#x60;/&#x60;1&#x60;).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;invalid or missing domain or record id&#x60; — zone not found or owned by another account.

**Related calls:**
- **Add a record:** &#x60;addDnsRecord&#x60; (POST same path).
- **Update a record:** &#x60;updateDnsRecord&#x60; (&#x60;POST /dns/{domainId}/{recordId}&#x60;).
- **Delete a record:** &#x60;deleteDnsRecord&#x60;.
- **Delete the whole zone:** &#x60;deleteDnsDomain&#x60; (DELETE same path).

     * @param id The DNS domain ID. Use the &#x60;id&#x60; from &#x60;GET /dns&#x60; to identify the domain. 
     */
    @Location("/dns/{id}") class getDnsDomain(val id: kotlin.Int)

    /**
     * List DNS zones hosted on the account with each zone&#x27;s apex A-record IP
     * Returns every PowerDNS-hosted authoritative zone owned by the authenticated account, one row per zone, with the IP from the apex &#x60;A&#x60; record. Canonical entry point for discovering zone IDs before reading or editing records. The list is filtered server-side by session &#x60;account_id&#x60; — cross-account zones are never returned. Empty array means the account holds no zones (not an error). **Note:** this is the hosted DNS zone list, not registrar delegation — use the Domains tag&#x27;s &#x60;updateDomainNameservers&#x60; to point a registered domain at &#x60;cdns1.interserver.net&#x60;/&#x60;cdns2.interserver.net&#x60;. Sibling ops: &#x60;getDnsDomain&#x60;, &#x60;addDnsDomain&#x60;, &#x60;addDnsRecord&#x60;, &#x60;deleteDnsDomain&#x60;.

**Path/Query/Body:** None.

**Returns:** Array of &#x60;DnsListItem&#x60;:
- &#x60;id&#x60; (integer) — zone ID; pass to &#x60;getDnsDomain&#x60; / &#x60;addDnsRecord&#x60; / &#x60;deleteDnsDomain&#x60;.
- &#x60;name&#x60; (string) — zone FQDN (e.g. &#x60;example.com&#x60;).
- &#x60;content&#x60; (string) — IP from the apex &#x60;A&#x60; record matching the zone name (empty when no apex A exists yet).

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Per-zone record list:** &#x60;getDnsDomain&#x60;.
- **Add a zone:** &#x60;addDnsDomain&#x60;.
- **Add a record to an existing zone:** &#x60;addDnsRecord&#x60;.
- **Registrar delegation:** &#x60;getDomainNameservers&#x60; / &#x60;updateDomainNameservers&#x60; (Domains tag).

     */
    @Location("/dns") class getDnsList()

    /**
     * Replace values on an existing DNS record (name, type, content, ttl, priority)
     * Replaces the record identified by &#x60;recordId&#x60; within zone &#x60;domainId&#x60; with new values. **TTL caveat:** the change is written to PowerDNS immediately, but already-cached resolver answers persist until the previous record&#x27;s TTL expires — plan TTL down ahead of a clean cutover. Type is validated against the global &#x60;$rtypes&#x60; allowlist; content is validated against the record type. Sibling ops: &#x60;getDnsDomain&#x60; (read), &#x60;addDnsRecord&#x60; (create), &#x60;deleteDnsRecord&#x60;.

**Path params:**
- &#x60;domainId&#x60; (integer, required) — zone ID from &#x60;getDnsList.id&#x60;.
- &#x60;recordId&#x60; (integer, required) — record ID from &#x60;getDnsDomain.id&#x60;.

**Body fields (form or JSON, schema &#x60;DnsUpdateRecord&#x60;):**
- &#x60;name&#x60; (string, required) — FQDN at/below zone apex.
- &#x60;type&#x60; (string, required) — one of the allowed PowerDNS types.
- &#x60;content&#x60; (string, required) — value matching &#x60;type&#x60;.
- &#x60;ttl&#x60; (integer, required) — seconds.
- &#x60;prio&#x60; (integer, required) — MX/SRV priority (&#x60;0&#x60; otherwise).

**Returns:** &#x60;{success: true, text: &quot;domain record updated&quot;}&#x60;.

**Auth:** Session/API key. Zone ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;Type must be one of: ...&#x60; — &#x60;type&#x60; not in &#x60;$rtypes&#x60;.
- &#x60;invalid or missing domain or record id&#x60; — zone/record not found / not owned.
- Content-format validation text — &#x60;validate_input()&#x60; failure.

**Related calls:**
- **Read first:** &#x60;getDnsDomain&#x60;.
- **Delete:** &#x60;deleteDnsRecord&#x60;.
- **Create new:** &#x60;addDnsRecord&#x60;.

     * @param name  
     * @param type  
     * @param content  
     * @param ttl  
     * @param prio  
     * @param disabled  
     * @param ordername  
     * @param auth  
     * @param domainId The DNS domain ID. Use the &#x60;id&#x60; from &#x60;GET /dns&#x60; to identify the domain. 
     * @param recordId The DNS record ID within the domain. Use the record &#x60;id&#x60; from &#x60;GET /dns/{id}&#x60; to identify the record. 
     */
    @Location("/dns/{domainId}/{recordId}") class updateDnsRecord(val name: kotlin.String, val type: DnsRecordType, val content: kotlin.String, val ttl: kotlin.String, val prio: kotlin.String, val disabled: kotlin.String, val ordername: kotlin.String, val auth: kotlin.String, val domainId: kotlin.Int, val recordId: kotlin.Int)

    /**
     * Place a new domain registration or transfer order, generate billing invoice
     * Places a new domain registration or transfer order. Resolves the TLD to a &#x60;services_id&#x60;, runs &#x60;validate_buy_domain()&#x60; (hostname, TLD service, fields, coupon, whois-privacy add-on), then calls &#x60;place_buy_domain()&#x60; to create the &#x60;Repeat_Invoice&#x60; recurring billing row, generate the initial &#x60;invoices&#x60; row, and (when &#x60;whois_privacy&#x3D;enable&#x60;) an additional add-on &#x60;Repeat_Invoice&#x60; for privacy. **Real money** — call &#x60;putDomains&#x60; then &#x60;patchDomains&#x60; first to preview and validate. Sibling ops: &#x60;getDomainLookup&#x60;, &#x60;getNewDomain&#x60;, &#x60;putDomains&#x60;, &#x60;patchDomains&#x60;, &#x60;initiatePayment&#x60;.

**Body fields (JSON or form):**
- &#x60;hostname&#x60; (string, required) — FQDN to register or transfer.
- &#x60;type&#x60; (string, optional, default &#x60;register&#x60;) — &#x60;register&#x60; or &#x60;transfer&#x60;.
- &#x60;whois_privacy&#x60; (string, optional) — &#x60;enable&#x60; to add the privacy add-on (separate recurring invoice).
- &#x60;coupon&#x60; (string, optional) — coupon code.
- All per-TLD contact/registration fields from &#x60;putDomains.domainFields&#x60; (registrant contact details, TLD-specific fields like nexus codes, EPP &#x60;auth_info&#x60; for transfers, etc.).

**Returns** (schema &#x60;ServiceOrderPostResponse&#x60;): &#x60;{total_cost, iid, iids, real_iids, serviceid (new domain_id), invoice_description, cj_params, payUrl}&#x60; — pass &#x60;real_iids&#x60; to &#x60;initiatePayment&#x60; to fund the order.

**Side effects:**
- Inserts &#x60;domains&#x60; service row in &#x60;pending&#x60; status.
- Inserts &#x60;repeat_invoices&#x60; row for recurring renewal.
- Inserts &#x60;invoices&#x60; row for the first-period charge.
- When &#x60;whois_privacy&#x3D;enable&#x60;: inserts a separate add-on &#x60;repeat_invoices&#x60; row + its initial invoice.
- For transfers: stores &#x60;auth_info&#x60; and marks &#x60;service_extra&#x60; as &#x60;transfer&#x60;.

**Auth:** Session/API key.

**Errors:**
- &#x60;400 Missing hostname parameter&#x60;.
- &#x60;400 Unable to determine service type for this domain TLD.&#x60;.
- &#x60;401&#x60; — unauthenticated.
- &#x60;422&#x60; — validation failure (e.g. coupon invalid, required TLD field missing, hostname not registerable). Response body is the combined &#x60;errors&#x60; array from &#x60;validate_buy_domain()&#x60;.

**Related calls:**
- **Prerequisites:** &#x60;getDomainLookup&#x60; → &#x60;getNewDomain&#x60; → &#x60;putDomains&#x60; → &#x60;patchDomains&#x60;.
- **Pay:** &#x60;initiatePayment&#x60; with &#x60;real_iids&#x60;.
- **Verify activation:** &#x60;getDomainInfo&#x60; (poll for &#x60;domain_status&#x3D;&#x27;active&#x27;&#x60;).
- **Track in-progress transfer:** &#x60;getDomainTransfer&#x60;.
- **For pending transfers needing EPP/auth_info:** &#x60;updateDomainContact&#x60; (set &#x60;auth_info&#x60;).

**Example happy path (register):**
&#x60;&#x60;&#x60;text
GET /apiv2/domains/lookup/example.com           -&gt; available, pricing, fields
PUT /apiv2/domains/order { hostname, type }     -&gt; domainFields
PATCH /apiv2/domains/order { hostname, ...fields } -&gt; &quot;success&quot;
POST /apiv2/domains/order { hostname, type, ...fields } -&gt; { serviceid, real_iids }
GET /apiv2/billing/pay/cc/{real_iids[0]}        -&gt; pay
GET /apiv2/domains/{serviceid}                  -&gt; poll until domain_status&#x3D;&#x3D;&quot;active&quot;
&#x60;&#x60;&#x60;

     * @param body  
     */
    @Location("/domains/order") class addDomain(val body: kotlin.collections.Map<kotlin.String, kotlin.Any>)

    /**
     * Register DNSSEC DS records on the domain at OpenSRS
     * Registers one or more DNSSEC DS records at the registrar. Body uses parallel arrays indexed per record. **Propagation caveat:** DNSSEC publication is asynchronous at the registry — a 200 here does not guarantee the records have propagated; re-call &#x60;getDomainDnssec&#x60; to verify. **Sets, not adds:** this replaces the full DS record set in one transaction; to remove all DS records use &#x60;deleteDomainDnssec&#x60;. Sibling ops: &#x60;getDomainDnssec&#x60;, &#x60;deleteDomainDnssec&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body fields (JSON or multipart, parallel arrays — &#x60;algorithm[0]&#x60; pairs with &#x60;key_tag[0]&#x60;, etc., schema &#x60;DomainDnssecRequest&#x60;):**
- &#x60;algorithm[]&#x60; (integer) — DNSKEY algorithm (e.g. 8 &#x3D; RSASHA256, 13 &#x3D; ECDSAP256SHA256).
- &#x60;key_tag[]&#x60; (integer) — must be &lt; 65536.
- &#x60;digest_type[]&#x60; (integer) — &#x60;1&#x60; (SHA-1, 40 hex chars), &#x60;2&#x60; (SHA-256, 64), &#x60;3&#x60; (GOST, 64), &#x60;4&#x60; (SHA-384, 96).
- &#x60;digest[]&#x60; (string) — hex digest; length must match &#x60;digest_type[i]&#x60;.

**Returns:** &#x60;SuccessTextResponse&#x60; on registrar confirmation.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60; or registrar refused.
- &#x60;422&#x60; — &#x60;key_tag &gt;&#x3D; 65536&#x60; or digest length mismatch.

**Related calls:**
- **Verify propagation:** &#x60;getDomainDnssec&#x60;.
- **Clear all records:** &#x60;deleteDomainDnssec&#x60;.

     * @param body  
     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/dnssec") class addDomainDnssec(val body: DomainDnssecRequest, val id: kotlin.Int)

    /**
     * Register a new nameserver host with glue IP at the registry (registered nameserver)
     * Adds a registered nameserver (host + glue IP) for the domain at the registrar via &#x60;opensrs_create_nameserver&#x60;. Use when running your own authoritative nameservers under the domain itself (e.g. &#x60;ns1.example.com&#x60;, &#x60;ns2.example.com&#x60;). **Glue records, not delegation:** this registers the host&#x27;s IP at the registry; the domain&#x27;s delegation must separately point at these names via &#x60;updateDomainNameservers&#x60;. Sibling ops: &#x60;getDomainNameservers&#x60;, &#x60;updateDomainNameservers&#x60;, &#x60;deleteDomainNameserver&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body fields (schema &#x60;DomainNameserverPostRequest&#x60;):**
- &#x60;name&#x60; (string, required) — FQDN of the nameserver (e.g. &#x60;ns1.example.com&#x60;). Validated by &#x60;valid_hostname()&#x60;.
- &#x60;ipAddress&#x60; (string, required) — IPv4 address. Validated by &#x60;validIp()&#x60;.

**Returns:** &#x60;SuccessTextResponse&#x60; on success.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.
- &#x60;422&#x60; — invalid hostname or IP, or registrar refused.

**Related calls:**
- **Verify glue record:** &#x60;getDomainNameservers&#x60;.
- **Use this nameserver in delegation:** &#x60;updateDomainNameservers&#x60;.

     * @param body  
     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/nameservers") class addDomainNameserver(val body: DomainNameserverPostRequest, val id: kotlin.Int)

    /**
     * Cancel a domain order in the billing system to stop auto-renewals
     * Stops billing and auto-renewal for a domain in the customer account by setting the service to &#x60;canceled&#x60; via the shared &#x60;Billing\CancelService::go($id)&#x60; flow with &#x60;module&#x3D;&#x27;domains&#x27;&#x60;. **Important:** this only stops billing on InterServer&#x27;s side — the domain registration at the registrar (OpenSRS) typically remains active until its current expiration date. To release the domain back to the public pool, let it expire OR submit a release request via support ticket. Sibling ops: &#x60;getDomainInfo&#x60; (verify status), &#x60;getDomainsList&#x60;, &#x60;postDomainRenewal&#x60; (re-activate before expiry).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns:** &#x60;DomainsCancelResponse&#x60; — confirmation envelope.

**Side effects:**
- Sets &#x60;domain_status&#x3D;&#x27;canceled&#x27;&#x60;.
- Marks the &#x60;repeat_invoices&#x60; row non-renewing — no future renewal invoices generated.
- Does **not** call the registrar — the registration remains active at OpenSRS until natural expiry.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — already canceled.

**Related calls:**
- **Re-activate before expiry:** &#x60;postDomainRenewal&#x60;.
- **Verify status:** &#x60;getDomainInfo&#x60;.
- **Sibling cancels on other modules:** &#x60;VPSCancel&#x60;, &#x60;mailCancel&#x60;, &#x60;webhostingCancel&#x60;, etc. (same &#x60;CancelService&#x60; handler).

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}") class cancelDomain(val id: kotlin.Int)

    /**
     * Clear all DNSSEC DS records on the domain (disable DNSSEC at the registrar)
     * Disables DNSSEC at the registrar by removing the entire DS record set in one call. **Propagation caveat:** DNSSEC removal can fail at the registry even after a 200 response — propagation is asynchronous; re-check with &#x60;getDomainDnssec&#x60; to confirm. To remove records selectively, replace the set via &#x60;addDomainDnssec&#x60; instead. Sibling ops: &#x60;getDomainDnssec&#x60;, &#x60;addDomainDnssec&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body:** None — removes the full DS record set.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.
- Registrar error surfaced as 4xx.

**Related calls:**
- **Verify propagation:** &#x60;getDomainDnssec&#x60;.
- **Replace records selectively:** &#x60;addDomainDnssec&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/dnssec") class deleteDomainDnssec(val id: kotlin.Int)

    /**
     * Remove one registered nameserver glue record from the domain
     * Removes a single registered nameserver entry from the domain at the registrar. Handler first calls OpenSRS &#x60;nsGet&#x60; to resolve the entry by index, then &#x60;nsDelete&#x60;. Per-entry — to replace the full delegation set use &#x60;updateDomainNameservers&#x60; instead. Sibling ops: &#x60;getDomainNameservers&#x60;, &#x60;addDomainNameserver&#x60;, &#x60;updateDomainNameservers&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Query params:**
- &#x60;index&#x60; (integer, required) — zero-based index from &#x60;getDomainNameservers&#x60; array — or alternatively pass &#x60;name&#x60; + &#x60;ip&#x60; to target by value.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.
- &#x60;422&#x60; — &#x60;index&#x60; out of range or &#x60;name&#x60;/&#x60;ip&#x60; not provided.
- Registrar errors surfaced as 4xx.

**Related calls:**
- **List candidates:** &#x60;getDomainNameservers&#x60;.
- **Replace delegation entirely:** &#x60;updateDomainNameservers&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     * @param index The index of the registered nameserver from the registered nameservers list to delete.   
     */
    @Location("/domains/{id}/nameservers") class deleteDomainNameserver(val id: kotlin.Int, val index: kotlin.Int)

    /**
     * Read the current registrant/admin/tech/billing contact field set for a domain
     * Returns the current contact field set (registrant/admin/tech/billing) with current values for the domain — schema and values mirror what was set at registration. For pending transfer services, the response also includes a &#x60;transfer&#x60; selector and the EPP &#x60;auth_info&#x60; code so the client can resubmit. Read-only. Sibling ops: &#x60;updateDomainContact&#x60; (push changes to OpenSRS), &#x60;getDomainInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns** (schema &#x60;DomainContactDetails&#x60;):
- &#x60;firstname&#x60;, &#x60;lastname&#x60;, &#x60;email&#x60;.
- &#x60;address&#x60;, &#x60;address2&#x60;, &#x60;address3&#x60;, &#x60;city&#x60;, &#x60;state&#x60;, &#x60;zip&#x60;, &#x60;country&#x60;.
- &#x60;phone&#x60;, &#x60;fax&#x60; (E.164 format expected).
- &#x60;company&#x60; (optional).
- &#x60;auth_info&#x60; (string) — EPP/transfer code (present on transfer services).
- &#x60;transfer&#x60; (string &#x60;yes&#x60;/&#x60;no&#x60;) — selector for pending transfer services.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Update:** &#x60;updateDomainContact&#x60;.
- **Transfer status:** &#x60;getDomainTransfer&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/contact") class getDomainContact(val id: kotlin.Int)

    /**
     * Read the DNSSEC DS record set currently registered with the registrar
     * Returns the DNSSEC DS record set currently registered for the domain at OpenSRS. Empty array means DNSSEC is not configured. Use to mirror existing settings or as a baseline before &#x60;addDomainDnssec&#x60; (which replaces the set). Sibling ops: &#x60;addDomainDnssec&#x60;, &#x60;deleteDomainDnssec&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns** (schema &#x60;DomainDnssecRecords&#x60;):
- &#x60;records&#x60; (array) — DS entries:
  - &#x60;algorithm&#x60; (integer) — DNSKEY algorithm (e.g. 8 for RSASHA256, 13 for ECDSAP256SHA256).
  - &#x60;key_tag&#x60; (integer, &lt; 65536).
  - &#x60;digest_type&#x60; (integer) — &#x60;1&#x60; (SHA-1), &#x60;2&#x60; (SHA-256), &#x60;3&#x60; (GOST), &#x60;4&#x60; (SHA-384).
  - &#x60;digest&#x60; (string, hex) — length depends on &#x60;digest_type&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Replace records:** &#x60;addDomainDnssec&#x60;.
- **Clear all records:** &#x60;deleteDomainDnssec&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/dnssec") class getDomainDnssec(val id: kotlin.Int)

    /**
     * Read full billing, registrar, and service detail for one domain
     * Returns the full &#x60;ViewDomain&#x60; payload for one domain — billing summary, registration status, lock state, expiry date, contact summary, and &#x60;client_links&#x60; for related dashboard actions. Read-only. Internal &#x60;admin_links&#x60;, &#x60;settings&#x60;, &#x60;csrf&#x60; are stripped before return. Use to render a domain detail page, verify ownership before mutating, or poll &#x60;domain_status&#x60; after &#x60;addDomain&#x60;. Sibling ops: &#x60;getDomainContact&#x60;, &#x60;getDomainNameservers&#x60;, &#x60;getDomainDnssec&#x60;, &#x60;getDomainWhoisPrivacy&#x60;, &#x60;getDomainInvoices&#x60;, &#x60;updateDomainInfo&#x60;, &#x60;CancelDomain&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns** (schema &#x60;Domain&#x60;):
- &#x60;serviceInfo&#x60; — &#x60;domain_id&#x60;, &#x60;domain_hostname&#x60;, &#x60;domain_status&#x60;, &#x60;domain_expire_date&#x60;, lock state, registrar metadata.
- &#x60;serviceType&#x60; — TLD service row.
- &#x60;client_links&#x60; (array) — &#x60;{name, link, icon}&#x60; for renew/transfer/contact/DNSSEC/whois-privacy actions. URLs pre-resolved.

**Auth:** Session/API key. Ownership enforced via &#x60;domain_custid&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Contact:** &#x60;getDomainContact&#x60; / &#x60;updateDomainContact&#x60;.
- **Nameservers:** &#x60;getDomainNameservers&#x60; / &#x60;updateDomainNameservers&#x60;.
- **DNSSEC:** &#x60;getDomainDnssec&#x60; / &#x60;addDomainDnssec&#x60; / &#x60;deleteDomainDnssec&#x60;.
- **Whois privacy:** &#x60;getDomainWhoisPrivacy&#x60; / &#x60;updateDomainWhoisPrivacy&#x60;.
- **Billing:** &#x60;getDomainInvoices&#x60;, &#x60;getDomainRenewal&#x60; / &#x60;postDomainRenewal&#x60;.
- **Transfer status:** &#x60;getDomainTransfer&#x60;.
- **Cancel:** &#x60;CancelDomain&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}") class getDomainInfo(val id: kotlin.Int)

    /**
     * List all billing invoices scoped to one domain order
     * Returns the billing history for one domain — initial registration/transfer invoice, recurring renewal invoices, Whois privacy add-on invoices. Extends &#x60;Billing\InvoicesList::go()&#x60; with &#x60;module&#x3D;&#x27;domains&#x27;&#x60;. Use to render a per-domain billing-history view or find an unpaid renewal/privacy invoice to pass to &#x60;initiatePayment&#x60;. Sibling ops: &#x60;getDomainInfo&#x60;, &#x60;postDomainRenewal&#x60;, &#x60;updateDomainWhoisPrivacy&#x60;, &#x60;initiatePayment&#x60;, &#x60;getBillingInvoice&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns:** &#x60;ChargeInvoiceRows&#x60; — array of &#x60;{id, amount, paid, description, date, due_date, currency, module: &quot;domains&quot;, service: &lt;id&gt;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Pay an unpaid invoice:** &#x60;initiatePayment&#x60;.
- **Renew:** &#x60;postDomainRenewal&#x60;.
- **Account-wide history:** &#x60;getBillingInvoices&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/invoices") class getDomainInvoices(val id: kotlin.Int)

    /**
     * Check availability, premium status, and pricing for a specific domain
     * Looks up a single FQDN against OpenSRS: returns availability, premium-name flag, current new/renewal/transfer prices, per-TLD order field metadata, and multi-currency quotes. **Public** endpoint — no auth required (rate-limited via &#x60;domainlookup&#x60; cache). Repeated lookups within a short window may return cached results from the &#x60;domainlookup&#x60; table. Use as step 1 of an order: discover availability and pricing, then call &#x60;addDomain&#x60; to commit. Sibling ops: &#x60;getDomainSearch&#x60; (suggestions), &#x60;getNewDomain&#x60; (catalog), &#x60;addDomain&#x60;, &#x60;postDomainSearch&#x60;.

**Path param:**
- &#x60;name&#x60; (string, required) — full FQDN (e.g. &#x60;example.com&#x60;).

**Returns** (schema &#x60;DomainLookupResponse&#x60;):
- &#x60;available&#x60; (bool) — registerable now.
- &#x60;premium&#x60; (bool) — premium-name pricing (often &gt; $100).
- &#x60;website&#x60; (bool) — same hostname is already a webhosting service on this account.
- &#x60;domain_service&#x60; (bool) — same hostname is already a domain on this account.
- &#x60;service&#x60; (object) — &#x60;services_id&#x60;, &#x60;services_name&#x60;, &#x60;services_cost&#x60;, &#x60;services_field1&#x60; (TLD), &#x60;services_module&#x60;.
- &#x60;whois_privacy&#x60; (bool) — privacy add-on available for this TLD.
- &#x60;new&#x60;, &#x60;renewal&#x60;, &#x60;transfer&#x60; (float) — base USD prices (with profit markup).
- &#x60;fields&#x60; (object) — per-TLD order form schema (labels, options, current account values).
- &#x60;currencies&#x60; (object) — &#x60;{&lt;code&gt;: {services_cost, new, renewal, transfer}}&#x60; converted to each enabled currency.

**Auth:** Public (no auth required).

**Errors:**
- &#x60;422 Invalid Domain&#x60; — &#x60;valid_domain()&#x60; rejected input.

**Related calls:**
- **Brainstorm alternatives:** &#x60;getDomainSearch&#x60;.
- **Place order:** &#x60;addDomain&#x60; with the resolved &#x60;service.services_id&#x60; and &#x60;fields&#x60;.
- **TLD catalog:** &#x60;getNewDomain&#x60;.

     * @param name The full domain name to look up (for example &#x60;example.com&#x60;). 
     */
    @Location("/domains/lookup/{name}") class getDomainLookup(val name: kotlin.String)

    /**
     * List registered nameserver hosts and glue IP addresses for a domain
     * Returns the registered-nameserver / glue-record entries currently set for the domain at OpenSRS. **Important distinction:** these are *registered nameservers* (&#x60;host.example.com&#x60; + glue IP records the registrant has created at the registry), NOT the domain&#x27;s delegation NS records. To replace the delegation set, use &#x60;updateDomainNameservers&#x60;. Empty array means no glue records are registered. Sibling ops: &#x60;addDomainNameserver&#x60;, &#x60;updateDomainNameservers&#x60;, &#x60;deleteDomainNameserver&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns** (schema &#x60;DomainNameserverGetResponse&#x60;):
- Array of &#x60;{name, ipaddress, sortorder}&#x60; — use the zero-based array index when calling &#x60;deleteDomainNameserver&#x60; with &#x60;index&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.
- &#x60;5xx&#x60; — registrar communication failure.

**Related calls:**
- **Add glue record:** &#x60;addDomainNameserver&#x60;.
- **Replace delegation set:** &#x60;updateDomainNameservers&#x60;.
- **Remove glue record:** &#x60;deleteDomainNameserver&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/nameservers") class getDomainNameservers(val id: kotlin.Int)

    /**
     * Read renewal pricing, expiry, and whether a renewal invoice already exists
     * Returns renewal pricing, current expiry, Whois privacy availability, and whether an unpaid renewal invoice already exists for the domain. Use before triggering &#x60;postDomainRenewal&#x60; to render a renewal form and prevent duplicate invoices. Costs are converted to the customer&#x27;s preferred currency. Sibling ops: &#x60;postDomainRenewal&#x60;, &#x60;getDomainInvoices&#x60;, &#x60;getDomainInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns:**
- &#x60;renewCost&#x60; (float) — renewal cost in &#x60;currency&#x60;.
- &#x60;whoisCost&#x60; (float) — Whois privacy renewal cost.
- &#x60;whoisAvailable&#x60; (bool) — privacy supported on this TLD.
- &#x60;currency&#x60; (string), &#x60;currencySymbol&#x60; (string).
- &#x60;expiryDate&#x60; (string).
- &#x60;alreadyInvoiced&#x60; (bool) — a renewal &#x60;Repeat_Invoice&#x60; already produced an invoice.
- &#x60;invoicePaid&#x60; (bool) — whether that invoice is paid.
- &#x60;tld&#x60; (string).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.
- &#x60;4xx&#x60; — renewal not available for this TLD.

**Related calls:**
- **Submit renewal:** &#x60;postDomainRenewal&#x60;.
- **Pay existing renewal invoice:** &#x60;getDomainInvoices&#x60; → &#x60;initiatePayment&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/renew") class getDomainRenewal(val id: kotlin.Int)

    /**
     * Get registrar-suggested domain alternatives and bulk availability for a search term
     * Returns registrar-suggested alternatives plus bulk availability data from OpenSRS for the supplied search term. Useful when a customer is brainstorming names. Pair with &#x60;getDomainLookup&#x60; to get full pricing and per-TLD order fields for any specific chosen result. Sibling ops: &#x60;postDomainSearch&#x60;, &#x60;getDomainLookup&#x60;, &#x60;getNewDomain&#x60;, &#x60;addDomain&#x60;.

**Path param:**
- &#x60;name&#x60; (string, required) — search term (e.g. &#x60;example&#x60; or &#x60;example.com&#x60;).

**Returns** (schema &#x60;DomainSearchResponse&#x60;):
- &#x60;success&#x60; (bool) — registrar call succeeded.
- &#x60;response_text&#x60; (string) — registrar response message.
- &#x60;response_time&#x60; (float) — registrar latency (seconds).
- &#x60;lookup&#x60; (array) — exact-match availability across the searched TLD set.
- &#x60;suggest&#x60; (array) — registrar&#x27;s recommended alternative names with availability.
- &#x60;tlds&#x60; (array) — TLDs queried.

**Auth:** Public.

**Errors:**
- &#x60;422 Invalid Search Response!&#x60; — registrar returned no usable results.

**Related calls:**
- **Single-domain detail:** &#x60;getDomainLookup&#x60;.
- **One-shot order preview from a search term:** &#x60;postDomainSearch&#x60;.

     * @param name The base domain name to search (for example &#x60;example&#x60; or &#x60;example.com&#x60;). 
     */
    @Location("/domains/search/{name}") class getDomainSearch(val name: kotlin.String)

    /**
     * Read OpenSRS transfer status for an in-progress domain transfer order
     * Returns the OpenSRS transfer state for a domain order flagged as a transfer in &#x60;service_extra&#x60;. Use to poll an in-progress transfer; &#x60;pending_owner&#x60; means the customer must click the approval link in the email sent by OpenSRS to the registrant. Sibling ops: &#x60;postDomainTransfer&#x60; (re-poll), &#x60;getDomainContact&#x60; (set &#x60;auth_info&#x60;), &#x60;addDomain&#x60; (initiate new transfer).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns:**
- When not a transfer: &#x60;{transfer: false, message: &quot;...&quot;}&#x60;.
- When a transfer: &#x60;{transfer: true, info: {status, statusText, type, transferrable, reason}}&#x60; where &#x60;status&#x60; is one of:
  - &#x60;pending&#x60; — submitted to OpenSRS, awaiting state change.
  - &#x60;pending_owner&#x60; — **customer action required** (approve the OpenSRS email).
  - &#x60;pending_admin&#x60; — InterServer staff review.
  - &#x60;pending_registry&#x60; — registry processing.
  - &#x60;declined&#x60; — transfer rejected (see &#x60;reason&#x60;).
  - &#x60;completed&#x60; — transfer landed.
  - &#x60;undef&#x60; — unknown.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.
- Registrar communication failures returned as errors.

**Related calls:**
- **Re-poll:** &#x60;postDomainTransfer&#x60;.
- **Update auth_info:** &#x60;updateDomainContact&#x60;.
- **Initiate new transfer:** &#x60;addDomain&#x60; with &#x60;type&#x3D;transfer&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/transfer") class getDomainTransfer(val id: kotlin.Int)

    /**
     * Read Whois privacy availability, current state, and add-on pricing for a domain
     * Returns Whois privacy state for the domain — whether the TLD supports privacy, whether it&#x27;s currently enabled at OpenSRS, and the add-on cost. Some TLDs (e.g. &#x60;.us&#x60;, &#x60;.uk&#x60;, country-code variants) do not allow privacy regardless of pricing. Sibling op: &#x60;updateDomainWhoisPrivacy&#x60; (order/enable/disable).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Returns:**
- &#x60;available&#x60; (bool) — privacy supported for this TLD (via &#x60;get_domain_tld_whois_privacy()&#x60;).
- &#x60;cost&#x60; (float) — annual privacy cost in &#x60;currency&#x60;.
- &#x60;currency&#x60; (string), &#x60;currencySymbol&#x60; (string).
- &#x60;whoisPrivacy&#x60; (string enum) — &#x60;enabled&#x60; / &#x60;disabled&#x60; (live OpenSRS state).
- &#x60;repeatInvoice&#x60; (object|null) — current privacy add-on &#x60;Repeat_Invoice&#x60; row, if one exists.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Order/enable/disable:** &#x60;updateDomainWhoisPrivacy&#x60;.
- **Billing:** &#x60;getDomainInvoices&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/whois") class getDomainWhoisPrivacy(val id: kotlin.Int)

    /**
     * List every domain registration on the account with billing and registration metadata
     * Enumerates every domain registration owned by the authenticated customer — hostname, expiry, recurring cost, status. The canonical entry point for finding a &#x60;domain_id&#x60; to pass into other Domains endpoints. Empty array means the account has no domains (not an error). Sibling ops: &#x60;getDomainInfo&#x60;, &#x60;getNewDomain&#x60;, &#x60;getDomainLookup&#x60;, &#x60;addDomain&#x60;, &#x60;CancelDomain&#x60;.

**Path/Query/Body:** None.

**Returns:** Array of &#x60;DomainRow&#x60;:
- &#x60;domain_id&#x60; (string) — canonical id; pass to every &#x60;/domains/{id}/*&#x60; endpoint.
- &#x60;domain_hostname&#x60; (string) — registered FQDN.
- &#x60;domain_expire_date&#x60; (string ISO 8601 or empty) — registry expiry; empty when not yet activated or unknown.
- &#x60;cost&#x60; (decimal string) — recurring renewal cost in the domain&#x27;s billing currency.
- &#x60;domain_status&#x60; (string enum) — &#x60;pending&#x60; / &#x60;active&#x60; / &#x60;expired&#x60; / &#x60;canceled&#x60; / &#x60;pending-transfer&#x60;.

**Auth:** Session/API key. Filtered by &#x60;domain_custid&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Per-domain detail:** &#x60;getDomainInfo&#x60;.
- **Manage:** &#x60;getDomainContact&#x60; / &#x60;updateDomainContact&#x60;, &#x60;getDomainNameservers&#x60; / &#x60;updateDomainNameservers&#x60;, &#x60;getDomainDnssec&#x60; / &#x60;addDomainDnssec&#x60;, &#x60;getDomainWhoisPrivacy&#x60; / &#x60;updateDomainWhoisPrivacy&#x60;.
- **Renew / transfer:** &#x60;getDomainRenewal&#x60; / &#x60;postDomainRenewal&#x60;, &#x60;getDomainTransfer&#x60;.
- **Order a new domain:** &#x60;getDomainLookup&#x60; → &#x60;getNewDomain&#x60; → &#x60;addDomain&#x60;.
- **Cancel:** &#x60;CancelDomain&#x60;.

     */
    @Location("/domains") class getDomainsList()

    /**
     * Resend the domain welcome email with registration details and management instructions
     * Resends the domain welcome email (registration details, management instructions, EPP code where applicable) to the customer&#x27;s address on file. Idempotent — safe to call multiple times. Sibling welcome-email endpoints: &#x60;getVpsWelcomeEmail&#x60;, &#x60;getWebsitesWelcomeEmail&#x60;, &#x60;getMailWelcomeEmail&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body:** None.

**Returns:** &#x60;{text: &quot;Welcome Email has been resent.&quot;}&#x60;.

**Side effects:**
- Sends an email to the account&#x27;s billing email address.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 Service is not active&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Domain detail:** &#x60;getDomainInfo&#x60;.
- **Contact info:** &#x60;getDomainContact&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/welcome_email") class getDomainsWelcomeEmail(val id: kotlin.Int)

    /**
     * Read the buyable domain TLD service catalog and Whois privacy pricing
     * Returns the catalog of buyable TLD services and the base Whois-privacy add-on pricing. Use to resolve a hostname&#x27;s TLD to a &#x60;service_id&#x60; for ordering, or to render a TLD picker. Pair with &#x60;getDomainLookup&#x60; for per-domain pricing and &#x60;addDomain&#x60; to commit. Sibling ops: &#x60;getDomainLookup&#x60;, &#x60;putDomains&#x60;, &#x60;patchDomains&#x60;, &#x60;addDomain&#x60;.

**Path/Query/Body:** None.

**Returns** (schema &#x60;DomainOrder&#x60;):
- &#x60;whoisPrivacyCost&#x60; (float) — base per-year privacy cost (&#x60;OPENSRS_PRIVACY_COST&#x60; constant).
- &#x60;whoisPrivacyCostTotal&#x60; (object) — privacy cost per TLD multiplied by that TLD&#x27;s term length: &#x60;{&lt;tld&gt;: &lt;total-cost&gt;}&#x60;.
- &#x60;services&#x60; (object) — &#x60;{&lt;services_id&gt;: {services_name, services_cost, services_field1 (tld), ...}}&#x60;. &#x60;services_ourcost&#x60; is stripped.
- &#x60;tldServices&#x60; (object) — TLD → &#x60;services_id&#x60; lookup map (e.g. &#x60;{&quot;com&quot;: 100, &quot;net&quot;: 101, &quot;io&quot;: 234}&#x60;).

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Per-domain pricing:** &#x60;getDomainLookup&#x60;.
- **Preview order fields:** &#x60;putDomains&#x60;.
- **Validate fields:** &#x60;patchDomains&#x60;.
- **Place order:** &#x60;addDomain&#x60;.

     */
    @Location("/domains/order") class getNewDomain()

    /**
     * Validate posted domain-order field values before committing — dry run
     * Validates posted contact/registration field values via &#x60;validate_domain_fields()&#x60;. Enforces per-TLD requirements (nexus codes, postal formats, registrant org rules, EPP &#x60;auth_info&#x60; syntax for transfers, etc.). Use as the last step before &#x60;addDomain&#x60; to surface form errors cheaply. No commit — no invoice, no service record. Sibling ops: &#x60;putDomains&#x60;, &#x60;addDomain&#x60;, &#x60;getDomainLookup&#x60;, &#x60;getNewDomain&#x60;.

**Body fields:**
- &#x60;hostname&#x60; (string, required).
- &#x60;type&#x60; (string, optional, default &#x60;register&#x60;) — &#x60;register&#x60; or &#x60;transfer&#x60;.
- All per-TLD fields from &#x60;putDomains.domainFields&#x60;.

**Returns:** &#x60;&quot;success&quot;&#x60; (string) when all fields validate; otherwise an &#x60;errors&#x60; object describing the failing fields and per-field validation messages.

**Auth:** Session/API key.

**Errors:**
- &#x60;400 Missing hostname parameter&#x60;.
- &#x60;400 Unable to determine service type for this domain TLD.&#x60;.
- &#x60;401&#x60; — unauthenticated.
- Validation error object — fields-level failures.

**Related calls:**
- **Schema:** &#x60;putDomains&#x60; (returns the field set to validate).
- **Commit:** &#x60;addDomain&#x60;.

     * @param body  
     */
    @Location("/domains/order") class patchDomains(val body: kotlin.collections.Map<kotlin.String, kotlin.Any>)

    /**
     * Submit a domain renewal request and generate the renewal invoice
     * Generates a renewal invoice for the domain (and optionally the Whois privacy add-on). Updates the domain&#x27;s &#x60;Repeat_Invoice&#x60; cost/frequency/currency to the current price, then calls &#x60;Repeat_Invoice::invoice()&#x60; to produce a fresh invoice. **Real money.** If a prior unpaid renewal invoice already exists, returns an error directing the user to pay that one instead — prevents double-billing. Renewal is not supported for some TLDs. Sibling ops: &#x60;getDomainRenewal&#x60;, &#x60;getDomainInvoices&#x60;, &#x60;initiatePayment&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body fields:**
- &#x60;whois_privacy&#x60; (string, optional) — &#x60;enable&#x60; to add or keep the privacy add-on; otherwise the existing privacy &#x60;Repeat_Invoice&#x60; is marked &#x60;deleted&#x3D;1&#x60; on renewal.

**Returns:** &#x60;{text, invoices, invoiceIds, payUrl}&#x60; — pass &#x60;invoiceIds&#x60; to &#x60;initiatePayment&#x60; to settle.

**Side effects:**
- Updates &#x60;repeat_invoices&#x60; cost/frequency/currency.
- Inserts a new &#x60;invoices&#x60; row for the renewal period.
- When &#x60;whois_privacy&#x3D;enable&#x60;: extends the privacy add-on &#x60;repeat_invoices&#x60; and creates its renewal invoice.
- When &#x60;whois_privacy&#x60; not enabled: marks the existing privacy &#x60;repeat_invoices&#x60; row &#x60;deleted&#x3D;1&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;, or unpaid renewal invoice already exists, or already-paid renewal exists.
- Registrar errors surfaced as 4xx.

**Related calls:**
- **Preview:** &#x60;getDomainRenewal&#x60;.
- **Pay:** &#x60;initiatePayment&#x60; with the returned &#x60;invoiceIds&#x60;.
- **Cancel auto-renew:** &#x60;CancelDomain&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/renew") class postDomainRenewal(val id: kotlin.Int)

    /**
     * Get the full order form data for a hostname in one round-trip (search → order preview)
     * Returns the complete order-form payload — pricing, service catalog entry, per-TLD order fields — for the hostname in a single POST. Equivalent to calling &#x60;getDomainLookup&#x60; + &#x60;getNewDomain&#x60; + &#x60;putDomains&#x60; and merging the results, but with one round-trip. The path &#x60;name&#x60; is moved server-side into &#x60;$_POST[&#x27;hostname&#x27;]&#x60; and passed to &#x60;getOrderDomainData(true)&#x60;. Sibling ops: &#x60;getDomainSearch&#x60;, &#x60;getDomainLookup&#x60;, &#x60;getNewDomain&#x60;, &#x60;addDomain&#x60;.

**Path param:**
- &#x60;name&#x60; (string, required) — hostname (e.g. &#x60;example.com&#x60;).

**Body:** None.

**Returns:** Combined order-data response — pricing, service catalog entry, form fields ready to populate for &#x60;addDomain&#x60;.

**Auth:** Session/API key (path is &#x60;client_api&#x60;, but called publicly).

**Errors:**
- &#x60;4xx&#x60; — hostname cannot be resolved to a TLD service.

**Related calls:**
- **Place order:** &#x60;addDomain&#x60; with the returned fields.

     * @param name The base domain name to search (for example &#x60;example&#x60; or &#x60;example.com&#x60;). 
     */
    @Location("/domains/search/{name}") class postDomainSearch(val name: kotlin.String)

    /**
     * Re-poll OpenSRS transfer status for a domain order via POST
     * Re-polls OpenSRS transfer state. Behaves identically to &#x60;getDomainTransfer&#x60; (same &#x60;go()&#x60; handler) — provided so dashboards can refresh via a form-action pattern. **This endpoint does not initiate transfers** — to start a transfer, use &#x60;addDomain&#x60; with &#x60;type&#x3D;transfer&#x60;. Sibling ops: &#x60;getDomainTransfer&#x60;, &#x60;addDomain&#x60; (initiate), &#x60;getDomainContact&#x60; (set &#x60;auth_info&#x60;).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body:** None.

**Returns:** Same payload as &#x60;getDomainTransfer&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Read:** &#x60;getDomainTransfer&#x60;.
- **Initiate new transfer:** &#x60;addDomain&#x60; with &#x60;type&#x3D;transfer&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/transfer") class postDomainTransfer(val id: kotlin.Int)

    /**
     * Preview per-TLD field requirements for a domain order — no commit
     * Pre-flight that returns the per-TLD field schema required to register or transfer the supplied hostname. The schema varies significantly by TLD: &#x60;.us&#x60; requires nexus codes, &#x60;.ca&#x60; requires CIRA legal type, &#x60;.eu&#x60; has residency rules, &#x60;.fr&#x60; requires VAT for orgs, etc. Values pre-populate from the account profile when possible. No commit — use &#x60;patchDomains&#x60; to validate filled values, then &#x60;addDomain&#x60; to place the order. Sibling ops: &#x60;getNewDomain&#x60;, &#x60;getDomainLookup&#x60;, &#x60;patchDomains&#x60;, &#x60;addDomain&#x60;.

**Body fields:**
- &#x60;hostname&#x60; (string, required) — FQDN.
- &#x60;type&#x60; (string, optional, default &#x60;register&#x60;) — &#x60;register&#x60; or &#x60;transfer&#x60;.
- &#x60;coupon&#x60; (string, optional) — coupon code.

**Returns:** &#x60;{domainFields: {&lt;field_name&gt;: {label, type, options, value, required, ...}}}&#x60; — schema for the dynamic order form.

**Auth:** Session/API key.

**Errors:**
- &#x60;400 Missing hostname parameter&#x60;.
- &#x60;400 Unable to determine service type for this domain TLD.&#x60; — unknown TLD.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Catalog first:** &#x60;getNewDomain&#x60;.
- **Validate filled values:** &#x60;patchDomains&#x60;.
- **Place order:** &#x60;addDomain&#x60;.

     * @param body  
     */
    @Location("/domains/order") class putDomains(val body: kotlin.collections.Map<kotlin.String, kotlin.Any>)

    /**
     * Update registrant/admin contact details and push them to OpenSRS
     * Pushes updated contact data to the registrar via OpenSRS &#x60;provModify&#x60;, applied to admin/tech/billing/owner contact roles via &#x60;also_apply_to&#x60;. Active services apply changes immediately at the registrar; pending services may trigger &#x60;queue_process_payment&#x60; when the order is paid. **Domain must not be locked** — locked domains return an error directing the user to unlock first. **Note:** registrant-name changes on some TLDs (e.g. &#x60;.com&#x60;, &#x60;.net&#x60;) require a 60-day transfer lock per ICANN rules. Sibling ops: &#x60;getDomainContact&#x60;, &#x60;getDomainInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body fields (JSON or multipart, schema &#x60;DomainContactDetails&#x60;):**
Same fields returned by &#x60;getDomainContact&#x60;: &#x60;firstname&#x60;, &#x60;lastname&#x60;, &#x60;email&#x60;, &#x60;address&#x60;/&#x60;2&#x60;/&#x60;3&#x60;, &#x60;city&#x60;, &#x60;state&#x60;, &#x60;zip&#x60;, &#x60;country&#x60;, &#x60;phone&#x60;, &#x60;fax&#x60;, &#x60;company&#x60;, optional &#x60;auth_info&#x60;, optional &#x60;transfer&#x60;.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Side effects:**
- Calls OpenSRS &#x60;provModify&#x60; with &#x60;also_apply_to&#x3D;admin,tech,billing,owner&#x60;.
- May trigger ICANN 60-day transfer lock for registrant-name changes on legacy TLDs.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — domain is locked (unlock first).
- Registrar error (e.g. OpenSRS error code 465 / 466) surfaced as 4xx.

**Related calls:**
- **Read first:** &#x60;getDomainContact&#x60;.
- **Transfer status:** &#x60;getDomainTransfer&#x60;.

     * @param body  
     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/contact") class updateDomainContact(val body: DomainContactDetails, val id: kotlin.Int)

    /**
     * POST mutation hook for the domain detail page (use dedicated ops where possible)
     * Account-level write-back hook for the domain service record. Runs the same &#x60;View::go()&#x60; handler as &#x60;getDomainInfo&#x60; — it does NOT push registrar-side changes by itself. **For specific changes use the dedicated endpoints** — they push to OpenSRS where appropriate. Sibling ops: &#x60;getDomainInfo&#x60;, &#x60;updateDomainContact&#x60;, &#x60;updateDomainNameservers&#x60;, &#x60;addDomainDnssec&#x60;, &#x60;updateDomainWhoisPrivacy&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body:** Form fields matching the domain service record.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Prefer these dedicated endpoints:**
- **Registrant/admin contact:** &#x60;updateDomainContact&#x60; (pushes to OpenSRS).
- **Nameservers:** &#x60;updateDomainNameservers&#x60;, &#x60;addDomainNameserver&#x60;, &#x60;deleteDomainNameserver&#x60;.
- **DNSSEC:** &#x60;addDomainDnssec&#x60;, &#x60;deleteDomainDnssec&#x60;.
- **Whois privacy:** &#x60;updateDomainWhoisPrivacy&#x60;.
- **Renew:** &#x60;postDomainRenewal&#x60;.
- **Cancel:** &#x60;CancelDomain&#x60;.

     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}") class updateDomainInfo(val id: kotlin.Int)

    /**
     * Replace the full authoritative-nameserver delegation list at the registrar
     * Atomically replaces the domain&#x27;s authoritative-nameserver delegation list via OpenSRS &#x60;nsAdvancedUpdt&#x60; with &#x60;op_type&#x3D;assign&#x60;. **Domain must be unlocked.** Use this to switch DNS providers (e.g. point at InterServer &#x60;cdns1&#x60;/&#x60;cdns2&#x60;, Cloudflare, AWS Route53, etc.). **Replaces the full set in one call** — partial updates are not supported through this endpoint. To register a new glue record (host + IP) at the registry, use &#x60;addDomainNameserver&#x60;. Sibling ops: &#x60;getDomainNameservers&#x60;, &#x60;addDomainNameserver&#x60;, &#x60;deleteDomainNameserver&#x60;, &#x60;addDnsDomain&#x60; (host a zone at InterServer).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body fields (JSON or multipart, schema &#x60;DomainNameserverPutRequest&#x60;):**
- &#x60;nameserver[]&#x60; (array of strings, required) — FQDN strings (e.g. &#x60;[&quot;ns1.example.com&quot;, &quot;ns2.example.com&quot;]&#x60;). Trimmed; empty entries dropped server-side.

**Returns:** &#x60;SuccessTextResponse&#x60; on registrar &#x60;is_success&#x3D;1&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60; or domain locked.
- Registrar errors surfaced as 4xx.

**Related calls:**
- **Read current set:** &#x60;getDomainNameservers&#x60;.
- **Register a glue record:** &#x60;addDomainNameserver&#x60;.
- **Host the DNS zone at InterServer:** &#x60;addDnsDomain&#x60; (DNS tag).

     * @param body  
     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/nameservers") class updateDomainNameservers(val body: DomainNameserverPutRequest, val id: kotlin.Int)

    /**
     * Order, enable, or cancel the Whois privacy add-on for a domain
     * Manages the Whois privacy add-on. Behavior branches on &#x60;action&#x60;:
- **&#x60;order&#x60;**: creates an add-on &#x60;Repeat_Invoice&#x60; and emits the first invoice; pass the returned &#x60;payUrl&#x60; to the customer or use &#x60;initiatePayment&#x60; with &#x60;invoiceId&#x60;. **Real money.**
- **&#x60;enable&#x60;**: activates Whois privacy at OpenSRS — call after the invoice is paid (calls &#x60;post_payment_processing_new&#x60;).
- **&#x60;disableCancel&#x60;**: disables Whois privacy at OpenSRS and marks the add-on &#x60;Repeat_Invoice&#x60; &#x60;deleted&#x3D;1&#x60;.
- **(no action)**: returns current state — same shape as &#x60;getDomainWhoisPrivacy&#x60;.

Sibling ops: &#x60;getDomainWhoisPrivacy&#x60;, &#x60;getDomainInvoices&#x60;, &#x60;initiatePayment&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;domain_id&#x60; from &#x60;getDomainsList&#x60;.

**Body fields (JSON or multipart, schema &#x60;DomainWhoisPrivacyRequest&#x60;):**
- &#x60;action&#x60; (string, optional) — one of &#x60;order&#x60; / &#x60;enable&#x60; / &#x60;disableCancel&#x60;. Omit for status.

**Returns:** (varies by action)
- &#x60;order&#x60;: &#x60;{text, invoiceId, repeatInvoiceId, payUrl}&#x60;.
- &#x60;enable&#x60; / &#x60;disableCancel&#x60;: &#x60;{text}&#x60;.
- No action: &#x60;{whoisPrivacy, cost, currency, currencySymbol}&#x60;.

**Side effects:**
- &#x60;order&#x60;: inserts add-on &#x60;repeat_invoices&#x60; + &#x60;invoices&#x60; rows.
- &#x60;enable&#x60;: OpenSRS &#x60;provModify&#x60; with privacy&#x3D;on; calls &#x60;post_payment_processing_new&#x60;.
- &#x60;disableCancel&#x60;: OpenSRS &#x60;provModify&#x60; with privacy&#x3D;off; marks add-on &#x60;repeat_invoices.deleted&#x3D;1&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;domain_status !&#x3D; &quot;active&quot;&#x60; or TLD doesn&#x27;t support privacy.
- &#x60;4xx&#x60; — no add-on found for &#x60;enable&#x60; / &#x60;disableCancel&#x60;.

**Related calls:**
- **Read state:** &#x60;getDomainWhoisPrivacy&#x60;.
- **Pay the order invoice:** &#x60;initiatePayment&#x60; (&#x60;method&#x3D;cc|paypal|...&#x60;).
- **Renew with privacy:** &#x60;postDomainRenewal&#x60; with &#x60;whois_privacy&#x3D;enable&#x60;.

     * @param body  
     * @param id The domain service ID. Use &#x60;domain_id&#x60; from &#x60;GET /domains&#x60;. 
     */
    @Location("/domains/{id}/whois") class updateDomainWhoisPrivacy(val body: DomainWhoisPrivacyRequest, val id: kotlin.Int)

    /**
     * Place a real Floating IP order, create billing records, and provision the service
     * Charges the customer and creates a new Floating IP service via &#x60;place_buy_floating_ip&#x60;. Validate first with &#x60;putFloating_ips&#x60; to avoid surprise failures. Body (form-encoded): &#x60;serviceType&#x60; (required, &#x60;services_id&#x60;), &#x60;coupon&#x60; (optional), &#x60;comment&#x60; (optional internal note). On success returns &#x60;{ continue:true, errors, total_cost, iid, iids, real_iids, serviceId, invoice_description, cj_params }&#x60; — &#x60;iid&#x60; is the master invoice ID, &#x60;serviceId&#x60; is the new &#x60;floating_ip_id&#x60;. On validation failure returns &#x60;{ continue:false, errors:[...] }&#x60; with no charge. Errors: 401 if unauthenticated; soft errors in &#x60;errors[]&#x60;. The newly-issued IP starts unassigned — point it at a target with &#x60;postFloatingIpsChangeIp&#x60; once the service is &#x60;active&#x60;.

Sibling ops: &#x60;getNewFloatingIp&#x60; (catalog), &#x60;putFloating_ips&#x60; (validate), &#x60;getFloatingIpInfo&#x60; (poll), &#x60;postFloatingIpsChangeIp&#x60; (route), &#x60;getBillingInvoice&#x60; + &#x60;initiatePayment&#x60; (settle invoice), &#x60;floating_ipsCancel&#x60;.
     * @param body  
     */
    @Location("/floating_ips/order") class addFloatingIp(val body: FloatingIpOrderRequest)

    /**
     * Cancel a Floating IP service and release the IP — destructive, billing stops
     * Cancels the Floating IP via the shared &#x60;Api\Billing\CancelService&#x60; flow — flips status to canceled, halts recurring billing, and releases the IP back to the pool so it can no longer be re-routed. Not reversible: the customer cannot recover the same IP after release. Path param &#x60;id&#x60; (&#x60;floating_ip_id&#x60; from &#x60;getFloatingIpsList&#x60;). No body. Returns the &#x60;FloatingIpsCancelResponse&#x60; shape (success text / cancellation outcome). Errors: 401 if unauthenticated; 404 / cross-customer hidden when &#x60;id&#x60; is not owned by the caller; 409 if already canceled or otherwise non-cancelable. Confirm with the customer before calling — for routing changes use &#x60;postFloatingIpsChangeIp&#x60; instead of cancel-and-reorder.

Sibling ops: &#x60;getFloatingIpInfo&#x60; (status), &#x60;getFloatingIpInvoices&#x60; (outstanding charges), &#x60;postFloatingIpsChangeIp&#x60; (re-route instead of cancel), &#x60;addFloatingIp&#x60; (re-order).
     * @param id The Floating IP service ID. Use the ID from &#x60;GET /floating_ips&#x60;. 
     */
    @Location("/floating_ips/{id}") class floatingIpsCancel(val id: kotlin.Int)

    /**
     * Fetch full details for one Floating IP service, including current target IP
     * Use for a Floating IP detail screen, or to read &#x60;floating_ip_ip&#x60; / &#x60;floating_ip_target_ip&#x60; before calling &#x60;postFloatingIpsChangeIp&#x60;. Read-only. Path param &#x60;id&#x60; (integer, &#x60;floating_ip_id&#x60; from &#x60;getFloatingIpsList&#x60;). No body. Returns the &#x60;ViewFloatingIp.getDetails()&#x60; payload — service info, billing/cost summary, status, target IP, and &#x60;client_links&#x60; (action URLs the UI can render). Internal-only fields (&#x60;admin_links&#x60;, &#x60;settings&#x60;, &#x60;csrf&#x60;) are stripped. Errors: 401 if unauthenticated; effectively 404 / cross-customer hidden when &#x60;id&#x60; is not owned by the caller (&#x60;get_service&#x60; filters by custid). Siblings: &#x60;postFloatingIpsChangeIp&#x60;, &#x60;updateFloatingIpInfo&#x60;, &#x60;getFloatingIpInvoices&#x60;, &#x60;getFloatingIpsWelcomeEmail&#x60;, &#x60;floating_ipsCancel&#x60;.
     * @param id The Floating IP service ID. Use the ID from &#x60;GET /floating_ips&#x60;. 
     */
    @Location("/floating_ips/{id}") class getFloatingIpInfo(val id: kotlin.Int)

    /**
     * List all billing invoices charged against a specific Floating IP service
     * Use for a per-service billing history view — pulls the standard &#x60;Api\Billing\InvoicesList&#x60; rows scoped to this Floating IP. Read-only. Path param &#x60;id&#x60; (&#x60;floating_ip_id&#x60; from &#x60;getFloatingIpsList&#x60;). No body. Returns the &#x60;ChargeInvoiceRows&#x60; schema: array of invoice rows with id, date, amount, status, etc. Use the invoice IDs with the global billing endpoints (&#x60;getBillingInvoice&#x60;, &#x60;initiatePayment&#x60;) for line-item detail. Errors: 401 if unauthenticated; effectively 404 / cross-customer hidden when &#x60;id&#x60; is not owned by the caller. Siblings: &#x60;getFloatingIpInfo&#x60; (service details), &#x60;getFloatingIpsWelcomeEmail&#x60;.
     * @param id The Floating IP service ID. Use the ID from &#x60;GET /floating_ips&#x60;. 
     */
    @Location("/floating_ips/{id}/invoices") class getFloatingIpInvoices(val id: kotlin.Int)

    /**
     * List all Floating IP services on the authenticated customer&#x27;s account
     * Use to enumerate every Floating IP the caller owns before drilling into a specific one. Read-only; safe to call frequently. No params, no body. Returns an array of rows: &#x60;floating_ip_id&#x60;, &#x60;repeat_invoices_cost&#x60; (recurring price), &#x60;floating_ip_ip&#x60; (the portable IP), &#x60;floating_ip_target_ip&#x60; (the IP it currently routes to), &#x60;floating_ip_status&#x60; (active/pending/canceled/etc.), &#x60;services_name&#x60; (package label). Empty array if the account owns no Floating IPs. Errors: 401 if unauthenticated. Use returned IDs with &#x60;getFloatingIpInfo&#x60;, &#x60;postFloatingIpsChangeIp&#x60;, &#x60;getFloatingIpInvoices&#x60;, &#x60;getFloatingIpsWelcomeEmail&#x60;, or &#x60;floating_ipsCancel&#x60;. To order a new one see &#x60;getNewFloatingIp&#x60; / &#x60;addFloatingIp&#x60;.

Sibling ops: &#x60;getFloatingIpInfo&#x60;, &#x60;getNewFloatingIp&#x60; (catalog), &#x60;addFloatingIp&#x60; (order).
     */
    @Location("/floating_ips") class getFloatingIpsList()

    /**
     * Resend the Floating IP welcome / setup email to the account contact
     * Triggers &#x60;floating_ip_welcome_email($id)&#x60; to re-deliver the original setup email (the IP, routing instructions, etc.) to the customer&#x27;s on-file address. Useful when the email was lost or the customer needs the IP/setup details again. No body, no params besides path &#x60;id&#x60; (&#x60;floating_ip_id&#x60;). Returns &#x60;{ text: &#x27;Welcome Email has been resent.&#x27; }&#x60;. Errors: 401 if unauthenticated; 404 (&#x60;Invalid Service Passed&#x60;) if &#x60;id&#x60; is not owned by the caller; 409 (&#x60;Service is not active&#x60;) if status is not &#x60;active&#x60;. Side effect: sends an outbound email — avoid in tight loops. Read state first via &#x60;getFloatingIpInfo&#x60; if unsure of status.

Sibling ops: &#x60;getFloatingIpInfo&#x60; (status), &#x60;addFloatingIp&#x60; (new order), &#x60;floating_ipsCancel&#x60;.
     * @param id The Floating IP service ID. Use the ID from &#x60;GET /floating_ips&#x60;. 
     */
    @Location("/floating_ips/{id}/welcome_email") class getFloatingIpsWelcomeEmail(val id: kotlin.Int)

    /**
     * Get pricing and service-type options for ordering a new Floating IP
     * Use before showing a Floating IP order form, or before calling &#x60;addFloatingIp&#x60;, to discover which service types (&#x60;serviceTypes&#x60;) and prices (&#x60;packageCosts&#x60;, keyed by &#x60;services_id&#x60; in the customer&#x27;s currency) are currently buyable. Read-only; no side effects. No params, no body. Returns &#x60;{ packageCosts: { &lt;services_id&gt;: &lt;cost&gt; }, serviceTypes: [ ... ] } &#x60;. Costs are &#x60;services.services_cost&#x60; filtered to &#x60;services_buyable&#x3D;1&#x60; for module &#x60;floating_ips&#x60;. Errors: 401 if unauthenticated. Next steps: validate the chosen &#x60;serviceType&#x60; with &#x60;putFloating_ips&#x60;, then place the order with &#x60;addFloatingIp&#x60;. Floating IPs are portable IPv4 addresses that route to a target IP on one of the customer&#x27;s active services.

Sibling ops: &#x60;putFloating_ips&#x60; (validate), &#x60;addFloatingIp&#x60; (commit), &#x60;getFloatingIpsList&#x60; (existing IPs).
     */
    @Location("/floating_ips/order") class getNewFloatingIp()

    /**
     * Re-point a Floating IP to a different target IP on one of the customer&#x27;s services
     * Reattaches the Floating IP by removing the old static route on the source switch and adding a new one on the destination switch (via &#x60;Sshwitch&#x60;), then updates &#x60;floating_ip_target_ip&#x60;. Use to move a portable IP between the customer&#x27;s VPS / Quickservers / websites / dedicated servers without renumbering apps. Path param &#x60;id&#x60; (&#x60;floating_ip_id&#x60;). Body: &#x60;{ ip: &lt;new target IP&gt; }&#x60; (also accepts multipart form). Returns &#x60;{ success:true, text:&#x27;IP Changed&#x27; }&#x60;. Errors (returned via &#x60;json_error&#x60;): invalid IP format; IP not in our datacenter; IP not in use by an active service of this customer; service not active; another Floating IP already points to that target; switch lookup failures; route still present after removal. 401 if unauthenticated.

Sibling ops: &#x60;getFloatingIpInfo&#x60; (read current target), &#x60;getFloatingIpsList&#x60;, &#x60;floating_ipsCancel&#x60;. Read current target with &#x60;getFloatingIpInfo&#x60; first.
     * @param ip  
     * @param id The Floating IP service ID. Use the ID from &#x60;GET /floating_ips&#x60;. 
     */
    @Location("/floating_ips/{id}/change_ip") class postFloatingIpsChangeIp(val ip: kotlin.String, val id: kotlin.Int)

    /**
     * Validate a Floating IP order and price it without charging the customer
     * Dry-run for &#x60;addFloatingIp&#x60; — runs &#x60;validate_buy_floating_ip&#x60; to apply coupons, compute intro/repeat pricing, and surface errors before committing. No charge, no service created. Body fields (form-encoded): &#x60;serviceType&#x60; (required, &#x60;services_id&#x60; from &#x60;getNewFloatingIp.packageCosts&#x60;), &#x60;coupon&#x60; (optional code). Returns &#x60;{ continue, errors, serviceType, serviceCost, originalCost, repeatServiceCost, password, introFrequency, coupon, couponCode }&#x60;. &#x60;continue&#x3D;true&#x60; means the order would succeed; &#x60;continue&#x3D;false&#x60; plus populated &#x60;errors[]&#x60; means it would not. Errors: 401 if unauthenticated; 422-style soft errors arrive in the &#x60;errors&#x60; array. Use the returned &#x60;serviceType&#x60; and &#x60;couponCode&#x60; when calling &#x60;addFloatingIp&#x60;.
Sibling ops: &#x60;getNewFloatingIp&#x60; (catalog), &#x60;addFloatingIp&#x60; (commit).
     * @param body  
     */
    @Location("/floating_ips/order") class putFloatingIps(val body: FloatingIpOrderRequest)

    /**
     * Update a Floating IP service&#x27;s editable settings (label / metadata)
     * Stub edit endpoint that delegates to the same handler as &#x60;getFloatingIpInfo&#x60; — currently used for label/metadata edits surfaced by &#x60;ViewFloatingIp&#x60;. To re-route the IP to a different target use the dedicated &#x60;postFloatingIpsChangeIp&#x60; instead; this op does not change routing. Path param &#x60;id&#x60; (&#x60;floating_ip_id&#x60;). Body: form-encoded fields exposed by the Floating IP edit form (label/comment style). Returns the standard success-text response. Errors: 401 if unauthenticated; effectively 404 if &#x60;id&#x60; not owned by the caller. Read state first with &#x60;getFloatingIpInfo&#x60;.

Sibling ops: &#x60;getFloatingIpInfo&#x60; (read), &#x60;postFloatingIpsChangeIp&#x60; (re-route), &#x60;floating_ipsCancel&#x60;.
     * @param id The Floating IP service ID. Use the ID from &#x60;GET /floating_ips&#x60;. 
     */
    @Location("/floating_ips/{id}") class updateFloatingIpInfo(val id: kotlin.String)

    /**
     * Order a new software license and create the recurring invoice
     * Places an order for a new software license (cPanel, Plesk, LiteSpeed, etc.). Re-runs validate_buy_license then place_buy_license, which creates the repeat_invoices row, the first invoice, and queues payment processing. Always call putLicenses first to surface validation errors cheaply; addLicense re-validates and returns error JSON if continue&#x3D;false. Body (form or JSON): package (services_id from getNewLicense), ip (target server IP the license binds to), frequency (billing months), coupon, comment, tos (truthy). No path params. Returns ServiceOrderPostResponse with the new service id and invoice info. Errors: 401 unauthenticated; validation or payment failures return json_error with the underlying message. Caveat: provisioning is asynchronous — poll getLicenseInfo for status.

Sibling ops: &#x60;getNewLicense&#x60; (catalog), &#x60;putLicenses&#x60; (validate), &#x60;getLicenseInfo&#x60; (poll status), &#x60;getLicenseInvoices&#x60;, &#x60;getBillingInvoice&#x60; + &#x60;initiatePayment&#x60; (settle invoice), &#x60;licensesCancel&#x60;.
     * @param body  
     */
    @Location("/licenses/order") class addLicense(val body: LicenseOrderRequest)

    /**
     * Get full details for one license including status, IP, and links
     * Returns rich detail for a single license service: serviceInfo row (license_id, hostname, license_ip, license_status, license_type), the underlying services row (name, cost, frequency), client_links for self-service actions (change IP, cancel, resend welcome email, view invoices), and provisioning state. Use after getLicenseList to drill into a specific license, or as the canonical lookup before postLicenseChangeIp / licensesCancel / getLicenseInvoices. Path: id (license_id from list). No body. Errors: 401 unauthenticated; 404 if id is invalid or owned by a different customer. Caveat: admin_links/settings/csrf are stripped — use admin endpoints for those. Sibling endpoints: updateLicenseInfo (mutate fields), postLicenseChangeIp.
     * @param id The license service ID. Use &#x60;license_id&#x60; from &#x60;GET /licenses&#x60;. 
     */
    @Location("/licenses/{id}") class getLicenseInfo(val id: kotlin.Int)

    /**
     * List all billing invoices tied to one software license service
     * Returns the full invoice history for a single license service: the original setup invoice plus every recurring renewal invoice generated by the repeat_invoices entry. Use this for billing reconciliation, to display past charges in the customer UI, or to confirm a renewal posted before contacting support. Path: id (license_id from getLicenseList). No body. Returns ChargeInvoiceRows: an array of invoice rows with id, date, amount, paid status, and payment method. Errors: 401 unauthenticated; returns success&#x3D;false with HTTP 400 if the service id is invalid or owned by a different customer. Caveat: only invoices linked via repeat_invoices_id are included — manual one-off charges from staff may not appear here. Sibling endpoints: getLicenseInfo, licensesCancel.
     * @param id The license service ID. Use &#x60;license_id&#x60; from &#x60;GET /licenses&#x60;. 
     */
    @Location("/licenses/{id}/invoices") class getLicenseInvoices(val id: kotlin.Int)

    /**
     * List all software licenses owned by the authenticated customer
     * Lists every software license service (cPanel, Plesk, LiteSpeed, CloudLinux, etc.) on the authenticated customer&#x27;s account. Use this as the entry point for license management to discover the license_id needed by every other Licenses endpoint. Returns an array of rows including license_id, hostname, bound IP, services_name (license type), recurring cost, status (pending/active/canceled), and last invoice date/paid state. No path or query parameters; the customer scope is taken from the session. Errors: 401 when the session is missing or expired. Caveats: list is unpaginated, includes canceled rows so callers should filter by status. Sibling: getLicenseInfo for full details on one license.
     */
    @Location("/licenses") class getLicenseList()

    /**
     * Resend the license welcome email with the key and activation steps
     * Resends the welcome email for an active license to the account email on file. The email contains the license key, the bound IP, and vendor-specific activation instructions (e.g. cPanel /usr/local/cpanel/cpkeyclt, LiteSpeed lswsctrl). Use this when the customer lost the original email or rotated mailboxes — the key itself is unchanged. Path: id (license_id). No body. Returns SuccessTextResponse with a translated confirmation. Errors: 401 unauthenticated; 404 if the id is invalid or not owned by the session customer; 409 if the license status is not active (cancelled licenses cannot resend). Caveat: delivery is best-effort — check the email log if it does not arrive. Sibling endpoints: getLicenseInfo, postLicenseChangeIp.
     * @param id The license service ID. Use &#x60;license_id&#x60; from &#x60;GET /licenses&#x60;. 
     */
    @Location("/licenses/{id}/welcome_email") class getLicensesWelcomeEmail(val id: kotlin.Int)

    /**
     * Get available license types, packages, and pricing for ordering
     * Returns the catalog needed to build the license-order form: service categories (category_id-&gt;name), buyable service types (services_id, name, cost, billing frequency), package costs map keyed by services_id, the customer&#x27;s currency symbol, and per-package field metadata via get_license_fields. Use this before addLicense to render type/package pickers and to validate a chosen package_id exists and is buyable (services_hidden&#x3D;0, services_buyable&#x3D;1). No path params or body. Returns LicensesOrder schema. Errors: 401 if unauthenticated. Sibling endpoints: putLicenses (validate selection), addLicense (place order). Note: pricing is converted to the session currency; coupon/IP/frequency are evaluated in the validate step, not here.
     */
    @Location("/licenses/order") class getNewLicense()

    /**
     * Cancel a license service and stop future billing (irreversible)
     * Cancels a license service: invokes cancel_service which marks the service canceled, deactivates the license key with the upstream vendor, and stops the recurring invoice so no further charges occur. Use carefully — once vendor-side deactivation propagates the key stops working on the bound machine. Path: id (license_id from getLicenseList). No body. Returns LicensesCancelResponse with success and a translated text message. Errors: 401 unauthenticated; the underlying handler returns success&#x3D;false JSON if the service id is invalid or cancellation fails (contact support path). Caveats: no prorated refund by default; pre-paid time is forfeited per TOS. Sibling endpoints: getLicenseInfo, getLicenseInvoices for billing history before cancelling.
     * @param id The license service ID. Use &#x60;license_id&#x60; from &#x60;GET /licenses&#x60;. 
     */
    @Location("/licenses/{id}") class licensesCancel(val id: kotlin.Int)

    /**
     * Rebind a license to a new IP address (may incur a vendor fee)
     * Changes the IP address that the license is bound to and triggers re-issuance with the upstream vendor (cPanel store, LiteSpeed key server, Plesk, etc.). The service must be active. Use getLicenseInfo first to read the current license_ip, then submit the new IP. Path: id (license_id). Body (JSON or multipart): IpObject with the new ip field. Returns SuccessTextResponse on success. Errors: 401 unauthenticated; 404 invalid id or not owned; 409 if status !&#x3D; active; 422-style failures from the vendor are returned via json_error with the upstream status_text. Caveats: many vendors charge a per-change fee and rate-limit changes (e.g. cPanel allows limited free changes per period); the new IP must be reachable for license verification. Sibling: updateLicenseInfo.
     * @param body  
     * @param id The license service ID. Use &#x60;license_id&#x60; from &#x60;GET /licenses&#x60;. 
     */
    @Location("/licenses/{id}/change_ip") class postLicenseChangeIp(val body: IpObject, val id: kotlin.Int)

    /**
     * Validate a software license order before placing it (dry run preview)
     * Dry-runs validate_buy_license against the same payload addLicense will accept, returning a structured result with continue&#x3D;true/false plus errors[], normalized package, ip, service_cost, original_cost, coupon_code, custid, currency and service_extra. Always call this before addLicense to surface package/IP/coupon/TOS issues without creating an invoice. Body fields (form or JSON): package (services_id), ip, frequency (billing cycle months), coupon, comment, tos. No path params. Returns the validation object. Errors: 401 unauthenticated; 422-style errors are returned inside the body with continue&#x3D;false rather than as HTTP errors. Caveat: a valid PUT does not reserve inventory; addLicense re-validates. Sibling: addLicense, getNewLicense.
     * @param body  
     */
    @Location("/licenses/order") class putLicenses(val body: LicenseOrderRequest)

    /**
     * Update mutable fields on a license service (e.g. assigned IP)
     * Updates settings on an existing license service. The primary mutable field is the bound IP, but the endpoint shares routing with View::go so other future fields flow through here. For IP changes prefer postLicenseChangeIp which has explicit semantics and triggers vendor rebinding. Path: id (license_id). Body: fields to update (form or JSON); shape varies by license type. Returns SuccessTextResponse. Errors: 401 unauthenticated; 404 if id is invalid or not owned; 409 if license is not active. Caveats: vendor-side propagation (cPanel store, LiteSpeed key server, etc.) is asynchronous; some IP/hostname changes incur a fee per vendor policy. Sibling: getLicenseInfo (read), postLicenseChangeIp (dedicated).
     * @param id The license service ID. Use &#x60;license_id&#x60; from &#x60;GET /licenses&#x60;. 
     */
    @Location("/licenses/{id}") class updateLicenseInfo(val id: kotlin.String)

    /**
     * Place a new Mail Baby order, generate invoice, and queue provisioning
     * Step 3 of the Mail Baby order flow. Revalidates via &#x60;validate_buy_mail()&#x60;, then calls &#x60;place_buy_mail()&#x60; to create a &#x60;Repeat_Invoice&#x60; recurring billing row, an initial &#x60;invoices&#x60; row, and a &#x60;mail&#x60; service record in pending status. SMTP credentials become active once the activation worker runs the welcome email (after the invoice is paid). **Real money** — call &#x60;putMail&#x60; first. Sibling ops: &#x60;getNewMail&#x60;, &#x60;putMail&#x60;, &#x60;getMailInfo&#x60;, &#x60;initiatePayment&#x60;.

**Body fields:**
- &#x60;serviceType&#x60; (integer, required) — plan id from &#x60;getNewMail&#x60;.
- &#x60;coupon&#x60; (string, optional).
- &#x60;comment&#x60; (string, optional) — saved on the order row.

**Returns** (on success): &#x60;{continue: true, total_cost, iid, iids, real_iids, serviceId (new mail_id), invoice_description, cj_params}&#x60; — pass &#x60;real_iids&#x60; to &#x60;initiatePayment&#x60;. On validation failure: &#x60;{continue: false, errors: [...]}&#x60; with HTTP 200.

**Side effects:**
- Inserts &#x60;mail&#x60; service row in &#x60;pending&#x60; status.
- Inserts &#x60;repeat_invoices&#x60; + &#x60;invoices&#x60; rows.

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Pay:** &#x60;initiatePayment&#x60; with &#x60;real_iids&#x60;.
- **Confirm activation:** &#x60;getMailInfo&#x60; (poll until &#x60;mail_status&#x3D;&#x3D;&#x27;active&#x27;&#x60;).
- **Resend credentials:** &#x60;getMailWelcomeEmail&#x60;.

**Full ordering happy path:**
&#x60;&#x60;&#x60;text
GET /mail/order                                    -&gt; catalog (getNewMail)
PUT /mail/order { serviceType, coupon? }           -&gt; quote (putMail)
POST /mail/order { serviceType, coupon?, comment? } -&gt; { serviceId, real_iids }
GET /billing/pay/cc/{real_iids[0]}                 -&gt; pay (initiatePayment)
GET /mail/{serviceId}                              -&gt; poll until mail_status&#x3D;&#x3D;&#x27;active&#x27;
&#x60;&#x60;&#x60;

     * @param body  
     */
    @Location("/mail/order") class addMail(val body: MailOrderRequest)

    /**
     * Create a new deny rule to auto-block matching submissions
     * Inserts a new &#x60;mail_spam&#x60; row scoped to this service&#x27;s &#x60;mail_username&#x60; so the relay drops matching submissions. Sibling ops: &#x60;getRules&#x60;, &#x60;updateRule&#x60;, &#x60;deleteRule&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (schema &#x60;DenyRuleNew&#x60;):**
- &#x60;type&#x60; (string, required) — &#x60;domain&#x60; / &#x60;email&#x60; / &#x60;startswith&#x60; / &#x60;destination&#x60;.
- &#x60;data&#x60; (string, required) — literal value matched; validation: no quotes, valid domain for &#x60;type&#x3D;domain&#x60;, valid email for &#x60;type&#x3D;email&#x60;, &#x60;[A-Z0-9+_.-]+&#x60; for &#x60;startswith&#x60;.

**Returns:** &#x60;&quot;Spam Block Added&quot;&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** field-level errors on validation failure, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body These are the fields needed to create a new email deny rule. 
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/rules") class addRule(val body: DenyRuleNew, val id: kotlin.Int)

    /**
     * Create a new Mail Baby alert for delivery, bounce, or quota events
     * Inserts a new alert row via the &#x60;Alert&#x60; ORM. The new &#x60;alert_id&#x60; is retrievable via &#x60;getMailAlerts&#x60;. Sibling ops: &#x60;getMailAlerts&#x60;, &#x60;updateMailAlert&#x60;, &#x60;deleteMailAlert&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (schema &#x60;MailAlertRequest&#x60;):**
- &#x60;type&#x60; (string, required).
- &#x60;value&#x60; (string/numeric, required) — threshold.
- &#x60;to&#x60; (string, required) — notification email; validated via &#x60;FILTER_VALIDATE_EMAIL&#x60;.
- &#x60;enabled&#x60; (bool, optional).

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** field-level errors for missing/invalid body, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/alerts") class createMailAlert(val body: MailAlertRequest, val id: kotlin.Int)

    /**
     * Delete a Mail Baby alert by alert_id (hard delete — no recovery)
     * Hard-deletes a single alert row. Handler verifies the alert belongs to this service+module before deleting. **Irreversible** — no history is preserved; recreate via &#x60;createMailAlert&#x60; if needed. Sibling ops: &#x60;getMailAlerts&#x60;, &#x60;createMailAlert&#x60;, &#x60;updateMailAlert&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields:**
- &#x60;alert_id&#x60; (integer, required) — from &#x60;getMailAlerts&#x60;.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;Invalid alert!&#x60; (alert not owned), &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/alerts") class deleteMailAlert(val body: IdAlertsBody, val id: kotlin.Int)

    /**
     * Delete a Mail Baby deny rule by rule ID (hard delete — no recovery)
     * Hard-deletes a single &#x60;mail_spam&#x60; row scoped to this service&#x27;s &#x60;mail_username&#x60;. **Irreversible** — no audit copy preserved. Query filter &#x60;id&#x3D;{rule} AND user&#x3D;&#x27;{mail_username}&#x27;&#x60; prevents cross-tenant deletes; passing a &#x60;rule&#x60; belonging to a different mail order is silently a no-op (still returns success). Sibling ops: &#x60;getRules&#x60;, &#x60;addRule&#x60;, &#x60;updateRule&#x60;.

**Path params:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.
- &#x60;rule&#x60; (string, required) — rule id from &#x60;getRules&#x60;.

**Returns:** &#x60;&quot;Block deleted successfully.&quot;&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     * @param rule The ID of the Rules entry. 
     */
    @Location("/mail/{id}/rules/{rule}") class deleteRule(val id: kotlin.Int, val rule: kotlin.String)

    /**
     * Delist a sender email from rspamd / mailchannels / mailbaby block lists
     * Removes block rows for the supplied email across the three reputation stores: &#x60;rspamd&#x60; (by &#x60;fromemail&#x60;), &#x60;mailchannels&#x60; (by &#x60;email&#x60;), &#x60;mailbaby&#x60; (by &#x60;emailfrom&#x60;). Functionally equivalent to &#x60;postMailDelist&#x60; but uses &#x60;email&#x60; parameter naming and returns 400 (not error JSON) for an invalid address. Sibling ops: &#x60;getMailBlocks&#x60;, &#x60;getMailDelist&#x60;, &#x60;postMailDelist&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (schema &#x60;EmailAddress&#x60;):**
- &#x60;email&#x60; (string, required) — sender address; validated via &#x60;FILTER_VALIDATE_EMAIL&#x60;.

**Returns:** &#x60;{status: &quot;ok&quot;, text: &quot;Email &#x27;...&#x27; removed from block list&quot;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;400&#x60; invalid email, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param email  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/blocks/delete") class delistBlock(val email: kotlin.String, val id: kotlin.Int)

    /**
     * List configured delivery/bounce/quota alerts for one Mail Baby service
     * Returns every alert row from &#x60;alerts&#x60; matching this service. Each row carries &#x60;alert_id&#x60; (use with PUT/DELETE), &#x60;alert_type&#x60;, &#x60;alert_value&#x60; (threshold), &#x60;alert_to&#x60; (notification email), &#x60;alert_enabled&#x60;, and timestamps. Sibling ops: &#x60;createMailAlert&#x60;, &#x60;updateMailAlert&#x60;, &#x60;deleteMailAlert&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns** (schema &#x60;MailAlertsResponse&#x60;): array of alert rows.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/alerts") class getMailAlerts(val id: kotlin.Int)

    /**
     * List recent local-blocklist hits and spam-trap captures for the mail user
     * Returns relay-side block events for the SMTP user behind &#x60;mail_id&#x60; — the last 24 hours of &#x60;LOCAL_BL_RCPT&#x60; and &#x60;MBTRAP&#x60; rspamd hits, plus a 3-day window of suspicious-subject hits (credential-leak heuristic firing on subjects containing &#x60;@&#x60; / &#x60;smtp&#x60; / &#x60;socks5&#x60; / &#x60;socks4&#x60; more than 4 times). Use the &#x60;from&#x60; value with &#x60;delistBlock&#x60; or &#x60;postMailDelist&#x60; to clear a block. Sibling ops: &#x60;delistBlock&#x60;, &#x60;getMailDelist&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns** (schema &#x60;MailBlocks&#x60;):
- &#x60;local&#x60; (array) — rspamd &#x60;LOCAL_BL_RCPT&#x60; hits: &#x60;{date, from, messageId, subject, to}&#x60;.
- &#x60;mbtrap&#x60; (array) — spam-trap captures (&#x60;MBTRAP&#x60; symbol): same shape.
- &#x60;subject&#x60; (array) — senders flagged by subject-line heuristic: &#x60;{from, subject}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;mail_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Clear a block:** &#x60;delistBlock&#x60; (POST &#x60;/mail/{id}/blocks/delete&#x60;).
- **Broader delist UI:** &#x60;getMailDelist&#x60;, &#x60;postMailDelist&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/blocks") class getMailBlocks(val id: kotlin.Int)

    /**
     * Read blocklist diagnostics and find senders eligible for delisting
     * Returns a richer diagnostic snapshot than &#x60;getMailBlocks&#x60; — intended for the delist UI. Use any &#x60;SMTPFrom&#x60;/&#x60;from&#x60; value as the &#x60;unblock&#x60; field for &#x60;postMailDelist&#x60;. Sibling ops: &#x60;postMailDelist&#x60;, &#x60;getMailBlocks&#x60;, &#x60;delistBlock&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns** (schema &#x60;MailDelistResponse&#x60;):
- &#x60;id&#x60; (integer) — &#x60;mail_id&#x60; echo.
- &#x60;local&#x60;, &#x60;mbtrap&#x60; (array) — last 24h rspamd hits with capitalized keys (&#x60;Date&#x60;, &#x60;SMTPFrom&#x60;, &#x60;MessageId&#x60;, &#x60;Subject&#x60;, &#x60;MimeRecipients&#x60;).
- &#x60;subject&#x60; (array) — credential-leak-heuristic firings (3-day window).
- &#x60;manual&#x60; (array) — manually added blocks.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/delist") class getMailDelist(val id: kotlin.Int)

    /**
     * Read delivered vs bounced totals broken down by sender (or by recipient domain)
     * Returns deliverability analytics from &#x60;MailDeliveryStats&#x60; (Dragonfly cache) for the SMTP user behind &#x60;mail_id&#x60;. Default pivot is by sender; pass &#x60;?filter_domain&#x3D;1&#x60; to pivot by recipient domain for the current year instead. Use to drive analytics dashboards. Sibling ops: &#x60;getStats&#x60;, &#x60;viewMailLog&#x60;, &#x60;getMailBlocks&#x60;, &#x60;getMailDelist&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Query params:**
- &#x60;filter_domain&#x60; (string &#x60;1&#x60;, optional) — pivot by recipient domain instead of sender.

**Returns** (schema &#x60;MailDeliverabilityResponse&#x60;):
- &#x60;stat&#x60;: &#x60;{delivered, bounced, percent}&#x60; — totals and bounce ratio.
- &#x60;header&#x60; (string), &#x60;col1&#x60; (string) — table headers.
- &#x60;table_data&#x60; (array) — rows of &#x60;[&lt;sender-or-domain&gt;, bounced, delivered, bouncePercent]&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/deliverability") class getMailDeliverability(val id: kotlin.Int)

    /**
     * Read full detail for one Mail Baby service including SMTP credentials
     * Returns the full &#x60;ViewMail&#x60; payload for one Mail Baby service — &#x60;serviceInfo&#x60;, &#x60;serviceType&#x60;, and &#x60;client_links&#x60; (URLs rewritten to API paths, e.g. &#x60;view_mail_log&#x60; → &#x60;log&#x60;). Admin fields (&#x60;admin_links&#x60;, &#x60;settings&#x60;, &#x60;csrf&#x60;) stripped. Use to render a service dashboard or retrieve SMTP host/username for MTA configuration. Sibling ops: &#x60;getMailList&#x60;, &#x60;updateMailInfo&#x60;, &#x60;mailCancel&#x60;, &#x60;resetMailPassword&#x60;, &#x60;getMailWelcomeEmail&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns** (schema &#x60;MailSchema&#x60;):
- &#x60;serviceInfo&#x60; — &#x60;mail_id&#x60;, &#x60;mail_username&#x60; (e.g. &#x60;mb1234&#x60;), &#x60;mail_status&#x60;, &#x60;mail_invoice&#x60;, &#x60;mail_custid&#x60;, dates, currency.
- &#x60;serviceType&#x60; — plan row (&#x60;services_ourcost&#x60; stripped).
- &#x60;client_links&#x60; (array) — action URLs (log, alerts, blocks, etc.).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Send:** &#x60;sendMail&#x60; / &#x60;sendAdvMail&#x60;.
- **Rotate password:** &#x60;resetMailPassword&#x60;.
- **Reset credentials:** &#x60;getMailWelcomeEmail&#x60;.
- **Cancel:** &#x60;mailCancel&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}") class getMailInfo(val id: kotlin.Int)

    /**
     * List billing invoices linked to this Mail Baby service
     * Returns every invoice associated with this &#x60;mail_id&#x60; via the shared &#x60;InvoicesList&#x60; workflow. Use to render per-service billing history or find unpaid invoices to pay via &#x60;initiatePayment&#x60;. Sibling ops: &#x60;getBillingInvoice&#x60;, &#x60;initiatePayment&#x60;, &#x60;addMail&#x60;, &#x60;mailCancel&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns:** &#x60;ChargeInvoiceRows&#x60; — array of &#x60;{id, amount, currency, paid, date, due_date, description, module: &quot;mail&quot;, service}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404 Invalid Service&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/invoices") class getMailInvoices(val id: kotlin.Int)

    /**
     * List every Mail Baby SMTP relay service on the account
     * Enumerates every Mail Baby SMTP relay service owned by the authenticated customer. Canonical entry point for finding a &#x60;mail_id&#x60; to pass to other Mail endpoints. Filtered server-side by &#x60;mail_custid&#x60;. Sibling ops: &#x60;getMailInfo&#x60;, &#x60;getStats&#x60;, &#x60;viewMailLog&#x60;, &#x60;getMailDeliverability&#x60;, &#x60;getMailBlocks&#x60;, &#x60;getMailInvoices&#x60;, &#x60;addMail&#x60;.

**Path/Query/Body:** None.

**Returns:** Array of &#x60;MailRow&#x60;:
- &#x60;mail_id&#x60; (integer) — canonical id.
- &#x60;mail_username&#x60; (string) — SMTP username (e.g. &#x60;mb1234&#x60;).
- &#x60;mail_status&#x60; (string enum) — &#x60;active&#x60; / &#x60;pending&#x60; / &#x60;canceled&#x60; / &#x60;suspended&#x60;.
- &#x60;services_name&#x60; (string) — plan label.
- &#x60;repeat_invoices_cost&#x60; (decimal string) — recurring cost.

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Per-service detail:** &#x60;getMailInfo&#x60;.
- **Send mail:** &#x60;sendMail&#x60; / &#x60;sendAdvMail&#x60;.
- **Reputation:** &#x60;getMailDeliverability&#x60; / &#x60;getMailBlocks&#x60; / &#x60;getMailDelist&#x60;.
- **Order a new service:** &#x60;getNewMail&#x60; → &#x60;putMail&#x60; → &#x60;addMail&#x60;.

     */
    @Location("/mail") class getMailList()

    /**
     * Resend the Mail Baby welcome email with SMTP credentials and setup info
     * Re-runs the &#x60;mail_welcome_email&#x60; plugin function — composes and sends the standard welcome email (SMTP host &#x60;relay.mailbaby.net&#x60;, port, username &#x60;mb{mail_id}&#x60;, current password, configuration tips) to the account-on-file. Use after &#x60;resetMailPassword&#x60; to redeliver the rotated credential, or when a customer reports losing the original setup email. Idempotent. Sibling ops: &#x60;resetMailPassword&#x60;, &#x60;getMailInfo&#x60;. Cross-module welcome-email endpoints: &#x60;getVpsWelcomeEmail&#x60;, &#x60;getWebsitesWelcomeEmail&#x60;, &#x60;getDomainsWelcomeEmail&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns:** &#x60;{text: &quot;Welcome Email has been resent.&quot;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/welcome_email") class getMailWelcomeEmail(val id: kotlin.Int)

    /**
     * Read the Mail Baby order catalog — plans, package costs, service-type metadata
     * Step 1 of the Mail Baby order flow. Returns the catalog used to bootstrap an order form: &#x60;packageCosts&#x60; keyed by &#x60;services_id&#x60; (only buyable services where &#x60;services_buyable&#x3D;1&#x60;) and the full &#x60;serviceTypes&#x60; map. Read-only. Pricing is normalized to the customer&#x27;s currency via &#x60;getCurrency()&#x60;. Sibling ops: &#x60;putMail&#x60;, &#x60;addMail&#x60;, &#x60;getMailList&#x60;.

**Path/Query/Body:** None.

**Returns** (schema &#x60;MailOrder&#x60;):
- &#x60;packageCosts&#x60; (object) — &#x60;{&lt;services_id&gt;: &lt;cost&gt;}&#x60; per buyable plan.
- &#x60;serviceTypes&#x60; (object) — full service-types registry (plan metadata).

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Next:** &#x60;putMail&#x60; (validate + quote — no charge), &#x60;addMail&#x60; (place order).

     */
    @Location("/mail/order") class getNewMail()

    /**
     * List configured deny rules (sender/recipient blocks) for a Mail Baby service
     * Returns every &#x60;mail_spam&#x60; row scoped to this service&#x27;s &#x60;mail_username&#x60; — local sender/recipient block rules the customer has configured. Sibling ops: &#x60;addRule&#x60;, &#x60;updateRule&#x60;, &#x60;deleteRule&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns:** Array of &#x60;DenyRuleRecord&#x60; — &#x60;{id, user, type, data, created}&#x60;. &#x60;type&#x60; values:
- &#x60;domain&#x60; — block by sender domain.
- &#x60;email&#x60; — block by exact sender email.
- &#x60;startswith&#x60; — block when sender local-part starts with a string.
- &#x60;destination&#x60; — block by recipient email.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/rules") class getRules(val id: kotlin.Int)

    /**
     * Read Mail Baby usage counts, send volume totals, top destinations, and projected cost
     * Returns aggregate usage and cost metrics for the SMTP user behind &#x60;mail_id&#x60; from the ZoneMTA &#x60;mail_messagestore&#x60; / &#x60;mail_senderdelivered&#x60; tables. Use to drive an analytics dashboard or to project end-of-cycle cost. Sibling ops: &#x60;viewMailLog&#x60;, &#x60;getMailDeliverability&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Query params:**
- &#x60;time&#x60; (string enum, optional, default &#x60;1h&#x60;) — window: &#x60;all&#x60; / &#x60;billing&#x60; (current invoice cycle) / &#x60;month&#x60; / &#x60;7d&#x60; / &#x60;24h&#x60; / &#x60;1d&#x60; / &#x60;1h&#x60;.

**Returns** (schema &#x60;MailStatsType&#x60;):
- &#x60;time&#x60; (string) — echo of selected window.
- &#x60;usage&#x60; (integer) — full-billing-cycle send count.
- &#x60;currency&#x60;, &#x60;currencySymbol&#x60; (string).
- &#x60;cost&#x60; (decimal) — projected &#x3D; base + &#x60;$0.20 / 1000 emails&#x60;.
- &#x60;received&#x60;, &#x60;sent&#x60; (integer).
- &#x60;volume.to&#x60;, &#x60;volume.from&#x60;, &#x60;volume.ip&#x60; (object) — top-500 destinations / senders / origin IPs by count.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;Invalid or missing mail order id&#x60;, &#x60;401&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     * @param time The timeframe for the statistics. (optional)
     */
    @Location("/mail/{id}/stats") class getStats(val id: kotlin.Int, val time: kotlin.String)

    /**
     * Cancel a Mail Baby service and stop the recurring invoice
     * Cancels the Mail Baby service through the shared &#x60;Billing\CancelService::go($id)&#x60; flow with &#x60;module&#x3D;&#x27;mail&#x27;&#x60;. SMTP credentials are deactivated, the service transitions to canceled, the &#x60;repeat_invoice&#x60; is stopped, and queued submissions stop being accepted. **Irreversible via API** — re-activation requires placing a new order via &#x60;addMail&#x60;. Sibling ops: &#x60;getMailInfo&#x60;, &#x60;getMailInvoices&#x60;, &#x60;addMail&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns:** &#x60;MailCancelResponse&#x60;.

**Side effects:**
- Sets &#x60;mail_status&#x3D;&#x27;canceled&#x27;&#x60;.
- Marks &#x60;repeat_invoices&#x60; non-renewing.
- ZoneMTA-side: stops accepting new submissions for &#x60;mb{mail_id}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Sibling cancels:** &#x60;VPSCancel&#x60;, &#x60;CancelDomain&#x60;, &#x60;webhostingCancel&#x60;, etc.
- **Re-provision:** &#x60;addMail&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}") class mailCancel(val id: kotlin.Int)

    /**
     * Delist a sender from rspamd / mailchannels / mailbaby block lists
     * Removes all block rows for one sender email across three reputation stores: &#x60;rspamd&#x60; (by &#x60;fromemail&#x60;), &#x60;mailchannels&#x60; (by &#x60;email&#x60;), &#x60;mailbaby&#x60; (by &#x60;emailfrom&#x60;). Effect is global per-address across all three tables; takes effect immediately for new submissions. Sibling ops: &#x60;getMailDelist&#x60;, &#x60;delistBlock&#x60; (alias at &#x60;/mail/{id}/blocks/delete&#x60;), &#x60;getMailBlocks&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (schema &#x60;MailDelistRequest&#x60;):**
- &#x60;unblock&#x60; (string, required) — sender email from &#x60;getMailDelist&#x60;/&#x60;getMailBlocks&#x60;.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;Missing parameter unblock&#x60;, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/delist") class postMailDelist(val body: MailDelistRequest, val id: kotlin.Int)

    /**
     * Validate Mail Baby order, quote pricing, and verify coupon — no charge
     * Step 2 of the Mail Baby order flow. Dry-runs the order through &#x60;validate_buy_mail()&#x60; without creating invoices. Returns the cost preview, coupon resolution, and validation errors. The endpoint also auto-generates an SMTP password preview the order will use. Use to surface live pricing in the UI before &#x60;addMail&#x60;. Sibling ops: &#x60;getNewMail&#x60;, &#x60;addMail&#x60;.

**Body fields:**
- &#x60;serviceType&#x60; (integer, required) — plan id from &#x60;getNewMail.packageCosts&#x60; keys.
- &#x60;coupon&#x60; (string, optional) — coupon code.

**Returns:**
- &#x60;continue&#x60; (bool) — &#x60;true&#x60; if order can safely be POSTed.
- &#x60;errors&#x60; (array) — validation messages.
- &#x60;serviceType&#x60;, &#x60;serviceCost&#x60;, &#x60;originalCost&#x60;, &#x60;repeatServiceCost&#x60; (numeric).
- &#x60;password&#x60; (string) — auto-generated SMTP password preview.
- &#x60;introFrequency&#x60; (integer).
- &#x60;coupon&#x60;, &#x60;couponCode&#x60; (string/integer) — resolved coupon.

**Auth:** Session/API key.

**Errors:**
- &#x60;200&#x60; with &#x60;continue&#x3D;false&#x60; and &#x60;errors[]&#x60; — validation problems.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Prerequisite:** &#x60;getNewMail&#x60; (catalog).
- **Place order:** &#x60;addMail&#x60;.

     * @param body  
     */
    @Location("/mail/order") class putMail(val body: MailOrderRequest)

    /**
     * Rotate the SMTP password and email the new credential to the account owner
     * Generates a new 20-char SMTP password (lower/upper/digits via &#x60;generate_password&#x60;), writes it to the ZoneMTA Mongo &#x60;users&#x60; collection for username &#x60;mb{mail_id}&#x60;, logs the change to &#x60;App::history()&#x60;, and emails the result to the account-on-file via &#x60;client_email.tpl&#x60;. **Any MTA, app, or saved client still using the old password will start failing auth immediately.** The new password is **not** returned in the response — fetch via &#x60;getMailWelcomeEmail&#x60; or &#x60;getMailInfo&#x60;. Sibling ops: &#x60;getMailWelcomeEmail&#x60;, &#x60;getMailInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Side effects:**
- Mongo update on ZoneMTA &#x60;users&#x60; for &#x60;mb{mail_id}&#x60;.
- &#x60;App::history()&#x60; audit entry.
- Email sent to account owner.

**Auth:** Session/API key. Ownership enforced.

**Errors:** Mongo update modified 0 rows → error text; &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/reset_password") class resetMailPassword(val id: kotlin.Int)

    /**
     * Send email via Mail Baby SMTP relay with attachments, CC/BCC, and multi-recipient
     * Submits an outbound message through &#x60;relay.mailbaby.net:25&#x60; using the service&#x27;s SMTP credentials (fetched via &#x60;mail_get_password&#x60;). Use for multi-recipient sends, named addresses, CC/BCC, ReplyTo, or attachments. For single-recipient plain sends, &#x60;sendMail&#x60; is the lighter option. Sibling ops: &#x60;sendMail&#x60;, &#x60;viewMailLog&#x60; (find queued message), &#x60;getMailDeliverability&#x60; (analyze bounces).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (JSON or form-urlencoded, schema &#x60;SendMailAdv&#x60;):**
- &#x60;from&#x60; (string or &#x60;{email, name}&#x60;, required).
- &#x60;to&#x60; (array of strings or &#x60;{email, name}&#x60; objects, required).
- &#x60;subject&#x60; (string, required).
- &#x60;body&#x60; (string, required) — HTML auto-detected when tags are present.
- &#x60;replyto&#x60; (array, optional) — same shape as &#x60;to&#x60;.
- &#x60;cc&#x60;, &#x60;bcc&#x60; (array, optional) — same shape as &#x60;to&#x60;.
- &#x60;attachments&#x60; (array, optional) — each &#x60;{filename, data}&#x60; where &#x60;data&#x60; is base64-encoded; added via &#x60;addStringAttachment&#x60;.

**Returns:** &#x60;{status: &quot;ok&quot;, text: &quot;Email queued successfully&quot;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;400&#x60; with PHPMailer &#x60;ErrorInfo&#x60; on send failure or missing required field.
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service Passed&#x60;.
- &#x60;409 Service is not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/advsend") class sendAdvMail(val body: SendMailAdv, val id: kotlin.Int)

    /**
     * Send a simple single-recipient email through the Mail Baby SMTP relay
     * Sends a single-recipient transactional email through &#x60;relay.mailbaby.net:25&#x60; authenticated as this &#x60;mail_id&#x60;. Body fields are the minimum needed for a plain send; Reply-To is auto-set to &#x60;from&#x60;. For multi-recipient sends, CC/BCC, named addresses, or attachments use &#x60;sendAdvMail&#x60; instead. Sibling ops: &#x60;sendAdvMail&#x60;, &#x60;viewMailLog&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (JSON or form-urlencoded, schema &#x60;SendMail&#x60;):**
- &#x60;to&#x60; (string, required) — recipient email.
- &#x60;from&#x60; (string, required) — sender email.
- &#x60;subject&#x60; (string, required).
- &#x60;body&#x60; (string, required) — HTML auto-detected when tags are present.

**Returns:** &#x60;{status: &quot;ok&quot;, text: &quot;Email queued successfully&quot;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;400&#x60; with PHPMailer &#x60;ErrorInfo&#x60; on send failure or missing required field, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/send") class sendMail(val body: SendMail, val id: kotlin.Int)

    /**
     * Update an existing Mail Baby alert by alert_id
     * Updates a single alert row by &#x60;alert_id&#x60;. Handler verifies the alert belongs to this service+module before writing. Sibling ops: &#x60;getMailAlerts&#x60;, &#x60;createMailAlert&#x60;, &#x60;deleteMailAlert&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body fields (schema &#x60;MailAlertUpdateRequest&#x60;):**
- &#x60;alert_id&#x60; (integer, required) — from &#x60;getMailAlerts&#x60;.
- &#x60;type&#x60; (string, required).
- &#x60;value&#x60; (string/numeric, required) — threshold.
- &#x60;to&#x60; (string, required) — notification email; validated via &#x60;FILTER_VALIDATE_EMAIL&#x60;.
- &#x60;enabled&#x60; (bool, optional).

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;Invalid alert!&#x60; (alert not owned), field-level errors for missing/invalid body, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}/alerts") class updateMailAlert(val body: MailAlertUpdateRequest, val id: kotlin.Int)

    /**
     * POST mutation hook for the Mail Baby service detail page
     * POST mutation hook for the Mail Baby service detail page. Currently delegates to the same &#x60;View::go()&#x60; handler as &#x60;getMailInfo&#x60; — placeholder for future field updates. Does NOT rotate credentials (use &#x60;resetMailPassword&#x60;) and does NOT change billing (use &#x60;/billing&#x60; endpoints). Sibling ops: &#x60;getMailInfo&#x60;, &#x60;mailCancel&#x60;, &#x60;resetMailPassword&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.

**Body:** Form fields.

**Returns:** &#x60;SuccessTextResponse&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — &#x60;mail_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Read:** &#x60;getMailInfo&#x60;.
- **Rotate password:** &#x60;resetMailPassword&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     */
    @Location("/mail/{id}") class updateMailInfo(val id: kotlin.String)

    /**
     * Update an existing Mail Baby deny rule&#x27;s type and match data
     * Updates &#x60;type&#x60; and &#x60;data&#x60; on a single &#x60;mail_spam&#x60; row. Query is bounded by &#x60;id&#x3D;{rule} AND user&#x3D;&#x27;{mail_username}&#x27;&#x60; so cross-tenant updates are impossible. Same validation rules as &#x60;addRule&#x60;. Sibling ops: &#x60;getRules&#x60;, &#x60;addRule&#x60;, &#x60;deleteRule&#x60;.

**Path params:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60;.
- &#x60;rule&#x60; (string, required) — rule id from &#x60;getRules&#x60;.

**Body fields (schema &#x60;DenyRuleNew&#x60;):**
- &#x60;type&#x60; (string, required) — &#x60;domain&#x60; / &#x60;email&#x60; / &#x60;startswith&#x60; / &#x60;destination&#x60;.
- &#x60;data&#x60; (string, required) — see &#x60;addRule&#x60; for type-specific validation.

**Returns:** &#x60;&quot;Record updated successfully.&quot;&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** field-level errors on validation failure, &#x60;401&#x60;, &#x60;404&#x60;, &#x60;409 not active&#x60;.

     * @param body  
     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     * @param rule The ID of the deny rule to update. 
     */
    @Location("/mail/{id}/rules/{rule}") class updateRule(val body: DenyRuleNew, val id: kotlin.Int, val rule: kotlin.String)

    /**
     * Search and paginate per-message Mail Baby delivery log entries
     * Paginated search over ZoneMTA&#x27;s &#x60;mail_messagestore&#x60; joined with &#x60;mail_senderdelivered&#x60; and &#x60;mail_queuerelease&#x60;. Supports envelope, header, and metadata filters; sortable; choose recipient-level or message-level grouping. Use to investigate delivery issues, find specific messages by Message-ID, audit bounce rates, or feed an analytics dashboard. Sibling ops: &#x60;getStats&#x60;, &#x60;getMailDeliverability&#x60;, &#x60;delistBlock&#x60; (clear a block surfaced by a bounce).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;mail_id&#x60; from &#x60;getMailList&#x60; (omit to span all owned mail users — admin-only).

**Query params:**
- &#x60;from&#x60;, &#x60;to&#x60; (string) — envelope address, exact match.
- &#x60;headerfrom&#x60;, &#x60;replyto&#x60; (string) — header address, exact match; validated as email.
- &#x60;subject&#x60; (string) — LIKE match on subject.
- &#x60;mailid&#x60; (string, 18–19 chars) — relay id, exact.
- &#x60;messageId&#x60; (string) — Message-ID header, substring match.
- &#x60;origin&#x60; (string) — submitter IP, exact.
- &#x60;mx&#x60; (string) — destination MX hostname, LIKE.
- &#x60;delivered&#x60; (integer 0/1).
- &#x60;startDate&#x60;, &#x60;endDate&#x60; (Unix timestamp or &#x60;strtotime&#x60;-parseable string).
- &#x60;skip&#x60; (integer, default 0), &#x60;limit&#x60; (integer 1–10000, default 100).
- &#x60;sort&#x60; (&#x60;time&#x60;), &#x60;dir&#x60; (&#x60;asc&#x60;/&#x60;desc&#x60;, default &#x60;desc&#x60;).
- &#x60;groupby&#x60; (&#x60;recipient&#x60; default — one row per delivery attempt; &#x60;message&#x60; — one row per &#x60;_id&#x60;).

**Returns** (schema &#x60;MailLog&#x60;):
&#x60;{total, skip, limit, emails: [{id, _id, from, to, subject, messageId, time, mxHostname, delivered, code, response, recipient, ...}]}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:** &#x60;400&#x60; bad input, &#x60;401&#x60;.

     * @param id The mail service ID. Use &#x60;mail_id&#x60; from &#x60;GET /mail&#x60;. 
     * @param id The numeric ID of the mail order to filter by.  When omitted, logs from the first active mail order are returned.  Obtain valid IDs from &#x60;GET /mail&#x60; or &#x60;GET /mail/{id}&#x60;. (optional)
     * @param origin Filter by the originating IP address from which the message was submitted to the relay.  Must be a valid IPv4 or IPv6 address. (optional)
     * @param mx Filter by the MX hostname the relay attempted delivery to.  For example &#x60;mx.google.com&#x60; would return messages destined for Gmail recipients. Maps to &#x60;mxHostname&#x60; in the &#x60;MailLogEntry&#x60; response. (optional)
     * @param from Filter by SMTP envelope &#x60;MAIL FROM&#x60; address (exact match).  This is the address the relay used for bounce handling and may differ from the &#x60;From:&#x60; message header.  For header-level filtering use &#x60;headerfrom&#x60;. (optional)
     * @param to Filter by SMTP envelope &#x60;RCPT TO&#x60; address (exact match).  This is the delivery address used by the relay and may differ from the &#x60;To:&#x60; header when BCC recipients are involved. (optional)
     * @param subject Filter by email &#x60;Subject&#x60; header (exact match).  MIME-encoded subjects are decoded automatically in the response. (optional)
     * @param mailid Filter by the relay-assigned mail ID string (exact match).  This corresponds to the &#x60;id&#x60; field in &#x60;MailLogEntry&#x60; and to the &#x60;text&#x60; value returned by the sending endpoints on success.  Format is an 18-19 character hexadecimal string such as &#x60;185997065c60008840&#x60;. (optional)
     * @param messageId Filter by the &#x60;Message-ID&#x60; email header using a substring (case-insensitive) match. The &#x60;Message-ID&#x60; is assigned by the sending mail client and is visible in the &#x60;messageId&#x60; field of &#x60;MailLogEntry&#x60;. (optional)
     * @param replyto Filter by the &#x60;Reply-To&#x60; message header address (exact match).  Only returns messages where this header was explicitly set. (optional)
     * @param headerfrom Filter by the &#x60;From&#x60; message header address (exact match).  This is the human-visible sender address and may differ from the SMTP envelope &#x60;from&#x60; parameter when sending on behalf of another address. (optional)
     * @param delivered Filter by delivery status.  &#x60;1&#x60; returns only messages that were successfully delivered to the destination MX.  &#x60;0&#x60; returns messages that are still queued, deferred, or failed.  Omit to return all messages regardless of delivery status. (optional)
     * @param skip Number of records to skip for pagination.  Use in combination with &#x60;limit&#x60; to page through large result sets.  Defaults to &#x60;0&#x60; (no skip). (optional, default to 0)
     * @param limit Maximum number of records to return per page.  Defaults to &#x60;100&#x60;. Maximum allowed value is &#x60;10000&#x60;.  The response also includes a &#x60;total&#x60; field with the full matched count so you can calculate the number of pages. (optional, default to 100)
     * @param startDate Earliest date to include.  Accepts either a Unix timestamp (integer seconds since epoch) or a date string parseable by &#x60;strtotime()&#x60; such as &#x60;2024-01-15&#x60; or &#x60;last monday&#x60;.  Messages with a &#x60;time&#x60; value **greater than or equal to** this value will be included. (optional)
     * @param endDate Latest date to include.  Accepts either a Unix timestamp (integer seconds since epoch) or a date string parseable by &#x60;strtotime()&#x60; such as &#x60;2024-01-31&#x60; or &#x60;yesterday&#x60;. Messages with a &#x60;time&#x60; value **less than or equal to** this value will be included. (optional)
     * @param sort Field to sort results by.  Currently only &#x60;time&#x60; is supported (sorts by internal row ID which corresponds to chronological order). (optional, default to time)
     * @param dir Sort direction.  &#x60;desc&#x60; returns newest first (default), &#x60;asc&#x60; returns oldest first. (optional, default to desc)
     * @param groupby Controls how results are grouped.  &#x60;recipient&#x60; (default) returns one row per delivery attempt — a message sent to 4 recipients produces 4 rows, each with its own &#x60;recipient&#x60;, &#x60;delivered&#x60;, &#x60;response&#x60;, and delivery metadata.  &#x60;message&#x60; collapses to one row per unique message ID; delivery-level fields will reflect one arbitrary recipient per message.  The &#x60;total&#x60; count in the response matches the grouping mode. (optional, default to recipient)
     */
    @Location("/mail/{id}/log") class viewMailLog(val id: kotlin.Int, val id: kotlin.Long, val origin: kotlin.String, val mx: kotlin.String, val from: kotlin.String, val to: kotlin.String, val subject: kotlin.String, val mailid: kotlin.String, val messageId: kotlin.String, val replyto: kotlin.String, val headerfrom: kotlin.String, val delivered: kotlin.Int, val skip: kotlin.Int, val limit: kotlin.Int, val startDate: StartDate, val endDate: EndDate, val sort: kotlin.String, val dir: kotlin.String, val groupby: kotlin.String)

    /**
     * List enabled currency codes accepted for billing and preferences
     * Populates a currency selector on signup, billing-preferences, or invoice-display forms. Public — no auth required. The list changes only when an admin enables/disables a currency — cache client-side. Sibling ops: &#x60;getCountries&#x60;, &#x60;getTimezones&#x60;, &#x60;getAccountLocales&#x60;, plus the billing-preference endpoints under &#x60;/account/*&#x60; and &#x60;/billing/*&#x60;.

**Path/Query/Body:** None.

**Returns:** flat JSON array of ISO-4217 currency codes — e.g. &#x60;[&quot;USD&quot;, &quot;EUR&quot;, &quot;GBP&quot;, &quot;INR&quot;]&#x60;. Sourced from rows in the &#x60;currencies&#x60; table where &#x60;currency_enabled&#x3D;1&#x60;, in the natural row order. The endpoint returns codes only — for symbols, decimals, or exchange rates use a separate currency-detail endpoint or a static client-side map.

**Auth:** None.

**Errors:** No documented error path.

**Related calls:**
- **Apply to account profile:** &#x60;updateAccountInfo&#x60;.
- **Other preference catalogs:** &#x60;getCountries&#x60;, &#x60;getTimezones&#x60;, &#x60;getAccountLocales&#x60;.

     */
    @Location("/account/currencies") class getAccountCurrencies()

    /**
     * List supported UI locales with English and native display names
     * Renders the language-picker for account preferences or login pages. Public — no auth required. Cross-references PHP&#x27;s Punic locale data with &#x60;locale/google_langs.php&#x60; so only locales with Google Translate support are returned. Result is essentially static — cache client-side. Sibling ops: &#x60;getCountries&#x60;, &#x60;getTimezones&#x60;, &#x60;getAccountCurrencies&#x60;, &#x60;updateAccountInfo&#x60; (consumes the chosen locale).

**Path/Query/Body:** None.

**Returns:** JSON object keyed by BCP-47-style locale code, with &#x60;{ name, local_name }&#x60; per entry — e.g.

    {
      &quot;en&quot;: { &quot;name&quot;: &quot;English&quot;, &quot;local_name&quot;: &quot;English&quot; },
      &quot;es&quot;: { &quot;name&quot;: &quot;Spanish&quot;, &quot;local_name&quot;: &quot;español&quot; },
      &quot;fr&quot;: { &quot;name&quot;: &quot;French&quot;, &quot;local_name&quot;: &quot;français&quot; }
    }

&#x60;name&#x60; is the English label; &#x60;local_name&#x60; is the locale&#x27;s name in its own language (good for accessibility and avoiding the wrong-script problem).

**Auth:** None.

**Errors:** No documented error path.

**Related calls:**
- **Apply to account profile:** &#x60;updateAccountInfo&#x60; (sets &#x60;locale&#x60;).
- **Other preference catalogs:** &#x60;getCountries&#x60;, &#x60;getTimezones&#x60;, &#x60;getAccountCurrencies&#x60;.

     */
    @Location("/account/locales") class getAccountLocales()

    /**
     * Fetch a base64 JPEG captcha challenge for human verification
     * Fetches a fresh captcha challenge image to display before submitting &#x60;submitSignup&#x60; (or any unauthenticated form that needs human verification). Public endpoint — no authentication required. Sibling ops: &#x60;getLoginInfo&#x60; (returns a captcha alongside other login-page data), &#x60;submitSignup&#x60; (consumes the answer), &#x60;submitLogin&#x60;.

**Path/Query/Body:** None.

**Returns:** &#x60;{ captcha: string }&#x60; — &#x60;captcha&#x60; is a &#x60;data:image/jpeg;base64,...&#x60; URL ready to drop into an &#x60;&lt;img src&gt;&#x60;.

**Side effects:** the phrase is stored server-side in &#x60;$_SESSION[&#x27;captcha&#x27;]&#x60; (also aliased to the signup-flow key &#x60;$_SESSION[&#x27;captchaSignup&#x27;]&#x60; and forgot-password key &#x60;$_SESSION[&#x27;captchaFP&#x27;]&#x60;). The browser must send the same &#x60;PHPSESSID&#x60; cookie back when posting the answer.

**Charset:** 8 chars from &#x60;3456789ABCDEFGHJKLMNPQRSTWXY&#x60; — no ambiguous &#x60;0&#x60;/&#x60;1&#x60;/&#x60;I&#x60;/&#x60;O&#x60;/&#x60;2&#x60;/&#x60;Z&#x60;.

**Related calls:**
- **Consumers:** &#x60;submitSignup&#x60;, &#x60;submitLogin&#x60;.
- **One-shot login bootstrap:** &#x60;getLoginInfo&#x60;.
answer in &#x60;captcha&#x60; field).

     */
    @Location("/captcha") class getCaptcha()

    /**
     * List enabled countries keyed by ISO-2/ISO-3/numeric code
     * Populates country dropdowns in account registration, billing-address forms, and domain/whois contact forms. Public — no auth required. Disabled countries (e.g. embargoed jurisdictions) are excluded — admins toggle this in &#x60;country_t.enabled&#x60;. Sibling ops: &#x60;getTimezones&#x60;, &#x60;getAccountLocales&#x60;, &#x60;getAccountCurrencies&#x60;, &#x60;updateAccountInfo&#x60; (consumes the chosen country).

**Query parameters:**
- &#x60;fetch_by&#x60; (string, optional) — one of &#x60;iso2&#x60; (default; two-letter codes like &#x60;US&#x60;, &#x60;GB&#x60;), &#x60;iso3&#x60; (three-letter like &#x60;USA&#x60;, &#x60;GBR&#x60;), or &#x60;numcode&#x60; (UN M49 numeric like &#x60;840&#x60;). Any other value silently falls back to &#x60;iso2&#x60;.

**Body:** None.

**Returns:** JSON object mapping the chosen key format to the country&#x27;s short name — e.g. &#x60;{ &quot;AF&quot;: &quot;Afghanistan&quot;, &quot;US&quot;: &quot;United States&quot;, &quot;ZW&quot;: &quot;Zimbabwe&quot; }&#x60;. Sourced from the &#x60;country_t&#x60; table, filtered to &#x60;enabled&#x3D;1&#x60;, ordered alphabetically by &#x60;short_name&#x60;.

**Auth:** None.

**Errors:** No documented error path.

**Related calls:**
- **Apply to account profile:** &#x60;updateAccountInfo&#x60;.
- **Other preference catalogs:** &#x60;getTimezones&#x60;, &#x60;getAccountLocales&#x60;, &#x60;getAccountCurrencies&#x60;.

     * @param fetchBy Get countries by iso2 or iso3 or numcode (optional)
     */
    @Location("/account/countries") class getCountries(val fetchBy: kotlin.String)

    /**
     * Discover available modules, service packages, categories, and types
     * Enumerates what services this MyAdmin install sells before placing orders or building a signup UI. Public — no auth required. Sibling ops: &#x60;getNewVps&#x60;, &#x60;getNewWebsite&#x60;, &#x60;getNewMail&#x60;, &#x60;getNewSsl&#x60;, &#x60;getNewLicense&#x60;, &#x60;getNewBackup&#x60;, &#x60;getNewQs&#x60;, &#x60;getNewServer&#x60; — each module&#x27;s catalog op for buyable-package details.

**Path/Query/Body:** None.

**Returns:** &#x60;{ modules, services, serviceTypes, serviceCategories }&#x60;.
- &#x60;modules&#x60; (array) — enabled plugin modules (&#x60;vps&#x60;, &#x60;webhosting&#x60;, &#x60;domains&#x60;, &#x60;ssl&#x60;, etc.).
- &#x60;services&#x60; (object) — map of &#x60;services_id&#x60; → row from the &#x60;services&#x60; table, filtered to &#x60;services_buyable&#x3D;1 AND services_hidden&#x3D;0&#x60;, with &#x60;services_ourcost&#x60; / &#x60;services_hidden&#x60; stripped, and &#x60;services_id&#x60; / &#x60;services_category&#x60; / &#x60;services_type&#x60; cast to int and &#x60;services_cost&#x60; cast to float.
- &#x60;serviceTypes&#x60; (object) — joins service rows to human-readable type names.
- &#x60;serviceCategories&#x60; (object) — joins service rows to category names.

**Auth:** None.

**Errors:** No documented error path; 401 only if a stricter auth layer is added upstream.

**Related calls:**
- **Module-specific order catalog:** &#x60;getNewVps&#x60;, &#x60;getNewWebsite&#x60;, &#x60;getNewMail&#x60;, &#x60;getNewSsl&#x60;, &#x60;getNewLicense&#x60;, &#x60;getNewBackup&#x60;, &#x60;getNewQs&#x60;, &#x60;getNewServer&#x60;.
- **Deeper health probe:** &#x60;pingServer&#x60;.

     */
    @Location("/info") class getInfo()

    /**
     * Fetch logo, captcha, language, and stats for rendering a login page
     * Bootstraps an unauthenticated login page in one round-trip — branding logo, fresh captcha challenge, auto-detected user language, and live counts of VPS / websites / servers managed by the system (often used as marketing stats). Public — no auth required. Sibling ops: &#x60;submitLogin&#x60; (consume the captcha), &#x60;getCaptcha&#x60; (refresh captcha only), &#x60;getAccountLocales&#x60;, &#x60;submitSignup&#x60;.

**Path/Query/Body:** None.

**Returns** &#x60;{ logo, captcha, language, counts }&#x60;:
- &#x60;logo&#x60; (string) — URL; uses the &#x60;LOGO&#x60; constant or a default.
- &#x60;captcha&#x60; (string) — &#x60;data:image/jpeg;base64,...&#x60; image; phrase is stored server-side under &#x60;$_SESSION[&#x27;captcha&#x27;]&#x60; (also aliased to &#x60;$_SESSION[&#x27;captchaSignup&#x27;]&#x60; and &#x60;$_SESSION[&#x27;captchaFP&#x27;]&#x60;) — the browser&#x27;s &#x60;PHPSESSID&#x60; cookie carries the phrase to &#x60;submitLogin&#x60; / &#x60;submitSignup&#x60;.
- &#x60;language&#x60; (string) — BCP-47 locale (e.g. &#x60;en-US&#x60;).
- &#x60;counts&#x60; (object) — &#x60;{ vps: int, websites: int, servers: int }&#x60; from live &#x60;SELECT COUNT(*)&#x60; on the underlying tables.

**Auth:** None.

**Errors:** &#x60;403&#x60; per &#x60;LoginResponseError&#x60; if a stricter login gate is configured upstream.

**Related calls:**
- **Next:** &#x60;submitLogin&#x60; (login form post) or &#x60;submitSignup&#x60; (new account).
- **Captcha refresh only:** &#x60;getCaptcha&#x60;.
- **OAuth alternative:** &#x60;getOauthRedirect&#x60;.

     */
    @Location("/login") class getLoginInfo()

    /**
     * List Rapid Deploy (Buy-It-Now) marketplace dedicated servers with live pricing
     * Use to browse pre-built dedicated servers ready for immediate provisioning (Rapid Deploy / marketplace). No params, no body. Pulls live inventory from &#x60;mynew.interserver.net/ajax/server_a.php&#x60;.
Returns: array of &#x60;{ server_id, cpu: [model, {img,type,speed,num_cpus,num_cores}], memory, disk, bandwidth, ips, location, price }&#x60;. The &#x60;server_id&#x60; is the marketplace asset id — feed it into &#x60;buyItNowServerOrder&#x60; (GET options for asset &#x60;?a&#x3D;&lt;id&gt;&#x60;) and &#x60;placeBuyNowServer&#x60; (POST to commit). Errors: 401 if session expired.
Sibling ops: &#x60;buyItNowServerOrder&#x60; (configure asset), &#x60;placeBuyNowServer&#x60; (purchase), &#x60;getNewServer&#x60;/&#x60;addServer&#x60; (custom-spec build, not pre-built), &#x60;getServerList&#x60; (already-owned servers).
     */
    @Location("/buy_now_servers_list") class getMPServers()

    /**
     * Begin OAuth login flow — redirect user to provider for authentication
     * Use as step 1 of social login. Navigate the browser (typically a popup) to &#x60;/apiv2/oauth?provider&#x3D;X&#x60; so the provider authenticates the user, then handle the postMessage from the popup. Public — no auth required.
Query params: &#x60;provider&#x60; (required, case-sensitive: &#x60;Google&#x60;/&#x60;GitHub&#x60;/&#x60;Facebook&#x60;/&#x60;Twitter&#x60;), &#x60;origin&#x60; (optional, opener window origin used to target postMessage instead of &#x60;*&#x60;).
The endpoint redirects directly to the provider rather than returning JSON. After the provider callback, the popup posts one of: &#x60;oauth_success&#x60; (logged in), &#x60;oauth_2fa_required&#x60; (call &#x60;patchOauthTwoFactor&#x60; with the &#x60;oauth_token&#x60;), &#x60;oauth_link_required&#x60; (call &#x60;postOauthCallback&#x60; to link or create), or &#x60;oauth_error&#x60;.
Siblings: &#x60;postOauthCallback&#x60;, &#x60;patchOauthTwoFactor&#x60;, &#x60;submitLogin&#x60; (password flow).
     * @param provider The OAuth provider name (e.g. &#x60;Google&#x60;). 
     */
    @Location("/oauth") class getOauthRedirect(val provider: kotlin.String)

    /**
     * List all PHP timezone identifiers usable on accounts and services
     * Populates a timezone picker for account preferences or for VPS / QuickServer timezone changes. Public — no auth required. Backed by PHP&#x27;s &#x60;DateTimeZone::listIdentifiers()&#x60; so the catalog is large (~400+ zones, including deprecated aliases like &#x60;US/Eastern&#x60;). Result is fixed for a given PHP build — cache aggressively client-side. Sibling ops: &#x60;postVpsChangeTimezone&#x60;, &#x60;postQsChangeTimezone&#x60;, &#x60;getCountries&#x60;, &#x60;getAccountLocales&#x60;, &#x60;getAccountCurrencies&#x60;.

**Path/Query/Body:** None.

**Returns:** flat JSON array of stable IANA tz strings, e.g. &#x60;[&quot;Africa/Abidjan&quot;, &quot;America/New_York&quot;, &quot;Asia/Tokyo&quot;, &quot;Europe/London&quot;, &quot;UTC&quot;]&#x60;. Values are usable verbatim on the timezone-change endpoints; no translation or country-grouping is performed here.

**Auth:** None.

**Errors:** No documented error path under normal operation.

**Related calls:**
- **Apply selection to a service:** &#x60;postVpsChangeTimezone&#x60; (&#x60;/vps/{id}/change_timezone&#x60;), &#x60;postQsChangeTimezone&#x60; (&#x60;/qs/{id}/change_timezone&#x60;).
- **Apply to account profile:** &#x60;updateAccountInfo&#x60; (sets &#x60;timezone&#x60;).
- **Other preference catalogs:** &#x60;getCountries&#x60;, &#x60;getAccountLocales&#x60;, &#x60;getAccountCurrencies&#x60;.

     */
    @Location("/account/timezones") class getTimezones()

    /**
     * Submit 2FA code to finish OAuth login when account has 2FA enabled
     * Final step of the OAuth login flow when the account has 2FA enabled. Called after &#x60;postOauthCallback&#x60; (or the popup&#x27;s &#x60;window.postMessage()&#x60; handshake) returned &#x60;2fa_required&#x60;. Verifies the TOTP against the account&#x27;s stored Google Authenticator secret and creates the session. Public — no auth required. Sibling ops: &#x60;postOauthCallback&#x60; (prior step), &#x60;getOauthRedirect&#x60; (entry point), &#x60;getAccountTfaSetup&#x60; (enroll 2FA), &#x60;submitLogin&#x60;.

**Body fields** (JSON or form):
- &#x60;code&#x60; (string, required) — 6-digit TOTP from the authenticator app.
- &#x60;account_id&#x60; (integer, required) — returned by the prior &#x60;postOauthCallback&#x60;.
- &#x60;oauth_token&#x60; (string, optional) — signed token from the original &#x60;postMessage&#x60; payload, type &#x60;2fa&#x60;, 10-minute expiry. When present, its embedded OAuth profile data is merged into the account (name / picture / phone / address) for any fields still empty.

**Returns:** &#x60;{ login: true, sessionId, account_id, account_lid, ima, name, gravatar }&#x60;.

**Errors:**
- &#x60;400&#x60; — invalid / expired &#x60;oauth_token&#x60; or no pending verification.
- &#x60;401&#x60; — invalid 2FA code.
- &#x60;409&#x60; — 2FA not enabled on the account.
- &#x60;422&#x60; — missing &#x60;code&#x60;.

**Related calls:**
- **Prerequisite:** &#x60;postOauthCallback&#x60;.
- **Enroll 2FA on the account first:** &#x60;getAccountTfaSetup&#x60; → &#x60;updateAccountTfa&#x60;.
- **Alternate login:** &#x60;submitLogin&#x60;.

     * @param body  
     */
    @Location("/oauth") class patchOauthTwoFactor(val body: OauthBody2)

    /**
     * Liveness check — returns the JSON string \&quot;pong\&quot; to confirm API is up
     * Trivial GET that returns the JSON string &#x60;&quot;pong&quot;&#x60; so AI agents and monitors can verify the API endpoint is reachable. Public — no auth required, no params, no body. Does not exercise the database, queue, or any plugin modules. Sibling ops: &#x60;getInfo&#x60; (richer probe that touches MySQL).

**Path/Query/Body:** None.

**Returns:** JSON-encoded string &#x60;&quot;pong&quot;&#x60; with HTTP 200.

**Auth:** None (public endpoint).

**Errors:** No documented error path under normal operation — a non-200 or absent response indicates the API is down, the host is unreachable, or upstream routing is broken.

**Use when:**
- Bootstrapping a new client and want to confirm the API is reachable.
- Smoke-testing in CI/health-check pipelines.
- Diagnosing connectivity issues before higher-cost calls.

**Related calls:**
- **Deeper health probe:** &#x60;getInfo&#x60; (exercises the DB layer).

     */
    @Location("/ping") class pingServer()

    /**
     * Complete OAuth login by linking provider to existing or new account
     * Step 3 of the OAuth login flow. Called after &#x60;getOauthRedirect&#x60; returned &#x60;oauth_link_required&#x60; via the popup&#x27;s &#x60;window.postMessage()&#x60;. Either links the OAuth identity to an existing account (verifying password) or creates a new account. Public — no auth required. Sibling ops: &#x60;patchOauthTwoFactor&#x60; (2FA follow-up), &#x60;getOauthRedirect&#x60; (start the flow), &#x60;submitSignup&#x60;, &#x60;submitLogin&#x60;.

**Body fields** (JSON or form):
- &#x60;oauth_token&#x60; (string, required) — signed token from the popup&#x27;s &#x60;window.postMessage()&#x60; payload; 10-minute expiry.
- &#x60;login&#x60; (string, required) — email.
- &#x60;password&#x60; (string, required).
- &#x60;create&#x60; (boolean, optional) — set &#x60;true&#x60; to create a new account instead of linking.
- &#x60;email_confirmation&#x60; (string, conditional) — 8-char code emailed on the first &#x60;create&#x3D;true&#x60; attempt; server returns 422 &#x60;email_verification_required&#x60; until provided.
- &#x60;tfa&#x60; (string, conditional) — 6-digit TOTP when the existing account has 2FA enabled (after the first attempt returns 422 &#x60;2fa_required&#x60;).

**Returns:** &#x60;{ login|signup|linked: true, sessionId, account_id, account_lid, ima, name, gravatar }&#x60;.

**Errors:**
- &#x60;400&#x60; — invalid / expired &#x60;oauth_token&#x60;.
- &#x60;401&#x60; — bad password or wrong 2FA code.
- &#x60;409&#x60; — account already exists (when &#x60;create: true&#x60;).
- &#x60;422&#x60; — missing field; &#x60;email_verification_required&#x60;; &#x60;2fa_required&#x60;.

**Related calls:**
- **Prerequisite:** &#x60;getOauthRedirect&#x60; to initiate the popup flow.
- **Follow-up when 2FA required:** &#x60;patchOauthTwoFactor&#x60;.
- **Alternate entry points:** &#x60;submitLogin&#x60;, &#x60;submitSignup&#x60;.

     * @param provider The OAuth provider name (e.g. &#x60;Google&#x60;). 
     * @param body  (optional)
     */
    @Location("/oauth") class postOauthCallback(val provider: kotlin.String, val body: OauthBody)

    /**
     * Authenticate with email + password and return a session token
     * Primary password→session-token exchange. Pass the returned session id back as the &#x60;sessionid&#x60; HTTP header on subsequent calls. Public — no auth required. Sibling ops: &#x60;getLoginInfo&#x60; (captcha + branding), &#x60;getOauthRedirect&#x60; (social login), &#x60;submitSignup&#x60;, &#x60;updateAccountApiKey&#x60; (rotate API key once logged in).

**Body fields** (JSON or form):
- &#x60;login&#x60; (string, required) — email.
- &#x60;passwd&#x60; (string, required) — password.
- &#x60;tfa&#x60; (string, conditional) — 6-digit TOTP when the account has 2FA enabled.
- &#x60;verify&#x60; (string, conditional) — 8-char email-confirmation code returned via email when logging in from a new IP. Triggered automatically when the IP has no &#x60;acquittal&#x60; trial record yet (see &#x60;Trial&#x60; ORM, type &#x60;verify_email&#x60;).
- &#x60;remember&#x60; (boolean / &#x60;&#x27;true&#x27;&#x60; / &#x60;&#x27;yes&#x27;&#x60; / &#x60;&#x27;1&#x27;&#x60;, optional) — extends cookie lifetime.

**Returns:** &#x60;{ sessionId, account_id, account_lid, ima, name, gravatar }&#x60;. The &#x60;sessionId&#x60; value is the credential to send on every subsequent authenticated request.

**Errors:**
- &#x60;401&#x60; — bad credentials or wrong 2FA / verify code.
- &#x60;422&#x60; — missing &#x60;login&#x60; / &#x60;passwd&#x60; / &#x60;tfa&#x60; / &#x60;verify&#x60;; response body&#x27;s &#x60;field&#x60; indicates which input is required next.
- &#x60;429&#x60; — too many failed attempts (login-log rate-limit) or max code retries reached.

**Related calls:**
- **Prerequisite:** &#x60;getLoginInfo&#x60; to fetch the captcha challenge and counts.
- **Alternate:** &#x60;getOauthRedirect&#x60; → &#x60;postOauthCallback&#x60; for social login.
- **After login:** &#x60;updateAccountApiKey&#x60;.

     * @param login  
     * @param passwd  
     * @param remember  
     * @param gRecaptchaResponse  
     * @param tfa  
     */
    @Location("/login") class submitLogin(val login: kotlin.String, val passwd: kotlin.String, val remember: kotlin.String, val gRecaptchaResponse: LoginSubmissionExampleGrecaptcharesponse, val tfa: kotlin.String)

    /**
     * Create a new customer account (email + password + captcha + ToS)
     * First step of the signup flow before adding payment or services. Public — no auth required. The account is created in &#x60;pending&#x60; state and moved to &#x60;active&#x60; once the email-confirmation code is verified; an &#x60;account.activated&#x60; event then fires (welcome email + admin notification). MaxMind GeoIP populates &#x60;country&#x60; from the client IP. Sibling ops: &#x60;submitLogin&#x60;, &#x60;getCaptcha&#x60;, &#x60;getLoginInfo&#x60;, &#x60;addBillingPrepay&#x60;, plus the &#x60;add*&#x60; service ops to follow up after signup.

**Body fields** (JSON or form):
- &#x60;login&#x60; (string, required) — email; must be valid and not an alias like &#x60;+tag&#x60; or dotted gmail.
- &#x60;passwd&#x60; (string, required) — 4–64 chars.
- &#x60;tos&#x60; (truthy, required) — &#x60;yes&#x60; / &#x60;true&#x60; / &#x60;1&#x60;.
- &#x60;captcha&#x60; (string, required) — answer to the phrase from &#x60;getCaptcha&#x60; or &#x60;getLoginInfo&#x60; (server reads the phrase from &#x60;$_SESSION[&#x27;captchaSignup&#x27;]&#x60;).
- &#x60;email_confirmation&#x60; (string, conditional) — 8-char code emailed on the first attempt; server returns &#x60;400 { field: &#x27;email_confirmation&#x27; }&#x60; until provided.
- &#x60;remember&#x60; (boolean / &#x60;&#x27;true&#x27;&#x60; / &#x60;&#x27;yes&#x27;&#x60; / &#x60;&#x27;1&#x27;&#x60;, optional) — 256-day cookie.

**Returns:** &#x60;{ sessionId, account_id, account_lid, ima }&#x60;.

**Errors:**
- &#x60;400&#x60; — missing or invalid &#x60;login&#x60; / &#x60;passwd&#x60; / &#x60;tos&#x60; / &#x60;captcha&#x60; / &#x60;email_confirmation&#x60;; blocked-domain or aliased-email; account already exists.
- &#x60;402&#x60; per &#x60;LoginResponseError&#x60; — signup gate misconfigured upstream.

**Related calls:**
- **Prerequisite:** &#x60;getCaptcha&#x60; or &#x60;getLoginInfo&#x60;.
- **After signup:** &#x60;submitLogin&#x60;, &#x60;addBillingPrepay&#x60;, plus any &#x60;add*&#x60; order op.

     * @param body  (optional)
     */
    @Location("/signup") class submitSignup(val body: LoginSubmissionExample)

    /**
     * Place a QuickServer order, generating a real invoice and queuing provisioning
     * Commits the validated order: creates the service row, generates a real invoice, and queues provisioning. Body fields match &#x60;putQs&#x60; (&#x60;server&#x60;, &#x60;password&#x60;, &#x60;os&#x60;, &#x60;comment&#x60;, &#x60;tos&#x60;) — call &#x60;putQs&#x60; first to catch errors. On &#x60;validation.continue&#x3D;false&#x60;, returns the joined error string with no charge.
Returns: &#x60;ServiceOrderPostResponse&#x60; with the new service ID and invoice info. Pay via &#x60;getBillingInvoice&#x60;/&#x60;initiatePayment&#x60;. Errors: 401 if unauthenticated, 4xx with message on validation failure.
Siblings: &#x60;putQs&#x60; (validate first), &#x60;getNewQs&#x60;, &#x60;addVps&#x60; (VPS equivalent).
     * @param body  
     */
    @Location("/qs/order") class addQs(val body: QsOrderRequest)

    /**
     * Permanently delete a QuickServer backup file from object storage
     * Removes the backup from its storage backend. Irreversible — the backup cannot be recovered. Path param: &#x60;id&#x60;. Required: &#x60;file&#x60; (the backup &#x60;name&#x60; from &#x60;getQsBackups&#x60;, in query or form body).
Works for &#x60;swift&#x60; and &#x60;minio&#x60; backups; &#x60;zfs&#x60; snapshots cannot be deleted via this endpoint (returns an error pointing to support). Returns: &#x60;SuccessTextResponse&#x60; with the removed name. Errors: 401, 404 if not owned, error message if backup type is unsupported or the storage operation fails.
Siblings: &#x60;getQsBackups&#x60; (list), &#x60;downloadQsBackup&#x60; (PATCH), &#x60;postQuickServerRestore&#x60;.
     * @param id QuickServer ID number 
     * @param file The backup filename to delete. 
     * @param all Set to &#x60;1&#x60; to list all backups across all services, not just the ones for the given QuickServer. (optional)
     */
    @Location("/qs/{id}/backups") class deleteQsBackup(val id: kotlin.Int, val file: kotlin.String, val all: kotlin.String)

    /**
     * Block outbound SMTP traffic on a QuickServer to halt mail abuse
     * Queues a firewall rule that drops outbound port 25 traffic, used to halt spam/abuse without taking the server offline. Path param: &#x60;id&#x60; (integer). No body.
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes via the queue worker, which also re-runs VNC setup. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;. Reversible only by support — there is no &#x60;unblock_smtp&#x60; endpoint.
Siblings: &#x60;doVpsBlockSmtp&#x60;, &#x60;getQsInfo&#x60;.
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/block_smtp") class doQsBlockSmtp(val id: kotlin.Int)

    /**
     * Disable the virtual CD/DVD drive device on a QuickServer
     * Queues removal of the virtual CD/DVD device from the QuickServer (full disable, not just eject). Path param: &#x60;id&#x60; (integer). No body.
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes; queue worker also re-runs VNC setup. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
Siblings: &#x60;doQsEjectCd&#x60; (eject the ISO but keep drive), &#x60;postQsInsertCd&#x60; (mount an ISO), &#x60;getQsInsertCd&#x60; (list available ISOs).
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/disable_cd") class doQsDisableCd(val id: kotlin.Int)

    /**
     * Disable disk-quota enforcement at OS level on a QuickServer
     * Queues a job to turn off disk-quota enforcement at the OS level. Use when quota errors block legitimate writes or before resizing disk space. Path param: &#x60;id&#x60; (integer). No body.
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes; queue worker also re-runs VNC setup. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;. Re-enable later with &#x60;doQsEnableQuota&#x60;.
Siblings: &#x60;doQsEnableQuota&#x60; (re-enable), &#x60;doVpsDisableQuota&#x60; (VPS equivalent).
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/disable_quota") class doQsDisableQuota(val id: kotlin.Int)

    /**
     * Eject the currently mounted ISO from a QuickServer&#x27;s virtual CD drive
     * Queues an eject — drive remains attached but no media. Path param: &#x60;id&#x60; (integer). No body.
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes. The queue worker also re-runs VNC setup so the console reflects the change. Errors: 401, 404 if &#x60;id&#x60; is not owned by caller. Note: this handler does not validate &#x60;active&#x60; status.
Siblings: &#x60;postQsInsertCd&#x60; (mount an ISO), &#x60;getQsInsertCd&#x60; (list ISOs), &#x60;doQsDisableCd&#x60; (remove the drive itself).
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/eject_cd") class doQsEjectCd(val id: kotlin.Int)

    /**
     * Enable disk-quota enforcement at OS level on a QuickServer
     * Queues a job to turn on disk-quota enforcement at the OS level. Pair with &#x60;doQsDisableQuota&#x60; when re-enabling after maintenance, disk resizing, or restoring a backup. Path param: &#x60;id&#x60; (integer). No body.
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes; queue worker also re-runs VNC setup. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
Siblings: &#x60;doQsDisableQuota&#x60; (turn off), &#x60;doVpsEnableQuota&#x60; (VPS equivalent).
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/enable_quota") class doQsEnableQuota(val id: kotlin.Int)

    /**
     * Reboot a QuickServer with a graceful OS-level restart
     * Queues a graceful restart — equivalent to &#x60;reboot&#x60; inside the OS. Path param: &#x60;id&#x60; (integer). No body. Use to recover from a hung service or apply pending kernel/config changes.
Returns: &#x60;{ text, queueId }&#x60;. Async — server is back online within ~2 minutes; queue worker also re-runs VNC setup. Errors: 401, 404 if not owned by caller. Note: handler does not gate on &#x60;active&#x60; status — restarts work even on suspended services.
Siblings: &#x60;doQsStart&#x60;, &#x60;doQsStop&#x60;, &#x60;doVpsRestart&#x60;.
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/restart") class doQsRestart(val id: kotlin.Int)

    /**
     * Power on a QuickServer that is currently stopped or pending boot
     * Queues a &#x60;start&#x60; command to bring the QuickServer online. Path param: &#x60;id&#x60; (integer). No body. Idempotent in practice — re-running on an already-on server is a no-op at the worker.
Returns: &#x60;{ text, queueId }&#x60;. Async — typically online within ~2 minutes; queue worker re-runs VNC setup. Errors: 401, 404 if not owned by caller. Note: handler does not gate on status, so it can be issued even for non-active services.
Siblings: &#x60;doQsStop&#x60;, &#x60;doQsRestart&#x60;, &#x60;getQsInfo&#x60;, &#x60;doVpsStart&#x60;.
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/start") class doQsStart(val id: kotlin.Int)

    /**
     * Power off a QuickServer with a graceful shutdown command
     * Queues a &#x60;stop&#x60; command. Path param: &#x60;id&#x60; (integer). No body. Use before maintenance, snapshot, or to halt traffic — billing continues regardless of power state, so use &#x60;quickserversCancel&#x60; to also stop charges.
Returns: &#x60;{ text, queueId }&#x60;. Async — typically off within ~2 minutes; queue worker re-runs VNC setup. Errors: 401, 404 if not owned by caller. Note: handler does not gate on status.
Siblings: &#x60;doQsStart&#x60;, &#x60;doQsRestart&#x60;, &#x60;doVpsStop&#x60;.
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}/stop") class doQsStop(val id: kotlin.Int)

    /**
     * Generate a 24-hour pre-signed download URL for a QuickServer backup
     * Returns a temporary signed URL to fetch the backup directly from object storage. Path param: &#x60;id&#x60;. Body (JSON or form): &#x60;file&#x60; (the backup &#x60;name&#x60; from &#x60;getQsBackups&#x60;).
Only available for &#x60;minio&#x60;-type backups; &#x60;swift&#x60; and &#x60;zfs&#x60; backups return an error directing the caller to contact support. URL expires in 24 hours. Returns: &#x60;{ text, url }&#x60;. Errors: 401, 404 if not owned, error message for unsupported backup type or sharing failure.
Siblings: &#x60;getQsBackups&#x60; (list, get &#x60;name&#x60;), &#x60;deleteQsBackup&#x60;, &#x60;postQuickServerRestore&#x60;.
     * @param body  
     * @param id QuickServer ID number 
     * @param all Set to &#x60;1&#x60; to list all backups across all services, not just the ones for the given QuickServer. (optional)
     */
    @Location("/qs/{id}/backups") class downloadQsBackup(val body: IdBackupsBody, val id: kotlin.Int, val all: kotlin.String)

    /**
     * Get QuickServer order form metadata and available plans/templates
     * Use before placing or validating a QuickServer order to retrieve pricing, available servers, OS templates, and form fields. Read-only — no params, no body, no charge.
Returns: &#x60;QuickserverOrder&#x60; schema with plan/template/server options used to build the order payload for &#x60;putQs&#x60; (validate) or &#x60;addQs&#x60; (place). Errors: 401 if unauthenticated.
Siblings: &#x60;putQs&#x60; (dry-run validation), &#x60;addQs&#x60; (commits and invoices), &#x60;getNewVps&#x60; (virtual VPS ordering surface).
     */
    @Location("/qs/order") class getNewQs()

    /**
     * Queue creation of a new QuickServer backup snapshot (note: GET triggers job)
     * Note: GET on &#x60;/qs/{id}/backup&#x60; triggers a backup job — despite the verb, this is a state-changing action. Queues a &#x60;backup&#x60; operation; backup name is auto-generated. Path param: &#x60;id&#x60; (integer).
Returns: &#x60;{ text, queueId }&#x60;. Async — backup completes in minutes to hours depending on disk size. Poll &#x60;getQsBackups&#x60; to see when it appears. Errors: 401 if unauthenticated, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
Siblings: &#x60;getQsBackups&#x60; (list), &#x60;postQuickServerRestore&#x60;, &#x60;downloadQsBackup&#x60;, &#x60;deleteQsBackup&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/backup") class getQsBackup(val id: kotlin.Int)

    /**
     * List available QuickServer backups across Swift, MinIO, and ZFS storage
     * Returns all backups visible to the caller for this QuickServer across the three backup backends. Path param: &#x60;id&#x60; (integer). Optional query &#x60;all&#x3D;1&#x60; lists every backup the customer owns, not just this server&#x27;s.
Returns: &#x60;VpsBackupRows&#x60; array — each row has &#x60;name&#x60;, &#x60;type&#x60; (swift/minio/zfs), &#x60;size&#x60;, &#x60;service&#x60;, &#x60;path&#x60;. Use &#x60;name&#x60; (not a numeric ID) with &#x60;downloadQsBackup&#x60; (PATCH), &#x60;deleteQsBackup&#x60; (DELETE), or &#x60;postQuickServerRestore&#x60;. Errors: 401, 404 if not owned by caller.
Siblings: &#x60;getQsBackup&#x60; (create), &#x60;postQuickServerRestore&#x60;.
     * @param id QuickServer ID number 
     * @param all Set to &#x60;1&#x60; to list all backups across all services, not just the ones for the given QuickServer. (optional)
     */
    @Location("/qs/{id}/backups") class getQsBackups(val id: kotlin.Int, val all: kotlin.String)

    /**
     * Get current QuickServer hostname plus change rules and platform support
     * Read-only probe before calling &#x60;postQsChangeHostname&#x60;. Path param: &#x60;id&#x60; (integer). Returns the current hostname and the validation rules the new hostname must satisfy.
Returns: object with hostname metadata. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;. Note: hostname changes are only supported on OpenVZ/Virtuozzo platforms — &#x60;postQsChangeHostname&#x60; rejects KVM/dedicated types with an explanatory error.
Siblings: &#x60;postQsChangeHostname&#x60;, &#x60;getVpsChangeHostname&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_hostname") class getQsChangeHostname(val id: kotlin.Int)

    /**
     * Get metadata for QuickServer root/OS password change requirements
     * Read-only probe before calling &#x60;postQsChangeRootPassword&#x60;. Path param: &#x60;id&#x60; (integer). Use to surface password complexity rules and confirm the QuickServer accepts root password changes.
Returns: object with reset metadata. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
Note: this changes the OS root password (Linux) — for the Webuzo control panel password use &#x60;postQsChangeWebuzoPassword&#x60;. Siblings: &#x60;postQsChangeRootPassword&#x60;, &#x60;postQsResetPassword&#x60; (random password), &#x60;getVpsChangeRootPassword&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_root_password") class getQsChangeRootPassword(val id: kotlin.Int)

    /**
     * List timezones the QuickServer can be set to via change_timezone
     * Returns the system timezone catalog (parsed from &#x60;/usr/share/zoneinfo/zone.tab&#x60;) for use with &#x60;postQsChangeTimezone&#x60;. Path param: &#x60;id&#x60; (integer). Read-only — no queue, no charge.
Returns: array of timezone strings (e.g. &#x60;America/New_York&#x60;, &#x60;Europe/London&#x60;). Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60; (handler labels these errors as &#x60;Invalid VPS Passed&#x60; / &#x60;VPS is not active&#x60; due to shared code).
Siblings: &#x60;postQsChangeTimezone&#x60; (commit), &#x60;getVpsChangeTimezone&#x60;, &#x60;getQsChangeHostname&#x60; (also informational).
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_timezone") class getQsChangeTimezone(val id: kotlin.Int)

    /**
     * Get metadata for changing the Webuzo control panel admin password
     * Read-only probe before &#x60;postQsChangeWebuzoPassword&#x60;. Path param: &#x60;id&#x60; (integer). Webuzo is a control panel optionally installed on QuickServers — its admin password is separate from the OS root password.
Returns: object with change instructions. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
Siblings: &#x60;postQsChangeWebuzoPassword&#x60;, &#x60;postQsChangeRootPassword&#x60; (OS root password), &#x60;postQsResetPassword&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_webuzo_password") class getQsChangeWebuzoPassword(val id: kotlin.Int)

    /**
     * Get full details for one QuickServer including credentials and links
     * Returns the QuickServer dashboard payload — service info, IPs, hostname, OS, status, billing, and the list of available &#x60;client_links&#x60; (action endpoints the caller is allowed to invoke). Path param: &#x60;id&#x60; (integer QuickServer ID).
Returns: &#x60;Quickserver&#x60; schema. Use response links to drive &#x60;doQsStart&#x60;, &#x60;doQsStop&#x60;, &#x60;doQsRestart&#x60;, &#x60;getQsBackups&#x60;, &#x60;getQsReinstallOs&#x60;, &#x60;getQsReverseDns&#x60;, &#x60;getQsInvoices&#x60;. Errors: 401 if unauthenticated, 404 if &#x60;id&#x60; is not owned by caller.
Siblings: &#x60;updateQsInfo&#x60; (mutate), &#x60;quickserversCancel&#x60; (delete), &#x60;getVpsInfo&#x60; (VPS equivalent).
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}") class getQsInfo(val id: kotlin.Int)

    /**
     * List ISO images available to mount on a QuickServer&#x27;s virtual CD
     * Returns the catalog of bootable ISOs the caller can mount via &#x60;postQsInsertCd&#x60;. Path param: &#x60;id&#x60; (integer). Read-only — no queue, no charge.
Returns: object with available ISO entries (URLs/labels) keyed for the QuickServer&#x27;s hardware type. Errors: 401 if unauthenticated. Note: this handler does not validate ownership or active status — pair with &#x60;getQsInfo&#x60; first if you need those checks before presenting options to a user.
Siblings: &#x60;postQsInsertCd&#x60; (mount the chosen URL), &#x60;doQsEjectCd&#x60;, &#x60;doQsDisableCd&#x60;, &#x60;getVpsInsertCd&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/insert_cd") class getQsInsertCd(val id: kotlin.Int)

    /**
     * List billing invoices charged for one QuickServer service
     * Returns invoices charged for this QuickServer (initial setup + recurring). Path param: &#x60;id&#x60; (integer).
Returns: &#x60;ChargeInvoiceRows&#x60; — each row has invoice ID, amount, status (paid/unpaid), date. Use the invoice ID with &#x60;getBillingInvoice&#x60; for full detail or &#x60;initiatePayment&#x60; to settle. Errors: 401 if unauthenticated, 404 if not owned by caller.
Siblings: &#x60;getQsInfo&#x60;, &#x60;getVpsInvoices&#x60;, &#x60;getBillingInvoice&#x60;, &#x60;quickserversCancel&#x60; (check next-invoice date before canceling).
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/invoices") class getQsInvoices(val id: kotlin.Int)

    /**
     * List QuickServer rapid-deploy dedicated servers on the account
     * Use to enumerate the caller&#x27;s QuickServers (quick-provision physical dedicated boxes that share the VPS billing model). No params, no body. Each row has &#x60;qs_id&#x60;, &#x60;qs_name&#x60;, &#x60;qs_hostname&#x60;, &#x60;qs_status&#x60;, &#x60;qs_comment&#x60;, and &#x60;cost&#x60;. Feed &#x60;qs_id&#x60; into &#x60;getQsInfo&#x60; for full details, or any per-server action (&#x60;doQsStart&#x60;, &#x60;doQsStop&#x60;, &#x60;doQsRestart&#x60;, &#x60;getQsBackups&#x60;, etc.).
Returns: array of QuickServer rows. Errors: 401 if unauthenticated.
Siblings: &#x60;getVpsList&#x60; (virtual VPS surface), &#x60;getQsInfo&#x60;, &#x60;getNewQs&#x60; for ordering metadata.
     */
    @Location("/qs") class getQsList()

    /**
     * List OS templates available for a QuickServer reinstall
     * Returns the OS template catalog filtered to the QuickServer&#x27;s hardware/template type. Path param: &#x60;id&#x60; (integer). Read-only — no provisioning happens.
Returns: &#x60;{ templates: [...] }&#x60; — each template has &#x60;template_file&#x60;, &#x60;template_name&#x60;, &#x60;template_version&#x60;. Use &#x60;template_file&#x60; with &#x60;postQsReinstallOs&#x60;. Non-admin callers only see templates with &#x60;template_available&#x3D;1&#x60;. Errors: 401 if unauthenticated.
Siblings: &#x60;postQsReinstallOs&#x60; (commit, destructive), &#x60;getVpsReinstallOs&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/reinstall_os") class getQsReinstallOs(val id: kotlin.Int)

    /**
     * Get options for QuickServer randomized root password reset
     * Read-only probe before &#x60;postQsResetPassword&#x60;. Path param: &#x60;id&#x60; (integer). Use to confirm the QuickServer is in a state that allows password resets.
Returns: object with reset configuration. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
Note: &#x60;postQsResetPassword&#x60; generates a random password — for a chosen value use &#x60;postQsChangeRootPassword&#x60;. Siblings: &#x60;postQsResetPassword&#x60;, &#x60;postQsChangeRootPassword&#x60;, &#x60;getVpsResetPassword&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/reset_password") class getQsResetPassword(val id: kotlin.Int)

    /**
     * Get reverse DNS (PTR) records for all of a QuickServer&#x27;s IPs
     * Returns the current PTR record for the primary IP and any additional IPs assigned to the QuickServer. Path param: &#x60;id&#x60; (integer). Read-only — looks up live DNS, no queue.
Returns: &#x60;{ ips: { &quot;&lt;ip&gt;&quot;: &quot;&lt;hostname&gt;&quot;, ... } }&#x60;. Use the keys with &#x60;postQsReverseDns&#x60; to update entries. Errors: 401 if unauthenticated. Note: handler does not gate on ownership/active status.
Siblings: &#x60;postQsReverseDns&#x60;, &#x60;getVpsReverseDns&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/reverse_dns") class getQsReverseDns(val id: kotlin.Int)

    /**
     * Get current VNC console connection details for a QuickServer
     * Read-only probe for the VNC tunnel that exposes the server&#x27;s console (host, port, credentials). Path param: &#x60;id&#x60; (integer).
Returns: object with VNC connection info. Errors: 401 if unauthenticated, 404 if &#x60;id&#x60; is not owned by caller, 409 if service is not &#x60;active&#x60;. Note: this endpoint is currently a stub — the &#x60;// todo: return vnc info&#x60; line indicates the response body may be empty until completed.
Siblings: &#x60;postQsSetupVnc&#x60; (configure access IP), &#x60;getVpsSetupVnc&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/setup_vnc") class getQsSetupVnc(val id: kotlin.Int)

    /**
     * Get bandwidth usage for the QuickServer&#x27;s current billing period
     * Returns the inbound/outbound bandwidth totals and time-series points for the QuickServer&#x27;s current cycle. Path param: &#x60;id&#x60; (integer). Read-only.
Returns: bandwidth-data object from &#x60;qs_bandwidth_data&#x60; (totals, daily/hourly points, overage flag). Errors: 401 if unauthenticated. Note: handler does not gate on ownership or active status.
Siblings: &#x60;postQsTrafficUsage&#x60; (same data, accessible via POST for filtered queries), &#x60;getVpsTrafficUsage&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/traffic_usage") class getQsTrafficUsage(val id: kotlin.Int)

    /**
     * Get the full QuickServer dashboard view payload (rich format)
     * Returns the same rich payload the AdminLTE UI uses — service info, billing, available client_links, resource graphs. Heavier than &#x60;getQsInfo&#x60; and intended for desktop dashboards. Path param: &#x60;id&#x60; (integer).
Returns: object with &#x60;serviceInfo&#x60;, &#x60;client_links&#x60;, etc. (admin-only fields stripped). Errors: 401 if unauthenticated. Note: handler does not gate on ownership/active status.
Siblings: &#x60;getQsInfo&#x60; (lighter), &#x60;postQsViewDesktop&#x60; (mutate variant), &#x60;getVpsViewDesktop&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/view_desktop") class getQsViewDesktop(val id: kotlin.Int)

    /**
     * Resend the QuickServer welcome email with login credentials
     * Re-runs the &#x60;qs_welcome_email&#x60; function which composes and sends the welcome email containing connection details, root password, and management URLs to the account owner. Path param: &#x60;id&#x60; (integer).
Returns: &#x60;{ text: &quot;Welcome Email has been resent.&quot; }&#x60;. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;. Use when the original welcome email was lost or the customer needs credentials again.
Siblings: &#x60;getVpsWelcomeEmail&#x60;, &#x60;getQsInfo&#x60; (also exposes connection info).
     * @param id Quickserver ID 
     */
    @Location("/qs/{id}/welcome_email") class getQsWelcomeEmail(val id: kotlin.String)

    /**
     * Change a QuickServer&#x27;s system hostname (OpenVZ/Virtuozzo only)
     * Updates the hostname and the matching reverse DNS entry. Path param: &#x60;id&#x60;. Body (JSON or form): &#x60;hostname&#x60; (must pass &#x60;valid_hostname&#x60;, must differ from current).
Only supported on OpenVZ/Virtuozzo platforms — KVM/dedicated returns a 4xx with a contact-support message. Pending services update the DB row directly (&#x60;{ text }&#x60;); active services queue the change (&#x60;{ text, queueId }&#x60;, ~2 min). Errors: 401, 404 if not owned, 409 if status !&#x3D; &#x60;active&#x60;, validation error for bad hostname or no change.
Siblings: &#x60;getQsChangeHostname&#x60;, &#x60;postVpsChangeHostname&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_hostname") class postQsChangeHostname(val id: kotlin.Int)

    /**
     * Change QuickServer root/administrator password to a chosen value
     * Queues a root password change. Path param: &#x60;id&#x60;. Body (JSON or form): &#x60;password&#x60; (the new password — required, no server-side complexity validation here).
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes. Both queue and history entries are written. Errors: 401, 404 if not owned, 409 if status !&#x3D; &#x60;active&#x60;, 400 if &#x60;password&#x60; is missing.
For a randomly generated password use &#x60;postQsResetPassword&#x60; instead. For Webuzo panel password use &#x60;postQsChangeWebuzoPassword&#x60;. Siblings: &#x60;getQsChangeRootPassword&#x60;, &#x60;postVpsChangeRootPassword&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_root_password") class postQsChangeRootPassword(val id: kotlin.Int)

    /**
     * Change the system timezone on a QuickServer to a catalog entry
     * Queues a timezone change. Path param: &#x60;id&#x60;. Body (JSON or form): &#x60;timezone&#x60; (must be one of the strings returned by &#x60;getQsChangeTimezone&#x60;).
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes by the queue worker. Errors: 401, 404 if not owned, 409 if status !&#x3D; &#x60;active&#x60;, 422 if &#x60;timezone&#x60; is not in the catalog.
Siblings: &#x60;getQsChangeTimezone&#x60; (call first to get valid options), &#x60;postVpsChangeTimezone&#x60;.
     * @param timezone  
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_timezone") class postQsChangeTimezone(val timezone: kotlin.String, val id: kotlin.Int)

    /**
     * Change Webuzo control panel admin password live (synchronous, not queued)
     * Calls the Webuzo SDK directly on the server to change the panel &#x60;admin&#x60; password, then emails the new credentials. Path param: &#x60;id&#x60;. Body: &#x60;password&#x60; (new Webuzo password, must pass &#x60;valid_password&#x60;), &#x60;login_password&#x60; (caller&#x27;s account login password — verified via md5 hash).
Synchronous — no queue ID. Requires a prior Webuzo-Details history entry. Returns: success message string. Errors: 401, 404 if not owned, 409 if status !&#x3D; &#x60;active&#x60;, validation errors for missing fields, wrong login password, weak new password, or SDK failure.
Siblings: &#x60;getQsChangeWebuzoPassword&#x60;, &#x60;postQsChangeRootPassword&#x60; (OS root).
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/change_webuzo_password") class postQsChangeWebuzoPassword(val id: kotlin.Int)

    /**
     * Mount an ISO image as the QuickServer&#x27;s virtual CD via URL
     * Queues an &#x60;insert_cd&#x60; job that attaches the given ISO URL to the QuickServer&#x27;s virtual CD drive (typically for OS reinstalls or rescue boots). Path param: &#x60;id&#x60;. Body (JSON or form): &#x60;url&#x60; (the ISO URL — pick one from &#x60;getQsInsertCd&#x60;).
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes. Errors: 401, 404 if not owned by caller. The action is idempotent in effect (latest mount wins).
Siblings: &#x60;getQsInsertCd&#x60; (list options), &#x60;doQsEjectCd&#x60; (unmount), &#x60;doQsDisableCd&#x60;, &#x60;postQsReinstallOs&#x60; (template-based).
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/insert_cd") class postQsInsertCd(val id: kotlin.Int)

    /**
     * Reinstall the operating system on a QuickServer (DESTRUCTIVE — wipes disk)
     * Wipes the disk and reinstalls the chosen OS template. All data, configs, and snapshots are erased. Path param: &#x60;id&#x60;. Body: &#x60;template&#x60; (a &#x60;template_file&#x60; from &#x60;getQsReinstallOs&#x60;), &#x60;password&#x60; (new root password — required for non-Windows templates).
For active services, queues &#x60;reinstall_os&#x60; (~2 min). For inactive services, just stores the OS preference for next activation. Updates &#x60;qs_status&#x60; to &#x60;Reinstalling&#x60; and clears screenshots. Returns flash messages — typical envelope. Errors: 401, invalid template name returns error flash.
Siblings: &#x60;getQsReinstallOs&#x60; (list options), &#x60;postVpsReinstallOs&#x60;, &#x60;postQuickServerRestore&#x60; (recover from backup instead).
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/reinstall_os") class postQsReinstallOs(val id: kotlin.Int)

    /**
     * Reset QuickServer root password to a server-generated random value
     * Queues a &#x60;reset_password&#x60; job that generates a new root password and emails it to the account owner. Path param: &#x60;id&#x60; (integer). No body — password is generated server-side.
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes. Errors: 401, 404 if not owned by caller, 409 if status !&#x3D; &#x60;active&#x60;.
For a chosen password use &#x60;postQsChangeRootPassword&#x60; instead; for the Webuzo panel password use &#x60;postQsChangeWebuzoPassword&#x60;. Siblings: &#x60;getQsResetPassword&#x60;, &#x60;postVpsResetPassword&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/reset_password") class postQsResetPassword(val id: kotlin.Int)

    /**
     * Update reverse DNS (PTR) records for a QuickServer&#x27;s IPs
     * Sets PTR records for one or more of the QuickServer&#x27;s IPs. Path param: &#x60;id&#x60;. Body (form): &#x60;ips&#x60; — keyed by IP, value is the desired hostname (must be valid).
Returns: &#x60;{ message: &quot;DNS Updated&quot;, success: true }&#x60;. Caveat: in the current implementation the body is parsed but the per-IP update loop is a no-op shell — verify with &#x60;getQsReverseDns&#x60; after calling, and use the support channel if changes don&#x27;t propagate. Errors: 401 if unauthenticated.
Siblings: &#x60;getQsReverseDns&#x60;, &#x60;postVpsReverseDns&#x60;.
     * @param body  
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/reverse_dns") class postQsReverseDns(val body: ReverseDnsEntries, val id: kotlin.Int)

    /**
     * Configure the source IP allowed to reach a QuickServer&#x27;s VNC console
     * Sets the IP allowed to reach the VNC tunnel and queues a &#x60;setup_vnc&#x60; to apply it. Path param: &#x60;id&#x60;. Body (JSON or form): &#x60;vnc&#x60; (a valid IPv4 address — only this address can reach the console).
Returns: &#x60;{ text, queueId }&#x60;. Async — applied within ~2 minutes. Errors: 401, 404 if not owned, 409 if status !&#x3D; &#x60;active&#x60;. Returns an inline &#x60;Invalid IP&#x60; message when &#x60;vnc&#x60; fails &#x60;validIp&#x60;. The VPS-style helper also runs after the DB update.
Siblings: &#x60;getQsSetupVnc&#x60; (read), &#x60;postVpsSetupVnc&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/setup_vnc") class postQsSetupVnc(val id: kotlin.Int)

    /**
     * Query QuickServer bandwidth usage via POST (filtered variant)
     * Functional duplicate of &#x60;getQsTrafficUsage&#x60; exposed under POST so clients can pass a filter body. Path param: &#x60;id&#x60; (integer). Body fields are accepted but the current handler ignores them and returns the full current-cycle dataset.
Returns: same bandwidth-data object as &#x60;getQsTrafficUsage&#x60;. Errors: 401 if unauthenticated. No active-status or ownership gate.
Siblings: &#x60;getQsTrafficUsage&#x60;, &#x60;postVpsTrafficUsage&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/traffic_usage") class postQsTrafficUsage(val id: kotlin.Int)

    /**
     * Submit changes and re-fetch the QuickServer dashboard view payload
     * Same handler as &#x60;getQsViewDesktop&#x60; but accessible via POST so callers can pass body fields alongside re-fetching the view. Path param: &#x60;id&#x60;. Body fields are accepted by the underlying View handler.
Returns: refreshed dashboard object — &#x60;serviceInfo&#x60;, &#x60;client_links&#x60;, etc. Errors: 401 if unauthenticated.
For structured updates prefer the dedicated endpoints (&#x60;postQsChangeHostname&#x60;, &#x60;postQsReverseDns&#x60;, &#x60;postQsSetupVnc&#x60;, etc.) which return queue IDs. Siblings: &#x60;getQsViewDesktop&#x60;, &#x60;postVpsViewDesktop&#x60;.
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/view_desktop") class postQsViewDesktop(val id: kotlin.Int)

    /**
     * Restore a QuickServer from a backup (DESTRUCTIVE — overwrites disk)
     * Overwrites the live disk with a backup. Path param: &#x60;id&#x60;. Body (form): &#x60;backup&#x60; (composite key &#x60;&lt;type&gt;:&lt;service&gt;:&lt;name&gt;&#x60; from &#x60;getQsBackups&#x60;), &#x60;password&#x60; (caller&#x27;s account login password — required for non-admin to confirm).
Validates backup exists, caller&#x27;s password (when applicable), and that the QuickServer disk is large enough (size check skipped for ZFS). Queues &#x60;snapshot_restore&#x60; for ZFS or &#x60;restore&#x60; for swift/minio; allow up to 10 minutes. Returns: &#x60;{ text, queueId }&#x60;. Errors: 401, 404 if not owned, 409 if status !&#x3D; &#x60;active&#x60;, errors for invalid password, missing backup, or insufficient disk space.
Siblings: &#x60;getQsBackups&#x60;, &#x60;getQsBackup&#x60; (create), &#x60;postVpsRestore&#x60;.
     * @param body QuickServer Restore request 
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}/restore") class postQuickServerRestore(val body: RestoreRequest, val id: kotlin.Int)

    /**
     * Validate a QuickServer order without charging or provisioning
     * Dry-run the order payload before calling &#x60;addQs&#x60;. No invoice is created and no service is provisioned. Use to surface form errors, compute the price, and resolve the chosen &#x60;server&#x60;/&#x60;os&#x60;/&#x60;distro&#x60; against the master pool.
Body (form): &#x60;server&#x60; (master ID), &#x60;password&#x60;, &#x60;os&#x60; (template), &#x60;comment&#x60;, &#x60;tos&#x60;. Returns the &#x60;validate_buy_qs&#x60; result with &#x60;continue&#x60; flag, normalized fields, &#x60;service_cost&#x60;, and &#x60;errors&#x60; array. Errors: 401 if unauthenticated; validation errors are returned in the body, not as 4xx.
Siblings: &#x60;addQs&#x60; (commits the order), &#x60;getNewQs&#x60; (form metadata), &#x60;putVps&#x60; (VPS equivalent).
     * @param body  
     */
    @Location("/qs/order") class putQs(val body: QsOrderRequest)

    /**
     * Cancel a QuickServer service at the end of the current billing cycle
     * Schedules deprovisioning. The server keeps running until the current billing period ends, then is canceled and the recurring invoice stops. Path param: &#x60;id&#x60; (integer).
Returns: &#x60;{ success: bool, text: string }&#x60;. Errors: 401 if unauthenticated, 404 if not owned by caller. Reversible only by support before the cycle closes — use &#x60;getQsInvoices&#x60; to check the next invoice date first.
Siblings: &#x60;getQsInfo&#x60;, &#x60;VPSCancel&#x60; (VPS equivalent), &#x60;serversCancel&#x60; (dedicated equivalent).
     * @param id QuickServer ID number 
     */
    @Location("/qs/{id}") class quickserversCancel(val id: kotlin.Int)

    /**
     * Update QuickServer order metadata or stored settings without OS impact
     * Mutates QuickServer-level settings (comment, stored notes) without affecting the running OS. Path param: &#x60;id&#x60;. Body fields are module-specific and processed by the shared &#x60;View::go&#x60; handler.
Returns: &#x60;SuccessTextResponse&#x60;. Errors: 401 if unauthenticated, 404 if not owned by caller.
For server-side actions use the dedicated endpoints — hostname via &#x60;postQsChangeHostname&#x60;, password via &#x60;postQsChangeRootPassword&#x60;, OS via &#x60;postQsReinstallOs&#x60;. Siblings: &#x60;getQsInfo&#x60; (read), &#x60;quickserversCancel&#x60; (delete).
     * @param id QuickServer ID number. 
     */
    @Location("/qs/{id}") class updateQsInfo(val id: kotlin.String)

    /**
     * Place a new SSL certificate order - creates invoice and queues issuance
     * [DESTRUCTIVE] Use after putSsl returns continue&#x3D;true to commit the SSL order. Body (form): frequency (default 12 months), service_type, hostname, csr, coupon_code, plus per-type vars/extra. Re-runs validate_buy_ssl then calls place_buy_ssl which creates the service row, generates invoice (iid/iids/real_iids), and returns serviceId, serviceCost, invoice_description. CA validation is async - issuance takes minutes to hours and may require DNS or email validation post-order. If validation fails, returns continue&#x3D;false with errors and no charge. Returns 401 unauthenticated, 422 invalid input. Caveat: cert is not active until invoice paid AND CA validation completes. Poll status via getSslInfo; resend instructions via getSslWelcomeEmail.

Sibling ops: &#x60;getNewSsl&#x60; (catalog), &#x60;putSsl&#x60; (validate), &#x60;getSslInfo&#x60; (poll), &#x60;getSslInvoices&#x60;, &#x60;initiatePayment&#x60; (settle invoice), &#x60;getSslWelcomeEmail&#x60;, &#x60;sslCancel&#x60;.
     * @param body  
     */
    @Location("/ssl/order") class addSsl(val body: SslOrderRequest)

    /**
     * Get available SSL certificate packages and pricing for placing a new order
     * Use before addSsl to discover which DV/OV/EV certificate types and validation tiers are buyable, plus their costs. Returns object with packageCosts (services_id keyed map of float costs) and serviceTypes (full list of SSL product offerings from the get_service_types event). No parameters required - prices are in the customer&#x27;s currency. Returns 401 if unauthenticated. Show these to the customer to pick a service_type, then call putSsl to dry-run validation (hostname, CSR, coupon) without charging, then addSsl to commit. Costs do not include taxes or applied coupons — putSsl returns the actual computed price with discounts.

Sibling ops: &#x60;putSsl&#x60; (validate), &#x60;addSsl&#x60; (commit), &#x60;getSslList&#x60; (existing certs), &#x60;getSslInfo&#x60; (per-cert).
     */
    @Location("/ssl/order") class getNewSsl()

    /**
     * Get full details for one SSL certificate by id - status, expiration, links
     * Use to inspect a single SSL cert after locating its id via getSslList. Path param id (integer, required) is the ssl_id; cross-account ids return 404 (get_service enforces ownership). Returns the ViewSSL detail payload: hostname, service_type, status, expiration, company, plus client_links (rewrite/reissue/install actions available to the customer). admin_links, settings, csrf are stripped from client responses. Returns 401 unauthenticated, 404 if id not owned by the session customer. Reissue/rekey/install actions surfaced in client_links are time-sensitive and may require fresh DNS validation. Pair with getSslInvoices for billing history, getSslWelcomeEmail to resend, sslCancel to terminate, updateSslInfo to modify settings.

Sibling ops: &#x60;updateSslInfo&#x60;, &#x60;getSslInvoices&#x60;, &#x60;getSslWelcomeEmail&#x60;, &#x60;sslCancel&#x60;, &#x60;getSslList&#x60;.
     * @param id SSL certificate ID number. 
     */
    @Location("/ssl/{id}") class getSslInfo(val id: kotlin.Int)

    /**
     * List all billing invoices and charges tied to one SSL certificate by id
     * Use to retrieve the full invoice history for a single SSL cert - initial order, renewals, and any addon charges. Path param id (integer, required) is the ssl_id; ownership is enforced via get_service so cross-account ids return an Invalid Service error. Returns ChargeInvoiceRows: success bool plus invoices array of charge/invoice rows with iid, date, cost, status (paid/unpaid/refunded), and description. Returns 401 unauthenticated, 400 if the id resolves to no service. Useful for auditing renewals before sslCancel, reconciling payment failures, or showing the customer their billing history.

Sibling ops: &#x60;getSslInfo&#x60;, &#x60;sslCancel&#x60;, &#x60;getSslWelcomeEmail&#x60;, &#x60;getBillingInvoice&#x60; (per-invoice detail), &#x60;initiatePayment&#x60; (settle unpaid).
     * @param id SSL Cert ID number 
     */
    @Location("/ssl/{id}/invoices") class getSslInvoices(val id: kotlin.Int)

    /**
     * List all SSL certificates on the authenticated customer account with status and hostname
     * Use to enumerate every SSL certificate (DV/OV/EV) the current customer owns before drilling into a specific cert. Returns an array of SslRow objects with id, hostname, services_name (package), status (pending/active/expired/canceled), and company. No query parameters - results are auto-scoped to the session account_id. Empty array if customer has no certs. Returns 401 if unauthenticated. Pair the returned id with getSslInfo for full details, getSslInvoices for billing, getSslWelcomeEmail to resend credentials, sslCancel to terminate, or addSsl to order a new cert. Status values may be stale relative to CA - issuance/validation can take minutes to hours after order.

Sibling ops: &#x60;getSslInfo&#x60;, &#x60;getNewSsl&#x60; (catalog), &#x60;addSsl&#x60; (order new cert).
     */
    @Location("/ssl") class getSslList()

    /**
     * Resend the SSL welcome email with cert credentials and install instructions
     * Use when a customer lost the original welcome email containing CSR submission steps, validation links, or installation guidance for an active SSL cert. Path param id (integer, required) is the ssl_id. Triggers the module&#x27;s ssl_welcome_email function to re-send to the account&#x27;s email on file. Returns SuccessTextResponse: text&#x3D;&#x27;Welcome Email has been resent.&#x27; Returns 401 unauthenticated, 404 if id not found or not owned by session customer (&#x27;Invalid Service Passed&#x27;), 409 if cert status is not &#x27;active&#x27; (pending/canceled/expired certs do not have a welcome email to resend). Caveat: cannot change the destination email - update the account profile first if the customer&#x27;s address has changed.

Sibling ops: &#x60;getSslInfo&#x60; (verify status), &#x60;sslCancel&#x60; (terminate), &#x60;updateAccountInfo&#x60; (change email first).
     * @param id SSL Cert ID number 
     */
    @Location("/ssl/{id}/welcome_email") class getSslWelcomeEmail(val id: kotlin.Int)

    /**
     * Validate an SSL certificate order without charging - dry-run before addSsl
     * Use after getNewSsl and before addSsl to verify hostname, CSR, service_type, frequency, and coupon_code are acceptable without creating an invoice or charging the customer. Body params (form): frequency (months, default 12), service_type, hostname, csr, coupon_code, plus extra/vars per cert type. Returns continue (bool), errors (array), serviceType, serviceCost (after coupon), originalCost, hostname, couponCode. If continue&#x3D;false the errors array explains what to fix - typical issues are invalid hostname/CSR mismatch, expired coupon, or unsupported service_type. Returns 401 if unauthenticated, 422 on validation failure semantics. No state is mutated. Always run this before addSsl to prevent failed charges.
Sibling ops: &#x60;getNewSsl&#x60; (catalog), &#x60;addSsl&#x60; (commit).
     * @param body  
     */
    @Location("/ssl/order") class putSsl(val body: SslOrderRequest)

    /**
     * Cancel an SSL certificate service - stops renewals at end of billing cycle
     * [DESTRUCTIVE] Use to cancel a customer-owned SSL cert. Path param id (integer, required) is the ssl_id. Cancellation marks the service for non-renewal - the cert stays valid until its current paid period ends, after which auto-billing stops. The CA-issued certificate itself is NOT revoked by this call (file a separate revocation request if needed). Returns SSLCancelResponse with success bool and text. Returns 401 unauthenticated, 404 if id not owned by session customer, error if the cancel_service hook fails. Caveat: irreversible at the billing level - re-enabling requires a new addSsl order. Verify the right cert with getSslInfo and confirm no unpaid charges via getSslInvoices first.

Sibling ops: &#x60;getSslInfo&#x60; (verify cert), &#x60;getSslInvoices&#x60; (check unpaid), &#x60;addSsl&#x60; (re-order).
     * @param id SSL Cert ID number 
     */
    @Location("/ssl/{id}") class sslCancel(val id: kotlin.Int)

    /**
     * Update mutable settings on an existing SSL certificate order by id
     * Use to modify mutable fields on a customer-owned SSL cert (e.g. contact info, renewal preferences, hostname or CSR data depending on cert state and CA rules). Path param id (string/int, required) is the ssl_id. Body params depend on the cert package and which fields the underlying service supports - inspect getSslInfo client_links first to see which actions are exposed. Returns SuccessTextResponse on success. Returns 401 unauthenticated, 404 if id not owned, 409 if cert state forbids the change (e.g. canceled or pending CA validation), 422 on invalid field values. Caveat: changes that affect the certificate identity (hostname, CSR) typically trigger a reissue with the CA which is time-sensitive and may require new DNS or email validation.

Sibling ops: &#x60;getSslInfo&#x60; (read), &#x60;sslCancel&#x60; (terminate), &#x60;getSslWelcomeEmail&#x60;.
     * @param id SSL certificate ID number. 
     */
    @Location("/ssl/{id}") class updateSslInfo(val id: kotlin.String)

    /**
     * Cancel a Scrub IP service and stop its recurring DDoS billing
     * Cancels the Scrub IP DDoS protection service. The protected IP is removed from the scrubbing infrastructure and the recurring invoice is closed; protection stops at end of the current billing cycle. Use only when the customer no longer needs DDoS scrubbing for the IP. Path param: &#x60;id&#x60; (integer, required) — service ID from getScrubIpsList. No request body. Returns {success: true, text: &#x27;Scrub Ips is canceled.&#x27;}. Errors: 401 unauthenticated; 404/Invalid Service if id is not owned by the session account; 409 if the service is not in a cancellable state. Caveat: leaves the underlying VPS/server IP exposed to attacks once protection ends; contact billing for refund handling. Siblings: getScrubIpDetails, disableScrub, getScrubIpInvoices.
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}") class cancelScrubIp(val id: kotlin.Int)

    /**
     * Apply a predefined scrubbing filter (DNS/HTTP/synproxy) to a port
     * Attaches a named scrubbing profile to a destination port on the protected IP, applying protocol-aware mitigation (DNS amplification protection, HTTP rate limiting, synproxy SYN-cookies). Call getScrubIpFilterTypes first to list valid &#x60;filter_type&#x60; values. Path param: &#x60;id&#x60; (integer, required) — service ID. Body (CreateFilter): &#x60;filter_type&#x60; (string, required, one of getScrubIpFilterTypes keys), &#x60;port&#x60; (int, required, &gt;&#x3D; 0). Destination IP is locked to the service IP server-side; synproxy uses a different shape internally. Returns 201 {success: true, text: &#x27;New filter has been created.&#x27;}. Errors: 400 &#x27;Filter type is empty/invalid&#x27;, &#x27;Port is invalid&#x27;, or Invalid Service; 401 unauthenticated; 500 if upstream Scrub::filterCreate fails. Siblings: deleteFilter, getScrubIpFilterTypes, createRule.
     * @param body  
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/create_filter") class createFilter(val body: CreateFilter, val id: kotlin.Int)

    /**
     * Add a geographic firewall rule (block/allow by country code or ASN)
     * Creates a geo-based XDP rule on the scrubber for the service&#x27;s protected IP. Use to block traffic from specific countries or ASNs (botnet source regions) or to allow only known regions. Path param: &#x60;id&#x60; (integer, required) — service ID. Body (CreateGeoFirewallRule): &#x60;country_code&#x60; (int, country numeric ID) OR &#x60;asn&#x60; (int) — at least one is required, &#x60;destination_port&#x60; (int, defaults 80), &#x60;xdp_action&#x60; (0 allow, 1 drop, defaults 1). Destination IP is locked to the service IP server-side. Returns 201 {success: true} when created. Errors: 400 errors[] &#x27;Country or Asn is required.&#x27; or Invalid Service; 401 unauthenticated; 500 if upstream Scrub::geoFirewallCreate fails. Caveat: country_code is an internal numeric ID, not ISO-3166. Siblings: scrubIpsDeleteGeoRule, createRule, createFilter.
     * @param body  
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/create_geo_rule") class createGeoRule(val body: CreateGeoFirewallRule, val id: kotlin.Int)

    /**
     * Add an L3/L4 firewall rule (allow/drop by IP, port, and protocol)
     * Creates an XDP firewall rule on the scrubber for the service&#x27;s protected IP. Use to whitelist a known good source, block an abusive source, or restrict a destination port. Path param: &#x60;id&#x60; (integer, required) — service ID. Body (CreateFirewallRule): &#x60;source_ip&#x60; (IPv4, 0 &#x3D; any), &#x60;source_port&#x60; (int, 0 &#x3D; any), &#x60;destination_port&#x60; (int, 0 &#x3D; any), &#x60;protocol_id&#x60; (1 ICMP or 2 TCP/UDP — must be 1 or 2), &#x60;xdp_action&#x60; (0 allow, 1 drop). Destination IP is locked to the service IP server-side. Returns 201 {success: true} when created. Errors: 400 with &#x60;errors[]&#x60; for invalid source_ip/protocol_id/xdp_action or Invalid Service; 401 unauthenticated; 500 if upstream Scrub::firewallCreate fails. Caveat: rules are stateless and may interact with active filters. Siblings: scrubIpsDeleteRule, createGeoRule, createFilter.
     * @param body  
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/create_rule") class createRule(val body: CreateFirewallRule, val id: kotlin.Int)

    /**
     * Remove a scrubbing filter by matching filter_type and port
     * Removes a previously attached scrubbing profile from the protected IP. Identification is by composite key, not &#x60;rule_id&#x60; — pass the same &#x60;filter_type&#x60; and &#x60;port&#x60; that were used in &#x60;createFilter&#x60;. The endpoint splits &#x60;filter_type&#x60; on &#x60;_&#x60; to dispatch to the correct delete shape (synproxy vs generic). Sibling ops: &#x60;createFilter&#x60;, &#x60;getScrubIpFilterTypes&#x60;.

**Path:** &#x60;id&#x60; (integer, required) — Scrub IP service ID.

**Body fields:**
- &#x60;filter_type&#x60; (string, required) — must match an enabled type from &#x60;getScrubIpFilterTypes&#x60;.
- &#x60;port&#x60; (integer, required) — must be &#x60;&gt; 0&#x60;.

**Returns:** &#x60;{ success: true, text: &#x27;Filter is deleted.&#x27; }&#x60;.

**Errors:**
- &#x60;400&#x60; — &#x60;&#x27;Filter is required.&#x27;&#x60; / &#x60;&#x27;Port is required.&#x27;&#x60; / &#x60;&#x27;Invalid filter&#x27;&#x60; / &#x60;Invalid Service&#x60;.
- &#x60;401&#x60; — unauthenticated.
- &#x60;500&#x60; — upstream &#x60;Scrub::filterDelete&#x60; failed.

**Caveat:** the port loses its protocol-specific scrubbing protection until &#x60;createFilter&#x60; is called again with the same composite key.

     * @param body  
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/delete_filter") class deleteFilter(val body: CreateFilter, val id: kotlin.Int)

    /**
     * Disable DDoS scrubbing and remove the BGP announcement on the IP
     * Withdraws the BGP announcement from Wanguard so the IP stops being routed through scrubbing; traffic resumes flowing directly to the backend. Use for maintenance windows or migration off scrub. Path param: &#x60;id&#x60; (integer, required) — service ID from getScrubIpsList. No body (HTTP GET). The endpoint reads the stored Wanguard &#x60;href&#x60; from the service&#x27;s &#x60;extra&#x60; JSON to know which announcement to delete; clears &#x60;extra&#x60; on success. Returns {success: true, text: &#x27;Scrub is disabled on your IP.&#x27;}. Errors: 400 Invalid Service if id is not owned, or &#x27;Scrub is not enabled in this service.&#x27; if there is no active announcement; 401 unauthenticated; 500 if upstream delete fails. Caveat: leaves the IP unprotected against DDoS until enableScrub is called. Siblings: enableScrub, cancelScrubIp, getScrubIpDetails.
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/disable") class disableScrub(val id: kotlin.Int)

    /**
     * Enable DDoS scrubbing (BGP announcement) on the service&#x27;s protected IP
     * Routes the service&#x27;s protected IP through the Wanguard scrubbing infrastructure by creating a BGP announcement, so inbound traffic passes through filtering before reaching the backend. Call after placeScrubOrder activation, after disableScrub, or whenever the announcement was lost. Path param: &#x60;id&#x60; (integer, required) — service ID from getScrubIpsList. No request body (HTTP GET). Returns {success: true, text: &#x27;Scrub is enabled on your IP.&#x27;} on 201 from Wanguard, persisted into the service&#x27;s &#x60;extra&#x60; column. Errors: 400 Invalid Service if id is not owned by the session account; 401 unauthenticated; 500 if the upstream Wanguard call fails. Caveat: enabling re-routes live traffic and can briefly disrupt active sessions. Siblings: disableScrub, getScrubIpDetails, getScrubIpLogs.
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/enable") class enableScrub(val id: kotlin.Int)

    /**
     * Get plans, pricing, and eligible IPs for a new Scrub IP order
     * Returns the data needed to render a new-order form: &#x60;packageCosts&#x60; (default services_id and recurring price in customer currency with symbol), &#x60;serviceTypes&#x60; (each buyable plan with services_id, services_name, services_cost, services_module), and &#x60;ips&#x60; (the customer&#x27;s existing VPS/server/floating IPs eligible to be put behind a scrubber, each with service_id, service_module, service_hostname). Use as a precursor to putScrubIps (validate) or placeScrubOrder (commit). No path/query/body parameters. Returns object. Errors: 401 unauthenticated. Caveat: ips list is filtered to the session account; pricing is converted to the customer&#x27;s currency. Siblings: putScrubIps, placeScrubOrder, getScrubIpsList.
     */
    @Location("/scrub_ips/order") class getOrderDetail()

    /**
     * Get full Scrub IP service detail (rules + geo + filters)
     * Returns the full service-detail payload for one Scrub IP — used to render the dashboard or before mutating rules/filters. Includes &#x60;serviceInfo&#x60; (status, scrubbed IP, custid), &#x60;billingDetails&#x60; (cost, frequency), &#x60;client_links&#x60; (allowed self-service actions), and &#x60;filter_firewall&#x60; with the active firewall &#x60;rules&#x60;, geographic &#x60;geo_rules&#x60;, and traffic &#x60;filters&#x60;. Each rule/filter row carries its own &#x60;id&#x60; used by the delete endpoints. Sibling ops: &#x60;getScrubIpsList&#x60;, &#x60;enableScrub&#x60;, &#x60;disableScrub&#x60;, &#x60;createRule&#x60;, &#x60;scrubIpsDeleteRule&#x60;, &#x60;createGeoRule&#x60;, &#x60;scrubIpsDeleteGeoRule&#x60;, &#x60;createFilter&#x60;, &#x60;deleteFilter&#x60;, &#x60;getScrubIpInvoices&#x60;, &#x60;getScrubIpLogs&#x60;, &#x60;cancelScrubIp&#x60;.

**Path:** &#x60;id&#x60; (integer, required) — service ID from &#x60;getScrubIpsList&#x60;.

**Body / query:** None.

**Returns:** object with &#x60;serviceInfo&#x60;, &#x60;billingDetails&#x60;, &#x60;client_links&#x60;, &#x60;filter_firewall&#x60; (&#x60;rules&#x60; / &#x60;geo_rules&#x60; / &#x60;filters&#x60;).

**Auth:** Session/API key. Ownership enforced via &#x60;scrub_ips_custid&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;Invalid Service&#x60; — &#x60;id&#x60; is not owned by the session account.

**Caveat:** rule/filter IDs are regenerated after recreate — re-fetch before calling a delete endpoint.

**Related calls:**
- **Mutations:** &#x60;enableScrub&#x60;, &#x60;disableScrub&#x60;, &#x60;createRule&#x60;, &#x60;createGeoRule&#x60;, &#x60;createFilter&#x60;.
- **Deletes:** &#x60;scrubIpsDeleteRule&#x60;, &#x60;scrubIpsDeleteGeoRule&#x60;, &#x60;deleteFilter&#x60;.
- **Billing / activity:** &#x60;getScrubIpInvoices&#x60;, &#x60;getScrubIpLogs&#x60;.
- **Cancel:** &#x60;cancelScrubIp&#x60;.

     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}") class getScrubIpDetails(val id: kotlin.Int)

    /**
     * List enabled traffic filter profiles available for createFilter
     * Returns the catalog of scrub filter profiles (e.g. dns, http, synproxy) currently enabled on the scrubbing platform, keyed by filter_name with a humanized display &#x60;name&#x60; and &#x60;desc&#x60;. Call this to populate a dropdown before invoking createFilter — the &#x60;filter_type&#x60; field on that endpoint must be one of the keys returned here. Not service-scoped: no path/query/body parameters and the same set applies to every Scrub IP. Returns {success: true, filters: {&lt;filter_name&gt;: {name, desc}, ...}}. Errors: 401 unauthenticated. Caveat: only filters with enabled&#x3D;1 are returned; profile semantics are platform-defined (synproxy uses different request shape internally). Siblings: createFilter, deleteFilter, getScrubIpDetails.
     */
    @Location("/scrub_ips/filter_types") class getScrubIpFilterTypes()

    /**
     * List recurring and one-time invoices billed for this Scrub IP service
     * Returns the recurring and one-time invoices generated for the Scrub IP service so the caller can verify billing status, present a payment history, or initiate payment on an unpaid invoice. Use after placeScrubOrder (to find the new invoice id) or before cancelScrubIp (to surface outstanding balance). Path param: &#x60;id&#x60; (integer, required) — service ID from getScrubIpsList. No body/query parameters. Returns ChargeInvoiceRows (array of invoice objects with id, amount, status, due dates). Errors: 401 unauthenticated; empty result if id is not owned by the session account. Caveat: paid invoices remain in history; filter on status client-side. Siblings: getScrubIpDetails, placeScrubOrder, cancelScrubIp.
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/invoices") class getScrubIpInvoices(val id: kotlin.Int)

    /**
     * Get last 50000 packet/event log entries for the protected IP
     * Pulls scrubbing telemetry directly from the SCRUBLOGS clickhouse-style backend: timestamp, source IP, target IP, target port, protocol (ICMP/IGMP/TCP/UDP/etc.), byte_count, action (Allow/Drop/Challenge), and the matching filter label. Use for incident analysis, validating new firewall rules, or proving a DDoS attack hit the scrubber. Path param: &#x60;id&#x60; (string, required) — service ID. No body/query parameters. Timestamps are converted to the customer&#x27;s timezone. Returns array of log rows (ScrubIpsLogRowSchema), most recent first, capped at 50000. Errors: 401 unauthenticated; returns false if id is not owned or upstream returns no data — not a 404. Caveat: large response; logs are not real-time and source IPs are reverse-byte-ordered. Siblings: getScrubIpDetails, enableScrub, createRule.
     * @param id Scrub Order ID 
     */
    @Location("/scrub_ips/{id}/logs") class getScrubIpLogs(val id: kotlin.String)

    /**
     * List all Scrub IP DDoS protection services on the authenticated account
     * Returns every Scrub IP service belonging to the authenticated customer with status, protected IP, plan name, and recurring cost. Use this for dashboards, picking a service ID for downstream calls (getScrubIpDetails, enableScrub, createRule, getScrubIpLogs), or auditing which IPs are routed through DDoS scrubbing. No path/query/body parameters; service ownership is enforced via session account_id. Returns an array of {id, repeat_invoices_cost, ip, status, services_name}; empty array if no scrub services. Errors: 401 unauthenticated. Caveat: only customer-owned services are visible. Siblings: getScrubIpDetails, getOrderDetail, placeScrubOrder, cancelScrubIp.
     */
    @Location("/scrub_ips") class getScrubIpsList()

    /**
     * Place a new Scrub IP DDoS protection order and generate an invoice
     * Commits the order: re-runs validate_buy_scrub_ip then place_buy_scrub_ip which creates the service row, repeat_invoice, and a one-time invoice for the prorated charge. Use putScrubIps first to surface errors without billing. No path parameters. Body (ScrubIpPlaceOrder): &#x60;serviceType&#x60; (services_id), &#x60;ip&#x60; (eligible IP from getOrderDetail). Returns 201 {success: true, text: &#x27;ScrubIp order is placed.&#x27;, order_details: {total_cost, service_id, invoice_id, invoice_description, cj_params}}. Errors: 400 {success: false, text: &#x27;Unable to place order.&#x27;, errors: []} on validation; 401 unauthenticated; 422 on invalid serviceType/ip; 409 if the IP is already protected. Caveat: invoice is unpaid at creation — pay via Pay endpoints to activate. Siblings: putScrubIps, getOrderDetail, enableScrub, getScrubIpInvoices.
     * @param body  
     */
    @Location("/scrub_ips/order") class placeScrubOrder(val body: ScrubIpPlaceOrder)

    /**
     * Validate a Scrub IP order and return effective pricing without billing
     * Dry-runs a Scrub IP purchase via validate_buy_scrub_ip and returns whether the order would succeed plus the resolved pricing — without creating an invoice. Use to render a real-time price/error panel as the user picks options. No path parameters. Body (ScrubIpPlaceOrder): &#x60;serviceType&#x60; (services_id from getOrderDetail.serviceTypes), &#x60;ip&#x60; (one of getOrderDetail.ips), optional &#x60;coupon&#x60;. Returns {continue: bool, errors: [], serviceType, serviceCost, originalCost, repeatServiceCost}. Errors: 401 unauthenticated; validation failures appear in &#x60;errors&#x60;, not as HTTP 4xx. Caveat: idempotent — call as often as needed; 422 on invalid coupon surfaces in the errors array. Siblings: getOrderDetail, placeScrubOrder, getScrubIpsList.
     * @param body  
     */
    @Location("/scrub_ips/order") class putScrubIps(val body: ScrubIpPlaceOrder)

    /**
     * Delete a geo firewall rule by rule_id from getScrubIpDetails
     * Removes a previously created geographic firewall rule from the Scrub IP service. The rule_id must come from the &#x60;filter_firewall.geo_rules[].id&#x60; array returned by getScrubIpDetails — the endpoint validates the id belongs to this service before deleting. Path param: &#x60;id&#x60; (integer, required) — Scrub IP service ID. Body (JSON): {&#x60;rule_id&#x60;: integer, required}. Returns {success: true, text: &#x27;Firewall Rule has been deleted.&#x27;}. Errors: 400 Invalid Service, &#x27;Rule Id is required.&#x27; or &#x27;Invalid rule id&#x27; (rule does not belong to this service); 401 unauthenticated; 500 if upstream Scrub::geoFirewallDelete fails. Caveat: removing a country/ASN block re-admits that traffic. Siblings: createGeoRule, scrubIpsDeleteRule, deleteFilter, getScrubIpDetails.
     * @param body  
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/delete_geo_rule") class scrubIpsDeleteGeoRule(val body: Delete_Geo_Firewall_Rule, val id: kotlin.Int)

    /**
     * Delete an L3/L4 firewall rule by rule_id from getScrubIpDetails
     * Removes a previously created L3/L4 firewall rule from the Scrub IP service. The rule_id must come from the &#x60;filter_firewall.rules[].id&#x60; array returned by getScrubIpDetails — the endpoint validates the id belongs to this service before deleting. Path param: &#x60;id&#x60; (integer, required) — Scrub IP service ID. Body (JSON): {&#x60;rule_id&#x60;: integer, required}. Returns {success: true, text: &#x27;Firewall Rule has been deleted.&#x27;}. Errors: 400 Invalid Service, &#x27;rule_id is required.&#x27; or &#x27;Invalid rule id&#x27; (rule does not belong to this service); 401 unauthenticated; 500 if upstream Scrub::firewallDelete fails. Caveat: if the rule was the only protection against a specific source, deleting it re-exposes the IP. Siblings: createRule, scrubIpsDeleteGeoRule, deleteFilter, getScrubIpDetails.
     * @param body  
     * @param id ScrubIp ID number 
     */
    @Location("/scrub_ips/{id}/delete_rule") class scrubIpsDeleteRule(val body: Delete_Firewall_Rule, val id: kotlin.Int)

    /**
     * Place a custom dedicated server order, creating a real billable invoice
     * Submits a fully custom dedicated server order. Creates a &#x60;pending&#x60; &#x60;servers&#x60; row, a &#x60;Repeat_Invoice&#x60;, and the first invoice, then emails customer + admin. Caveat: real billable order — confirm with the user first.
Body (form fields): &#x60;cpu&#x60; (id from &#x60;cpu_li&#x60;), &#x60;hd[]&#x60; (array of drive ids), &#x60;memory&#x60;, &#x60;bandwidth&#x60;, &#x60;ips&#x60;, &#x60;os&#x60;, &#x60;cp&#x60;, &#x60;raid&#x60; (ids from &#x60;getNewServer&#x60;), &#x60;region&#x60; (region_id), &#x60;servername&#x60; (valid hostname), &#x60;rootpass&#x60;, &#x60;tos&#x60; (must be true), optional &#x60;comment&#x60;. &#x60;account.server_order_discount&#x60; (if set) applies.
Returns: &#x60;{ text:&#x27;Order Completed&#x27;, invoice, order }&#x60;. Errors: 422 &#x27;Missing/Invalid &lt;field&gt;&#x27;; 401 unauth.
Sibling ops: &#x60;getNewServer&#x60; (options), &#x60;placeBuyNowServer&#x60; (pre-built path), &#x60;getServerInfo&#x60; (view new order), &#x60;getServerInvoices&#x60;.
     * @param body  
     */
    @Location("/servers/order") class addServer(val body: ServerOrderPostRequest)

    /**
     * Get configurable options for a Rapid Deploy / coupon dedicated server
     * Step 1 of the Rapid Deploy / coupon dedicated server order flow. Returns options + pricing for either a marketplace asset (&#x60;a&#x3D;&lt;asset_id&gt;&#x60;) or a coupon (&#x60;c&#x3D;&lt;coupon_name&gt;&#x60;) so the order form can be rendered before &#x60;placeBuyNowServer&#x60;. Read-only; no charge. Sibling ops: &#x60;placeBuyNowServer&#x60; (commit), &#x60;getMPServers&#x60; (browse marketplace), &#x60;addServer&#x60; (custom build flow).

**Query (one required):**
- &#x60;a&#x60; (integer) — asset_id from &#x60;getMPServers&#x60;.
- &#x60;c&#x60; (string) — &#x60;server_coupons.name&#x60;.

**Returns:** &#x60;{ bandwidth[], ips[], os[], cp[], raid[], regions[], a?: {asset + items}, c?: {coupon + region} }&#x60;. Each option row is &#x60;{ id, short_desc, long_desc, monthly_price }&#x60; — feed those ids into &#x60;placeBuyNowServer&#x60;.

**Auth:** Session/API key.

**Errors:**
- &#x60;400&#x60; — &#x60;&#x27;No Server Coupon or Market-Place Asset Specified&#x27;&#x60; when neither &#x60;a&#x60; nor &#x60;c&#x60; is passed.
- &#x60;400&#x60; — &#x60;&#x27;Invalid Asset ID&#x27;&#x60; / &#x60;&#x27;No Server Coupon with that name&#x27;&#x60;.
- &#x60;409&#x60; — &#x60;&#x27;Server already sold!&#x27;&#x60; (asset already in-cart) or &#x60;&#x27;Server Out of stock&#x27;&#x60; (coupon).
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Next:** &#x60;placeBuyNowServer&#x60; (commit the order).
- **Browse:** &#x60;getMPServers&#x60;.
- **Custom build alternative:** &#x60;addServer&#x60;.

     */
    @Location("/servers/order/buy_now_server") class buyItNowServerOrder()

    /**
     * List Rapid Deploy (Buy-It-Now) marketplace dedicated servers with live pricing
     * Use to browse pre-built dedicated servers ready for immediate provisioning (Rapid Deploy / marketplace). No params, no body. Pulls live inventory from &#x60;mynew.interserver.net/ajax/server_a.php&#x60;.
Returns: array of &#x60;{ server_id, cpu: [model, {img,type,speed,num_cpus,num_cores}], memory, disk, bandwidth, ips, location, price }&#x60;. The &#x60;server_id&#x60; is the marketplace asset id — feed it into &#x60;buyItNowServerOrder&#x60; (GET options for asset &#x60;?a&#x3D;&lt;id&gt;&#x60;) and &#x60;placeBuyNowServer&#x60; (POST to commit). Errors: 401 if session expired.
Sibling ops: &#x60;buyItNowServerOrder&#x60; (configure asset), &#x60;placeBuyNowServer&#x60; (purchase), &#x60;getNewServer&#x60;/&#x60;addServer&#x60; (custom-spec build, not pre-built), &#x60;getServerList&#x60; (already-owned servers).
     */
    @Location("/buy_now_servers_list") class getMPServers()

    /**
     * Get custom dedicated server ordering options, regions, and pricing
     * Use before placing a fully custom (non-Rapid-Deploy) dedicated server order to discover available CPUs, drives, memory tiers, OS images, control panels, RAID levels, bandwidth packages, IP blocks, and regions with monthly prices. No params, no body.
Returns: object with &#x60;config_li&#x60; keyed by category (&#x60;cpu_li&#x60;, &#x60;hd_li&#x60;, &#x60;memory_li&#x60;, &#x60;bandwidth_li&#x60;, &#x60;ips_li&#x60;, &#x60;os_li&#x60;, &#x60;cp_li&#x60;, &#x60;raid_li&#x60;) plus &#x60;regions&#x60;. Use returned IDs as POST values for &#x60;addServer&#x60;. Note &#x60;hd_li&#x60; and &#x60;memory_li&#x60; are nested by &#x60;cpu&#x60; id — the chosen CPU constrains valid drive/memory options. Errors: 401 if not authenticated.
Sibling ops: &#x60;addServer&#x60; (commits the order), &#x60;buyItNowServerOrder&#x60; (pre-built marketplace alternative), &#x60;getMPServers&#x60; (browse marketplace).
     */
    @Location("/servers/order") class getNewServer()

    /**
     * Get full hardware, network, and lifecycle details for a dedicated server
     * Use to fetch complete configuration for one dedicated server — hardware, network/VLAN/IP layout, asset assignments, location, status, billing references, and client action links. Path param: &#x60;id&#x60; (integer server_id, from &#x60;getServerList&#x60;). No body.
Returns: &#x60;ViewServer::getDetails()&#x60; shape: &#x60;serviceInfo&#x60;, &#x60;networkInfo&#x60; (vlans + assets, with &#x60;ipmi_admin_username&#x60;/&#x60;ipmi_admin_password&#x60; and admin lease creds REDACTED for client safety), normalized &#x60;client_links&#x60;, &#x60;serviceType&#x60;. &#x60;admin_links&#x60;/raw &#x60;settings&#x60;/&#x60;csrf&#x60; stripped. Errors: 404 not owned; 401 unauth.
Sibling ops: &#x60;getServerInvoices&#x60;, &#x60;serverIpmiLiveGet&#x60;, &#x60;serverIpmiPowerGet&#x60; (single — prefer &#x60;serverBulkIpmiPowerGet&#x60; for many), &#x60;getServerReverseDns&#x60;, &#x60;getServersWelcomeEmail&#x60;, &#x60;serversCancel&#x60;.
     * @param id Server ID number. 
     */
    @Location("/servers/{id}") class getServerInfo(val id: kotlin.Int)

    /**
     * List billing invoices (charges + payments) tied to one dedicated server
     * Use to retrieve the invoice history for a single dedicated server — e.g. before a cancel, refund, or to show outstanding balances. Path param: &#x60;id&#x60; (integer server_id from &#x60;getServerList&#x60;). No body. Inherits from &#x60;MyAdmin\Api\Billing\InvoicesList&#x60; with module&#x3D;servers.
Returns: &#x60;ChargeInvoiceRows&#x60; array — invoice rows with id, date, amount, status, currency, line items. Errors: 404 if &#x60;id&#x60; not owned by the caller; 401 unauth.
Sibling ops: &#x60;getServerInfo&#x60; (current service state), &#x60;serversCancel&#x60; (cancel), &#x60;getBillingInvoice&#x60; (single invoice by invoice id), &#x60;getVpsInvoices&#x60;/&#x60;getDomainInvoices&#x60; for other modules, &#x60;getServersWelcomeEmail&#x60; to resend setup info.
     * @param id Server ID number 
     */
    @Location("/servers/{id}/invoices") class getServerInvoices(val id: kotlin.Int)

    /**
     * List all dedicated servers owned by the authenticated customer
     * Use to enumerate physical bare-metal dedicated servers on the calling account. No params, no body. Filters &#x60;servers&#x60; by session &#x60;account_id&#x60;.
Returns: array of &#x60;{ server_id, account_lid, server_hostname, server_status }&#x60;. Use &#x60;server_id&#x60; with &#x60;getServerInfo&#x60; for full hardware/network/IPMI details, &#x60;getServerInvoices&#x60; for billing, or &#x60;serverIpmiPowerGet&#x60; for chassis power state. Errors: 401 if not authenticated; empty array if account owns no servers.
Sibling ops: &#x60;getServerInfo&#x60; (details), &#x60;getVpsList&#x60; (virtual instead of physical hardware), &#x60;getMPServers&#x60; (purchasable inventory, not owned). For IPMI status across many servers in one call, prefer &#x60;serverBulkIpmiPowerGet&#x60;.
     */
    @Location("/servers") class getServerList()

    /**
     * List current reverse-DNS (PTR) records for a dedicated server&#x27;s IPs
     * Use to read the existing PTR/rDNS hostnames assigned to each public IP in the server&#x27;s VLANs — typically before calling &#x60;postServerReverseDns&#x60; to update them. Path param: &#x60;id&#x60; (integer server_id). No body. Walks &#x60;networkInfo.vlans&#x60;, expands each network to usable host IPs (handles /31 and /32 edge cases), and resolves each via &#x60;get_hostname()&#x60;.
Returns: &#x60;{ ips: { &#x27;&lt;ipv4&gt;&#x27;: &#x27;&lt;ptr_or_empty_string&gt;&#x27;, ... } }&#x60;. Empty string indicates no PTR set. Errors: 404 if &#x60;id&#x60; not owned by caller; 401 unauth.
Sibling ops: &#x60;postServerReverseDns&#x60; (update PTRs), &#x60;getServerInfo&#x60; (full network), &#x60;getVpsReverseDns&#x60; for VPS, &#x60;getDomainNameservers&#x60; / DNS endpoints for forward records. Note rDNS propagation is delegated to the in-addr.arpa zone — changes are not always instant.
     * @param id Server ID number 
     */
    @Location("/servers/{id}/reverse_dns") class getServerReverseDns(val id: kotlin.Int)

    /**
     * Resend the dedicated server welcome email with setup credentials
     * Use when the customer asks for the original setup/login info to be re-sent (root password, IPs, control-panel URL). Path param: &#x60;id&#x60; (integer server_id, must be &#x60;active&#x60;). No body. Invokes &#x60;server_welcome_email($id)&#x60; which re-sends the welcome message to the account&#x27;s email.
Returns: &#x60;{ text:&#x27;Welcome Email has been resent.&#x27; }&#x60;. Errors: 404 if &#x60;id&#x60; not owned by caller; 409 if service not active (cancelled/pending/suspended); 401 unauth. Caveat: re-sending is rate-sensitive; do not call repeatedly in a loop. The email may contain root credentials — confirm intent before triggering.
Sibling ops: &#x60;getServerInfo&#x60; (status check), &#x60;getServerInvoices&#x60;, &#x60;getVpsWelcomeEmail&#x60; for VPS, &#x60;getDomainsWelcomeEmail&#x60; for domains.
     * @param id Server ID number 
     */
    @Location("/servers/{id}/welcome_email") class getServersWelcomeEmail(val id: kotlin.Int)

    /**
     * Place a Rapid Deploy / coupon dedicated server order; creates real invoice
     * Step 2 of the Rapid Deploy / coupon order flow. Commits a marketplace asset OR coupon-based dedicated server order. Inserts the &#x60;servers&#x60; row, creates a &#x60;Repeat_Invoice&#x60; plus the first &#x60;invoices&#x60; row, marks the asset &#x60;MarketPlace-Incart&#x60; (or decrements &#x60;server_coupons.in_stock&#x60;), then emails customer + admin. **Real billable order — confirm intent first.** Sibling ops: &#x60;buyItNowServerOrder&#x60; (catalog), &#x60;getServerInfo&#x60; (poll provisioning), &#x60;getServerInvoices&#x60; (billing), &#x60;addServer&#x60; (custom build alternative).

**Query (one required, same as &#x60;buyItNowServerOrder&#x60;):**
- &#x60;a&#x60; (integer) — asset_id.
- &#x60;c&#x60; (string) — &#x60;server_coupons.name&#x60;.

**Body fields:**
- &#x60;hostname&#x60; (string, required) — valid FQDN; validated by &#x60;valid_hostname&#x60;.
- &#x60;enablepassword&#x60; (boolean, optional, default &#x60;false&#x60;) — when true the client must supply &#x60;rootPassword&#x60;; otherwise a secure password is generated server-side via &#x60;generate_password()&#x60;.
- &#x60;rootPassword&#x60; (string, required when &#x60;enablepassword&#x3D;true&#x60;) — must be ≥8 chars with at least one uppercase, lowercase, digit, and special character (&#x60;valid_password&#x60;).
- &#x60;os&#x60;, &#x60;bandwidth&#x60;, &#x60;ips&#x60;, &#x60;cp&#x60;, &#x60;raid&#x60; (integer, optional) — option ids from &#x60;buyItNowServerOrder&#x60;; defaults &#x60;30&#x60; / &#x60;10&#x60; / &#x60;9&#x60; / &#x60;1&#x60; / &#x60;0&#x60; applied when missing.
- &#x60;comments&#x60; (string, optional) — appended to the order comment.

**Returns:** &#x60;201 { success: true, text: &#x27;Server order is placed.&#x27;, service_id, invoice_id }&#x60;.

**Auth:** Session/API key.

**Errors:**
- &#x60;400&#x60; — &#x60;&#x27;Server Hostname is missing.&#x27;&#x60; / &#x60;&#x27;Invalid Hostname!&#x27;&#x60; / &#x60;&#x27;Server Password is missing.&#x27;&#x60; / password complexity message.
- &#x60;409&#x60; — &#x60;&#x27;Server already sold!&#x27;&#x60; / &#x60;&#x27;Server Out of stock.&#x27;&#x60;
- &#x60;401&#x60; — unauthenticated.

**Side effects:** inserts &#x60;servers&#x60; row, creates &#x60;repeat_invoices&#x60; + &#x60;invoices&#x60; rows, updates &#x60;assets.status&#x60; or &#x60;server_coupons.in_stock&#x60;, queues admin + customer welcome emails.

**Related calls:**
- **Prerequisite:** &#x60;buyItNowServerOrder&#x60;.
- **Next:** &#x60;getBillingInvoice&#x60; + &#x60;initiatePayment&#x60; to pay, then poll &#x60;getServerInfo&#x60; for provisioning state.
- **Custom build alternative:** &#x60;addServer&#x60;.

     * @param body  (optional)
     */
    @Location("/servers/order/buy_now_server") class placeBuyNowServer(val body: OrderBuyNowServerBody)

    /**
     * Update reverse-DNS (PTR) hostnames on a dedicated server&#x27;s IPs
     * Use to set or remove PTR records for the server&#x27;s public IPs. Path param: &#x60;id&#x60; (server_id). Body: &#x60;ips&#x60; (object mapping &#x60;&#x27;&lt;ipv4&gt;&#x27;&#x60; to desired hostname; empty string removes the PTR). Only IPs that already exist on the server&#x27;s VLANs and whose hostname differs from current are updated; each diff calls &#x60;reverse_dns($ip, $host, &#x27;set_reverse&#x27;|&#x27;remove_reverse&#x27;)&#x60;.
Returns: &#x60;{ message, success:bool }&#x60;. &#x60;success:false&#x60; with &#x27;No valid IPs were passed or there were no changes&#x27; when nothing to update; otherwise reports update count. Errors: 404 invalid id; 401 unauth. Caveats: caller can only set PTRs for IPs they actually own; rDNS propagation is async — do not assume immediate visibility downstream.
Sibling ops: &#x60;getServerReverseDns&#x60; (read first), &#x60;getServerInfo&#x60;, VPS counterpart &#x60;postVpsReverseDns&#x60;.
     * @param body  
     * @param id Server ID number 
     */
    @Location("/servers/{id}/reverse_dns") class postServerReverseDns(val body: ReverseDnsEntries, val id: kotlin.Int)

    /**
     * Read IPMI chassis power status for many dedicated servers in one call
     * Use when you need power status for several owned servers at once (dashboards, mass health checks). Each server is queried independently; per-server failures (invalid id, inactive service, no asset, BMC error) are reported in the same response without aborting the batch. Read-only — does NOT change power state.
Query: &#x60;ids&#x60; (required) — comma-separated string &#x60;?ids&#x3D;2313,2314,2315&#x60; OR repeated &#x60;ids[]&#x60; array. Duplicates de-duped; non-positive ints become per-row errors. Returns: &#x60;{ results: [ { id, asset?, text|error } ] }&#x60;. Errors: 400 &#x27;No server IDs provided.&#x27; if &#x60;ids&#x60; empty/missing; 401 unauth.
Sibling ops: &#x60;serverIpmiPowerGet&#x60; (single-server equivalent), &#x60;serverIpmiPowerPost&#x60; (DESTRUCTIVE — change power; no bulk equivalent — call per server), &#x60;getServerList&#x60; (discover ids).
     * @param ids Comma-separated list of Server IDs to query (e.g. &#x60;2313,2314,2315&#x60;). May also be passed as repeated &#x60;ids[]&#x60; query parameters. 
     */
    @Location("/servers/bulk/ipmi_power") class serverBulkIpmiPowerGet(val ids: kotlin.String)

    /**
     * Read current IPMI Live whitelist + KVM gateway URL for a dedicated server
     * Reads the active IPMI Live session for a dedicated server — the temporary whitelisted public IP, the customer-side IPMI gateway URL, and the IPMI client (read-only) credentials so the customer can open the KVM/console. Looks up the asset&#x27;s IPMI IP, the location&#x27;s IPMI group, and any active &#x60;ipmi_ips&#x60; lease (3-hour TTL). Sibling ops: &#x60;serverIpmiLivePost&#x60; (allocate whitelist slot), &#x60;serverIpmiPowerGet&#x60; / &#x60;serverIpmiPowerPost&#x60; (chassis power).

**Path:** &#x60;id&#x60; (integer, required) — server_id from &#x60;getServerList&#x60;.

**Body / query:** None. Optionally pass &#x60;asset&#x60; (asset_id) to target a specific asset; default is first asset.

**Returns:** when an active lease exists &#x60;{ text (html), public_ip, allowed_ip, client_username, client_password }&#x60;. When no lease yet: &#x60;{ text: &#x27;Setup not yet completed&#x27; }&#x60; — then call &#x60;serverIpmiLivePost&#x60; to allocate a slot.

**Auth:** Session/API key. Ownership enforced via &#x60;server_custid&#x60;.

**Errors:**
- &#x60;404&#x60; — &#x60;id&#x60; not owned, or &#x60;asset&#x60; not on this server.
- &#x60;409&#x60; — service not &#x60;active&#x60;.
- &#x60;200&#x60; with error text &#x60;&#x27;No IPMI IP Set&#x27;&#x60; / &#x60;&#x27;Invalid IPMI IP&#x27;&#x60; / &#x60;&#x27;Live IPMI not Available for this location.&#x27;&#x60; when the asset/location is not configured for IPMI Live.

**Caveat:** returns &#x60;client_password&#x60; — never log/echo verbatim.

**Related calls:**
- **Allocate:** &#x60;serverIpmiLivePost&#x60;.
- **Chassis power:** &#x60;serverIpmiPowerGet&#x60;, &#x60;serverIpmiPowerPost&#x60;.

     * @param id Server ID number 
     */
    @Location("/servers/{id}/ipmi_live") class serverIpmiLiveGet(val id: kotlin.Int)

    /**
     * Whitelist an IP for IPMI Live KVM gateway access (3-hour lease)
     * Allocates / refreshes an IPMI Live whitelist slot so the customer&#x27;s specified IP can reach the BMC&#x27;s KVM/console for 3 hours. Picks a free &#x60;ipmi_ips&#x60; row for the location&#x27;s &#x60;ipmi_group&#x60;, refreshes the lease if the same IP is already allocated, otherwise pushes the new whitelist via &#x60;ipmi_live_setup()&#x60;. Sibling ops: &#x60;serverIpmiLiveGet&#x60; (read current lease), &#x60;serverIpmiPowerPost&#x60; (DESTRUCTIVE — chassis power).

**Path:** &#x60;id&#x60; (integer, required) — server_id.

**Body fields:**
- &#x60;ip&#x60; (string, required) — public IPv4 to whitelist.
- &#x60;asset&#x60; (integer, optional) — asset_id; defaults to first asset on the server.

**Returns:** &#x60;{ text (html), public_ip, allowed_ip, client_username, client_password }&#x60; for KVM login.

**Auth:** Session/API key. Ownership enforced via &#x60;server_custid&#x60;.

**Errors:**
- &#x60;404&#x60; — &#x60;id&#x60; not owned, or &#x60;asset&#x60; not on this server.
- &#x60;409&#x60; — service not &#x60;active&#x60;.
- &#x60;200&#x60; with error text — &#x60;&#x27;An Invalid IP was passed.&#x27;&#x60;, &#x60;&#x27;No Live IPs are currently free for use with the IPMI Gateway. Please wait &lt;duration&gt; for the next IP to free up.&#x27;&#x60;, &#x60;&#x27;There was an error communicating with the IPMI Management server&#x27;&#x60;, &#x60;&#x27;No IPMI IP Set&#x27;&#x60; / &#x60;&#x27;Invalid IPMI IP&#x27;&#x60; / &#x60;&#x27;Live IPMI not Available for this location.&#x27;&#x60;.

**Caveat:** returns IPMI client password — handle securely; whitelist exposes the BMC briefly.

**Related calls:**
- **Read current lease:** &#x60;serverIpmiLiveGet&#x60;.
- **Power control:** &#x60;serverIpmiPowerPost&#x60;.

     * @param asset  
     * @param ip  
     * @param id Server ID number 
     */
    @Location("/servers/{id}/ipmi_live") class serverIpmiLivePost(val asset: kotlin.Int, val ip: kotlin.String, val id: kotlin.Int)

    /**
     * Read IPMI chassis power status for a dedicated server (single)
     * Use to check whether a server&#x27;s chassis is currently &#x60;on&#x60;/&#x60;off&#x60; via IPMI before issuing a power action. Path param: &#x60;id&#x60; (integer server_id). Optional body &#x60;asset&#x60; (asset_id — defaults to first asset). Issues &#x60;ipmitool power status&#x60; against the asset&#x27;s &#x60;ipmi_ip&#x60; using its location IPMI group/credentials.
Returns: &#x60;{ text:&#x27;Chassis Power is on&#x27; }&#x60; (or &#x27;off&#x27;). Errors: 404 if &#x60;id&#x60; not owned by caller; 409 if service not active; &#x27;There was an error sending the IPMI command&#x27; if BMC unreachable. Caveat: BMCs occasionally rate-limit — back off on repeated errors.
Sibling ops: &#x60;serverBulkIpmiPowerGet&#x60; (preferred when polling many servers — single round-trip), &#x60;serverIpmiPowerPost&#x60; (DESTRUCTIVE — change power), &#x60;getServerInfo&#x60; (full state), &#x60;serverIpmiLiveGet&#x60; (IPMI Live KVM).
     * @param id Server ID number 
     */
    @Location("/servers/{id}/ipmi_power") class serverIpmiPowerGet(val id: kotlin.Int)

    /**
     * DESTRUCTIVE — change chassis power state on a bare-metal server
     * Sends an IPMI chassis power command (&#x60;on&#x60;, &#x60;off&#x60;, &#x60;cycle&#x60;, &#x60;reset&#x60;, &#x60;soft&#x60;) to a customer&#x27;s physical dedicated server. **DESTRUCTIVE on running hardware:** &#x60;off&#x60; / &#x60;cycle&#x60; / &#x60;reset&#x60; are forced power events that can corrupt filesystems, lose un-flushed data, or break in-flight workloads. &#x60;soft&#x60; requests an ACPI shutdown (safer when the guest OS is responsive). Always confirm intent with the operator. Sibling ops: &#x60;serverIpmiPowerGet&#x60; (read first), &#x60;serverBulkIpmiPowerGet&#x60; (status only), &#x60;serverIpmiLivePost&#x60; (KVM access).

**Path:** &#x60;id&#x60; (integer, required) — server_id.

**Body fields:**
- &#x60;action&#x60; (string, required) — one of &#x60;on&#x60; / &#x60;off&#x60; / &#x60;cycle&#x60; / &#x60;reset&#x60; / &#x60;soft&#x60;.
- &#x60;asset&#x60; (integer, optional) — asset_id; defaults to first asset on the server.

**Returns:** &#x60;{ text: &#x27;Power command sent. Response: &lt;ipmi output&gt;&#x27; }&#x60;.

**Auth:** Session/API key. Ownership enforced via &#x60;server_custid&#x60;.

**Errors:**
- &#x60;422&#x60; / inline error text — &#x60;Invalid Action&#x60; when &#x60;action&#x60; is not in the allowed set.
- &#x60;404&#x60; — &#x60;id&#x60; not owned, or &#x60;asset&#x60; not on this server.
- &#x60;409&#x60; — service not &#x60;active&#x60;.
- &#x60;200&#x60; with error text — &#x60;&#x27;There was an error sending the IPMI command.&#x27;&#x60; when BMC is unreachable or rate-limiting.

**Related calls:**
- **Status (single / bulk):** &#x60;serverIpmiPowerGet&#x60;, &#x60;serverBulkIpmiPowerGet&#x60;.
- **KVM console:** &#x60;serverIpmiLivePost&#x60;.

     * @param asset  
     * @param action  
     * @param id Server ID number 
     */
    @Location("/servers/{id}/ipmi_power") class serverIpmiPowerPost(val asset: kotlin.Int, val action: kotlin.String, val id: kotlin.Int)

    /**
     * Cancel a dedicated server service at the end of the current billing cycle
     * Submits a cancellation request for a dedicated server. The server is deprovisioned and recurring billing stops at the end of the current billing cycle (not an immediate refund). Path param: &#x60;id&#x60; (integer server_id, from &#x60;getServerList&#x60;). No body.
Caveat: billing-affecting action — always confirm with the user. Hardware-attached data may be wiped on deprovisioning. Returns: &#x60;{ success:bool, text:&#x27;Servers is canceled.&#x27; }&#x60;. Errors: 404 if &#x60;id&#x60; not owned by caller; 409 if already cancelled or non-active; 401 unauth.
Sibling ops: &#x60;getServerInfo&#x60; (current status), &#x60;getServerInvoices&#x60; (outstanding charges), VPS counterpart &#x60;VPSCancel&#x60;. To re-order after cancel use &#x60;addServer&#x60; or &#x60;placeBuyNowServer&#x60;.
     * @param id Server ID number 
     */
    @Location("/servers/{id}") class serversCancel(val id: kotlin.Int)

    /**
     * Update settings on a dedicated server order (shares handler with view)
     * Use to modify metadata on an existing dedicated server order. Path param: &#x60;id&#x60; (integer server_id). Currently this method shares the same handler as &#x60;getServerInfo&#x60; (&#x60;View::go()&#x60;) — no dedicated update fields are processed; treat it as deprecated/no-op pending field-specific endpoints. For hostname, password, or rDNS changes use the dedicated ops below.
Returns: same payload shape as &#x60;getServerInfo&#x60;. Errors: 404 if &#x60;id&#x60; not owned by caller; 401 unauth.
Sibling ops: prefer &#x60;postServerReverseDns&#x60; (rDNS), &#x60;serverIpmiPowerPost&#x60; (power), &#x60;serverIpmiLivePost&#x60; (IPMI access), &#x60;serversCancel&#x60; (cancel). For new orders use &#x60;addServer&#x60; or &#x60;placeBuyNowServer&#x60;. View-only: &#x60;getServerInfo&#x60;.
     * @param id Server ID number. 
     */
    @Location("/servers/{id}") class updateServerInfo(val id: kotlin.String)

    /**
     * Open a new helpdesk ticket, optionally linked to a service and attachments
     * Use when the customer wants to contact support. Creates the Kayako ticket in the &#x27;New Unassigned&#x27; department (id 18). Body (form): subject (string, required), body (string, required), product (string, optional, format &#x27;{module}-{service_id}&#x27; from getNewTicket), service_id+service_module (alternative to product), attachments[] (optional, each {name, type, content base64}), and optional server-access custom fields ip, root_pass, sudo_user, sudo_pass, port_no, server_access (passwords are AES-encrypted with a generated auth_key). Returns: {success: true, text, ticket: ticketmaskid}. Errors: 400 missing subject or body; 401 unauthorized; 422 ticket creation failure. Sibling: getNewTicket for product list, getTicketInfo to view, ReplyTicket to add replies.
     * @param body  
     */
    @Location("/tickets/new") class addNewTicket(val body: TicketNew)

    /**
     * Close an open support ticket via simple GET request (no body required)
     * Use to close a ticket from a link or one-click action — closure-only equivalent of deleteTicketInfo with friendlier semantics. Calls Ticket::closeTicket on the resolved ticket and leaves the record fully readable; closed tickets disappear from the active inbox but remain in getTicketsList when view&#x3D;Closed. Path: id (int ticket ID, e.g. 1511222). Body: none. Returns: {success: true, text: &#x27;Ticket is closed!&#x27;} or {success: false, text: &#x27;Unable to close ticket&#x27;}. Errors: 401 unauthorized; 404 implied via &#x27;Unable to close ticket&#x27; when id is unknown or cross-account. Idempotent on already-closed tickets. Siblings: deleteTicketInfo (DELETE /tickets/{id} — same effect), getTicketInfo to confirm new status.
     * @param id Ticket ID 
     */
    @Location("/tickets/{id}/close") class closeTicket(val id: kotlin.String)

    /**
     * Close a customer ticket via DELETE verb (closes only, never destroys data)
     * Use when the customer marks a ticket resolved. IMPORTANT: despite the DELETE verb this only CLOSES the ticket via Ticket::closeTicket — no data is destroyed. Closed tickets remain readable through getTicketInfo and appear in getTicketsList when view&#x3D;Closed. Path: id (int ticket ID). Body: none. Returns: &#x27;Ticket is closed!&#x27; string on success. Errors: 401 unauthorized; 404/422 &#x27;Invalid ticket!&#x27; when id is unknown or owned by another account. Idempotent on already-closed tickets. Siblings: CloseTicket (GET /tickets/{id}/close — same effect, simpler URL), ReplyTicket to add a final reply before closing, getTicketInfo to verify state.
     * @param id Ticket ID number. 
     */
    @Location("/tickets/{id}") class deleteTicketInfo(val id: java.math.BigDecimal)

    /**
     * Fetch services and product options to populate the new-ticket form
     * Use to populate dropdowns before calling addNewTicket. Returns the customer&#x27;s services grouped by product type so the user can attach a ticket to a specific resource. Iterates all enabled modules (vps, webhosting, domains, mail, etc.; mailbaby instances see only mail) and filters out services with status canceled, deleted, or fraud. Params: none. Body: none. Returns: object keyed by product TITLE (e.g. &#x27;Vps&#x27;, &#x27;Webhosting&#x27;), each value a map of &#x27;{module}-{service_id}&#x27; to a description string including title, type/plan, VPS hypervisor name where applicable, and uppercase status tag. Errors: 401 unauthorized. Use the returned product key as the &#x27;product&#x27; field on addNewTicket.

Sibling ops: &#x60;addNewTicket&#x60; (consumes the product key), &#x60;getTicketsList&#x60;.
     */
    @Location("/tickets/new") class getNewTicket()

    /**
     * Get full ticket details including subject, status, and the reply thread
     * Use to render a ticket page or feed full context to an LLM. Path: id (int, ticket ID, e.g. 1511222). Returns ticket header (subject, status, department, dates), the ordered post/reply history, attachments, and any custom-field values. Resolved via Ticket::getTicket(id, account_lid) so cross-account access returns Invalid ticket. Body: none. Errors: 401 unauthorized; 404/422 &#x27;Invalid ticket!&#x27; when the id is unknown or owned by another account. Caveats: the same path with POST appends a reply (postTicketInfo) and DELETE closes the ticket (deleteTicketInfo) — it does not destroy data. Siblings: ReplyTicket, updateTicketInfo, CloseTicket, getTicketsList.
     * @param id Ticket ID number. 
     */
    @Location("/tickets/{id}") class getTicketInfo(val id: java.math.BigDecimal)

    /**
     * List the authenticated account&#x27;s support tickets with status and date filters
     * Use to browse the customer&#x27;s helpdesk tickets, paginated, with optional status and recency filters. Returns tickets where email matches the session account_lid. Query params: page (int, default 1, 50 per page), period (string: &#x27;30&#x27;, &#x27;90&#x27;, &#x27;365&#x27;, &#x27;1825&#x27;, or &#x27;all&#x27; days back; default &#x27;30&#x27;), view (string: &#x27;Open&#x27;, &#x27;Closed&#x27;, &#x27;On Hold&#x27;, &#x27;In Progress&#x27;; omit for all). Body: none. Returns: object with tickets[], total, pages, currentPage, st_count[] (counts grouped by status: Open/On Hold/Closed), selected_period, view. Errors: 401 unauthorized session. Note ticketstatusid mapping (Open&#x3D;4, On Hold&#x3D;5, Closed&#x3D;6, In Progress&#x3D;7). To search by subject/email/mask use postTicketsList. To open a ticket detail use getTicketInfo with the returned id. To create a new ticket see addNewTicket.

Sibling ops: &#x60;getTicketInfo&#x60; (detail), &#x60;postTicketsList&#x60; (search), &#x60;addNewTicket&#x60; (open new).
     * @param page Page number for paginated results. (optional, default to 1)
     * @param period How far back to show tickets from. Value is in days. (optional, default to 30)
     * @param view The status of tickets to view. Possible values are Open, Closed, On Hold, and In Progress.  If not specified it will show all types. (optional)
     */
    @Location("/tickets") class getTicketsList(val page: kotlin.Int, val period: kotlin.String, val view: kotlin.String)

    /**
     * Append a reply (and optional attachment, server-access fields) to a ticket
     * Use to post a customer reply on an existing ticket. Path: id (int ticket ID). Body: body (string reply text; trimmed to first 500 words), file_attachment (multipart upload, optional), and the server-access custom fields ip/root_pass/sudo_user/sudo_pass/port_no/server_access (passwords AES-encrypted with auth_key&#x3D;7). Either body OR an attachment is required. Notifies any swticketwatchers staff via templated email after posting. Returns: {status: &#x27;success&#x27;, message: &#x27;Reply posted successfully&#x27;}. Errors: 400 &#x27;Please enter a message or attach a file&#x27;; 401 unauthorized; 404/422 &#x27;Invalid ticket!&#x27; when id missing or cross-account. Sibling: ReplyTicket (cleaner JSON-only reply at /tickets/{id}/reply), updateTicketInfo, getTicketInfo, deleteTicketInfo.
     * @param id Ticket ID number. 
     */
    @Location("/tickets/{id}") class postTicketInfo(val id: java.math.BigDecimal)

    /**
     * Search the authenticated account&#x27;s tickets by subject, email, or mask ID
     * Use when the user supplies a search term (subject keyword, email substring, or full ticket mask ID like &#x27;ABC-123-456&#x27;). Scoped to tickets owned by the session account_lid. Body (form): search (string, required). If the term contains exactly two hyphens it is treated as an exact ticketmaskid match; otherwise a LIKE search runs across subject, email, and ticketmaskid. Returns: array of up to 25 matching ticket rows ordered by lastactivity DESC, each enriched with lastactivity_time (human-relative). Errors: 400 if search is empty or missing; 401 unauthorized. Caveat: this is a POST that reads, not a creator. To create see addNewTicket. To paginate full inbox use getTicketsList. To open one use getTicketInfo.

Sibling ops: &#x60;getTicketsList&#x60; (full inbox), &#x60;getTicketInfo&#x60; (detail), &#x60;addNewTicket&#x60; (open new).
     */
    @Location("/tickets") class postTicketsList()

    /**
     * Update a ticket&#x27;s properties such as subject or status (stub, not implemented)
     * Reserved for future use to update ticket subject/status. The PHP handler is currently an empty stub that returns no body, so callers should not rely on it in production. Path: id (int). Body: would carry subject/status fields when implemented. Returns: undefined behavior today. Errors: 401 unauthorized; expect 404/422 when implemented if id is invalid or not owned. Caveats: prefer updateTicketInfo (POST /tickets/{id}/update) for editing custom-field values today, postTicketInfo to add a reply, CloseTicket or deleteTicketInfo to close. Avoid scripting against this endpoint until the handler ships. Siblings: getTicketInfo, ReplyTicket.
     * @param id Ticket ID number. 
     */
    @Location("/tickets/{id}") class putTicketInfo(val id: java.math.BigDecimal)

    /**
     * Post a simple text reply to an existing ticket thread (no attachments)
     * Use this lightweight endpoint to add a reply to an existing ticket without attachments or server-access fields. Cleaner alternative to postTicketInfo when only text is being submitted. Path: id (int ticket ID). Body (form): content (string, required reply body). Returns: {success: true, post_id: int} on success or {success: false, text: &#x27;Reply content cannot be empty!&#x27; | &#x27;Unable to reply ticket&#x27;}. Errors: 401 unauthorized; 404 implied via &#x27;Unable to reply ticket&#x27; when id is invalid or owned by another account. Siblings: postTicketInfo (POST /tickets/{id}, supports attachments + custom fields), updateTicketInfo (custom fields only), CloseTicket, getTicketInfo to verify the new post_id appears in the thread.
     * @param id The ticket ID number. 
     * @param body  (optional)
     */
    @Location("/tickets/{id}/reply") class replyTicket(val id: java.math.BigDecimal, val body: ReplyTicketRequest)

    /**
     * Update a ticket&#x27;s custom field values (server-access details, etc.)
     * Use to save or change the structured custom-field values attached to a ticket — typically server-access details supplied by the customer. Path: id (int ticket ID). Body (form): one field per custom-field title, lowercased with spaces replaced by underscores (e.g. ip, root_pass, sudo_user, sudo_pass, port_no, server_access). Field id 7 (auth_key) is skipped — never set it directly. Returns: {success: true, text: &#x27;Ticket is updated!&#x27;} or {success: false, text: &#x27;Unable to update ticket&#x27;}. Errors: 401 unauthorized; 404 invalid or non-owned ticket. Caveats: this updates metadata only — to add a reply use ReplyTicket, to close use CloseTicket, to read current state use getTicketInfo.

Sibling ops: &#x60;getTicketInfo&#x60; (read), &#x60;ReplyTicket&#x60; (reply), &#x60;CloseTicket&#x60; (close).
     * @param id The ticket ID number. 
     * @param body  (optional)
     */
    @Location("/tickets/{id}/update") class updateTicketInfo(val id: java.math.BigDecimal, val body: UpdateTicket)

    /**
     * Place a new VPS order, create the invoice, and queue provisioning
     * Step 3 of the VPS order flow — actually places the order. Revalidates the same configuration that &#x60;putVps&#x60; accepts (so the request is safe even if &#x60;putVps&#x60; was skipped), then calls &#x60;place_buy_vps&#x60;: allocates a backing hypervisor server via &#x60;get_vps_next_server&#x60;, creates a &#x60;Repeat_Invoice&#x60; ORM row for the recurring charge, generates the initial &#x60;invoices&#x60; row via &#x60;$repeat_invoice-&gt;invoice()&#x60;, inserts a &#x60;vps&#x60; service record with &#x60;vps_status&#x3D;&#x27;pending&#x27;&#x60;, and creates any control-panel addon invoices (CPanel/DirectAdmin). Returns the new service id plus invoice ids the caller must pay before provisioning runs. **Real money** — call &#x60;putVps&#x60; first to preview cost. Sibling ops: &#x60;getNewVps&#x60;, &#x60;putVps&#x60;, &#x60;getVpsInfo&#x60;, &#x60;VPSCancel&#x60;.

**Body fields:** Identical to &#x60;putVps&#x60;. Required: &#x60;osDistro&#x60;, &#x60;osVersion&#x60;, &#x60;vpsPlatform&#x60;, &#x60;slices&#x60;. Optional: &#x60;location&#x60; (default 1), &#x60;period&#x60; (default 1), &#x60;coupon&#x60;, &#x60;hostname&#x60;, &#x60;rootpass&#x60;, &#x60;controlpanel&#x60; (default &#x60;none&#x60;), &#x60;comment&#x60;. Same validation rules apply (slice range, rootpass regex for Linux, hostname FQDN format, platform↔OS↔controlpanel compatibility).

**Returned fields** (schema &#x60;ServiceOrderPostResponse&#x60;):
- &#x60;success&#x60; (bool) — &#x60;true&#x60; on successful placement.
- &#x60;serviceid&#x60; (integer) — new VPS id; use this with &#x60;getVpsInfo&#x60; to poll status.
- &#x60;iid&#x60; (string) — primary invoice id (numeric).
- &#x60;real_iids&#x60; (array of strings) — numeric invoice ids to pass to &#x60;initiatePayment&#x60; (&#x60;invoices&#x60; path param).
- &#x60;iids&#x60; (array of strings) — tagged invoice ids (e.g. &#x60;SERVICEvps12345&#x60;) — alternative payment identifier.
- &#x60;total_cost&#x60; (decimal string) — total to pay across all generated invoices.
- &#x60;invoice_description&#x60; (string) — human-readable summary (e.g. &#x60;KVM 2 Slices&#x60;).
- &#x60;cj_params&#x60; (object) — Commission Junction tracking parameters (affiliate flows).

**Side effects:**
- Inserts row into &#x60;vps&#x60; table (&#x60;vps_status&#x3D;&#x27;pending&#x27;&#x60;).
- Inserts &#x60;repeat_invoices&#x60; row for the recurring charge.
- Inserts &#x60;invoices&#x60; row for the first period charge.
- Inserts additional &#x60;invoices&#x60; rows for CPanel/DirectAdmin addons if &#x60;controlpanel !&#x3D; &#x27;none&#x27;&#x60;.
- Logs a &#x60;vps&#x60; signup event in &#x60;history_log&#x60;.
- Saves root password to &#x60;history_log&#x60; (encrypted at rest).

**Errors:**
- &#x60;400 Bad Request&#x60; — validation failed; response body is the &#x60;errors&#x60; array from validation.
- &#x60;401 Unauthorized&#x60; — missing session/API key.

**Related calls:**
- **Prerequisite:** &#x60;getNewVps&#x60; (catalog), &#x60;putVps&#x60; (preview cost — strongly recommended).
- **Next:** &#x60;getBillingInvoice&#x60; (review invoice line items), &#x60;initiatePayment&#x60; (&#x60;GET /billing/pay/{method}/{invoices}&#x60; — pay with &#x60;real_iids&#x60;), then &#x60;getVpsInfo&#x60; (poll for &#x60;vps_status &#x3D;&#x3D; &quot;active&quot;&#x60;), &#x60;getVpsWelcomeEmail&#x60; (resend credentials).
- **Cancel before paying:** &#x60;VPSCancel&#x60;.

**Example request body:** Same as &#x60;putVps&#x60;.

**Example response:**
&#x60;&#x60;&#x60;json
{
  &quot;success&quot;: true,
  &quot;serviceid&quot;: 12345,
  &quot;iid&quot;: &quot;25296600&quot;,
  &quot;real_iids&quot;: [&quot;25296600&quot;],
  &quot;iids&quot;: [&quot;SERVICEvps12345&quot;],
  &quot;total_cost&quot;: &quot;12.00&quot;,
  &quot;invoice_description&quot;: &quot;KVM 2 Slices&quot;,
  &quot;cj_params&quot;: {}
}
&#x60;&#x60;&#x60;
**Full ordering happy path:**
&#x60;&#x60;&#x60;text
GET /vps/order                                  -&gt; catalog (getNewVps)
PUT /vps/order { ...config }                    -&gt; price quote (putVps)
POST /vps/order { ...config }                   -&gt; { serviceid, real_iids } (addVps)
GET /billing/invoices/{iid}                     -&gt; confirm invoice (getBillingInvoice)
GET /billing/pay/cc/{real_iids[0]}              -&gt; pay (payInvoice; type&#x3D;submit|redirect|single)
GET /vps/{serviceid}                            -&gt; poll until vps_status&#x3D;&#x3D;&quot;active&quot; (getVpsInfo)
&#x60;&#x60;&#x60;

     * @param body  (optional)
     */
    @Location("/vps/order") class addVps(val body: VpsOrderPostRequest)

    /**
     * Permanently delete a VPS backup file by name (irreversible)
     * Removes a backup file from storage to free space. For &#x60;minio&#x60;-typed backups runs &#x60;mc rm --force --recursive&#x60; on the path; for &#x60;swift&#x60;-typed backups removes the storage object via the Swift API. ZFS-typed backups **cannot** be deleted through this endpoint — they return an error directing the caller to open a support ticket. **Irreversible** — once deleted the backup cannot be used with &#x60;postVpsRestore&#x60; or &#x60;downloadVpsBackup&#x60;. Sibling ops: &#x60;getVpsBackups&#x60; (list), &#x60;downloadVpsBackup&#x60; (download first), &#x60;getVpsBackup&#x60; (create new).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Query params:**
- &#x60;file&#x60; (string, required) — exact &#x60;name&#x60; from &#x60;getVpsBackups&#x60; (the canonical backup identifier).

**Returns:** &#x60;SuccessTextResponse&#x60; — &#x60;Backup &lt;name&gt; removed.&#x60; on success.

**Side effects:**
- **minio**: &#x60;mc rm --force --recursive&#x60; removes the entire backup directory.
- **swift**: deletes the listed object(s) plus any multi-part &#x60;extra&#x60; segments.

**Auth:** Session/API key. Ownership enforced via parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;No file specified&#x60; — &#x60;file&#x60; query param missing.
- **ZFS backup:** &#x60;This type of backup if not removable. Please contact support if you need this removed.&#x60;
- **MinIO rm failure:** &#x60;Error removing file &lt;name&gt;&#x60;.

**Related calls:**
- **List first to get &#x60;name&#x60;:** &#x60;getVpsBackups&#x60;.
- **Download before deleting:** &#x60;downloadVpsBackup&#x60; (MinIO only; Swift/ZFS disabled).
- **Restore (don&#x27;t delete):** &#x60;postVpsRestore&#x60;.

     * @param id VPS ID number 
     * @param file The backup filename to delete. 
     * @param all Set to &#x60;1&#x60; to list all backups across all services, not just the ones for the given VPS. (optional)
     */
    @Location("/vps/{id}/backups") class deleteVpsBackup(val id: kotlin.Int, val file: kotlin.String, val all: kotlin.String)

    /**
     * Block outbound SMTP (port 25) on the VPS to prevent spam/abuse
     * Blocks outbound SMTP (port 25) traffic on the VPS at the hypervisor level — typical for cPanel/WHM customers who route through a smart relay, or for VPS that should never emit mail directly. Queues a &#x60;block_smtp&#x60; action on the &#x60;vpsqueue&#x60; and triggers a VNC re-setup. Despite being GET, this is a side-effecting action and the MCP parser flags it accordingly. **One-way from the client side:** there is no public unblock endpoint — re-enabling outbound SMTP requires a support ticket so abuse history can be reviewed. Sibling ops: &#x60;getVpsInfo&#x60; (verify state), &#x60;doVpsRestart&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — &#x60;queueId&#x60; references the &#x60;queue_log&#x60; row; allow up to 2 minutes for the iptables/firewall rule to take effect.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 VPS is not active&#x60; — &#x60;vps_status !&#x3D; &quot;active&quot;&#x60;.

**Reversibility:** Not client-reversible — open a ticket.

**Related calls:**
- **Verify state:** &#x60;getVpsInfo&#x60;.
- **General lifecycle:** &#x60;doVpsStart&#x60;, &#x60;doVpsStop&#x60;, &#x60;doVpsRestart&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/block_smtp") class doVpsBlockSmtp(val id: kotlin.Int)

    /**
     * Remove the virtual CD/DVD device entirely from the VPS configuration
     * Removes the virtual CD/DVD device from the VPS hardware configuration entirely — distinct from &#x60;doVpsEjectCd&#x60;, which only unmounts the ISO but leaves the drive attached. Queues a &#x60;disable_cd&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET. Reversible by attaching a new CD via &#x60;postVpsInsertCd&#x60;. Sibling ops: &#x60;doVpsEjectCd&#x60; (eject ISO but keep drive), &#x60;getVpsInsertCd&#x60; (list ISOs), &#x60;postVpsInsertCd&#x60; (mount ISO).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes for hypervisor action.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;disable_cd&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60; to refresh the VNC config.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Re-attach drive:** &#x60;postVpsInsertCd&#x60; (provide ISO URL).
- **Just unmount the ISO:** &#x60;doVpsEjectCd&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/disable_cd") class doVpsDisableCd(val id: kotlin.Int)

    /**
     * Disable per-user disk quota enforcement inside the VPS guest OS
     * Stops enforcing per-user disk quotas inside the VPS guest OS — useful when an application or user workflow conflicts with quota limits. Queues a &#x60;disable_quota&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET. Reversible via &#x60;doVpsEnableQuota&#x60;. Sibling op: &#x60;doVpsEnableQuota&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;disable_quota&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Re-enable:** &#x60;doVpsEnableQuota&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/disable_quota") class doVpsDisableQuota(val id: kotlin.Int)

    /**
     * Eject the mounted ISO from the VPS virtual CD drive (keep the drive)
     * Unmounts whatever ISO is currently in the VPS virtual CD drive, leaving the drive attached so another ISO can be mounted. Distinct from &#x60;doVpsDisableCd&#x60; (which removes the drive itself). Queues an &#x60;eject_cd&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET. Sibling ops: &#x60;getVpsInsertCd&#x60; (list available ISOs), &#x60;postVpsInsertCd&#x60; (mount a different one), &#x60;doVpsDisableCd&#x60; (remove drive entirely).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;eject_cd&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Mount a different ISO:** &#x60;postVpsInsertCd&#x60;.
- **Remove the drive entirely:** &#x60;doVpsDisableCd&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/eject_cd") class doVpsEjectCd(val id: kotlin.Int)

    /**
     * Enable per-user disk quota enforcement inside the VPS guest OS
     * Turns on per-user disk-quota enforcement inside the VPS guest OS. Queues an &#x60;enable_quota&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET. Reversible via &#x60;doVpsDisableQuota&#x60;. Sibling op: &#x60;doVpsDisableQuota&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;enable_quota&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Disable later:** &#x60;doVpsDisableQuota&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/enable_quota") class doVpsEnableQuota(val id: kotlin.Int)

    /**
     * Reboot the VPS — preferred over stop+start for software changes
     * Reboots the VPS — typically after a kernel update, configuration change, or to recover from an unresponsive state. **Preferred over &#x60;doVpsStop&#x60; followed by &#x60;doVpsStart&#x60;** because it preserves the boot context and lets the hypervisor handle the sequence atomically. Queues a &#x60;restart&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET. Idempotent in effect — restarting a running VPS reboots it, restarting a stopped VPS starts it. Sibling ops: &#x60;doVpsStart&#x60;, &#x60;doVpsStop&#x60;, &#x60;getVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes; poll &#x60;getVpsInfo&#x60; to confirm state.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;restart&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60; to refresh the VNC config.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60; — also returned for &#x60;cancelled&#x60;/&#x60;suspended&#x60; services.

**Related calls:**
- **Verify state:** &#x60;getVpsInfo&#x60;.
- **Power off only:** &#x60;doVpsStop&#x60;.
- **Power on:** &#x60;doVpsStart&#x60;.
- **Boot from CD:** &#x60;postVpsInsertCd&#x60; then &#x60;doVpsRestart&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/restart") class doVpsRestart(val id: kotlin.Int)

    /**
     * Power on a stopped VPS instance
     * Powers on a stopped VPS. Queues a &#x60;start&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET, idempotent in practice — calling on an already-running VPS is a no-op at the hypervisor. The &#x60;vps_status&#x60; field at the service level remains &#x60;active&#x60; (status reflects billing/lifecycle, not running power state); use &#x60;getVpsTrafficUsage&#x60; or external monitoring to confirm the VPS is actually up. Sibling ops: &#x60;doVpsStop&#x60;, &#x60;doVpsRestart&#x60;, &#x60;getVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60; — &#x60;queueId&#x60; references the &#x60;queue_log&#x60; entry. Allow ~10–30 s for the hypervisor to act.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;start&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60; — service is &#x60;cancelled&#x60;, &#x60;suspended&#x60; (non-payment), or &#x60;pending&#x60;. Resolve via payment (&#x60;initiatePayment&#x60;) for &#x60;suspended&#x60;, or contact support for &#x60;cancelled&#x60;/&#x60;pending&#x60; issues.

**Related calls:**
- **Reboot instead:** &#x60;doVpsRestart&#x60; (preferred over stop+start).
- **Power off:** &#x60;doVpsStop&#x60;.
- **Current state:** &#x60;getVpsInfo&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/start") class doVpsStart(val id: kotlin.Int)

    /**
     * Power off a running VPS — billing continues until cancellation
     * Halts the VPS without rebooting — typical before manually triggering a snapshot, freeing hypervisor resources, or temporarily taking a workload offline. Queues a &#x60;stop&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and triggers a VNC re-setup. Side-effecting GET, idempotent — stopping an already-stopped VPS is a no-op. **Billing continues while the VPS is stopped** — to stop both the workload and billing, use &#x60;VPSCancel&#x60;. Sibling ops: &#x60;doVpsStart&#x60;, &#x60;doVpsRestart&#x60;, &#x60;VPSCancel&#x60;, &#x60;getVpsBackup&#x60; (snapshot first).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text, queueId }&#x60;. Allow ~10–30 s.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;stop&#x60; row.
- Calls &#x60;vps_resetup_vnc()&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Reboot instead:** &#x60;doVpsRestart&#x60; (preferred for software changes).
- **Power on later:** &#x60;doVpsStart&#x60;.
- **Snapshot first:** &#x60;getVpsBackup&#x60;.
- **Stop billing too:** &#x60;VPSCancel&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}/stop") class doVpsStop(val id: kotlin.Int)

    /**
     * Issue a 24-hour pre-signed URL to download a MinIO-backed VPS backup
     * Generates a time-limited download link for a MinIO/S3-backed VPS backup so the customer can fetch it off-platform. Runs &#x60;mc share download --expire&#x3D;24h&#x60; against the resolved backup path and returns the resulting public URL — valid for 24 hours from issue. Only &#x60;minio&#x60;-typed backups are downloadable; &#x60;swift&#x60; and &#x60;zfs&#x60; backups have direct download disabled (returns an error directing the customer to support). Sibling ops: &#x60;getVpsBackups&#x60; (list to find &#x60;name&#x60;), &#x60;postVpsRestore&#x60; (restore in place — no download needed), &#x60;deleteVpsBackup&#x60;, &#x60;getVpsBackup&#x60; (create new).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body (JSON or multipart, required):**
- &#x60;file&#x60; (string, required) — exact &#x60;name&#x60; from &#x60;getVpsBackups&#x60;.

**Returns:**
- &#x60;text&#x60; (string) — &#x60;URL available for the next 24 hours&#x60;.
- &#x60;url&#x60; (string) — pre-signed download URL (HTTPS).

**Auth:** Session/API key. Ownership enforced via parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;No file specified&#x60; — &#x60;file&#x60; body field missing.
- **Swift backup:** &#x60;Downloads for this type have been disabled. Please contact support if you need this backup.&#x60;
- **ZFS backup:** same disabled message.
- **MinIO share failure:** &#x60;Error sharing file &lt;name&gt;&#x60;.

**Related calls:**
- **Prerequisite:** &#x60;getVpsBackups&#x60; (find a backup with &#x60;type &#x3D;&#x3D; &quot;minio&quot;&#x60;).
- **Alternative:** &#x60;postVpsRestore&#x60; (restore in place — no download).
- **Cleanup after download:** &#x60;deleteVpsBackup&#x60;.

     * @param body  
     * @param id VPS ID number 
     * @param all Set to &#x60;1&#x60; to list all backups across all services, not just the ones for the given VPS. (optional)
     */
    @Location("/vps/{id}/backups") class downloadVpsBackup(val body: IdBackupsBody2, val id: kotlin.Int, val all: kotlin.String)

    /**
     * Get the VPS order catalog — platforms, OS templates, locations, pricing
     * Step 1 of the VPS order flow. Returns the full ordering catalog the customer needs to build a valid VPS configuration: virtualization platforms (&#x60;kvm&#x60;, &#x60;kvmstorage&#x60;, &#x60;hyperv&#x60;), OS templates grouped by platform+distro, datacenter locations with current stock flags, per-slice resource costs converted to the customer&#x27;s billing currency, control-panel prices, and slice resource defaults (RAM/HD/BW per slice, max slices per VPS). No path or query params, no body. The response drives the order form; once the user picks a config, call &#x60;putVps&#x60; for a dry-run price quote, then &#x60;addVps&#x60; to actually place the order. Sibling ops: &#x60;putVps&#x60;, &#x60;addVps&#x60;, &#x60;getVpsList&#x60; (existing VPS).

**Returned top-level fields** (schema &#x60;VpsOrder&#x60;):
- &#x60;platformNames&#x60; (object) — display names keyed by platform tag (&#x60;{kvm: &quot;KVM&quot;, kvmstorage: &quot;KVM Storage&quot;, hyperv: &quot;HyperV&quot;}&#x60;).
- &#x60;platformPackages&#x60; (object) — service-type ids keyed by platform tag (&#x60;{kvm: 32, kvmstorage: 57, hyperv: 54}&#x60;).
- &#x60;packageCosts&#x60; (object) — base list cost keyed by service-type id.
- &#x60;templates&#x60; (object) — nested &#x60;{platform: {os: {template_file: template_version}}}&#x60; template tree.
- &#x60;osNames&#x60; (object) — display name per &#x60;template_os&#x60; key.
- &#x60;locationNames&#x60; (object) — &#x60;{1: &quot;New Jersey&quot;, 2: &quot;Los Angeles&quot;, 3: &quot;Dallas, TX&quot;}&#x60;.
- &#x60;locationStock&#x60; (object) — &#x60;{location_id: {platform_tag: bool}}&#x60; — &#x60;true&#x60; &#x3D; in stock.
- &#x60;vpsSlice&lt;Platform&gt;Cost&#x60; (float) — per-slice cost per platform in customer currency (e.g. &#x60;vpsSliceKvmLCost&#x60;, &#x60;vpsSliceKvmStorageCost&#x60;, &#x60;vpsSliceHypervCost&#x60;, &#x60;vpsSliceOvzCost&#x60;).
- &#x60;cpanelCost&#x60;, &#x60;daCost&#x60; (float) — control-panel addon costs.
- &#x60;ramSlice&#x60;, &#x60;hdSlice&#x60;, &#x60;bwSlice&#x60; (int) — RAM (MB), HD (GB), BW (GB) per slice.
- &#x60;maxSlices&#x60; (int) — &#x60;VPS_SLICE_MAX&#x60; cap for non-admin callers.
- &#x60;currency&#x60;, &#x60;currencySymbol&#x60; (string) — derived from the account profile.

**Auth:** Session or API key.

**Errors:**
- &#x60;401 Unauthorized&#x60; — missing session/API key.

**Related calls:**
- **Next:** &#x60;putVps&#x60; (validate + quote a chosen config — no charge), &#x60;addVps&#x60; (place the order).
- **After ordering:** pay via &#x60;initiatePayment&#x60; with the returned &#x60;real_iids&#x60;, then poll &#x60;getVpsInfo&#x60; until &#x60;vps_status &#x3D;&#x3D; &quot;active&quot;&#x60;.

**Example happy-path response (abridged):**
&#x60;&#x60;&#x60;json
{
  &quot;platformNames&quot;: {&quot;kvm&quot;: &quot;KVM&quot;, &quot;kvmstorage&quot;: &quot;KVM Storage&quot;, &quot;hyperv&quot;: &quot;HyperV&quot;},
  &quot;platformPackages&quot;: {&quot;kvm&quot;: 32, &quot;kvmstorage&quot;: 57, &quot;hyperv&quot;: 54},
  &quot;locationNames&quot;: {&quot;1&quot;: &quot;New Jersey&quot;, &quot;2&quot;: &quot;Los Angeles&quot;, &quot;3&quot;: &quot;Dallas, TX&quot;},
  &quot;locationStock&quot;: {&quot;1&quot;: {&quot;kvm&quot;: true, &quot;kvmstorage&quot;: true, &quot;hyperv&quot;: false}},
  &quot;osNames&quot;: {&quot;centos-7-x86_64&quot;: &quot;CentOS 7&quot;, &quot;ubuntu-22.04-x86_64&quot;: &quot;Ubuntu 22.04&quot;},
  &quot;templates&quot;: {&quot;kvm&quot;: {&quot;centos-7-x86_64&quot;: {&quot;centos-7-x86_64.qcow2&quot;: &quot;7&quot;}}},
  &quot;vpsSliceKvmLCost&quot;: 6.00,
  &quot;cpanelCost&quot;: 18.00,
  &quot;ramSlice&quot;: 2048, &quot;hdSlice&quot;: 25, &quot;bwSlice&quot;: 2000, &quot;maxSlices&quot;: 8,
  &quot;currency&quot;: &quot;USD&quot;, &quot;currencySymbol&quot;: &quot;$&quot;
}
&#x60;&#x60;&#x60;

     */
    @Location("/vps/order") class getNewVps()

    /**
     * Trigger a manual on-demand snapshot/backup of the VPS
     * Creates an on-demand backup of the VPS — typically called before a risky change (OS reinstall, slice upgrade, restore from older backup). Enqueues a &#x60;backup&#x60; action on the hypervisor (&#x60;history_log&#x60; &#x60;vpsqueue&#x60; entry) and returns immediately; the actual snapshot runs asynchronously and may take a few minutes. Despite being GET, this is a side-effecting action and the MCP parser flags it accordingly. The new backup, once complete, appears in &#x60;getVpsBackups&#x60; keyed by &#x60;name&#x60;. Sibling ops: &#x60;getVpsBackups&#x60; (list), &#x60;downloadVpsBackup&#x60; (download via pre-signed URL), &#x60;deleteVpsBackup&#x60;, &#x60;postVpsRestore&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;{ text: &quot;Action has been sent to the server. Please allow up to 2 minutes for action to be completed.&quot;, queueId: &lt;integer&gt; }&#x60; — &#x60;queueId&#x60; is the row id in &#x60;queue_log&#x60;/&#x60;history_log&#x60; and can be used to track action status.

**Backup limits (per platform):**
- KVM / KVM Storage: backups **enabled**.
- HyperV, OpenVZ, SSD-OpenVZ, Virtuozzo, SSD-Virtuozzo: **disabled** server-side (returns 400 &quot;Backups are disabled for this type&quot;).
- Max 4 backups per VPS for non-admin callers. If at the cap, returns &quot;Currently 4 backups per VPS max&quot; — delete an old one first via &#x60;deleteVpsBackup&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 VPS is not active&#x60; — &#x60;vps_status !&#x3D; &quot;active&quot;&#x60;.
- &#x60;400 Backups are disabled for this type&#x60; — incompatible platform.
- &#x60;400 Currently 4 backups per VPS max&#x60; — at cap.

**Related calls:**
- **List existing:** &#x60;getVpsBackups&#x60;.
- **Download:** &#x60;downloadVpsBackup&#x60; (PATCH; returns 24-hr pre-signed URL for MinIO backups; Swift/ZFS disabled).
- **Delete:** &#x60;deleteVpsBackup&#x60; (DELETE; Swift/MinIO only).
- **Restore from a backup:** &#x60;postVpsRestore&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/backup") class getVpsBackup(val id: kotlin.Int)

    /**
     * List existing backups for the VPS across Swift, MinIO, and ZFS
     * Enumerates the backup files available for the VPS across all backend storage systems (OpenStack Swift, MinIO/S3, and ZFS snapshots). Each entry&#x27;s &#x60;name&#x60; is the canonical identifier the caller must pass to sibling endpoints (&#x60;downloadVpsBackup&#x60;, &#x60;deleteVpsBackup&#x60;, &#x60;postVpsRestore&#x60;) — there is no separate integer id. The list is filtered to the VPS&#x27;s owner by default; admins can list all backups on the account by passing &#x60;all&#x3D;1&#x60;. Sibling ops: &#x60;getVpsBackup&#x60; (create new), &#x60;downloadVpsBackup&#x60;, &#x60;deleteVpsBackup&#x60;, &#x60;postVpsRestore&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Query params:**
- &#x60;all&#x60; (string, optional, enum &#x60;0&#x60;/&#x60;1&#x60;, default &#x60;0&#x60;) — set to &#x60;1&#x60; to list every backup across all services on the account, not just the ones for &#x60;{id}&#x60;.

**Returns:** &#x60;VpsBackupRows&#x60; — array of objects:
- &#x60;name&#x60; (string) — canonical identifier, e.g. &#x60;vps-12345-2026-05-12.tar.gz&#x60;.
- &#x60;type&#x60; (string enum) — &#x60;swift&#x60; / &#x60;minio&#x60; / &#x60;zfs&#x60;. Determines which operations are available (see Sibling notes).
- &#x60;service&#x60; (integer) — VPS id the backup belongs to.
- &#x60;path&#x60; (string) — storage path/URL.
- &#x60;size&#x60; (integer) — bytes.
- &#x60;repoIdx&#x60; (integer) — repository index (0 or 1 for Swift; selects which credentials/bucket).
- &#x60;extra&#x60; (array, optional) — multi-part backup pieces.

**Auth:** Session/API key. Ownership enforced via &#x60;vps_custid&#x60; on the parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.

**Capability matrix by backup type:**
- &#x60;swift&#x60;: list ✓, download ✗ (disabled — contact support), delete ✓.
- &#x60;minio&#x60;: list ✓, download ✓ (24-hr pre-signed URL via &#x60;downloadVpsBackup&#x60;), delete ✓.
- &#x60;zfs&#x60;: list ✓, download ✗ (disabled), delete ✗ (open a ticket).

**Related calls:**
- **Create new:** &#x60;getVpsBackup&#x60;.
- **Download:** &#x60;downloadVpsBackup&#x60; (PATCH).
- **Delete:** &#x60;deleteVpsBackup&#x60; (DELETE).
- **Restore:** &#x60;postVpsRestore&#x60; — pass &#x60;backup&#x60; as &#x60;&lt;type&gt;:&lt;service&gt;:&lt;name&gt;&#x60;.

     * @param id VPS ID number 
     * @param all Set to &#x60;1&#x60; to list all backups across all services, not just the ones for the given VPS. (optional)
     */
    @Location("/vps/{id}/backups") class getVpsBackups(val id: kotlin.Int, val all: kotlin.String)

    /**
     * Get current additional disk size and per-GB monthly cost for the VPS
     * Step 1 of the disk-space addon flow. Returns the current &quot;Additional N GB Space&quot; already purchased for the VPS (0 if none) and the per-GB monthly cost in USD — both adjusted for the customer&#x27;s reseller pricing tier via &#x60;get_reseller_price&#x60;. Read-only. Use this to populate a disk-upgrade form before calling &#x60;putVpsBuyHdSpace&#x60; (preview) and &#x60;postVpsBuyHdSpace&#x60; (commit). For whole-plan upgrades (CPU+RAM+disk together) use the slices flow instead (&#x60;getVpsSlices&#x60; / &#x60;postVpsSlices&#x60;). Sibling ops: &#x60;putVpsBuyHdSpace&#x60;, &#x60;postVpsBuyHdSpace&#x60;, &#x60;postVpsSlices&#x60;, &#x60;getVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:**
- &#x60;gbCost&#x60; (float) — per-GB monthly cost in USD (after reseller discount).
- &#x60;size&#x60; (integer) — current additional GB already purchased (0 if none).

**Auth:** Session/API key. Ownership enforced via parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- **Pre-condition:** an existing &#x60;Additional N GB Space for VPS {id}&#x60; repeat-invoice is required for the lookup to find a baseline; if it isn&#x27;t parseable, the endpoint returns an error asking the customer to contact support. New installs always start at &#x60;size: 0&#x60;.

**Related calls:**
- **Next (preview):** &#x60;putVpsBuyHdSpace&#x60; — returns prorated &#x60;diffCost&#x60; for a target size.
- **Next (commit):** &#x60;postVpsBuyHdSpace&#x60; — creates/updates the addon repeat invoice.
- **Alternative path (whole plan):** &#x60;getVpsSlices&#x60; → &#x60;postVpsSlices&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/buy_hd_space") class getVpsBuyHdSpace(val id: kotlin.Int)

    /**
     * Read current additional IPs, cap, and per-IP monthly cost for the VPS
     * Step 1 of the additional-IP addon flow. Returns the list of extra IPs already on the VPS (each with a &#x60;cancel_link&#x60; for removing that specific addon), how many more are allowed (&#x60;maxIps&#x60; &#x3D; &#x60;VPS_MAX_IPS&#x60; constant), and the per-IP monthly cost converted to the VPS&#x27;s billing currency. Read-only. Use to render the &quot;buy another IP&quot; form and to enforce the cap before calling &#x60;postVpsBuyIp&#x60;. Sibling ops: &#x60;postVpsBuyIp&#x60; (purchase one more), &#x60;postVpsReverseDns&#x60; (set PTR on the new IP), &#x60;getVpsReverseDns&#x60;, &#x60;getVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:**
- &#x60;ipsDetails&#x60; (array) — one entry per existing extra IP. Each entry includes:
  - &#x60;ip&#x60; (string) — the IPv4 address (parsed from the repeat-invoice description).
  - &#x60;cancel_link&#x60; (string) — relative URL &#x60;cancel_addon?module&#x3D;vps&amp;r&#x3D;&lt;repeat_invoice_id&gt;&#x60; to cancel that specific IP addon.
  - The underlying &#x60;repeat_invoices&#x60; / &#x60;invoices&#x60; columns (description, amount, dates, etc.).
- &#x60;ipCount&#x60; (integer) — current count of extra IPs already purchased.
- &#x60;maxIps&#x60; (integer) — hard cap (&#x60;VPS_MAX_IPS&#x60;).
- &#x60;ipCost&#x60; (float) — per-IP monthly cost, converted from &#x60;VPS_IP_COST&#x60; to the VPS&#x27;s billing currency.
- &#x60;currency&#x60; (string) — VPS billing currency code (ISO 4217, e.g. &#x60;USD&#x60;).
- &#x60;currencySymbol&#x60; (string).

**Auth:** Session/API key. Ownership enforced via parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Next (buy one more):** &#x60;postVpsBuyIp&#x60; — auto-allocates the next free IP on the same hypervisor.
- **After activation:** &#x60;postVpsReverseDns&#x60; (set PTR for the new IP), &#x60;getVpsInfo&#x60; (verify allocation).
- **Cancel an existing extra IP:** follow the &#x60;cancel_link&#x60; URL (renders the cancel-addon page).

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/buy_ip") class getVpsBuyIp(val id: kotlin.Int)

    /**
     * Read the VPS&#x27;s current hostname before changing it
     * Step 1 of the hostname-change flow. Returns the hostname currently stored on the &#x60;vps&#x60; row so the customer can confirm the existing value before submitting a new one. Read-only. **Platform restriction:** hostname changes through &#x60;postVpsChangeHostname&#x60; are only supported on OpenVZ/SSD-OpenVZ/Virtuozzo/SSD-Virtuozzo; KVM and HyperV require a support ticket — so for those platforms this endpoint is informational only. Sibling ops: &#x60;postVpsChangeHostname&#x60; (apply new value), &#x60;postVpsReverseDns&#x60; (PTR for primary IP — auto-updated by &#x60;postVpsChangeHostname&#x60;).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Current hostname (object form: &#x60;{ hostname: &quot;&lt;fqdn&gt;&quot; }&#x60;).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 VPS is not active&#x60; — &#x60;vps_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Next:** &#x60;postVpsChangeHostname&#x60; (OpenVZ/Virtuozzo only; auto-updates PTR for the primary IP).
- **PTR for extra IPs:** &#x60;postVpsReverseDns&#x60;.
- **Verify after change:** &#x60;getVpsInfo&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_hostname") class getVpsChangeHostname(val id: kotlin.Int)

    /**
     * Pre-flight check before changing the VPS root password
     * Step 1 of the root-password change flow. Validates ownership and active status; the response is a placeholder/policy object the dashboard uses to render the form (current implementation does not yet return a populated policy — it short-circuits after the ownership/status checks). Read-only. Use to confirm the VPS exists and is active before calling &#x60;postVpsChangeRootPassword&#x60;. For a server-generated random password instead, use &#x60;postVpsResetPassword&#x60;. Sibling ops: &#x60;postVpsChangeRootPassword&#x60;, &#x60;postVpsResetPassword&#x60;, &#x60;postVpsChangeWebuzoPassword&#x60; (Webuzo control panel).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Object with password requirements/state. Currently a no-op pre-check; reserved for future policy fields (min length, complexity rules, last-change timestamp).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 VPS is not active&#x60; — &#x60;vps_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Next (specific password):** &#x60;postVpsChangeRootPassword&#x60;.
- **Random password:** &#x60;postVpsResetPassword&#x60;.
- **Webuzo control panel password:** &#x60;postVpsChangeWebuzoPassword&#x60; (separate credential).

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_root_password") class getVpsChangeRootPassword(val id: kotlin.Int)

    /**
     * List IANA timezones supported by the VPS guest OS
     * Step 1 of the timezone-change flow. Returns the list of IANA timezone identifiers the VPS accepts (e.g. &#x60;America/New_York&#x60;, &#x60;Europe/London&#x60;, &#x60;Asia/Tokyo&#x60;) — sourced from &#x60;/usr/share/zoneinfo/zone.tab&#x60; on the MyAdmin host. Use to populate a timezone picker before calling &#x60;postVpsChangeTimezone&#x60;. Read-only. Sibling op: &#x60;postVpsChangeTimezone&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Array of strings — IANA timezone identifiers, sorted alphabetically.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Next:** &#x60;postVpsChangeTimezone&#x60; (must pass a value present in this array).
- **Account-level timezone:** &#x60;updateAccountInfo&#x60; (sets the default for new VPS).

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_timezone") class getVpsChangeTimezone(val id: kotlin.Int)

    /**
     * Get full details for one VPS — IPs, hostname, OS, slices, status, addons
     * Returns everything the customer dashboard shows for a single VPS — hostname, primary IP plus any extra IPs, OS, allocated slices (CPU/RAM/disk), current &#x60;vps_status&#x60;, plan/service-type, datacenter location, billing currency, and &#x60;serviceAddons&#x60; (extra IPs and additional GB disk). Read-only. Backed by &#x60;ViewVPS::getDetails()&#x60;; ownership is enforced via &#x60;get_service($id, &#x27;vps&#x27;)&#x60; — cross-customer requests return 404. Use to render a VPS detail page, to verify ownership before mutating, or to poll &#x60;vps_status&#x60; after &#x60;addVps&#x60; (status flips &#x60;pending&#x60; → &#x60;active&#x60; once provisioning completes). Sibling ops: &#x60;getVpsList&#x60;, &#x60;doVpsRestart&#x60;/&#x60;doVpsStart&#x60;/&#x60;doVpsStop&#x60; (lifecycle), &#x60;getVpsTrafficUsage&#x60; (bandwidth), &#x60;getVpsBackups&#x60;, &#x60;getVpsInvoices&#x60;, &#x60;updateVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Returned fields** (schema &#x60;Vps&#x60; plus extras):
- Core: &#x60;vps_id&#x60;, &#x60;vps_hostname&#x60;, &#x60;vps_ip&#x60;, &#x60;vps_status&#x60;, &#x60;vps_slices&#x60;, &#x60;vps_os&#x60;, &#x60;vps_type&#x60; (service-type id), &#x60;vps_server&#x60; (backing hypervisor id), &#x60;vps_custid&#x60;, &#x60;vps_comment&#x60;, &#x60;vps_coupon&#x60;.
- &#x60;services_name&#x60; (string) — plan name (e.g. &#x60;KVM&#x60;, &#x60;HyperV&#x60;).
- &#x60;client_links&#x60; (array) — UI action links (&#x60;{name, link, icon}&#x60;) for restart, snapshot, console, etc. Internal &#x60;?link&#x3D;queue&amp;action&#x3D;...&#x60; URLs are pre-resolved.
- &#x60;serviceAddons&#x60; (object) — &#x60;{extra_ips: [...], additional_gb: &lt;int&gt;}&#x60; populated from &#x60;repeat_invoices&#x60; rows that match &#x60;Additional IP*&#x60; / &#x60;Additional N GB Space*&#x60; patterns.
- **Stripped fields:** &#x60;admin_links&#x60;, &#x60;settings&#x60;, &#x60;csrf&#x60; are removed before response.

**Auth:** Session or API key. Customer must own the VPS (enforced via &#x60;vps_custid&#x60; match).

**Errors:**
- &#x60;401 Unauthorized&#x60; — missing session/API key.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; does not exist or is owned by a different account.

**Related calls:**
- **Lifecycle:** &#x60;doVpsStart&#x60;, &#x60;doVpsStop&#x60;, &#x60;doVpsRestart&#x60;.
- **Maintenance:** &#x60;postVpsChangeHostname&#x60;, &#x60;postVpsChangeRootPassword&#x60;, &#x60;postVpsReverseDns&#x60;.
- **Upgrade:** &#x60;getVpsSlices&#x60;/&#x60;postVpsSlices&#x60;, &#x60;getVpsBuyHdSpace&#x60;/&#x60;putVpsBuyHdSpace&#x60;/&#x60;postVpsBuyHdSpace&#x60;, &#x60;getVpsBuyIp&#x60;/&#x60;postVpsBuyIp&#x60;.
- **Backups:** &#x60;getVpsBackup&#x60; (create), &#x60;getVpsBackups&#x60; (list), &#x60;downloadVpsBackup&#x60;, &#x60;postVpsRestore&#x60;.
- **Billing:** &#x60;getVpsInvoices&#x60;, &#x60;VPSCancel&#x60;.
- **Metrics:** &#x60;getVpsTrafficUsage&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}") class getVpsInfo(val id: kotlin.Int)

    /**
     * List ISO templates that can be mounted in the VPS virtual CD drive
     * Step 1 of the CD-mount flow. Returns the catalog of ISO images the customer can mount in the VPS virtual CD drive — typically rescue ISOs, OS installers, or recovery media. Read-only. Use to populate a CD/ISO picker before calling &#x60;postVpsInsertCd&#x60; with a chosen URL. Sibling ops: &#x60;postVpsInsertCd&#x60; (mount), &#x60;doVpsEjectCd&#x60; (unmount), &#x60;doVpsDisableCd&#x60; (remove drive), &#x60;doVpsRestart&#x60; (boot from mounted CD).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Object with available ISO templates (current implementation returns the platform&#x27;s CD options).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Next:** &#x60;postVpsInsertCd&#x60; (provide &#x60;url&#x60; for the ISO to mount).
- **Boot from CD:** &#x60;doVpsRestart&#x60; after mounting.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/insert_cd") class getVpsInsertCd(val id: kotlin.Int)

    /**
     * List all billing invoices associated with this specific VPS
     * Returns the billing history for one VPS — initial purchase invoice, monthly/period renewal invoices, addon invoices (extra IPs, additional disk space), and any prorated upgrade invoices for slice changes. Read-only. Backed by &#x60;Billing\InvoicesList::go()&#x60;. Use to render a per-VPS billing-history view, to find an unpaid invoice id to pass to &#x60;initiatePayment&#x60;, or to confirm a recent charge. Sibling ops: &#x60;getVpsInfo&#x60;, &#x60;getBillingInvoice&#x60; (single invoice detail), &#x60;initiatePayment&#x60;, &#x60;addVps&#x60; (creates the first invoice).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;ChargeInvoiceRows&#x60; — array of invoice rows with &#x60;id&#x60;, &#x60;amount&#x60;, &#x60;paid&#x60;, &#x60;description&#x60;, &#x60;date&#x60;, &#x60;due_date&#x60;, &#x60;currency&#x60;, &#x60;module&#x3D;vps&#x60;, &#x60;service&#x3D;{id}&#x60;, and any addon-specific fields. Order is most-recent-first.

**Auth:** Session/API key. Ownership enforced via parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service Passed&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Single invoice detail:** &#x60;getBillingInvoice&#x60;.
- **Pay an unpaid invoice:** &#x60;initiatePayment&#x60; (&#x60;GET /billing/pay/{method}/{invoices}&#x60;).
- **All invoices across account:** &#x60;getBillingInvoices&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/invoices") class getVpsInvoices(val id: kotlin.Int)

    /**
     * List all VPS services on the customer&#x27;s account
     * Enumerates every VPS owned by the authenticated customer — status, hostname, primary IP, plan name, and monthly cost. The canonical entry point for finding a VPS &#x60;id&#x60; to pass into other VPS operations (&#x60;getVpsInfo&#x60;, lifecycle, billing, backups, etc.). No path params, no query params, no body. Server-side filtered by session account; rows come from the &#x60;vps&#x60; table joined to &#x60;repeat_invoices&#x60; (for cost) and &#x60;services&#x60; (for plan name). Returns an array of &#x60;VpsRow&#x60; (empty array if the account has no VPS). Sibling ops: &#x60;getVpsInfo&#x60; (full detail), &#x60;getNewVps&#x60;/&#x60;putVps&#x60;/&#x60;addVps&#x60; (order a new one).

**Returned fields (per row):**
- &#x60;vps_id&#x60; (integer) — canonical VPS id, used in every &#x60;/vps/{id}/*&#x60; path.
- &#x60;vps_name&#x60; (string) — display name shown in the dashboard.
- &#x60;vps_hostname&#x60; (string) — FQDN currently assigned to the VPS.
- &#x60;vps_ip&#x60; (string) — primary IPv4 address.
- &#x60;vps_status&#x60; (string enum) — &#x60;active&#x60;, &#x60;pending&#x60; (awaiting payment/provisioning), &#x60;suspended&#x60; (non-payment), or &#x60;cancelled&#x60;.
- &#x60;services_name&#x60; (string) — service-type name (e.g. &#x60;KVM&#x60;, &#x60;KVM Storage&#x60;, &#x60;HyperV&#x60;).
- &#x60;repeat_invoices_cost&#x60; (decimal) — current monthly cost in the VPS&#x27;s billing currency.
- &#x60;vps_comment&#x60; (string|null) — customer-provided note.

**Auth:** Session (&#x60;sessionid&#x60; header) or API key (&#x60;X-API-KEY&#x60; header). API key preferred for integrations.

**Errors:**
- &#x60;401 Unauthorized&#x60; — missing/invalid session or API key.

**Related calls:**
- **Next (per-VPS):** &#x60;getVpsInfo&#x60; (full detail incl. extra IPs, slices, addons), &#x60;getVpsInvoices&#x60; (billing per VPS), &#x60;doVpsRestart&#x60;/&#x60;doVpsStart&#x60;/&#x60;doVpsStop&#x60; (lifecycle).
- **Order a new VPS:** &#x60;getNewVps&#x60; (catalog) → &#x60;putVps&#x60; (validate + quote) → &#x60;addVps&#x60; (place + invoice).
- **Cancel:** &#x60;VPSCancel&#x60; (end of cycle, customer-initiated).

     */
    @Location("/vps") class getVpsList()

    /**
     * List OS templates compatible with this VPS&#x27;s hypervisor for reinstall
     * Step 1 of the OS-reinstall flow. Returns the list of OS templates that can be installed on this specific VPS — filtered server-side by the VPS&#x27;s backing hypervisor type (KVM, HyperV, OpenVZ, Virtuozzo) and by &#x60;template_available&#x3D;1&#x60; (non-admin callers only see published templates). Use to populate the reinstall picker; the &#x60;template_file&#x60; from a chosen row is what &#x60;postVpsReinstallOs&#x60; accepts. **Reinstall destroys all data** — recommend a backup via &#x60;getVpsBackup&#x60; first. Sibling ops: &#x60;postVpsReinstallOs&#x60; (commit reinstall), &#x60;getVpsBackup&#x60; (snapshot first), &#x60;postVpsRestore&#x60; (restore from backup instead).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;VpsTemplatesList&#x60;:
- &#x60;templates&#x60; (array) — one entry per available template:
  - &#x60;template_id&#x60; (integer)
  - &#x60;template_name&#x60; (string) — display name (e.g. &#x60;CentOS 7&#x60;).
  - &#x60;template_version&#x60; (string) — version (e.g. &#x60;7&#x60;).
  - &#x60;template_file&#x60; (string) — **canonical identifier** to pass to &#x60;postVpsReinstallOs&#x60; (e.g. &#x60;centos-7-x86_64.qcow2&#x60;).
  - &#x60;template_os&#x60; (string) — OS family tag.
  - &#x60;template_type&#x60; (integer) — internal hypervisor type id.
  - &#x60;template_available&#x60; (integer) — &#x60;1&#x60; for non-admin visible templates.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Snapshot before reinstall:** &#x60;getVpsBackup&#x60;.
- **Commit reinstall:** &#x60;postVpsReinstallOs&#x60; (pass &#x60;template_file&#x60; + MyAdmin login password).
- **Alternative — restore old backup:** &#x60;postVpsRestore&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/reinstall_os") class getVpsReinstallOs(val id: kotlin.Int)

    /**
     * Pre-flight check before resetting the VPS root password to a random value
     * Step 1 of the random-root-password reset flow. Validates ownership and active status; the response describes the reset behavior (currently a passthrough — full implementation reserved for future policy fields). Read-only. Use to confirm the VPS exists and is active before triggering the reset via &#x60;postVpsResetPassword&#x60;. For a customer-chosen password use &#x60;postVpsChangeRootPassword&#x60; instead. Sibling ops: &#x60;postVpsResetPassword&#x60;, &#x60;postVpsChangeRootPassword&#x60;, &#x60;postVpsChangeWebuzoPassword&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Object with reset options (reserved for policy info).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Next (random):** &#x60;postVpsResetPassword&#x60;.
- **Specific password instead:** &#x60;postVpsChangeRootPassword&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/reset_password") class getVpsResetPassword(val id: kotlin.Int)

    /**
     * Read the current PTR (reverse-DNS) records for every IP on the VPS
     * Returns the PTR/reverse-DNS hostname currently resolving for every IP attached to the VPS — primary &#x60;vps_ip&#x60; plus any extras purchased via &#x60;postVpsBuyIp&#x60;. PTRs are read live via &#x60;get_hostname()&#x60; (DNS lookup), not cached. Read-only. Sibling ops: &#x60;postVpsReverseDns&#x60; (update entries), &#x60;getVpsBuyIp&#x60; (add more IPs first), &#x60;postVpsChangeHostname&#x60; (auto-updates PTR for the primary IP).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;ReverseDnsEntries&#x60; — &#x60;{ ips: { &quot;&lt;ip&gt;&quot;: &quot;&lt;ptr-hostname&gt;&quot;, ... } }&#x60;. Empty string for IPs with no PTR set.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Update PTRs:** &#x60;postVpsReverseDns&#x60;.
- **Add IPs first:** &#x60;getVpsBuyIp&#x60; → &#x60;postVpsBuyIp&#x60;.
- **Hostname change (auto-PTR for primary):** &#x60;postVpsChangeHostname&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/reverse_dns") class getVpsReverseDns(val id: kotlin.Int)

    /**
     * Read current VNC console connection info for the VPS
     * Returns the VNC IP/port the customer can connect to for an out-of-band console (KVM-style remote console — useful when SSH/RDP is unavailable, during boot, or for rescue work). Read-only. **Note:** the current implementation is a stub for some platforms — if you get an empty response, call &#x60;postVpsSetupVnc&#x60; to (re)provision the VNC endpoint, then call this again. Sibling ops: &#x60;postVpsSetupVnc&#x60;, &#x60;getVpsViewDesktop&#x60; (Windows GUI access via RDP/HTML5).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Object with VNC connection info (IP, port, credentials when provisioned).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Provision/refresh VNC:** &#x60;postVpsSetupVnc&#x60;.
- **Windows remote desktop:** &#x60;getVpsViewDesktop&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/setup_vnc") class getVpsSetupVnc(val id: kotlin.Int)

    /**
     * Read current slice count, min/max range, and prorated per-slice upgrade cost
     * Step 1 of the slice upgrade/downgrade flow. A &quot;slice&quot; bundles RAM, disk, and CPU on the VPS — the smallest unit of vertical scaling. Returns the current slice count (&#x60;vps_slices&#x60;), the range available (&#x60;min_slices &#x3D; current&#x60;, &#x60;max_slices &#x3D; host capacity&#x60;), the per-slice recurring cost (after coupon and frequency discount), the prorated cost for the remainder of the current cycle, and the underlying resource units (&#x60;slice_ram&#x60; in MB, &#x60;slice_hd&#x60; in GB). Read-only. Use to render an upgrade picker before calling &#x60;postVpsSlices&#x60;. Sibling ops: &#x60;postVpsSlices&#x60; (commit), &#x60;postVpsBuyHdSpace&#x60; (disk-only addon).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:**
- &#x60;min_slices&#x60; (integer) — current allocation; floor for downgrades is also this value (downgrade decreases from here).
- &#x60;max_slices&#x60; (integer) — host-capacity-limited upper bound (&#x60;get_vps_max_slices()&#x60;).
- &#x60;slice_cost&#x60; (float) — per-slice recurring cost in customer currency.
- &#x60;prorated_slice_cost&#x60; (float) — prorated cost for the remainder of the current billing cycle.
- &#x60;frequency&#x60; (integer) — billing cycle in months (1/6/12/24/36).
- &#x60;slice_ram&#x60; (integer) — RAM (GB) per slice.
- &#x60;slice_hd&#x60; (integer) — disk (GB) per slice. For KVM Storage (service-type 57) this comes from &#x60;services_field2.slice_hd&#x60;.
- &#x60;vps_slices&#x60; (integer) — current count.
- &#x60;vps_cost&#x60; (float) — current monthly cost.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Next:** &#x60;postVpsSlices&#x60; (commit; creates prorated invoice for upgrades, opens ticket for active services).
- **Disk-only:** &#x60;getVpsBuyHdSpace&#x60;/&#x60;putVpsBuyHdSpace&#x60;/&#x60;postVpsBuyHdSpace&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/slices") class getVpsSlices(val id: kotlin.Int)

    /**
     * Read bandwidth traffic usage data for the VPS
     * Returns bandwidth-consumption data for the VPS — inbound/outbound bytes per day and aggregated totals against the plan&#x27;s &#x60;bwSlice&#x60; × &#x60;vps_slices&#x60; allowance. Pulled via &#x60;vps_bandwidth_data($vps_id)&#x60; from the bandwidth-tracking subsystem. Read-only. For custom date-range or granularity filters use &#x60;postVpsTrafficUsage&#x60; (currently mirrors GET behavior but reserved for filter parameters). Sibling ops: &#x60;postVpsTrafficUsage&#x60;, &#x60;getVpsInfo&#x60; (BW allowance fields are shown there).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;VpsTrafficResponse&#x60; — array/object with bandwidth usage points (timestamp, inbound bytes, outbound bytes, totals).

**Auth:** Session/API key. Ownership enforced via parent VPS.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.

**Related calls:**
- **Filtered query:** &#x60;postVpsTrafficUsage&#x60; (reserved for date-range filters).
- **Plan allowance:** &#x60;getVpsInfo&#x60; returns &#x60;bw_total&#x60; / &#x60;slices&#x60; you can compute against.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/traffic_usage") class getVpsTrafficUsage(val id: kotlin.Int)

    /**
     * Read remote-desktop (RDP/HTML5) connection info for a Windows/GUI VPS
     * Returns remote-desktop connection details for a Windows VPS or any VPS with a GUI session — IP, port, recommended client, and the &#x60;client_links&#x60; the dashboard surfaces for launching the session. Backed by &#x60;ViewVPS::getDetails()&#x60;; response shape mirrors &#x60;getVpsInfo&#x60; minus the &#x60;admin_links&#x60; block. Sibling ops: &#x60;postVpsViewDesktop&#x60; (refresh), &#x60;getVpsSetupVnc&#x60;/&#x60;postVpsSetupVnc&#x60; (low-level VNC console).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** Same shape as &#x60;getVpsInfo&#x60; (sans &#x60;admin_links&#x60;) — includes &#x60;client_links&#x60; with RDP/HTML5 launch URLs.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Refresh session:** &#x60;postVpsViewDesktop&#x60;.
- **Low-level console:** &#x60;getVpsSetupVnc&#x60; / &#x60;postVpsSetupVnc&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/view_desktop") class getVpsViewDesktop(val id: kotlin.Int)

    /**
     * Resend the welcome email containing VPS IP, hostname, and root credentials
     * Resends the VPS welcome email — the original new-service email containing IP, hostname, root/Administrator credentials, and connection instructions. Calls &#x60;vps_welcome_email($id)&#x60; to regenerate and dispatch via the standard mail pipeline. Use when the customer didn&#x27;t receive (or lost) the original right after provisioning. The dashboard&#x27;s &quot;show credentials&quot; view is the alternative for in-app retrieval. Sibling ops: &#x60;getVpsInfo&#x60; (shows connection details in the response), &#x60;postVpsChangeRootPassword&#x60; / &#x60;postVpsResetPassword&#x60; (rotate before resending if security is a concern).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;SuccessTextResponse&#x60; — &#x60;Welcome Email has been resent.&#x60;

**Side effects:**
- Sends an email to the account&#x27;s billing email address with the credentials currently stored in &#x60;history_log&#x60; for this VPS.

**Auth:** Session/API key. Ownership enforced via &#x60;vps_custid&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 Service is not active&#x60; — &#x60;vps_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **In-app credential view:** &#x60;getVpsInfo&#x60;.
- **Before resending, rotate password:** &#x60;postVpsResetPassword&#x60; or &#x60;postVpsChangeRootPassword&#x60;.

     * @param id VPS ID 
     */
    @Location("/vps/{id}/welcome_email") class getVpsWelcomeEmail(val id: kotlin.String)

    /**
     * Buy or resize the VPS additional-disk addon and create a prorated invoice
     * Step 3 of the disk-space addon flow — commit. Creates or updates the &#x60;Additional N GB Space for VPS {id}&#x60; &#x60;repeat_invoices&#x60; row with the new size and recurring cost, then generates a one-off prorated &#x60;invoices&#x60; row for the immediate difference. The hypervisor disk-grow action is queued either immediately (&#x60;update_hdsize&#x60; in &#x60;vpsqueue&#x60;) when no charge is owed, or after the invoice is paid. When increasing from an existing size, any unpaid prior addon invoice is deleted and any already-paid one is credited against &#x60;diffCost&#x60;. **Real money** — call &#x60;putVpsBuyHdSpace&#x60; first to preview. Sibling ops: &#x60;getVpsBuyHdSpace&#x60;, &#x60;putVpsBuyHdSpace&#x60;, &#x60;postVpsSlices&#x60;, &#x60;initiatePayment&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;size&#x60; (integer, required) — target additional GB. Range &#x60;1..100&#x60;. Must differ from current.

**Returns:**
- When immediate charge owed: &#x60;{ text: &quot;Invoice Created, Please Pay This To Activate Extra Space&quot;, invoice: &lt;integer&gt; }&#x60; — pass &#x60;invoice&#x60; to &#x60;initiatePayment&#x60;.
- When no charge owed (downgrade/credit): &#x60;{ text: &quot;Repeat Invoice Updated, Server Size Update Queued&quot; }&#x60; — disk grow already queued.

**Side effects:**
- Inserts or updates &#x60;repeat_invoices&#x60; row for the addon.
- Inserts &#x60;invoices&#x60; row for &#x60;diffCost&#x60; when &gt; 0.
- Deletes any unpaid prior addon invoices for the same VPS within the last month.
- Credits any paid prior invoice against &#x60;diffCost&#x60;.
- Queues &#x60;update_hdsize&#x60; in &#x60;vpsqueue&#x60; when no payment is owed.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;Invalid Size Specified&#x60; — &#x60;size&#x60; out of &#x60;1..100&#x60;.
- &#x60;No Change Made, Size The Same&#x60;.
- **Pre-condition:** an existing addon row is required. If not found, the request short-circuits (&#x60;go()&#x60; returns without acting); use the order flow for the very first addon, or &#x60;postVpsSlices&#x60; for whole-plan upgrades.

**Related calls:**
- **Preview first:** &#x60;putVpsBuyHdSpace&#x60;.
- **Pay the invoice:** &#x60;initiatePayment&#x60; (&#x60;GET /billing/pay/{method}/{invoices}&#x60;).
- **Whole-plan upgrades:** &#x60;postVpsSlices&#x60; (bundles disk + RAM + CPU).

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/buy_hd_space") class postVpsBuyHdSpace(val id: kotlin.Int)

    /**
     * Purchase one additional IP for the VPS and create the invoice
     * Step 2 of the additional-IP addon flow — commit. Auto-selects the next free IP on the same hypervisor via &#x60;vps_get_next_ip&#x60;, creates a &#x60;Additional IP for VPS {id}&#x60; recurring invoice (&#x60;repeat_invoices&#x60;), and generates an immediate one-off &#x60;invoices&#x60; row at the current IP cost. **Real money.** The network-side IP allocation happens once the invoice is paid; the IP is bound to the VPS during the next provisioning sweep. Sibling ops: &#x60;getVpsBuyIp&#x60; (preview), &#x60;initiatePayment&#x60;, &#x60;getVpsInfo&#x60; (verify), &#x60;postVpsReverseDns&#x60; (set PTR after activation).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None — the next free IP is auto-selected.

**Returns:**
- &#x60;text&#x60; (string) — &#x60;Ordered Additional IP successfully.&#x60;
- &#x60;invoice&#x60; (integer) — new invoice id to pay via &#x60;initiatePayment&#x60;.

**Side effects:**
- Reserves the next free IP on the VPS&#x27;s &#x60;vps_server&#x60; (parked until payment).
- Inserts &#x60;repeat_invoices&#x60; row (&#x60;Additional IP for VPS {id}&#x60;, recurring at &#x60;ipCost&#x60;, frequency from parent service).
- Inserts &#x60;invoices&#x60; row for the immediate one-period charge.
- Logs the addon creation in &#x60;myadmin_log&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;VPS already has the maximum number of IPs allowed. If you require additional IPs please contact support.&#x60; — &#x60;ipCount &gt;&#x3D; maxIps&#x60; (&#x60;VPS_MAX_IPS&#x60;).
- &#x60;No available free ips on this server. Please contact support to order additional ips.&#x60; — &#x60;vps_get_next_ip&#x60; returned false.

**Related calls:**
- **Prerequisite:** &#x60;getVpsBuyIp&#x60; (capacity check + preview).
- **Next:** &#x60;initiatePayment&#x60; with the returned &#x60;invoice&#x60; id, then &#x60;getVpsInfo&#x60; to confirm allocation.
- **Post-activation:** &#x60;postVpsReverseDns&#x60; to set the PTR for the new IP.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/buy_ip") class postVpsBuyIp(val id: kotlin.Int)

    /**
     * Rename the VPS hostname (OpenVZ/Virtuozzo only) and auto-set PTR for the primary IP
     * Renames the VPS — validates the FQDN with &#x60;valid_hostname()&#x60;, sets the reverse-DNS PTR record for the primary IP (&#x60;reverse_dns($vps_ip, $hostname)&#x60;), and either updates the &#x60;vps_hostname&#x60; column directly (if the VPS is still &#x60;pending&#x60;) or queues a &#x60;change_hostname&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) for active services. **Platform restriction:** rejected unless the VPS runs on OpenVZ, SSD-OpenVZ, Virtuozzo, or SSD-Virtuozzo — KVM/HyperV must open a support ticket. Sibling ops: &#x60;getVpsChangeHostname&#x60;, &#x60;postVpsReverseDns&#x60;, &#x60;getVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;hostname&#x60; (string, required) — new FQDN (e.g. &#x60;web1.example.com&#x60;). Validated by &#x60;valid_hostname()&#x60;.

**Returns:**
- For active services: &#x60;{ text, queueId }&#x60; — &#x60;queueId&#x60; references the &#x60;queue_log&#x60; row. Allow ~2 minutes.
- For pending services: &#x60;{ text: &quot;Hostname Updated&quot; }&#x60; — applied in place.

**Side effects:**
- Sets PTR record for &#x60;vps_ip&#x60; via &#x60;reverse_dns()&#x60;.
- Either updates &#x60;vps_hostname&#x60; directly (pending) or queues &#x60;change_hostname&#x60; (active) plus logs &#x60;change_hostname&#x60; history entry with the &#x60;old to new&#x60; transition.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;Invalid Hostname&#x60; — fails &#x60;valid_hostname()&#x60;.
- &#x60;No change in hostname&#x60; — value matches current.
- &#x60;Hostname changing is only enabled on OpenVZ/Virtuozzo Platforms currently. Contact support and we can change it for you.&#x60; — wrong platform.

**Related calls:**
- **Prerequisite:** &#x60;getVpsChangeHostname&#x60; (read current).
- **Extra IPs need separate PTR updates:** &#x60;postVpsReverseDns&#x60;.
- **Verify:** &#x60;getVpsInfo&#x60; (look for updated &#x60;vps_hostname&#x60;).

     * @param hostname  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_hostname") class postVpsChangeHostname(val hostname: kotlin.String, val id: kotlin.Int)

    /**
     * Set a specific new root/Administrator password on the VPS
     * Sets a specific root password (Administrator on Windows) chosen by the customer. Queues a &#x60;change_root&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) and records the new password in &#x60;history_log&#x60; as a &#x60;change_root_password&#x60; entry for operator reference. The password takes effect within ~2 minutes. **Caveat:** there is no rollback — to &quot;undo&quot;, set another new password. For a server-generated random password instead, use &#x60;postVpsResetPassword&#x60;. Sibling ops: &#x60;getVpsChangeRootPassword&#x60;, &#x60;postVpsResetPassword&#x60;, &#x60;postVpsChangeWebuzoPassword&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;password&#x60; (string, required) — new root/Administrator password. The endpoint does not enforce a regex here (the hypervisor agent applies platform policy), but &#x60;validate_buy_vps&#x60;-style strength is strongly recommended: 8+ chars, upper, lower, digit, special.

**Returns:** &#x60;{ text, queueId }&#x60; — &#x60;queueId&#x60; tracks the action in &#x60;queue_log&#x60;.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;change_root&#x60; row.
- Inserts &#x60;history_log&#x60; &#x60;change_root_password&#x60; audit entry storing the new password (operator-readable for support).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;400 Missing field &quot;password&quot;&#x60;.

**Related calls:**
- **Pre-flight:** &#x60;getVpsChangeRootPassword&#x60;.
- **Random instead:** &#x60;postVpsResetPassword&#x60;.
- **Control panel password:** &#x60;postVpsChangeWebuzoPassword&#x60;.
- **Verify:** &#x60;getVpsInfo&#x60; (no field change — verification is operational, not via API).

     * @param password  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_root_password") class postVpsChangeRootPassword(val password: kotlin.String, val id: kotlin.Int)

    /**
     * Set the system timezone on the VPS guest OS
     * Step 2 of the timezone-change flow — commit. Validates &#x60;timezone&#x60; against the list from &#x60;getVpsChangeTimezone&#x60;, then queues a &#x60;change_timezone&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;). Action takes effect within ~2 minutes. Sibling op: &#x60;getVpsChangeTimezone&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;timezone&#x60; (string, required) — IANA identifier; **must** be one of the values returned by &#x60;getVpsChangeTimezone&#x60; (in-array check enforced server-side).

**Returns:** &#x60;{ text, queueId }&#x60;.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;change_timezone&#x60; row with the validated value.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;422 Invalid timezone&#x60; — value not in the supported list.

**Related calls:**
- **Prerequisite:** &#x60;getVpsChangeTimezone&#x60; (the only valid source for &#x60;timezone&#x60; values).

     * @param timezone  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_timezone") class postVpsChangeTimezone(val timezone: kotlin.String, val id: kotlin.Int)

    /**
     * Rotate the Webuzo control panel admin password (re-auth required)
     * Rotates the admin password on the Webuzo control panel that ships pre-installed on certain VPS templates. Re-authenticates the caller via their MyAdmin account password (&#x60;account_passwd&#x60; md5 check), then calls the Webuzo SDK (&#x60;Webuzo_API::change_password&#x60;) to apply the new password, updates the stored credential in &#x60;history_log&#x60;, and emails the customer a confirmation via the &#x60;client/client_email.tpl&#x60; template. Used for the control panel only — for the underlying OS root/Administrator password use &#x60;postVpsChangeRootPassword&#x60;/&#x60;postVpsResetPassword&#x60;. Sibling ops: &#x60;postVpsChangeRootPassword&#x60;, &#x60;postVpsResetPassword&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields (both required):**
- &#x60;password&#x60; (string, required) — new Webuzo admin password. Validated by &#x60;valid_password()&#x60;.
- &#x60;login_password&#x60; (string, required) — the customer&#x27;s current MyAdmin account password (re-auth check; md5-compared to &#x60;accounts.account_passwd&#x60;).

**Returns:** &#x60;{ text }&#x60; — &#x60;Password updated successfully!&#x60;

**Side effects:**
- Calls Webuzo API to apply new password.
- Updates the &#x60;Webuzo Details&#x60; row in &#x60;history_log&#x60; with the new value.
- Sends a confirmation email to the account&#x27;s billing email.
- Logs the rotation in &#x60;myadmin_log&#x60;.

**Auth:** Session/API key plus re-auth via &#x60;login_password&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;Missing Password&#x60; / &#x60;Missing Login Password&#x60; — body field absent.
- &#x60;Login Password is incorrect!&#x60; — &#x60;login_password&#x60; doesn&#x27;t match stored hash.
- &#x60;New Password is not valid&#x60; — fails &#x60;valid_password()&#x60;.
- &#x60;Missing Existing Webuzo Password Details.&#x60; — no Webuzo credential in &#x60;history_log&#x60; (contact support).
- &#x60;Unable to update password. Please contact support team for further assistance.&#x60; — Webuzo API call failed.

**Related calls:**
- **OS root password instead:** &#x60;postVpsChangeRootPassword&#x60;, &#x60;postVpsResetPassword&#x60;.
- **Account password rotation:** &#x60;updateAccountPassword&#x60;.

     * @param password  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/change_webuzo_password") class postVpsChangeWebuzoPassword(val password: kotlin.String, val id: kotlin.Int)

    /**
     * Mount an ISO image in the VPS virtual CD drive from a URL
     * Mounts an ISO image in the VPS virtual CD drive from the supplied URL — used to boot into rescue media, run an OS installer, or temporarily attach removable media. Queues an &#x60;insert_cd&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;) with the URL. After mounting, restart the VPS with &#x60;doVpsRestart&#x60; to boot from the CD. Sibling ops: &#x60;getVpsInsertCd&#x60; (list), &#x60;doVpsEjectCd&#x60; (unmount), &#x60;doVpsDisableCd&#x60; (remove drive), &#x60;doVpsRestart&#x60; (boot from CD).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;url&#x60; (string, required) — http(s):// URL to a &#x60;.iso&#x60; file accessible from the hypervisor.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;insert_cd&#x60; row with the URL.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **List options first:** &#x60;getVpsInsertCd&#x60;.
- **Boot the ISO:** &#x60;doVpsRestart&#x60;.
- **Unmount when done:** &#x60;doVpsEjectCd&#x60;.

     * @param url  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/insert_cd") class postVpsInsertCd(val url: kotlin.String, val id: kotlin.Int)

    /**
     * Reinstall the VPS OS (DESTRUCTIVE — wipes disk; requires re-auth)
     * **DESTRUCTIVE.** Wipes the VPS disk and reinstalls the chosen OS template. Re-authenticates via the customer&#x27;s MyAdmin account password (&#x60;auth-&gt;authenticate&#x60; against &#x60;account_lid&#x60;+&#x60;localPassword&#x60;), updates the &#x60;vps&#x60; row (&#x60;vps_server_status&#x3D;&#x27;Reinstalling&#x27;&#x60;, &#x60;vps_os&#x3D;&lt;template&gt;&#x60;), saves any new root password to &#x60;history_log&#x60;, and queues a &#x60;reinstall_os&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;). **No rollback** — recover by restoring a backup via &#x60;postVpsRestore&#x60; (must have been created beforehand). Allow ~2 minutes for reinstall to start. Sibling ops: &#x60;getVpsReinstallOs&#x60; (list templates), &#x60;getVpsBackup&#x60; (snapshot before reinstalling), &#x60;postVpsRestore&#x60; (alternative — restore from backup instead).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields (required):**
- &#x60;template&#x60; (string, required) — &#x60;template_file&#x60; from &#x60;getVpsReinstallOs.templates[].template_file&#x60;. Rejected if not found in &#x60;vps_templates&#x60; for the VPS&#x27;s &#x60;template_type&#x60;.
- &#x60;localPassword&#x60; (string, required) — the customer&#x27;s current MyAdmin account password (re-auth check).

**Body fields (optional):**
- &#x60;password&#x60; (string, optional) — new root password to set during reinstall. If absent, the template default is used.

**Returns:** &#x60;{ text: &quot;Reinstall to has been sent to the server. Please allow up to 2 minutes for action to be completed.&quot; }&#x60;. If the VPS is &#x60;pending&#x60; rather than &#x60;active&#x60;, the OS selection is saved for activation and &#x60;{ text: &quot;OS selection has been updated in our system for when the service is activated.&quot; }&#x60; is returned.

**Side effects:**
- Updates &#x60;vps_server_status&#x60; and &#x60;vps_os&#x60; columns.
- Inserts new password into &#x60;history_log&#x60; when provided.
- Inserts &#x60;vpsqueue&#x60; &#x60;reinstall_os&#x60; row (active services only).

**Auth:** Session/API key plus re-auth via &#x60;localPassword&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;Missing Account Password&#x60; — &#x60;localPassword&#x60; body field absent/empty.
- &#x60;Invalid Account Password&#x60; — &#x60;localPassword&#x60; re-auth failed.
- &#x60;This Template &lt;name&gt; does not exist&#x60; — &#x60;template&#x60; not found for this VPS&#x27;s platform.

**Related calls:**
- **Prerequisite:** &#x60;getVpsReinstallOs&#x60; (find valid &#x60;template_file&#x60;).
- **Recommended pre-step:** &#x60;getVpsBackup&#x60; (snapshot).
- **Alternative (preserve state):** &#x60;postVpsRestore&#x60;.
- **Verify after reinstall:** &#x60;getVpsInfo&#x60; (look for updated &#x60;vps_os&#x60;).

     * @param template  
     * @param password  
     * @param localPassword  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/reinstall_os") class postVpsReinstallOs(val template: kotlin.String, val password: kotlin.String, val localPassword: kotlin.String, val id: kotlin.Int)

    /**
     * Reset the VPS root password to a server-generated random value
     * Resets the VPS root/Administrator password to a fresh random value generated on the hypervisor — typical when the customer has lost the existing password and cannot recover it. Queues a &#x60;reset_password&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;). The new password is delivered via the standard hypervisor password-change channel (logged to &#x60;history_log&#x60; and surfaced through &#x60;getVpsWelcomeEmail&#x60; / dashboard credential views). **No rollback** — to undo, set a new password via &#x60;postVpsChangeRootPassword&#x60; or call &#x60;postVpsResetPassword&#x60; again. Sibling ops: &#x60;getVpsResetPassword&#x60;, &#x60;postVpsChangeRootPassword&#x60;, &#x60;postVpsChangeWebuzoPassword&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None — password is generated server-side.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;reset_password&#x60; row; hypervisor agent generates and applies the new password.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Specific password instead:** &#x60;postVpsChangeRootPassword&#x60;.
- **Retrieve the new credentials:** &#x60;getVpsWelcomeEmail&#x60; (resends with current credentials).

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/reset_password") class postVpsResetPassword(val id: kotlin.Int)

    /**
     * Restore the VPS from a backup (DESTRUCTIVE — overwrites disk)
     * **DESTRUCTIVE.** Overwrites the VPS disk with a previously created backup. Re-authenticates via the customer&#x27;s MyAdmin password (when set), validates the backup row from &#x60;getVpsBackups&#x60;, checks disk capacity (skipped for ZFS), then queues &#x60;snapshot_restore&#x60; (ZFS — instant) or &#x60;restore&#x60; (Swift/MinIO — copy) on the hypervisor. Allow ~10 minutes. **Recommended pre-step:** &#x60;getVpsBackup&#x60; to snapshot current state first. Sibling ops: &#x60;getVpsBackups&#x60;, &#x60;getVpsBackup&#x60;, &#x60;postVpsReinstallOs&#x60; (wipe to fresh OS instead).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;backup&#x60; (string, required) — composite key &#x60;&lt;type&gt;:&lt;service&gt;:&lt;name&gt;&#x60; matching one of the entries from &#x60;getVpsBackups&#x60;. &#x60;type&#x60; is &#x60;swift&#x60; / &#x60;minio&#x60; / &#x60;zfs&#x60;; &#x60;service&#x60; is the originating VPS id; &#x60;name&#x60; is the backup filename.
- &#x60;password&#x60; (string, required for non-admin callers when the account has a password set) — the customer&#x27;s MyAdmin account password (re-auth check via &#x60;auth-&gt;authenticate&#x60;).

**Returns:** &#x60;{ text: &quot;Action has been sent to the server. Please allow up to 10 minutes for action to be completed.&quot;, queueId: &lt;integer&gt; }&#x60;.

**Side effects:**
- Inserts &#x60;vpsqueue&#x60; &#x60;snapshot_restore&#x60; (ZFS) or &#x60;restore&#x60; (Swift/MinIO) row.
- Calls &#x60;vps_resetup_vnc()&#x60;.

**Auth:** Session/API key plus re-auth via &#x60;password&#x60; for non-admin callers.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;You do not seem to currently have a backup that you are allowed to restore yourself.&#x60; — no eligible backups found (admin-only Swift backups are excluded for non-admin callers).
- &#x60;Invalid Password&#x60; — &#x60;password&#x60; re-auth failed.
- &#x60;Invalid Backup Image&#x60; — &#x60;backup&#x60; doesn&#x27;t match any row in &#x60;getVpsBackups&#x60;.
- &#x60;Not Enough Space To Restore Backup. (Backup Takes up X bytes, The VPS Has Y)&#x60; — disk-size check failed (skipped for ZFS).

**Related calls:**
- **Find the backup:** &#x60;getVpsBackups&#x60; (capture &#x60;type&#x60;, &#x60;service&#x60;, &#x60;name&#x60;).
- **Snapshot before restoring:** &#x60;getVpsBackup&#x60;.
- **Alternative (fresh OS, no data preserved):** &#x60;postVpsReinstallOs&#x60;.
- **Verify after restore:** &#x60;getVpsInfo&#x60;.

     * @param body VPS Restore request 
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/restore") class postVpsRestore(val body: RestoreRequest, val id: kotlin.Int)

    /**
     * Bulk-update PTR (reverse-DNS) records for one or more VPS IPs
     * Sets the PTR hostname for each VPS IP — bulk update via the &#x60;ips&#x60; map. Calls &#x60;reverse_dns($ip, $newHostname)&#x60; for every IP in the body whose value differs from the current PTR; IPs not currently attached to the VPS are silently ignored. Propagation depends on the reverse-zone TTL but is typically minutes, not instant. Sibling ops: &#x60;getVpsReverseDns&#x60;, &#x60;postVpsChangeHostname&#x60; (auto-sets PTR for primary IP), &#x60;getVpsBuyIp&#x60;/&#x60;postVpsBuyIp&#x60; (add more IPs first).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;ips&#x60; (object, required) — &#x60;{ &quot;&lt;ip&gt;&quot;: &quot;&lt;new-hostname&gt;&quot;, ... }&#x60;. Only IPs that already belong to the VPS will be updated; others are ignored. Empty-string values are skipped.

**Returns:** &#x60;{ message: &quot;DNS Updated&quot;, success: true }&#x60;.

**Side effects:**
- One &#x60;reverse_dns()&#x60; call per IP whose value changed.
- PTR records are written to the in-addr.arpa zone; propagation depends on TTL.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Read current PTRs first:** &#x60;getVpsReverseDns&#x60;.
- **For the primary IP:** &#x60;postVpsChangeHostname&#x60; (renames the VPS hostname and auto-PTRs in one go).
- **Adding IPs:** &#x60;getVpsBuyIp&#x60; → &#x60;postVpsBuyIp&#x60; → &#x60;postVpsReverseDns&#x60;.

     * @param body  
     * @param id VPS ID number 
     */
    @Location("/vps/{id}/reverse_dns") class postVpsReverseDns(val body: ReverseDnsEntries, val id: kotlin.Int)

    /**
     * Provision or refresh the VNC console endpoint for the VPS
     * (Re)establishes out-of-band VNC console access on the VPS — typically after a network change, hypervisor migration, or when troubleshooting boot issues. Validates the supplied VNC IP via &#x60;validIp()&#x60;, persists it to the &#x60;vps&#x60; row (&#x60;vps_vnc&#x60; column), and queues a &#x60;setup_vnc&#x60; action on the hypervisor (&#x60;vpsqueue&#x60;). Sibling ops: &#x60;getVpsSetupVnc&#x60; (read current), &#x60;getVpsViewDesktop&#x60; (Windows GUI/RDP path).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;vnc&#x60; (string, required) — IPv4 address for the VNC endpoint. Validated by &#x60;validIp()&#x60;.

**Returns:** &#x60;{ text, queueId }&#x60; — allow ~2 minutes for the hypervisor to bring up the listener.

**Side effects:**
- Updates &#x60;vps.vps_vnc&#x60; to the new IP.
- Inserts &#x60;vpsqueue&#x60; &#x60;setup_vnc&#x60; row.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;Invalid IP &quot;&lt;value&gt;&quot; or is blank&#x60; — &#x60;vnc&#x60; failed &#x60;validIp()&#x60;.

**Related calls:**
- **Read after provisioning:** &#x60;getVpsSetupVnc&#x60;.
- **Windows GUI access:** &#x60;getVpsViewDesktop&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/setup_vnc") class postVpsSetupVnc(val id: kotlin.Int)

    /**
     * Upgrade or downgrade the VPS slice count (creates prorated invoice on upgrade)
     * Changes the VPS&#x27;s slice count — bumps or shrinks CPU/RAM/disk allocation. Deletes any unpaid prior slice-upgrade invoices for this VPS, updates the recurring &#x60;repeat_invoices&#x60; row to the new slice count&#x27;s cost, creates a one-off &#x60;invoices&#x60; row prorated for the rest of the cycle, and either auto-opens a support ticket (active services — slice upgrades typically need a manual hypervisor action) or queues &#x60;set_slices&#x60; directly. Downgrades complete free and immediately (&#x60;paid&#x3D;1&#x60; zero-amount invoice). **Real money** on upgrades. Sibling ops: &#x60;getVpsSlices&#x60;, &#x60;postVpsBuyHdSpace&#x60;, &#x60;initiatePayment&#x60;, &#x60;getVpsInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;slices&#x60; (integer, required) — target slice count. &#x60;min_slices ≤ slices ≤ max_slices&#x60; per &#x60;getVpsSlices&#x60;. Must differ from current.

**Returns:**
- **Upgrade with payment owed:** &#x60;{ text: &quot;Thank you for your upgrade request. Kindly Pay the invoice to activate the upgrade.&quot;, invoice: &lt;integer&gt; }&#x60; — pay via &#x60;initiatePayment&#x60;.
- **Active VPS, upgrade queued via ticket:** &#x60;{ text: &quot;Thank you for your upgrade request. A ticket has been automatically opened for you. Please allow us 24 hours to complete your upgrade. ...&quot; }&#x60;.
- **Downgrade:** &#x60;{ text: &quot;You have downgraded N slices from your VPS, the changes will be apply shortly.&quot; }&#x60;.

**Side effects:**
- Deletes unpaid &#x60;N Slice Upgrade for VPS {id}&#x60; invoices.
- Updates &#x60;repeat_invoices&#x60; recurring cost and description (&#x60;&lt;plan_name&gt; N Slices&#x60;).
- Creates a new &#x60;invoices&#x60; row for the prorated upgrade amount (or &#x60;paid&#x3D;1&#x60; zero-amount for downgrades).
- Updates &#x60;vps.vps_slices&#x60; and &#x60;vps.vps_currency&#x60;.
- **Active VPS:** opens a support ticket via &#x60;create_ticket()&#x60; so an operator can resize manually, OR (when &#x60;$deferUpgradeViaTicket&#x60; is false) inserts &#x60;vpsqueue&#x60; &#x60;set_slices&#x60; row.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.
- &#x60;Must pass the slices field.&#x60; — body field missing.
- &#x60;Invalid Slices. You requested N but that amount is not available currently.&#x60; — out of range.
- &#x60;No Changes were made, Please Try Again!&#x60; — equals current.
- &#x60;Please activate the service first.&#x60; — VPS not in &#x60;pending&#x60;/&#x60;active&#x60;.

**Related calls:**
- **Prerequisite:** &#x60;getVpsSlices&#x60; (read range + prorated cost).
- **Pay the upgrade invoice:** &#x60;initiatePayment&#x60; with the returned &#x60;invoice&#x60; id.
- **Disk-only addon:** &#x60;postVpsBuyHdSpace&#x60;.
- **Verify:** &#x60;getVpsInfo&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/slices") class postVpsSlices(val id: kotlin.Int)

    /**
     * Search/filter VPS bandwidth usage with custom criteria (reserved)
     * Filtered variant of the bandwidth-usage endpoint — reserved for date-range and granularity filters. The current implementation mirrors &#x60;getVpsTrafficUsage&#x60; behavior and returns the full dataset; the body shape is reserved for future filter parameters (start/end date, day/hour granularity). Sibling op: &#x60;getVpsTrafficUsage&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** Filter fields (reserved — date range, granularity).

**Returns:** Same &#x60;VpsTrafficResponse&#x60; shape as &#x60;getVpsTrafficUsage&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.

**Related calls:**
- **Unfiltered alternative:** &#x60;getVpsTrafficUsage&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/traffic_usage") class postVpsTrafficUsage(val id: kotlin.Int)

    /**
     * Refresh the remote-desktop session connection info after IP/hostname changes
     * Force-refreshes the remote-desktop connection metadata — typically called after a hostname change (&#x60;postVpsChangeHostname&#x60;), IP addition (&#x60;postVpsBuyIp&#x60;), or reverse-DNS update (&#x60;postVpsReverseDns&#x60;) so the dashboard can re-fetch via its form-action pattern. Returns the same payload as &#x60;getVpsViewDesktop&#x60;. Sibling op: &#x60;getVpsViewDesktop&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None (form-action pattern).

**Returns:** Same shape as &#x60;getVpsViewDesktop&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60;.
- &#x60;409 VPS is not active&#x60;.

**Related calls:**
- **Read without refresh:** &#x60;getVpsViewDesktop&#x60;.
- **Common triggers:** &#x60;postVpsChangeHostname&#x60;, &#x60;postVpsBuyIp&#x60;, &#x60;postVpsReverseDns&#x60;.

Path param: &#x60;id&#x60; (integer). No body.

Returns the VPS view-desktop payload. Errors: HTTP 404 wrong owner, HTTP 409 not &#x60;active&#x60;. Sibling:
&#x60;getVpsViewDesktop&#x60;, &#x60;postVpsSetupVnc&#x60;.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/view_desktop") class postVpsViewDesktop(val id: kotlin.Int)

    /**
     * Validate a VPS order configuration and quote the cost — dry run, no charge
     * Step 2 of the VPS order flow. Validates a chosen VPS configuration (platform, OS, slices, location, control panel, coupon, etc.) against stock and policy, applies any coupon discount and frequency discount, and returns a cost breakdown — without creating any invoice or service record. Use this to preview the first-month and recurring cost before the customer commits via &#x60;addVps&#x60;. The body shape is identical between &#x60;putVps&#x60; and &#x60;addVps&#x60;; the only difference is the HTTP verb — PUT validates, POST commits. Sibling ops: &#x60;getNewVps&#x60; (catalog), &#x60;addVps&#x60; (place order).

**Required body fields:**
- &#x60;osDistro&#x60; (string) — OS template tag from &#x60;getNewVps.osNames&#x60; (e.g. &#x60;centos-7-x86_64&#x60;).
- &#x60;osVersion&#x60; (string) — OS version from &#x60;getNewVps.templates[platform][os][template_file]&#x60;.
- &#x60;vpsPlatform&#x60; (string) — one of the keys in &#x60;getNewVps.platformNames&#x60;: &#x60;kvm&#x60;, &#x60;kvmstorage&#x60;, &#x60;hyperv&#x60;, &#x60;openvz&#x60;, &#x60;ssdopenvz&#x60;, &#x60;virtuozzo&#x60;, &#x60;ssdvirtuozzo&#x60;, &#x60;lxc&#x60;, &#x60;cloudkvm&#x60;, &#x60;docker&#x60;. HTML stripped server-side.
- &#x60;slices&#x60; (integer) — &#x60;1 ≤ slices ≤ getNewVps.maxSlices&#x60;. Windows (&#x60;kvm&#x60; with &#x60;osDistro&#x60; starting &#x60;windows&#x60; or &#x60;os&#x3D;&#x3D;5&#x60;, plus &#x60;hyperv&#x60;/&#x60;cloudkvm&#x60; Windows) requires &#x60;slices ≥ 2&#x60;.

**Optional body fields:**
- &#x60;location&#x60; (integer, default 1) — &#x60;1&#x60;&#x3D;NJ, &#x60;2&#x60;&#x3D;LA, &#x60;3&#x60;&#x3D;TX. Out-of-stock platforms in a location auto-fail with an error.
- &#x60;period&#x60; (integer, default 1) — billing cycle in months: &#x60;1&#x60; / &#x60;6&#x60; / &#x60;12&#x60; / &#x60;24&#x60; / &#x60;36&#x60;. Discounts: 6mo&#x3D;5%, 12mo&#x3D;10%, 24mo&#x3D;15%, 36mo&#x3D;20%.
- &#x60;controlpanel&#x60; (string, default &#x60;none&#x60;) — &#x60;none&#x60; / &#x60;cpanel&#x60; (forces CentOS) / &#x60;da&#x60; (DirectAdmin). Incompatible with Windows.
- &#x60;coupon&#x60; (string) — coupon code; validated against &#x60;coupons&#x60; table (custid match, module&#x3D;&#x60;vps&#x60;, applies-to-service-type, usable count). Returns &quot;Invalid Coupon&quot; if not found/usable.
- &#x60;hostname&#x60; (string) — FQDN matching &#x60;/^.*\..*\..*$/&#x60; (e.g. &#x60;server.example.com&#x60;). Skipped for Windows KVM (auto-set to &#x60;vps{id}&#x60; server-side).
- &#x60;rootpass&#x60; (string) — required for all Linux platforms. Must match &#x60;/(?&#x3D;.{8,})(?&#x3D;.*[a-z])(?&#x3D;.*[A-Z])(?&#x3D;.*\d)(?&#x3D;.*\W)/&#x60;. Not required for Windows.
- &#x60;comment&#x60; (string) — free-form note saved on the &#x60;vps&#x60; row.

**Returned fields** (schema &#x60;VpsOrderPutResponse&#x60;):
- &#x60;continue&#x60; (bool) — &#x60;true&#x60; if validation passed and the order can be POSTed. If &#x60;false&#x60;, render &#x60;errors&#x60; and do not call &#x60;addVps&#x60;.
- &#x60;errors&#x60; (array of strings) — human-readable validation messages.
- &#x60;coupon_code&#x60; (integer) — id of the matched coupon row, or &#x60;0&#x60; if no coupon applied.
- &#x60;service_cost&#x60; (float) — first-period cost in customer currency (includes coupon + period discount).
- &#x60;slice_cost&#x60; (float) — per-slice cost after coupon.
- &#x60;repeat_service_cost&#x60; (float) — recurring monthly/period cost after coupon and period discount.
- &#x60;original_slice_cost&#x60;, &#x60;original_cost&#x60; (float) — undiscounted reference values.
- &#x60;service_type&#x60; (integer) — resolved service-type id (e.g. KVM Linux&#x3D;33, KVM Win&#x3D;32, KVM Storage&#x3D;57, HyperV&#x3D;54, OpenVZ&#x3D;31, Virtuozzo&#x3D;55).
- &#x60;monthly_service_cost&#x60; (float) — recurring cost normalized to monthly.

**Side effects:** None — &#x60;PUT /vps/order&#x60; is a pure read.

**Errors:**
- &#x60;400&#x60; — missing required field (&#x60;osDistro&#x60; / &#x60;vpsPlatform&#x60; / &#x60;slices&#x60; / &#x60;osVersion&#x60;) or invalid &#x60;location&#x60;. Body shape: &#x60;{error: &quot;Missing field &lt;name&gt;&quot;}&#x60;.
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Prerequisite:** &#x60;getNewVps&#x60; (provides every option value referenced in the body).
- **Next:** &#x60;addVps&#x60; (place the order with the same body once &#x60;continue &#x3D;&#x3D; true&#x60;).

**Example request body:**
&#x60;&#x60;&#x60;json
{
  &quot;vpsPlatform&quot;: &quot;kvm&quot;,
  &quot;osDistro&quot;: &quot;centos-7-x86_64&quot;,
  &quot;osVersion&quot;: &quot;centos-7-x86_64.qcow2&quot;,
  &quot;slices&quot;: 2,
  &quot;location&quot;: 1,
  &quot;period&quot;: 1,
  &quot;controlpanel&quot;: &quot;none&quot;,
  &quot;hostname&quot;: &quot;web1.example.com&quot;,
  &quot;rootpass&quot;: &quot;Sup3rS3cret!&quot;,
  &quot;coupon&quot;: &quot;&quot;
}
&#x60;&#x60;&#x60;
**Example response (validation passed):**
&#x60;&#x60;&#x60;json
{
  &quot;continue&quot;: true,
  &quot;errors&quot;: [],
  &quot;coupon_code&quot;: 0,
  &quot;service_cost&quot;: 12.00,
  &quot;slice_cost&quot;: 6.00,
  &quot;repeat_service_cost&quot;: 12.00,
  &quot;service_type&quot;: 33,
  &quot;monthly_service_cost&quot;: 12.00,
  &quot;platform&quot;: &quot;kvm&quot;, &quot;os&quot;: &quot;centos-7-x86_64&quot;,
  &quot;slices&quot;: 2, &quot;location&quot;: 1, &quot;period&quot;: 1,
  &quot;hostname&quot;: &quot;web1.example.com&quot;
}
&#x60;&#x60;&#x60;

     * @param body  (optional)
     */
    @Location("/vps/order") class putVps(val body: VpsOrderPutRequest)

    /**
     * Preview cost to set additional VPS disk to a target GB size — dry run
     * Step 2 of the disk-space addon flow. Dry-run that quotes a new &quot;Additional N GB Space&quot; addon at the target size, prorated to the VPS&#x27;s existing billing cycle. **No invoice is created and no charge happens.** Use to show the customer the immediate prorated &#x60;diffCost&#x60; and the new recurring &#x60;cost&#x60; before they commit via &#x60;postVpsBuyHdSpace&#x60;. Sibling ops: &#x60;getVpsBuyHdSpace&#x60;, &#x60;postVpsBuyHdSpace&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body fields:**
- &#x60;size&#x60; (integer, required) — target additional GB. Range &#x60;1 ≤ size ≤ 100&#x60;; rejected with &quot;Invalid Size Specified&quot; otherwise. Rejected with &quot;No Change Made, Size The Same&quot; if it equals current.

**Returns:**
- &#x60;gbCost&#x60; (float) — per-GB monthly cost in USD.
- &#x60;curSize&#x60; (integer) — currently purchased additional GB.
- &#x60;newSize&#x60; (integer) — requested target size.
- &#x60;cost&#x60; (float) — new recurring cost (size × gbCost × frequency).
- &#x60;diffCost&#x60; (float) — prorated immediate charge for the partial cycle plus the remainder of the period (when frequency &gt; 1).
- &#x60;frequency&#x60; (integer) — billing cycle in months (e.g. 1, 6, 12).

**Side effects:** None — pure read.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;Invalid Size Specified&#x60; — &#x60;size&#x60; out of &#x60;1..100&#x60;.
- &#x60;No Change Made, Size The Same&#x60; — &#x60;size &#x3D;&#x3D; curSize&#x60;.

**Related calls:**
- **Prerequisite:** &#x60;getVpsBuyHdSpace&#x60; (read current state).
- **Next:** &#x60;postVpsBuyHdSpace&#x60; (commit; creates invoice when diffCost &gt; 0, queues immediate update otherwise).

     * @param id VPS ID number 
     */
    @Location("/vps/{id}/buy_hd_space") class putVpsBuyHdSpace(val id: kotlin.Int)

    /**
     * Update editable settings on a VPS service record
     * Write-back endpoint for the VPS service record — typically the dashboard&#x27;s &quot;save changes&quot; action. The body is processed by &#x60;ViewVPS::getDetails()&#x60;, the same handler as the GET, so the accepted fields mirror what the VPS detail view edits in place (e.g. customer comment/label, display preferences). For lifecycle or provisioning changes use the dedicated endpoints — they enforce platform-specific validation and queue hypervisor actions correctly. Sibling ops: &#x60;getVpsInfo&#x60;, &#x60;VPSCancel&#x60;, and all the dedicated mutation endpoints listed below.

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** Form-encoded or JSON with editable fields (handler decides which are persisted). Most callers should use the dedicated endpoints instead.

**Returns:** &#x60;SuccessTextResponse&#x60; — &#x60;{text: &quot;...&quot;}&#x60; on success.

**Auth:** Session/API key. Ownership enforced via &#x60;vps_custid&#x60; match.

**Errors:**
- &#x60;401 Unauthorized&#x60; — missing session/API key.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.

**Prefer these dedicated endpoints when applicable:**
- Hostname → &#x60;postVpsChangeHostname&#x60; (OpenVZ/Virtuozzo only).
- Root password → &#x60;postVpsChangeRootPassword&#x60; (specific value) or &#x60;postVpsResetPassword&#x60; (random).
- Reverse DNS → &#x60;postVpsReverseDns&#x60;.
- Slice upgrade/downgrade → &#x60;getVpsSlices&#x60; → &#x60;postVpsSlices&#x60; (creates prorated invoice).
- Additional disk → &#x60;getVpsBuyHdSpace&#x60; → &#x60;putVpsBuyHdSpace&#x60; → &#x60;postVpsBuyHdSpace&#x60;.
- Additional IPs → &#x60;getVpsBuyIp&#x60; → &#x60;postVpsBuyIp&#x60;.
- Timezone → &#x60;getVpsChangeTimezone&#x60; → &#x60;postVpsChangeTimezone&#x60;.
- Cancel service entirely → &#x60;VPSCancel&#x60;.

     * @param id VPS ID number. 
     */
    @Location("/vps/{id}") class updateVpsInfo(val id: kotlin.String)

    /**
     * Cancel a VPS service at the end of the current billing cycle
     * Customer-facing cancel — schedules termination, stops future renewals, and queues deprovisioning. Billing continues until the end of the already-paid period, and the customer keeps access until then; this endpoint does **not** issue refunds. Delegates to &#x60;Billing\CancelService::go()&#x60; (shared cancellation handler used across all service modules). The repeat-invoice is marked for cancellation and the VPS row&#x27;s status will eventually flip to &#x60;cancelled&#x60;. Reversible: a customer can typically un-cancel before the cycle ends by opening a support ticket. Sibling ops: &#x60;getVpsInfo&#x60; (verify status), &#x60;getVpsInvoices&#x60; (review final invoices), &#x60;getVpsBackup&#x60; (snapshot before cancellation).

**Path param:**
- &#x60;id&#x60; (integer, required) — VPS id from &#x60;getVpsList.vps_id&#x60;.

**Body:** None.

**Returns:** &#x60;VPSCancelResponse&#x60; — confirmation text plus the scheduled cancellation date.

**Side effects:**
- Sets the &#x60;repeat_invoices&#x60; row for the VPS to non-renewing.
- Logs the cancellation event in &#x60;history_log&#x60;.
- Queues &#x60;vpsqueue&#x60; deprovisioning action to run at end-of-cycle.
- Does NOT immediately stop the VPS — power state is unchanged until the cycle ends.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401 Unauthorized&#x60; — missing session/API key.
- &#x60;404 Invalid VPS Passed&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Before cancelling:** &#x60;getVpsBackup&#x60; (create a final snapshot), &#x60;downloadVpsBackup&#x60; (export it).
- **After cancelling:** &#x60;getVpsInfo&#x60; (confirm &#x60;vps_status&#x60; flipped), &#x60;getVpsInvoices&#x60; (final invoices).
- **Sibling cancels on other modules:** &#x60;CancelDomain&#x60;, &#x60;mailCancel&#x60;, &#x60;webhostingCancel&#x60;, etc. all use the same &#x60;CancelService&#x60; handler.

     * @param id VPS ID number 
     */
    @Location("/vps/{id}") class vPSCancel(val id: kotlin.Int)

    /**
     * Place a new webhosting order, create the invoice, and queue provisioning
     * Step 3 of the webhosting order flow — actually places the order. Revalidates via &#x60;validate_buy_website()&#x60; (same checks as &#x60;putWebsites&#x60;), then calls &#x60;place_buy_website()&#x60; to allocate a backing webhosting server, create the &#x60;webhosting&#x60; service row in &#x60;pending&#x60; status, generate a &#x60;Repeat_Invoice&#x60; recurring billing row, produce an initial &#x60;invoices&#x60; row, and (when &#x60;registerDomain&#x3D;true&#x60;) also kick off a domain order with its own invoice. The activator runs once the invoice is paid; &#x60;getWebsitesWelcomeEmail&#x60; then fires automatically with control-panel credentials. **Real money** — call &#x60;putWebsites&#x60; first to preview cost. Sibling ops: &#x60;getNewWebsite&#x60;, &#x60;putWebsites&#x60;, &#x60;getWebsiteInfo&#x60;, &#x60;webhostingCancel&#x60;.

**Body fields:** Identical to &#x60;putWebsites&#x60;. Required: &#x60;hostname&#x60;, &#x60;packageId&#x60;. Optional: &#x60;rootpass&#x60; (auto-generated if blank), &#x60;period&#x60;, &#x60;coupon&#x60;, &#x60;serviceOfferId&#x60;, &#x60;script&#x60;, &#x60;comment&#x60;, &#x60;registerDomain&#x60;.

**Returns** (schema &#x60;ServiceOrderPostResponse&#x60;):
- &#x60;total_cost&#x60; (string/decimal) — total to pay across all generated invoices.
- &#x60;iid&#x60; (string) — primary invoice id (numeric).
- &#x60;iids&#x60; (array) — tagged invoice ids (e.g. &#x60;SERVICEwebhosting12345&#x60;).
- &#x60;real_iids&#x60; (array) — numeric invoice ids to pass to &#x60;initiatePayment&#x60;.
- &#x60;serviceId&#x60; (integer) — new &#x60;website_id&#x60;; use with &#x60;getWebsiteInfo&#x60; to poll status.
- &#x60;invoice_description&#x60; (string) — human-readable summary.
- &#x60;cj_params&#x60; (object) — Commission Junction tracking parameters.

**Side effects:**
- Inserts &#x60;webhosting&#x60; service row (&#x60;website_status&#x3D;&#x27;pending&#x27;&#x60;).
- Inserts &#x60;repeat_invoices&#x60; row for recurring charge.
- Inserts &#x60;invoices&#x60; row for the first period.
- When &#x60;registerDomain&#x3D;true&#x60;: also creates a domain service row and its own invoice (&#x60;domain_serviceid&#x60;, &#x60;diid&#x60; returned alongside).
- Hashes/encrypts &#x60;rootpass&#x60; to &#x60;history_log&#x60;.

**Auth:** Session/API key.

**Errors:**
- When validation fails: response is the same &#x60;errors&#x60; array from &#x60;putWebsites&#x60; (HTTP 200 with &#x60;continue&#x3D;false&#x60; shape).
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Prerequisite:** &#x60;getNewWebsite&#x60;, &#x60;putWebsites&#x60;.
- **Next:** &#x60;getBillingInvoice&#x60; (confirm), &#x60;initiatePayment&#x60; (pay with &#x60;real_iids&#x60;), then poll &#x60;getWebsiteInfo&#x60; until &#x60;website_status&#x3D;&#x3D;&#x27;active&#x27;&#x60;.
- **Resend credentials after activation:** &#x60;getWebsitesWelcomeEmail&#x60;.
- **Cancel before paying:** &#x60;webhostingCancel&#x60; (or &#x60;deleteBillingInvoice&#x60; for the pending invoice).

**Full ordering happy path:**
&#x60;&#x60;&#x60;text
GET /websites/order                              -&gt; catalog (getNewWebsite)
PUT /websites/order { ...config }                -&gt; price quote (putWebsites)
POST /websites/order { ...config }               -&gt; { serviceId, real_iids } (addWebsite)
GET /billing/invoices/{iid}                      -&gt; confirm invoice (getBillingInvoice)
GET /billing/pay/cc/{real_iids[0]}               -&gt; pay (initiatePayment)
GET /websites/{serviceId}                        -&gt; poll until website_status&#x3D;&#x3D;&quot;active&quot;
GET /websites/{serviceId}/welcome_email          -&gt; resend credentials if needed
&#x60;&#x60;&#x60;

     * @param body  
     */
    @Location("/websites/order") class addWebsite(val body: WebsiteOrderPostRequest)

    /**
     * Read the webhosting order catalog — plans, packages, promo offers, pricing
     * Step 1 of the webhosting order flow. Returns the full ordering catalog needed to build a valid order: available &#x60;serviceTypes&#x60; (plans), &#x60;serviceOffers&#x60; (promotional bundles), &#x60;packages&#x60;, billing &#x60;period&#x60; options, the customer&#x27;s currency symbol, default &#x60;serviceOfferId&#x60;, and &#x60;enableDomainRegistering&#x60; (whether free/paid domain registration is bundled). Read-only — no service or invoice created. Sibling discovery endpoints in other modules: &#x60;getNewVps&#x60;, &#x60;getNewMail&#x60;, &#x60;getNewDomain&#x60;. Sibling order-flow ops: &#x60;putWebsites&#x60;, &#x60;addWebsite&#x60;.

**Path/Query/Body:** None.

**Returns** (schema &#x60;WebsitesOrder&#x60;):
- &#x60;currencySymbol&#x60; (string) — locale currency symbol for display.
- &#x60;step&#x60; (integer) — current step in the multi-step order wizard.
- &#x60;website&#x60; (integer) — pre-selected default plan id.
- &#x60;period&#x60; (integer) — pre-selected default billing frequency.
- &#x60;serviceOfferId&#x60; (integer) — pre-selected promo offer.
- &#x60;serviceTypes&#x60; (array) — every plan; &#x60;services_ourcost&#x60; stripped server-side. Keys per row: &#x60;services_id&#x60;, &#x60;services_name&#x60;, &#x60;services_cost&#x60;, &#x60;services_type&#x60; (&#x60;WEB_CPANEL&#x60; / &#x60;WEB_DIRECTADMIN&#x60; / &#x60;WEB_PLESK&#x60; / &#x60;WEB_VESTA&#x60; / &#x60;WEB_PPA&#x60; / &#x60;WEB_WORDPRESS&#x60; / &#x60;WEB_STORAGE&#x60;), etc.
- &#x60;serviceOffers&#x60; (array) — current promotional bundles.
- &#x60;packages&#x60;, &#x60;packges&#x60; (array — legacy field name preserved alongside &#x60;packages&#x60;).
- &#x60;enableDomainRegistering&#x60; (bool) — when &#x60;true&#x60;, the order can also register/transfer a domain.
- &#x60;jsonServices&#x60;, &#x60;jsonServiceOffers&#x60; (string) — JSON-encoded copies for inline use in HTML.

**Auth:** Session/API key.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Next:** &#x60;putWebsites&#x60; (validate + quote — no charge), &#x60;addWebsite&#x60; (place order).

**Example abridged response:**
&#x60;&#x60;&#x60;json
{
  &quot;currencySymbol&quot;: &quot;$&quot;,
  &quot;step&quot;: 1,
  &quot;website&quot;: 23,
  &quot;period&quot;: 1,
  &quot;enableDomainRegistering&quot;: true,
  &quot;serviceTypes&quot;: [
    {&quot;services_id&quot;: 23, &quot;services_name&quot;: &quot;Standard&quot;, &quot;services_cost&quot;: 8.00, &quot;services_type&quot;: 1},
    {&quot;services_id&quot;: 25, &quot;services_name&quot;: &quot;Reseller&quot;, &quot;services_cost&quot;: 24.95, &quot;services_type&quot;: 1}
  ]
}
&#x60;&#x60;&#x60;

     */
    @Location("/websites/order") class getNewWebsite()

    /**
     * Read website IPs, current reverse DNS, and additional-IP pricing
     * Combined IP/billing view for a website: returns the primary &#x60;website_ip&#x60; plus any addon extras, each mapped to its current PTR hostname (via &#x60;get_hostname()&#x60;), the list of existing additional-IP repeat invoices (with &#x60;cancel_link&#x60; URLs), the count of paid extras, and the per-IP cost (in the website&#x27;s billing currency, falling back to USD/&#x60;WEBSITE_IP_COST&#x60;). Read-only. Use to populate a &quot;buy another IP&quot; form or to audit current IP allocations. Sibling ops: &#x60;postWebsiteBuyIp&#x60; (buy or update PTR), &#x60;gettWebsiteReverseDns&#x60; (PTR-only view), &#x60;postWebsitesReverseDns&#x60; (PTR-only update).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns:**
- &#x60;ips&#x60; (object) — &#x60;{&quot;&lt;ipv4&gt;&quot;: &quot;&lt;ptr-hostname&gt;&quot;, ...}&#x60; for every IP attached.
- &#x60;ipsDetails&#x60; (array) — existing addon invoices with each row&#x27;s &#x60;ip&#x60;, &#x60;cancel_link&#x60; (&#x60;cancel_addon?module&#x3D;webhosting&amp;r&#x3D;&lt;rid&gt;&#x60;), invoice metadata.
- &#x60;ipCount&#x60; (integer) — count of paid addon IPs.
- &#x60;ipCost&#x60; (float) — per-IP recurring cost in &#x60;currency&#x60;.
- &#x60;currency&#x60; (string), &#x60;currencySymbol&#x60; (string).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Website Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 Website is not active&#x60; — &#x60;website_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Buy another IP:** &#x60;postWebsiteBuyIp&#x60;.
- **Update PTRs only:** &#x60;postWebsitesReverseDns&#x60; (or &#x60;postWebsiteBuyIp&#x60; with &#x60;action&#x3D;reverse_dns&#x60;).
- **Cancel an addon IP:** follow the &#x60;cancel_link&#x60; URL.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/buy_ip") class getWebsiteBuyIp(val id: kotlin.Int)

    /**
     * Read full configuration and status detail for one webhosting service
     * Returns everything the customer dashboard shows for one website — status, hostname, control-panel username, primary IP, host server, plan, billing summary, action &#x60;client_links&#x60;, and supported addons. Read-only. Backed by &#x60;ViewWebsite::getDetails()&#x60;. Internal &#x60;admin_links&#x60;, &#x60;settings&#x60;, &#x60;csrf&#x60;, and &#x60;serviceMaster.website_key&#x60; (the API key) are stripped before return. Use to render a website detail page, verify ownership before mutating, or poll &#x60;website_status&#x60; after &#x60;addWebsite&#x60;. Sibling ops: &#x60;getWebsiteList&#x60;, &#x60;getWebsitesLogin&#x60;, &#x60;getWebsitesBackups&#x60;, &#x60;getWebsiteInvoices&#x60;, &#x60;webhostingCancel&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns** (schema &#x60;Website&#x60;):
- &#x60;serviceInfo&#x60; — &#x60;website_id&#x60;, &#x60;website_hostname&#x60;, &#x60;website_username&#x60;, &#x60;website_ip&#x60;, &#x60;website_server&#x60;, &#x60;website_type&#x60; (plan id), &#x60;website_status&#x60;, &#x60;website_comment&#x60;.
- &#x60;serviceMaster&#x60; — host-server row (cPanel/DA/Plesk hostname, panel URL). &#x60;website_key&#x60; is stripped.
- &#x60;serviceType&#x60; — plan row (&#x60;services_ourcost&#x60; stripped).
- &#x60;client_links&#x60; (array) — &#x60;{name, link, icon}&#x60; for restart, login, backup, etc. Internal &#x60;?link&#x3D;queue&amp;action&#x3D;...&#x60; URLs are pre-resolved to plain action names.
- &#x60;serviceAddons&#x60; — extra IPs, additional resources.

**Auth:** Session/API key. Ownership enforced via &#x60;website_custid&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; (legacy text — webhosting reuses the helper) — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Login to panel:** &#x60;getWebsitesLogin&#x60; (auto-login URL).
- **Backups + restore:** &#x60;getWebsitesBackups&#x60;.
- **Billing:** &#x60;getWebsiteInvoices&#x60;.
- **Reverse DNS:** &#x60;gettWebsiteReverseDns&#x60;, &#x60;postWebsitesReverseDns&#x60;.
- **Buy extra IP:** &#x60;getWebsiteBuyIp&#x60;, &#x60;postWebsiteBuyIp&#x60;.
- **Migration:** &#x60;postWebsiteMigration&#x60;.
- **Resend welcome email:** &#x60;getWebsitesWelcomeEmail&#x60;.
- **Cancel:** &#x60;webhostingCancel&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}") class getWebsiteInfo(val id: kotlin.Int)

    /**
     * List all billing invoices and recurring charges scoped to one website
     * Returns the billing history for one webhosting service — initial purchase invoice, recurring monthly/period invoices, and any IP-addon invoices created via &#x60;postWebsiteBuyIp&#x60;. Backed by &#x60;Billing\InvoicesList::go()&#x60; with &#x60;module&#x3D;&#x27;webhosting&#x27;&#x60; (same handler pattern as VPS/Mail/etc. per-service invoice endpoints). Use to render a per-website billing-history view or find an unpaid invoice id to pass to &#x60;initiatePayment&#x60;. Sibling ops: &#x60;getBillingInvoice&#x60;, &#x60;initiatePayment&#x60;, sibling cross-module: &#x60;getVpsInvoices&#x60;, &#x60;getDomainInvoices&#x60;, &#x60;getMailInvoices&#x60;. For account-wide history use top-level &#x60;getBillingInvoices&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns:** &#x60;ChargeInvoiceRows&#x60; — array of invoice rows: &#x60;id&#x60;, &#x60;amount&#x60;, &#x60;paid&#x60;, &#x60;description&#x60;, &#x60;date&#x60;, &#x60;due_date&#x60;, &#x60;currency&#x60;, &#x60;module&#x3D;webhosting&#x60;, &#x60;service&#x3D;{id}&#x60;.

**Auth:** Session/API key. Ownership enforced via parent website.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;400 Invalid Service&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Single invoice detail:** &#x60;getBillingInvoice&#x60;.
- **Pay an unpaid invoice:** &#x60;initiatePayment&#x60;.
- **Account-wide history:** &#x60;getBillingInvoices&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/invoices") class getWebsiteInvoices(val id: kotlin.Int)

    /**
     * List the caller&#x27;s webhosting (cPanel/DirectAdmin/Plesk/Webuzo) services
     * Enumerates every shared/reseller hosting account (&quot;website&quot;) owned by the authenticated customer. The canonical entry point for discovering a &#x60;website_id&#x60; to pass into other webhosting endpoints. Filtered server-side by &#x60;website_custid &#x3D; session account_id&#x60; — cross-customer leaks are not possible. Empty array means the account has no websites (not an error). Sibling ops: &#x60;getWebsiteInfo&#x60;, &#x60;getWebsitesLogin&#x60;, &#x60;getWebsitesBackups&#x60;, &#x60;getWebsiteInvoices&#x60;, &#x60;webhostingCancel&#x60;, &#x60;getNewWebsite&#x60; (order a new one).

**Path/Query/Body:** None.

**Returns:** Array of &#x60;WebsiteRow&#x60; — per-website summary:
- &#x60;website_id&#x60; (integer) — canonical id used in &#x60;/websites/{id}/*&#x60; paths.
- &#x60;website_hostname&#x60; (string) — primary FQDN.
- &#x60;website_status&#x60; (string enum) — &#x60;pending&#x60; / &#x60;active&#x60; / &#x60;pending-cancel&#x60; / &#x60;canceled&#x60;.
- &#x60;services_name&#x60; (string) — plan/package label (e.g. &#x60;Standard&#x60;, &#x60;Reseller&#x60;).
- &#x60;repeat_invoices_cost&#x60; (decimal) — current recurring cost in the website&#x27;s billing currency.
- &#x60;website_comment&#x60; (string|null) — customer-provided note.

**Auth:** Session/API key. Ownership filter enforced via &#x60;website_custid&#x60;.

**Errors:**
- &#x60;401&#x60; — unauthenticated.

**Related calls:**
- **Per-website detail:** &#x60;getWebsiteInfo&#x60; (full).
- **Control panel:** &#x60;getWebsitesLogin&#x60; (auto-login URL).
- **Backups + restore points:** &#x60;getWebsitesBackups&#x60;.
- **Billing:** &#x60;getWebsiteInvoices&#x60;.
- **Order a new site:** &#x60;getNewWebsite&#x60; → &#x60;putWebsites&#x60; → &#x60;addWebsite&#x60;.
- **Cancel:** &#x60;webhostingCancel&#x60;.

     */
    @Location("/websites") class getWebsiteList()

    /**
     * List off-site cpmove backups stored in Swift — list or inline-download archive
     * Returns the list of off-site cpmove backups stored for the webhosting account, or — with the &#x60;download&#x3D;&lt;name&gt;&#x60; query param — inline-streams the chosen archive as base64. Backups are read from the OpenStack Swift container &#x60;serviceMaster.website_name&#x60; (authenticated with &#x60;SWIFT_WEBHOSTING_USER&#x60;/&#x60;SWIFT_WEBHOSTING_PASS&#x60;) and filtered to objects matching &#x60;cpmove-{website_username}-*&#x60;. Use to find restore points before a risky change or before &#x60;webhostingCancel&#x60;. Empty array means no off-site cpmoves have been pushed for this account. Sibling ops: &#x60;webhostingCancel&#x60; (snapshot before terminating), &#x60;getWebsiteInfo&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Query params:**
- &#x60;download&#x60; (string, optional) — when set to a backup &#x60;name&#x60; from the list, switches to inline download mode (returns the file base64-encoded). **Large payload** — only fetch when actually restoring.

**Returns:**
- **List mode** (no &#x60;download&#x60;): array of &#x60;{name: &quot;&lt;cpmove-...&gt;&quot;, size: &quot;&lt;human-scaled&gt;&quot;}&#x60; (size from &#x60;Content-Length&#x60; via &#x60;Scale($len, &#x27;bytes&#x27;, 1)&#x60;).
- **Download mode** (&#x60;?download&#x3D;&lt;name&gt;&#x60;): single object &#x60;{name, size, file: &quot;&lt;base64-encoded-archive&gt;&quot;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; (legacy text) — &#x60;id&#x60; not owned by caller.
- &#x60;409 Website is not active&#x60; — &#x60;website_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Take a backup before cancelling:** &#x60;getWebsitesBackups&#x60; (with &#x60;download&#x3D;&#x60;) → &#x60;webhostingCancel&#x60;.
- **Migrate to/from another host:** &#x60;postWebsiteMigration&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/backups") class getWebsitesBackups(val id: kotlin.Int)

    /**
     * Get a one-time auto-login URL for the website&#x27;s control panel
     * Returns a single-use auto-login URL so the customer can jump into their control panel without entering credentials. Branches on &#x60;serviceMaster.website_type&#x60;:
- **WEB_CPANEL** (default): calls WHM &#x60;create_user_session&#x60; for the &#x60;cpaneld&#x60; service, returns a session-bound cPanel URL.
- **WEB_DIRECTADMIN**: calls DA &#x60;CMD_API_LOGIN_KEYS&#x60; (&#x60;max_uses&#x3D;2&#x60;, IP-locked to &#x60;127.0.0.1&#x60; plus the caller&#x27;s &#x60;client_ip&#x60;); returns one-time URL.
- **WEB_PLESK**: calls Plesk SDK &#x60;createSession&#x60;, returns &#x60;https://&lt;host&gt;:8443/enterprise/rsession_init.php?PLESKSESSID&#x3D;...&#x60;.
- **WEB_PPA**, **WEB_VESTA**: placeholders (return &#x60;Unhandled Server Type&#x60;).

Sibling ops: &#x60;getWebsiteInfo&#x60;, &#x60;getWebsitesWelcomeEmail&#x60; (re-send credentials instead).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns:** &#x60;{type: &quot;location&quot;, location: &quot;&lt;one-time-url&gt;&quot;}&#x60;.

**Side effects:**
- WHM/DA/Plesk-side session creation; sessions usually expire after first use (DirectAdmin: &#x60;max_uses&#x3D;2&#x60;, IP-locked).

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;Invalid Website Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;Website is &lt;status&gt;, only websites that are &quot;active&quot; can do this.&#x60; — &#x60;website_status !&#x3D; &quot;active&quot;&#x60;.
- &#x60;No Host server or username&#x60; — service has no &#x60;website_username&#x60; or &#x60;website_server&#x60; resolved.
- &#x60;Sorry! something went wrong, couldn&#x27;t connect to &lt;panel&gt;!&#x60; — panel-side failure.
- &#x60;Unhandled Server Type&#x60; — &#x60;website_type&#x60; is WEB_PPA / WEB_VESTA (or unrecognized).

**Related calls:**
- **If you need the credentials themselves:** &#x60;getWebsitesWelcomeEmail&#x60; (re-sends the welcome email with username/password).
- **List sites first:** &#x60;getWebsiteList&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/login") class getWebsitesLogin(val id: kotlin.Int)

    /**
     * Resend the webhosting welcome email with control-panel credentials and URL
     * Resends the webhosting welcome email — the new-account email containing control-panel hostname, username, password, and getting-started instructions. Calls the dynamically-resolved &#x60;website_welcome_email($id)&#x60; helper which composes and dispatches the message to the account&#x27;s &#x60;account_lid&#x60;. Idempotent — safe to call multiple times. Use after &#x60;addWebsite&#x60; finishes provisioning, or whenever a customer reports losing the original. Sibling welcome-email endpoints in other modules: &#x60;getVpsWelcomeEmail&#x60;, &#x60;getDomainsWelcomeEmail&#x60;, &#x60;getMailWelcomeEmail&#x60;. For an auto-login URL (no password reveal), use &#x60;getWebsitesLogin&#x60; instead.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns:** &#x60;SuccessTextResponse&#x60; — &#x60;{text: &quot;Welcome Email has been resent.&quot;}&#x60;.

**Side effects:**
- Sends an email to the account&#x27;s billing email address with the control-panel credentials currently stored in &#x60;history_log&#x60; for this website.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service Passed&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409 Service is not active&#x60; — &#x60;website_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Auto-login instead:** &#x60;getWebsitesLogin&#x60; (one-time URL, no password disclosure).
- **List sites first:** &#x60;getWebsiteList&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/welcome_email") class getWebsitesWelcomeEmail(val id: kotlin.Int)

    /**
     * Read current reverse-DNS (PTR) records for the website&#x27;s IPs
     * Returns the current PTR/reverse-DNS hostname for every IP attached to the website — primary &#x60;website_ip&#x60; plus any addons (from &#x60;get_service_addons().extra_ips&#x60;). PTRs are read live via &#x60;get_hostname()&#x60;, not cached. Use to render a PTR editor before calling &#x60;postWebsitesReverseDns&#x60;. **Note:** the operationId has a typo (&#x60;gettWebsiteReverseDns&#x60; with double-t) preserved for back-compat — do not rename. Sibling ops: &#x60;postWebsitesReverseDns&#x60; (update), &#x60;getWebsiteBuyIp&#x60; (broader IP+billing view), &#x60;postWebsiteBuyIp&#x60; (also supports &#x60;action&#x3D;reverse_dns&#x60;).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns:** &#x60;ReverseDnsEntries&#x60; — &#x60;{&quot;ips&quot;: {&quot;&lt;ip&gt;&quot;: &quot;&lt;ptr-hostname&gt;&quot;, ...}}&#x60;. Empty string for IPs with no PTR set.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; (legacy text) — &#x60;id&#x60; not owned by caller.
- &#x60;409 Website is not active&#x60; — &#x60;website_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Update PTRs:** &#x60;postWebsitesReverseDns&#x60;.
- **Add IPs first:** &#x60;getWebsiteBuyIp&#x60; → &#x60;postWebsiteBuyIp&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/reverse_dns") class gettWebsiteReverseDns(val id: kotlin.Int)

    /**
     * Buy an additional IP for the website OR update reverse DNS records
     * Dual-purpose mutation that branches on the &#x60;action&#x60; body field. **&#x60;action&#x3D;buy_ip&#x60;** (default): allocates a new addon IP via &#x60;website_addon_get_free_ips&#x60;, creates an addon &#x60;repeat_invoices&#x60; row at &#x60;WEBSITE_IP_COST&#x60; (currency-converted to the parent invoice&#x27;s currency), and emits a one-period &#x60;invoices&#x60; row to fund the first month — provisioning waits on payment and free-IP availability on the host server. **Real money**. **&#x60;action&#x3D;reverse_dns&#x60;**: skips billing entirely and updates PTR records via &#x60;reverse_dns()&#x60; for any IP in the &#x60;ips&#x60; map whose new hostname differs from the current &#x60;get_hostname()&#x60; value. Sibling ops: &#x60;getWebsiteBuyIp&#x60; (preview), &#x60;gettWebsiteReverseDns&#x60; / &#x60;postWebsitesReverseDns&#x60; (PTR-only).

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body fields:**
- &#x60;action&#x60; (string, optional, default &#x60;buy_ip&#x60;) — &#x60;buy_ip&#x60; or &#x60;reverse_dns&#x60;.
- For &#x60;action&#x3D;reverse_dns&#x60;: &#x60;ips&#x60; (object, required) — &#x60;{&quot;&lt;ip&gt;&quot;: &quot;&lt;new-hostname&gt;&quot;, ...}&#x60;. Only IPs already on the website are updated; others ignored. Empty-string values skipped.

**Returns:**
- For &#x60;buy_ip&#x60;: &#x60;{text: &quot;Ordered Additional IP successfully.&quot;, invoice: &lt;integer&gt;, repeatInvoice: &lt;integer&gt;}&#x60;.
- For &#x60;reverse_dns&#x60;: &#x60;{message: &quot;DNS Updated&quot;, success: true}&#x60;.

**Side effects:**
- &#x60;buy_ip&#x60;: inserts &#x60;repeat_invoices&#x60; row (&#x60;Additional IP for Webhosting &lt;id&gt;&#x60;) and an &#x60;invoices&#x60; row for the first period.
- &#x60;reverse_dns&#x60;: writes PTR records to the in-addr.arpa zone for changed IPs.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Website Passed&#x60;.
- &#x60;409 Website is not active&#x60;.
- &#x60;No available free IPs on this server. Please contact support to order additional IPs.&#x60; — host has no free IPs.

**Related calls:**
- **Preview first:** &#x60;getWebsiteBuyIp&#x60;.
- **Pay the new addon invoice:** &#x60;initiatePayment&#x60; with the returned &#x60;invoice&#x60;.

     * @param body  
     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/buy_ip") class postWebsiteBuyIp(val body: IdBuyIpBody, val id: kotlin.Int)

    /**
     * Submit a request for InterServer staff to migrate a website from another host
     * Submits a migration request: opens a support ticket containing the customer&#x27;s credentials for their current host (cPanel/FTP/domain registrar) so InterServer staff can copy the site, databases, and email into this webhosting account. **Sensitive** — the body contains plaintext credentials for the source host. Do not log responses. The created ticket&#x27;s id is returned; track progress with the helpdesk/tickets API. Sibling ops: &#x60;getWebsiteInfo&#x60;, &#x60;getWebsitesBackups&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body fields** (JSON or multipart):
- &#x60;custPortal&#x60; (string) — URL of the current hosting provider&#x27;s customer portal (e.g. &#x60;sso.godaddy.com&#x60;).
- &#x60;regEmail&#x60; (string) — email/username at the current host.
- &#x60;password&#x60; (string) — password at the current host.
- &#x60;ctrlPanel&#x60; (string) — current control-panel URL (e.g. &#x60;yourdomain.com/cpanel/&#x60;).
- &#x60;ftpUsername&#x60; (string), &#x60;ftpPassword&#x60; (string) — FTP credentials.
- &#x60;siteBusyMig&#x60; (string) — info on site traffic / whether a holding page can be shown during migration.
- &#x60;splReqMig&#x60; (string) — special requirements (PHP version, modules, etc.).
- &#x60;domainReg&#x60; (string) — whether domain-registration transfer is also needed (&#x60;yes&#x60;/&#x60;no&#x60; or freeform).
- &#x60;dataMig&#x60; (string) — nameserver switch timing preference.
- &#x60;domainRegPortal&#x60;, &#x60;domainRegEmail&#x60;, &#x60;domainRegPassword&#x60; (strings) — domain-registrar credentials.

**Returns:** &#x60;{text: &quot;Your migration request has been sucessfully submitted...&quot;, ticket: &lt;integer&gt;}&#x60; — pass &#x60;ticket&#x60; to the tickets API to monitor.

**Side effects:**
- Creates a support ticket via &#x60;create_ticket()&#x60; with the credentials in the ticket body.
- Inserts a &#x60;history_log&#x60; row of type &#x60;Webhost Migration&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid Service Passed&#x60; — &#x60;id&#x60; not owned by caller.

**Related calls:**
- **Track migration progress:** Tickets API (use the returned &#x60;ticket&#x60; id).
- **Verify after migration:** &#x60;getWebsitesLogin&#x60;, &#x60;getWebsiteInfo&#x60;.

     * @param body  
     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/migration") class postWebsiteMigration(val body: IdMigrationBody, val id: kotlin.Int)

    /**
     * Bulk-update reverse-DNS (PTR) records for one or more website IPs
     * Sets the PTR hostname for each IP in the website&#x27;s IP set. Calls &#x60;reverse_dns($ip, $newHostname)&#x60; for every IP in the body whose value differs from the current PTR and is non-empty; IPs not in the body are left alone. Always returns &#x60;{message: &quot;DNS Updated&quot;, success: true}&#x60; even if no entries actually changed. PTR propagation is asynchronous — re-call &#x60;gettWebsiteReverseDns&#x60; after a few minutes to confirm. Equivalent to calling &#x60;postWebsiteBuyIp&#x60; with &#x60;action&#x3D;reverse_dns&#x60;. Sibling ops: &#x60;gettWebsiteReverseDns&#x60;, &#x60;getWebsiteBuyIp&#x60;, &#x60;postWebsiteBuyIp&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body fields** (schema &#x60;ReverseDnsEntries&#x60;):
- &#x60;ips&#x60; (object, required) — &#x60;{&quot;&lt;ip&gt;&quot;: &quot;&lt;new-hostname&gt;&quot;, ...}&#x60;. Only IPs that already belong to the website are updated; others ignored. Empty-string values skipped.

**Returns:** &#x60;{message: &quot;DNS Updated&quot;, success: true}&#x60;.

**Side effects:**
- One &#x60;reverse_dns()&#x60; call per IP whose value changed. Records are written to the in-addr.arpa zone; TTL-dependent propagation.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404 Invalid VPS Passed&#x60; (legacy text) — &#x60;id&#x60; not owned by caller.
- &#x60;409 Website is not active&#x60; — &#x60;website_status !&#x3D; &quot;active&quot;&#x60;.

**Related calls:**
- **Read current PTRs first:** &#x60;gettWebsiteReverseDns&#x60;.
- **Equivalent endpoint:** &#x60;postWebsiteBuyIp&#x60; (&#x60;action&#x3D;reverse_dns&#x60;).

     * @param body  
     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}/reverse_dns") class postWebsitesReverseDns(val body: ReverseDnsEntries, val id: kotlin.Int)

    /**
     * Validate a webhosting order and preview cost — dry run, no charge
     * Step 2 of the webhosting order flow. Dry-runs the order through &#x60;validate_buy_website()&#x60;: checks &#x60;hostname&#x60; against &#x60;valid_hostname()&#x60; and the keyword blocklist, validates &#x60;packageId&#x60; against the customer&#x27;s plan eligibility, confirms the chosen plan&#x27;s hypervisor pool is in stock (&#x60;OUTOFSTOCK_WEBHOSTING_*&#x60; constants), applies any coupon and frequency discount, and returns a cost preview plus any validation errors. No invoice or service record is created. **Always call before &#x60;addWebsite&#x60;** to surface coupon/pricing/hostname problems cheaply. Sibling ops: &#x60;getNewWebsite&#x60; (catalog), &#x60;addWebsite&#x60; (place order).

**Body fields (form or JSON):**
- &#x60;hostname&#x60; (string, required) — primary FQDN for the website. Must pass &#x60;valid_hostname()&#x60;, must not contain &#x60;interserver.net&#x60; (non-admin), must not be on the blocked-keyword list, must match the plan&#x27;s TOS rules.
- &#x60;rootpass&#x60; (string, optional) — control-panel admin password; if blank, a random 8-char password is generated server-side via &#x60;generateRandomString(8,1,1,1,1)&#x60;.
- &#x60;packageId&#x60; (integer, required) — plan id from &#x60;getNewWebsite.serviceTypes[].services_id&#x60;. Must have &#x60;services_module&#x3D;&#x27;webhosting&#x27;&#x60; and &#x60;services_buyable&#x3D;1&#x60; (non-admin).
- &#x60;period&#x60; (integer, optional, default 1) — billing cycle in months: 1 / 6 / 12 / 24 / 36. Same frequency discounts as VPS apply.
- &#x60;coupon&#x60; (string, optional) — coupon code.
- &#x60;serviceOfferId&#x60; (integer, optional) — promo bundle from &#x60;getNewWebsite.serviceOffers&#x60;.
- &#x60;script&#x60; (integer, optional, default 0) — auto-installer id (Softaculous/WordPress/etc., 0 &#x3D; none).
- &#x60;comment&#x60; (string, optional) — free-form note saved on the service row.
- &#x60;registerDomain&#x60; (bool, optional) — when &#x60;true&#x60; and &#x60;enableDomainRegistering&#x3D;true&#x60; from the catalog, also registers/transfers the domain through the order.
- Implicit: TOS acceptance (validated via &#x60;tos&#x3D;&#x27;yes&#x27;&#x60; in source — required for non-admin).

**Returns** (validation envelope):
- &#x60;continue&#x60; (bool) — &#x60;true&#x60; if the order can safely be POSTed.
- &#x60;errors&#x60; (array of strings) — human-readable validation messages.
- &#x60;frequency&#x60; (integer) — resolved billing frequency.
- &#x60;coupon&#x60; (string) — the applied coupon name (echoed).
- &#x60;couponCode&#x60; (integer) — the matched coupon row id, or &#x60;0&#x60; if none.
- &#x60;serviceType&#x60; (integer) — resolved plan id.
- &#x60;serviceCost&#x60; (float) — first-period total cost (includes coupon + period discount).
- &#x60;originalCost&#x60; (float) — undiscounted reference.
- &#x60;repeatServiceCost&#x60; (float) — recurring cost after discounts.
- &#x60;hostname&#x60;, &#x60;password&#x60; (string) — final sanitized values (may differ from input — e.g. random password generated).
- &#x60;introFrequency&#x60; (integer) — first-period bonus length (intro pricing).

**Side effects:** None — pure read.

**Auth:** Session/API key.

**Errors (within &#x60;errors&#x60; array, &#x60;continue&#x3D;false&#x60;):**
- &#x60;Invalid Billing Interval&#x60; — &#x60;period&#x60; not numeric.
- &#x60;All webhosting servers are currently full.&#x60; — &#x60;OUTOFSTOCK_WEBHOSTING&#x60;.
- &#x60;Invalid Package Specified.&#x60; — plan id not in the webhosting module or not buyable.
- &#x60;Our &lt;Plan&gt; Webhosting Servers are currently full.&#x60; — plan-specific stock check.
- &#x60;The hostname cannot contain interserver.net&#x60;.
- &#x60;Hostname &quot;&lt;x&gt;&quot; Contains Invalid Characters Or Is Blank&#x60;.
- &#x60;Hostname contains a blocked keyword.&#x60;.
- &#x60;You must agree to the terms of service and click the checkbox saying so.&#x60;.
- &#x60;Invalid Coupon Specified&#x60; — coupon not usable for this plan/customer.

Top-level HTTP errors: &#x60;401&#x60; unauthenticated.

**Related calls:**
- **Prerequisite:** &#x60;getNewWebsite&#x60; (catalog).
- **Next:** &#x60;addWebsite&#x60; (same body — actually places the order).

**Example request body:**
&#x60;&#x60;&#x60;json
{
  &quot;hostname&quot;: &quot;mystore.example.com&quot;,
  &quot;rootpass&quot;: &quot;Sup3rS3cret!&quot;,
  &quot;packageId&quot;: 23,
  &quot;period&quot;: 12,
  &quot;coupon&quot;: &quot;&quot;,
  &quot;registerDomain&quot;: false,
  &quot;script&quot;: 0
}
&#x60;&#x60;&#x60;

     * @param body  
     */
    @Location("/websites/order") class putWebsites(val body: WebsiteOrderPutRequest)

    /**
     * POST mutation hook for the website detail page (use dedicated ops where possible)
     * POST mutation hook for the website detail page. The implementation currently routes through the same &#x60;View::go()&#x60; handler as &#x60;getWebsiteInfo&#x60;; concrete update behavior depends on which &#x60;client_links&#x60; action the form is driving. **For specific changes, prefer the dedicated endpoints** — they enforce field-level validation and queue the correct hypervisor/panel actions. Sibling ops: &#x60;getWebsiteInfo&#x60;, all dedicated mutation endpoints below.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** Form-encoded fields appropriate to the &#x60;client_links&#x60; action being driven.

**Returns:** &#x60;SuccessTextResponse&#x60; — &#x60;{text: &quot;...&quot;}&#x60;.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.

**Prefer these dedicated endpoints:**
- **Buy a paid IP or update reverse DNS:** &#x60;postWebsiteBuyIp&#x60; (the latter via &#x60;action&#x3D;reverse_dns&#x60;).
- **PTR-only changes:** &#x60;postWebsitesReverseDns&#x60;.
- **Migrate site from another host:** &#x60;postWebsiteMigration&#x60;.
- **Resend control-panel credentials:** &#x60;getWebsitesWelcomeEmail&#x60;.
- **Auto-login to cPanel/DA/Plesk:** &#x60;getWebsitesLogin&#x60;.
- **Cancel:** &#x60;webhostingCancel&#x60;.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}") class updateWebsiteInfo(val id: kotlin.String)

    /**
     * Schedule termination of a webhosting service — wipes panel account at cycle end
     * **DESTRUCTIVE.** Schedules the website for cancellation via the shared &#x60;Billing\CancelService::go($id)&#x60; flow with &#x60;module&#x3D;&#x27;webhosting&#x27;&#x60;. Marks the service &#x60;pending-cancel&#x60;, halts the recurring invoice, and queues deprovisioning so cPanel/DirectAdmin/Plesk/Webuzo removes the account and **all hosted files, databases, mailboxes, and DNS** at end-of-cycle. **There is no client-side restore** — take a cpmove backup via &#x60;getWebsitesBackups&#x60; first (with &#x60;download&#x3D;&lt;name&gt;&#x60;) if data must be preserved. Sibling ops: &#x60;getWebsitesBackups&#x60;, &#x60;getWebsiteInfo&#x60; (verify status flipped), &#x60;getWebsiteInvoices&#x60;.

**Path param:**
- &#x60;id&#x60; (integer, required) — &#x60;website_id&#x60; from &#x60;getWebsiteList&#x60;.

**Body:** None.

**Returns:** &#x60;WebsiteCancelResponse&#x60; — cancel-service confirmation payload.

**Side effects:**
- Sets &#x60;website_status&#x3D;&#x27;pending-cancel&#x27;&#x60;.
- Marks the &#x60;repeat_invoices&#x60; row as non-renewing.
- Logs the cancellation in &#x60;history_log&#x60;.
- Queues deprovisioning to run at end-of-cycle (the cPanel/DA/Plesk account, all hosted files, databases, email accounts, and DNS will be removed).
- Customer retains panel access until the cycle ends.

**Auth:** Session/API key. Ownership enforced.

**Errors:**
- &#x60;401&#x60; — unauthenticated.
- &#x60;404&#x60; — &#x60;id&#x60; not owned by caller.
- &#x60;409&#x60; — service in a state that cannot be cancelled (already &#x60;canceled&#x60;, etc.).

**Related calls:**
- **Before cancelling:** &#x60;getWebsitesBackups&#x60; (download a cpmove archive — irretrievable after deprovisioning).
- **After cancelling:** &#x60;getWebsiteInfo&#x60; (confirm &#x60;pending-cancel&#x60;), &#x60;getWebsiteInvoices&#x60; (final invoices).
- **Sibling cancels on other modules:** &#x60;VPSCancel&#x60;, &#x60;CancelDomain&#x60;, &#x60;mailCancel&#x60;, etc. all use the same &#x60;CancelService&#x60; handler.

     * @param id The website service ID. Use &#x60;website_id&#x60; from &#x60;GET /websites&#x60;. 
     */
    @Location("/websites/{id}") class webhostingCancel(val id: kotlin.String)

}
